    {"id": 0x0001, "text": "\x1A\x13\x2D\x08Du hast ein \x05\x41Ei \x05\x40ausgeliehen!\x09\x01Bald wird Kiki ausschlüpfen.\x01Gib es zurück, wenn Du\x01es nicht mehr benötigst!\x02", "box_type": 2},
    {"id": 0x0002, "text": "\x1A\x13\x2F\x08Du hast Kiki zurückgegeben\x01und dafür \x05\x41Henni\x05\x40 bekommen.\x09\x01Im Gegensatz zu anderen\x01Hühnern kräht Henni selten!\x02", "box_type": 2},
    {"id": 0x0003, "text": "\x1A\x13\x30\x08Der \x05\x41Schimmelpilz\x05\x40!\x09\x05\x41\x01\x05\x40So ein frischer Pilz fault sehr\x01schnell. Also bringe ihn rasch\x01zum Hexenladen in Kakariko!\x02", "box_type": 2},
    {"id": 0x0004, "text": "\x1A\x13\x31\x08Der \x05\x41Modertrank\x05\x40!\x09\x05\x41\x01\x05\x40Der Modertrank ist bestimmt\x01nützlich... Geh doch mal \x01in die Verlorenen Wälder!\x02", "box_type": 2},
    {"id": 0x0005, "text": "\x1A\x13\x32\x08Du hast den Modertrank\x01gegen die \x05\x41Säge\x05\x40 eingetauscht!\x09\x01Der komische Kerl hat das\x01wohl hier liegen gelassen.\x02", "box_type": 2},
    {"id": 0x0006, "text": "\x08Bomben   20 Stück   80 Rubine\x09\x01\x01\x1B\x05\x42Kaufen\x01Nicht kaufen\x05\x40\x02", "box_type": 0},
    {"id": 0x0007, "text": "\x1A\x13\x48\x08Du hast eine \x05\x41Munitionstasche\x01für Deku-Kerne\x05\x40 erhalten.\x09\x01In der Tasche kannst Du \x01\x05\x4640 \x05\x40Deku-Kerne aufbewahren!\x02", "box_type": 2},
    {"id": 0x0008, "text": "\x1A\x13\x33\x08Du hast die Säge gegen ein\x01\x05\x41zerbrochenes Goronen-Schwert\x01\x05\x40eingetauscht!\x09\x01Besuche damit Biggoron!\x02", "box_type": 2},
    {"id": 0x0009, "text": "\x1A\x13\x34\x08Du hast Biggoron das\x01zerbrochene Goronen-Schwert\x01gegeben und dafür ein \x05\x41Rezept\x01\x05\x40erhalten!\x09 Geh zu König Zora!\x02", "box_type": 2},
    {"id": 0x000A, "text": "\x1A\x13\x37\x08Biggorons Schwert!\x09\x01Du hast ein \x05\x41Zertifikat\x05\x40 erhalten.\x01Hoffentlich ist das Schwert\x01bald wieder repariert!\x02", "box_type": 2},
    {"id": 0x000B, "text": "\x1A\x13\x3D\x08Du hast das Langschwert\x01gegen das \x05\x41Biggoron-Schwert\x01\x05\x40getauscht!\x09 Diese Klinge ist\x01unzerbrechlich!\x02", "box_type": 2},
    {"id": 0x000C, "text": "\x1A\x13\x3D\x08Du hast das Zertifikat gegen\x01das \x05\x41Biggoron-Schwert\x01\x05\x40getauscht!\x09 Diese Klinge\x01ist unzerbrechlich!\x02", "box_type": 2},
    {"id": 0x000D, "text": "\x1A\x13\x35\x08Du hast für das Rezept\x01einen \x05\x41Glotzfrosch\x05\x40 erhalten!\x09\x01Schnell! Bringe ihn zum Hylia-\x01See, bevor ihm warm wird!\x02", "box_type": 2},
    {"id": 0x000E, "text": "\x1A\x13\x36\x08Du hast für den Glotzfrosch\x01die \x05\x41Augentropfen\x05\x40 erhalten!\x09\x01Bringe sie zu Biggoron, bevor\x01sie die Wirkung verlieren!\x02", "box_type": 2},
    {"id": 0x000F, "text": "\x06\x40\x05\x41GEWINNER!!\x05\x40\x0B\x02", "box_type": 0},
    {"id": 0x0010, "text": "\x13\x25\x08Die \x05\x41Schädel-Maske\x05\x40!\x09\x01Trage sie mit \x05\x46¡\x05\x40, um andere\x01zu erschrecken! Du fühlst\x01Dich wie ein böses Monster!\x02", "box_type": 2},
    {"id": 0x0011, "text": "\x13\x26\x08Die \x05\x41Geister-Maske\x05\x40!\x09\x01Trage sie mit \x05\x46¡\x05\x40, um sie zu\x01zeigen! Eine Menge Leute\x01kannst Du damit erschrecken!\x02", "box_type": 2},
    {"id": 0x0012, "text": "\x13\x24\x08Die \x05\x41Fuchs-Maske\x05\x40!\x09\x01Trage sie mit \x05\x46¡\x05\x40, um sie zu\x01zeigen! Wetten, Du machst\x01Dich damit beliebt?\x02", "box_type": 2},
    {"id": 0x0013, "text": "\x13\x27\x08Die \x05\x41Hasenohren\x05\x40!\x09\x01Trage sie mit \x05\x46¡\x05\x40, um sie zu\x01zeigen! Die langen Ohren\x01sehen doch putzig aus!\x02", "box_type": 2},
    {"id": 0x0014, "text": "\x13\x28\x08Die \x05\x41Goronen-Maske\x05\x40!\x09\x01Trage sie mit \x05\x46¡\x05\x40, um sie zu\x01zeigen! Du siehst selbst\x01fast aus wie ein Gorone...\x02", "box_type": 2},
    {"id": 0x0015, "text": "\x13\x29\x08Die \x05\x41Zora-Maske\x05\x40!\x09\x01Trage sie mit \x05\x46¡\x05\x40, um sie zu\x01zeigen! Mit dieser Maske\x01bist Du einer von ihnen!\x02", "box_type": 2},
    {"id": 0x0016, "text": "\x13\x2A\x08Die \x05\x41Gerudo-Maske\x05\x40!\x09\x01Trage sie mit \x05\x46¡\x05\x40, um sie zu\x01zeigen! Du siehst damit aus\x01wie - ein Mädchen?!\x02", "box_type": 2},
    {"id": 0x0017, "text": "\x13\x2B\x08Die \x05\x41Maske des Wissens\x05\x40!\x09\x05\x41\x01\x05\x40Trage sie mit \x05\x46¡\x05\x40, um sie\x01möglichst vielen Leuten\x01zu zeigen!\x02", "box_type": 2},
    {"id": 0x0018, "text": "Willkommen auf der bombigen...\x04\x06\x2F\x05\x41Minenbowlingbahn!!!\x05\x40\x04Was man hier gewinnt? Das bleibt\x01zunächst mein \x14\x03Geheimnis.\x14\x00\x01Ich verrate es erst, wenn Du für\x01ein Spiel bezahlt hast.\x04Ein Spiel kostet \x05\x4130 Rubine\x05\x40.\x01Willst Du?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x0019, "text": "\x08\x06\x55OKAY!\x09\x04Ziele auf das Loch in der Mitte\x01und schicke eine \x05\x41Krabbelmine\x05\x40 los!\x01Du hast \x05\x41zehn\x05\x40 \x05\x41Versuche\x05\x40. Fertig?\x04\x08\x06\x42\x05\x41LOS GEHT'S!\x05\x40\x09\x0B\x02", "box_type": 0},
    {"id": 0x001A, "text": "Willst Du nochmal spielen?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x001B, "text": "Oh, das hätte ich fast vergessen!\x01Das hier kannst Du gewinnen!\x0B\x02", "box_type": 0},
    {"id": 0x001C, "text": "\x08\x05\x41Bomben   20 Stück   80 Rubine\x01\x05\x40Halte die Bombe mit \x05\x46¡\x05\x40, drücke\x01zum Ablegen nochmal \x05\x46¡\x05\x40.\x09\x0A\x02", "box_type": 0},
    {"id": 0x001D, "text": "\x08\x05\x41Bomben   30 Stück   120 Rubine\x01\x05\x40Halte die Bombe mit \x05\x46¡\x05\x40, drücke\x01zum Ablegen nochmal \x05\x46¡\x05\x40.\x09\x0A\x02", "box_type": 0},
    {"id": 0x001E, "text": "\x08Bomben   30 Stück   120 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x001F, "text": "Ein Fluch ist etwas Schreckliches!\x01Doch nun ist er von uns genommen!\x02", "box_type": 0},
    {"id": 0x0020, "text": "Du hilfst doch auch meinen\x01Brüdern, oder?\x04Ich bin sicher, sie geben Dir\x01noch etwas viel Besseres!\x02", "box_type": 0},
    {"id": 0x0021, "text": "\x1ADer Fluch ist von mir genommen!\x01Tausend Dank! Hier ist eine\x01wertvolle Belohnung für Dich!\x0B\x02", "box_type": 0},
    {"id": 0x0022, "text": "Aarrrgh! Ich bin verflucht!\x02", "box_type": 0},
    {"id": 0x0023, "text": "Wir werden künftig aufpassen, daß\x01uns nicht wieder jemand verflucht!\x02", "box_type": 0},
    {"id": 0x0024, "text": "Du hast \x05\x41\x19 \x05\x40Skulltulas zerstört,\x01daher läßt nun langsam die \x01Wirkung des Fluchs nach.\x04Haben Dir meine Kinder, die Du\x01erlöst hast, etwas zur Belohnung\x01gegeben?\x04Man wird übrigens nur dann\x01\x05\x41sehr reich\x05\x40, wenn man so viele\x01goldene Skulltulas wie möglich\x01vernichtet.\x04Du findest sie nur, wenn Du\x01Deine Umgebung stets\x01aufmerksam erkundest!\x04Bitte hilf uns!\x01Wir zählen auf Dich!\x02", "box_type": 0},
    {"id": 0x0025, "text": "\x1AWir sehen so aus, weil auf uns\x01der Fluch der Skulltulas lastet.\x01Aber...\x07\x00\x24\x02", "box_type": 0},
    {"id": 0x0026, "text": "Wir sehen so aus, weil auf uns\x01der \x05\x41Fluch der Skulltulas\x05\x40 lastet.\x04Werden jedoch alle Skulltulas\x01dieser Welt zerstört, verliert\x01der Fluch seine Wirkung.\x04Tötest Du eine Skulltula, erscheint\x01ein Symbol. Sammle es ein!\x04\x13\x71Die Zahl neben dem \x05\x46Spinnensymbol\x05\x40\x01auf dem \x05\x44Status-Bildschirm\x05\x40 gibt an,\x01wieviele Skulltulas Du bis zu\x01diesem Zeitpunkt zerstört hast.\x04\x13\x71Erscheint das \x05\x46Spinnensymbol\x05\x40 neben\x01einem Namen auf dem \x05\x41Karten-\x01Bildschirm\x05\x40, findest Du in diesem\x01Gebiet keine Skulltulas mehr.\x07\x00\xFE\x02", "box_type": 0},
    {"id": 0x0027, "text": "Brichst Du den Fluch, werden\x01wir Dich \x05\x41reich\x05\x40 belohnen.\x02", "box_type": 0},
    {"id": 0x0028, "text": "\x1ADa Du \x05\x41\x19\x05\x40 Skulltulas zerstört\x01hast, wurde nun endlich der Fluch\x01von mir genommen.\x04\x1AVielen Dank! Hier ist ein Zeichen\x01meiner Dankbarkeit!\x01Bitte nimm es an!\x0B\x02", "box_type": 0},
    {"id": 0x0029, "text": "Danke, daß Du meine\x01Kinder befreit hast.\x04Was mit mir ist? Oh, das ist\x01schon in Ordnung.\x04Du hast jetzt bereits\x01\x05\x41\x19\x05\x40 Skulltulas zerstört! Mach Dir\x01um mich mal keine Sorgen...\x02", "box_type": 0},
    {"id": 0x002A, "text": "\x08Krabbelminen 20 Stück 180 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x002B, "text": "Willst Du ein Spielchen wagen?\x01Es kostet Dich nur \x05\x4120 Rubine\x05\x40!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x002C, "text": "Pech gehabt! Dafür brauchst Du\x01einen Bogen!\x0B\x02", "box_type": 0},
    {"id": 0x002D, "text": "Na gut. Dann eben nicht!\x0B\x02", "box_type": 0},
    {"id": 0x002E, "text": "\x08OKAY!\x09\x01Das hier ist nur was für echte\x01Kerle! Die berühmteste\x01\x05\x41Schießbude\x05\x40 des Landes!\x04Stell Dich auf die Plattform und\x01ziele genau! Du hast \x05\x41fünfzehn\x05\x40\x01Schüsse und mußt alle \x05\x41zehn\x01\x05\x40Steine treffen!\x04Schieße mit \x05\x42 \x05\x40. \x01Fertig? Dann los und viel Glück!\x0B\x02", "box_type": 0},
    {"id": 0x002F, "text": "Hier ist ein Loch in der Erde. Ob\x01man wohl etwas einpflanzen kann?\x02", "box_type": 0},
    {"id": 0x0030, "text": "\x1A\x13\x06\x08Die \x05\x41Feen-Schleuder\x05\x40!\x09\x01Im \x05\x46Gegenstands-Menü \x05\x40kannst\x01Du sie auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder\x05\x46 ¨\x01\x05\x40plazieren.\x04\x1A\x13\x06Drücke \x05\x46¡\x05\x40, um die Schleuder\x01zu benutzen. Halte \x05\x46¡ \x05\x40und\x01ziele mit \x05\x44ª\x05\x40. Laß \x05\x46¡\x05\x40 los,\x01um \x05\x41Deku-Kerne \x05\x40abzuschießen!\x04\x1A\x13\x06Wenn Du sofort schießen\x01willst, halte \x05\x46¡\x05\x40 etwas länger\x01gedrückt und laß dann los.\x02", "box_type": 2},
    {"id": 0x0031, "text": "\x1A\x13\x03\x08Der \x05\x41Feen-Bogen\x05\x40!\x09\x01Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du ihn auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x1A\x13\x03Drücke \x05\x46¡\x05\x40, um den Bogen\x01zu benutzen. Halte \x05\x46¡\x05\x40 und\x01ziele mit \x05\x44ª\x05\x40. Laß \x05\x46¡\x05\x40 los,\x01um \x05\x41Pfeile\x05\x40 abzuschießen!\x02", "box_type": 2},
    {"id": 0x0032, "text": "\x13\x02\x08Die \x05\x41Bomben\x05\x40!\x09\x01Im Gegenstands-Menü kannst\x01Du sie auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x13\x02Mit \x05\x46¡\x05\x40 kannst Du sie halten\x01und ablegen. Drückst Du \x05\x46¡\x01\x05\x40während Du rennst, kannst\x01Du die Bomben auch werfen!\x02", "box_type": 2},
    {"id": 0x0033, "text": "\x13\x09\x08Die \x05\x41Krabbelminen\x05\x40!\x09\x01Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du sie auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x13\x09Lege sie mit \x05\x46¡\x05\x40 ab.\x01Diese neuartige Bombe kann\x01an Wänden hinaufkrabbeln -\x01also ziele gut!\x02", "box_type": 2},
    {"id": 0x0034, "text": "\x13\x01\x08Die \x05\x41Deku-Nuß\x05\x40!\x09\x01Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du sie auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x13\x01Wirf die Deku-Nuß. Sie wird\x01zerplatzen und Deine\x01Gegner betäuben!\x02", "box_type": 2},
    {"id": 0x0035, "text": "\x1A\x13\x0E\x08Der \x05\x41Bumerang\x05\x40!\x09\x01Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du ihn auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x1A\x13\x0EDrücke \x05\x46¡\x05\x40, um Gegner\x01zu treffen, die weiter\x01entfernt sind!\x02", "box_type": 2},
    {"id": 0x0036, "text": "\x1A\x13\x0A\x08Der \x05\x41Fanghaken!\x05\x40\x09\x01Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du ihn auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x1A\x13\x0ABenutze ihn, um entfernte\x01Objekte zu Dir zu holen oder\x01um Dich an ein Objekt\x01heranzuziehen.\x04\x1A\x13\x0AHalte \x05\x46¡\x05\x40 gedrückt und ziele\x01mit \x05\x44ª\x05\x40. Läßt Du \x05\x46¡ \x05\x40los,\x01schießt Du den Fanghaken ab.\x02", "box_type": 2},
    {"id": 0x0037, "text": "\x13\x00\x08Der \x05\x41Deku-Stab\x05\x40!\x09\x01Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du ihn auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x13\x00Benutze ihn mit \x05\x46¡\x05\x40. Wenn Du\x01\x05\x43\x05\x40 drückst, kannst Du ihn\x01wieder wegpacken.\x04\x13\x00 Du kannst höchstens\x0110 Deku-Stäbe tragen, also\x01setze sie mit Bedacht ein!\x02", "box_type": 2},
    {"id": 0x0038, "text": "\x1A\x13\x11\x08Der \x05\x41Stahlhammer\x05\x40!\x09\x01Drücke \x05\x46¡\x05\x40, um mit ihm\x01Objekte zu zerschlagen!\x01Du brauchst beide Hände!\x02", "box_type": 2},
    {"id": 0x0039, "text": "\x1A\x13\x0F\x08Das \x05\x41Auge der Wahrheit\x05\x40!\x09\x01Plaziere es auf \x05\x46¡\x05\x40 und sieh\x01mit \x05\x46¡ \x05\x40hindurch! Du wirst\x01viele Geheimnisse lüften!\x04\x1A\x13\x0FSetzt Du es ein,\x01kostet es magische Energie.\x01Mit \x05\x46¡ \x05\x40kannst Du es auch\x01wieder deaktivieren.\x02", "box_type": 2},
    {"id": 0x003A, "text": "\x1A\x13\x08\x08Die \x05\x41Okarina der Zeit\x05\x40!\x09\x01Die Okarina ist ein Artefakt\x01aus dem Besitz des Königs.\x01Sie hat geheimnisvolle Kräfte!\x02", "box_type": 2},
    {"id": 0x003B, "text": "Du hast Farores Kräfte beschworen!\x01\x1C\x05\x42Zum Teleporter zurück\x01Teleporter entfernen\x01Zurück\x05\x40\x02", "box_type": 2},
    {"id": 0x003C, "text": "\x1A\x13\x67\x08Das \x05\x41Amulett des Feuers\x05\x40!\x09\x01Darunia gibt sich als einer\x01der Weisen zu erkennen und\x01überträgt Dir seine Kraft!\x02", "box_type": 2},
    {"id": 0x003D, "text": "\x1A\x13\x68\x08Das \x05\x43Amulett des Wassers\x05\x40!\x09\x01Ruto gibt sich als eine der\x01Weisen zu erkennen und\x01überträgt Dir ihre Kraft!\x02", "box_type": 2},
    {"id": 0x003E, "text": "\x1A\x13\x66\x08Das \x05\x42Amulett des Waldes\x05\x40!\x09\x01Salia gibt sich als eine der\x01Weisen zu erkennen und\x01überträgt Dir ihre Kraft!\x02", "box_type": 2},
    {"id": 0x003F, "text": "\x1A\x13\x69\x08Das \x05\x46Amulett der Geister\x05\x40!\x09\x01Naboru gibt sich als eine der\x01Weisen zu erkennen und\x01überträgt Dir ihre Kraft!\x02", "box_type": 2},
    {"id": 0x0040, "text": "\x1A\x13\x6B\x08Das \x05\x44Amulett des Lichts\x05\x40!\x09\x01Rauru, der Weise, gibt\x01Dir seine Kraft!\x02", "box_type": 2},
    {"id": 0x0041, "text": "\x1A\x13\x6A\x08Das \x05\x45Amulett des Schattens\x05\x40!\x09\x01Impa gibt sich als eine der\x01Weisen zu erkennen und\x01überträgt Dir ihre Kraft!\x02", "box_type": 2},
    {"id": 0x0042, "text": "\x1A\x13\x14\x08Eine leere\x05\x41 Flasche\x05\x40!\x09\x01Plaziere die Flasche auf \x05\x46¡\x05\x40,\x01um sie einzusetzen.\x02", "box_type": 2},
    {"id": 0x0043, "text": "\x13\x15\x08Das \x05\x41Rote Elixier\x05\x40!\x09\x01Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du es auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x13\x15Benutze es mit \x05\x46¡\x05\x40, um Deine \x01Energieleiste aufzufüllen.\x01Das Elixier befindet sich in\x01einer Deiner Flaschen.\x02", "box_type": 2},
    {"id": 0x0044, "text": "\x13\x16\x08Das \x05\x42Grüne Elixier\x05\x40!\x09\x01Im Gegenstands-Menü kannst\x01Du es auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x13\x16Benutze es mit \x05\x46¡\x05\x40, um Deine \x01Magieleiste aufzufüllen.\x01Das Elixier befindet sich in\x01einer Deiner Flaschen.\x02", "box_type": 2},
    {"id": 0x0045, "text": "\x13\x17\x08Das \x05\x43Blaue Elixier\x05\x40!\x09\x01Benutze es mit \x05\x46¡\x05\x40, um\x01Magie- und Energieleiste\x01komplett aufzufüllen!\x02", "box_type": 2},
    {"id": 0x0046, "text": "\x13\x18\x08Du besitzt jetzt eine \x05\x41Fee\x05\x40!\x09\x01Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du sie auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x13\x18Diese kleine Fee wird Dich\x01wiederbeleben, wenn Du keine\x01Energie mehr hast.\x04\x13\x18Hast Du sie auf \x05\x46¡ \x05\x40plaziert, \x01kannst Du ihre Hilfe jederzeit\x01in Anspruch nehmen.\x02", "box_type": 2},
    {"id": 0x0047, "text": "\x13\x19\x08Du besitzt jetzt einen \x05\x41Fisch\x05\x40!\x09\x01Lasse ihn mit \x05\x46¡\x05\x40 frei. Er sieht\x01richtig frisch aus!\x04\x13\x19Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du ihn auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x01Mit \x05\x46¡ \x05\x40läßt Du ihn frei.\x02", "box_type": 2},
    {"id": 0x0048, "text": "\x13\x10\x08Die \x05\x41Wundererbse\x05\x40!\x09\x01Suche nach einer Stelle,\x01um sie mit \x05\x46¡ \x05\x40einzupflanzen.\x01Warte ab, was passiert!\x04\x13\x10Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du sie auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren und\x01mit \x05\x46¡\x05\x40 einpflanzen.\x02", "box_type": 2},
    {"id": 0x0049, "text": "Tut mir leid... Na gut, also...\x04\x08\x06\x45\x05\x41LOS GEHT'S!\x05\x40\x09\x0B\x02", "box_type": 0},
    {"id": 0x004A, "text": "\x1A\x13\x07\x08Die \x05\x41Feen-Okarina\x05\x40!\x09\x01Sie ist ein Andenken an Salia!\x04\x1A\x13\x07Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du sie auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x04\x1A\x13\x07Mit \x05\x43\x05\x40 und den \x05\x46¡-Knöpfen \x05\x40spielst\x01Du eine Melodie. Mit \x05\x42 \x05\x40 kannst\x01Du aufhören oder neu beginnen.\x02", "box_type": 2},
    {"id": 0x004B, "text": "\x13\x3D\x08Das \x05\x42Langschwert\x05\x40!\x09\x01Schwinge es mit \x05\x42 \x05\x40!\x01Benutzt Du es, kannst Du\x01Deinen \x05\x44Schild\x05\x40 nicht einsetzen!\x02", "box_type": 2},
    {"id": 0x004C, "text": "\x13\x3E\x08Der \x05\x44Deku-Schild\x05\x40!\x09\x01Gehe ins \x05\x43Ausrüstungs-Menü\x05\x40,\x01um ihn mit \x05\x43 \x05\x40auszuwählen.\x04\x13\x3EDrücke \x05\x44£\x05\x40, um Angriffe\x01abzuwehren. Drückst Du \x05\x44£\x05\x40 und\x01bewegst \x05\x43ª\x05\x40, schwenkst Du\x01den Schild.\x02", "box_type": 2},
    {"id": 0x004D, "text": "\x13\x3F\x08Der \x05\x44Hylia-Schild\x05\x40!\x09\x01Gehe ins \x05\x43Ausrüstungs-Menü\x05\x40,\x01um ihn mit \x05\x43\x05\x40 auszuwählen.\x02", "box_type": 2},
    {"id": 0x004E, "text": "\x1A\x13\x40\x08Der \x05\x44Spiegel-Schild\x05\x40!\x09\x01Der Spiegel-Schild reflektiert\x01Licht oder Energie. Mit \x05\x44£\x05\x40\x01setzt Du ihn ein.\x02", "box_type": 2},
    {"id": 0x004F, "text": "\x1A\x13\x0B\x08Der \x05\x41Enterhaken\x05\x40!\x09\x01Dies ist ein viel besserer\x01Fanghaken - er reicht\x01\x05\x41doppelt so weit\x05\x40!\x02", "box_type": 2},
    {"id": 0x0050, "text": "\x13\x42\x08Die \x05\x41Goronen-Rüstung\x05\x40!\x09\x01Diese feuerfeste Rüstung\x01paßt nur Erwachsenen. Sie\x01schützt vor extremer Hitze!\x02", "box_type": 2},
    {"id": 0x0051, "text": "\x13\x43\x08Die \x05\x43Zora-Rüstung\x05\x40!\x09\x01Diese Unterwasser-Rüstung\x01paßt nur Erwachsenen. Du\x01kannst unter Wasser atmen!\x02", "box_type": 2},
    {"id": 0x0052, "text": "\x08Ein \x05\x42Magie-Krug\x05\x40!\x09\x01Deine Magieleiste\x01wird aufgefüllt.\x02", "box_type": 2},
    {"id": 0x0053, "text": "\x1A\x13\x45\x08Die \x05\x41Eisenstiefel\x05\x40!\x09\x01Zu schwer, um zu rennen.\x01Zu schwer, um zu schwimmen.\x02", "box_type": 2},
    {"id": 0x0054, "text": "\x1A\x13\x46\x08Die \x05\x41Gleitstiefel\x05\x40!\x09\x01Mit diesen seltsamen Schuhen\x01schwebst Du über den Boden.\x04\x1A\x13\x46Du kannst damit für\x01kurze Zeit sogar Abgründe\x01überqueren. Habe Mut und\x01vertraue den Stiefeln!\x02", "box_type": 2},
    {"id": 0x0055, "text": "\x08Ein \x05\x45Herz\x05\x40!\x09\x01Es füllt eines Deiner \x01Energieherzen auf!\x02", "box_type": 2},
    {"id": 0x0056, "text": "\x1A\x13\x4B\x08Der \x05\x41Große Köcher\x05\x40!\x09\x01Jetzt kannst Du insgesamt\x01\x05\x4640 \x05\x40Pfeile tragen!\x02", "box_type": 2},
    {"id": 0x0057, "text": "\x1A\x13\x4B\x08Der \x05\x41Riesenköcher\x05\x40!\x09\x01Jetzt kannst Du insgesamt\x01\x05\x4650\x05\x40 Pfeile tragen!\x02", "box_type": 2},
    {"id": 0x0058, "text": "\x1A\x13\x4D\x08Die \x05\x41Bombentasche\x05\x40!\x09\x01Diese Bombentasche ist aus\x01Dodongo-Leder hergestellt.\x04\x1A\x13\x02\x08Darin findest Du \x05\x4120 Bomben\x05\x40!\x09\x01Du kannst die Bomben auf \x05\x46¡\x05\x40\x01plazieren und Hindernisse\x01wegsprengen! Das ist bombig!\x02", "box_type": 2},
    {"id": 0x0059, "text": "\x1A\x13\x4E\x08Die \x05\x41Große Bombentasche\x05\x40!\x09\x01Jetzt kannst Du insgesamt \x05\x4630\x05\x40\x01Bomben tragen!\x02", "box_type": 2},
    {"id": 0x005A, "text": "\x1A\x13\x4F\x08Die \x05\x41Riesen-Bombentasche\x05\x40!\x09\x01Jetzt kannst Du insgesamt \x05\x4640\x01\x05\x40Bomben tragen!\x02", "box_type": 2},
    {"id": 0x005B, "text": "\x1A\x13\x51\x08Die \x05\x43Krafthandschuhe\x05\x40!\x09\x01Trägst Du sie, hast Du\x01die Kraft, mit \x05\x43\x05\x40 auch sehr\x01schwere Dinge anzuheben!\x04\x1A\x13\x51Aber einem kleinen Jungen\x01sind sie zu groß... Zudem hast\x01Du versprochen, sie \x05\x41Naboru\x05\x40 zu\x01geben! Halte also Wort!\x02", "box_type": 2},
    {"id": 0x005C, "text": "\x1A\x13\x52\x08Die \x05\x43Titanhandschuhe\x05\x40!\x09\x01Du fühlst noch größere Kraft\x01in den Armen! Du packst\x01schwerste Dinge mit \x05\x43\x05\x40!\x02", "box_type": 2},
    {"id": 0x005D, "text": "\x13\x1C\x08\x05\x44Blaues Feuer\x05\x40 eingefangen!\x09\x01Es ist eine kalte Flamme.\x01Benutze sie mit\x01\x05\x46§\x05\x40,\x05\x46 ¦\x05\x40 oder\x05\x46 ¨\x05\x40.\x02", "box_type": 2},
    {"id": 0x005E, "text": "\x1A\x13\x56\x08Die \x05\x43Große Börse\x05\x40!\x09\x01Jetzt hast Du eine größere\x01Geldbörse erhalten und kannst\x01insgesamt \x05\x46200\x05\x40 \x05\x46Rubine\x05\x40 tragen!\x02", "box_type": 2},
    {"id": 0x005F, "text": "\x1A\x13\x57\x08Die \x05\x43Riesenbörse\x05\x40!\x09\x01Welch eine riesige Geldbörse!\x01Jetzt kannst Du sogar \x01\x05\x46500 Rubine\x05\x40 tragen!\x02", "box_type": 2},
    {"id": 0x0060, "text": "\x13\x77\x08Ein \x05\x41kleiner Schlüssel\x05\x40!\x09\x01Er öffnet eine verschlossene\x01Tür. Du kannst ihn nur in\x01diesem Labyrinth einsetzen.\x02", "box_type": 2},
    {"id": 0x0061, "text": "\x08\x05\x41Krabbelmine  20 Stück  180 Rubine\x01\x05\x40Das ist eine praktische Zeitbombe,\x01die Du als Distanzwaffe\x01einsetzen kannst!\x09\x0A\x02", "box_type": 0},
    {"id": 0x0062, "text": "\x08Rotes Elixier   40 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0063, "text": "\x08Rotes Elixier   50 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0064, "text": "\x08\x05\x41Rotes Elixier   40 Rubine\x01\x05\x40Damit füllst Du Deine Energieleiste\x01wieder vollständig auf.\x01Zur einmaligen Anwendung.\x09\x0A\x02", "box_type": 0},
    {"id": 0x0065, "text": "\x08\x05\x41Rotes Elixier   50 Rubine\x01\x05\x40Damit füllst Du Deine Energieleiste\x01wieder vollständig auf.\x01Zur einmaligen Anwendung.\x09\x0A\x02", "box_type": 0},
    {"id": 0x0066, "text": "\x13\x76\x08Die \x05\x41Labyrinth-Karte\x05\x40!\x09\x01Drücke \x05\x41START\x05\x40, um sie im\x01\x05\x41Karten-Bildschirm \x05\x40anzusehen!\x04\x13\x76\x05\x43Blaue Räume\x05\x40 hast Du bereits\x01aufgesucht.\x01Der \x05\x44blinkende Raum \x05\x40zeigt\x01Deine derzeitige Position.\x04\x13\x76Bewege \x05\x44ª\x05\x40,\x05\x44 \x05\x40um ein\x01Stockwerk auszuwählen.\x02", "box_type": 2},
    {"id": 0x0067, "text": "\x13\x75\x08Der \x05\x41Kompaß\x05\x40!\x09\x01Jetzt siehst Du auf Deiner\x01Karte alle Schatztruhen\x01dieses Labyrinths!\x02", "box_type": 2},
    {"id": 0x0068, "text": "\x1A\x13\x6F\x08Der \x05\x41Stein des Wissens\x05\x40!\x09\x01Benutzt Du ab jetzt Dein\x01\x05\x44Rumble Pak\x05\x40, reagiert es... auf\x01naheliegende Geheimnisse!\x02", "box_type": 2},
    {"id": 0x0069, "text": "\x1A\x13\x23\x08Das ist \x05\x41Zeldas Brief\x05\x40!\x09\x01Er trägt Prinzessin Zeldas\x01Unterschrift!\x04\x1A\x13\x23Im \x05\x46Gegenstands-Menü \x05\x40kannst\x01Du ihn auf \x05\x46§\x05\x40, \x05\x46¦ \x05\x40oder \x05\x46¨\x01\x05\x40plazieren. Benutze \x05\x46¡\x05\x40, um ihn\x01jemandem zu zeigen.\x02", "box_type": 2},
    {"id": 0x006A, "text": "\x08Hi! Was soll's denn sein?\x09\x01\x01\x1B\x05\x42Ich will einkaufen!\x01Ich schau nur mal...\x05\x40\x02", "box_type": 0},
    {"id": 0x006B, "text": "\x08Möchtest Du noch etwas kaufen?\x09\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x006C, "text": "\x13\x49\x08Deine \x05\x41Munitionstasche\x01\x05\x40ist größer geworden!\x09\x01Jetzt kannst Du insgesamt\x01\x05\x4650\x05\x41 Deku-Kerne \x05\x40tragen!\x02", "box_type": 2},
    {"id": 0x006D, "text": "Öffne eine Truhe und... Voilà!\x01Findest Du einen Schlüssel, darfst\x01Du den nächsten Raum betreten!\x01Links oder rechts? Probier's aus!\x04\x05\x4110 Rubine \x05\x40pro Spiel.\x01Machst Du mit?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x006E, "text": "Klasse! Ein echter Zocker!\x02", "box_type": 0},
    {"id": 0x006F, "text": "\x08Du hast einen \x05\x42Rubin\x05\x40\x01erhalten!\x09\x02", "box_type": 2},
    {"id": 0x0070, "text": "\x1A\x13\x04\x08Die \x05\x41Feuer-Pfeile\x05\x40!\x09\x01Plaziere sie auf \x05\x46¡\x05\x40,\x05\x46 \x05\x40um sie\x01abzuschießen! Triffst Du,\x01wird Dein Ziel entflammen!\x02", "box_type": 2},
    {"id": 0x0071, "text": "\x1A\x13\x0C\x08Die \x05\x43Eis-Pfeile\x05\x40!\x09\x01Plaziere sie auf \x05\x46¡\x05\x40, um sie\x01zu verschießen! Triffst Du,\x01wird Dein Ziel einfrieren!\x04\x1A\x13\x0CDiese magischen Pfeile darf\x01nur der verschießen, der das\x01Kampftraining der Gerudo-\x01Kriegerinnen bestanden hat!\x02", "box_type": 2},
    {"id": 0x0072, "text": "\x1A\x13\x12\x08Die \x05\x44Licht-Pfeile\x05\x40!\x09\x01Plaziere sie auf \x05\x46¡\x05\x40, um sie \x01zu verschießen - das Licht\x01des Guten zerstört Böses!\x02", "box_type": 2},
    {"id": 0x0073, "text": "\x1A\x06\x46Du hast das\x01\x06\x32\x05\x42Menuett des Waldes\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x0074, "text": "\x1A\x06\x46Du hast den\x01\x06\x35\x05\x41Bolero des Feuers\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x0075, "text": "\x1A\x06\x46Du hast die\x01\x06\x29\x05\x43Serenade des Wassers\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x0076, "text": "\x1A\x06\x46Du hast das\x01\x06\x2F\x05\x46Requiem der Geister\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x0077, "text": "\x1A\x06\x46Du hast die\x01\x06\x29\x05\x45Nocturne des Schattens\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x0078, "text": "\x1A\x06\x46Du hast die\x01\x06\x33\x05\x44Kantate des Lichts\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x0079, "text": "\x1A\x13\x50\x08Das \x05\x41Goronen-Armband\x05\x40!\x09\x01Nun kannst Du Donnerblumen\x01pflücken. Stelle Dich davor\x01und nimm sie mit \x05\x43\x05\x40 auf!\x02", "box_type": 2},
    {"id": 0x007A, "text": "\x13\x1D\x08Du hast einen \x05\x41Käfer \x05\x40gefangen!\x09\x01Du kannst ihn mit \x05\x46¡\x05\x40 freilassen.\x01Du findest diese Käfer häufig in \x01dunklen Erdhöhlen.\x02", "box_type": 2},
    {"id": 0x007B, "text": "\x1A\x13\x70\x08Der \x05\x41Gerudo-Paß\x05\x40!\x09\x01Jetzt hast Du Zutritt zur\x01großen Trainingsarena der\x01Gerudo-Kriegerinnen.\x02", "box_type": 2},
    {"id": 0x007C, "text": "\x08Bomben  10 Stück  50 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x007D, "text": "\x08Pfeile  50 Stück  90 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x007E, "text": "\x08Fisch   200 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x007F, "text": "\x08Deku-Nüsse   5 Stück   15 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0080, "text": "\x1A\x13\x6C\x08Der \x05\x42Kokiri-Smaragd\x05\x40!\x09\x01Der Deku-Baum hat Dir diesen\x01Heiligen Stein des Waldes\x01anvertraut!\x02", "box_type": 2},
    {"id": 0x0081, "text": "\x1A\x13\x6D\x08Der \x05\x41Goronen-Opal\x05\x40!\x09\x01Von den Goronen wurde Dir\x01dieser Heilige Stein\x01des Feuers übergeben!\x02", "box_type": 2},
    {"id": 0x0082, "text": "\x1A\x13\x6E\x08Der \x05\x43Zora-Saphir\x05\x40!\x09\x01Von den Zoras wurde Dir\x01dieser Heilige Stein\x01des Wassers übergeben!\x02", "box_type": 2},
    {"id": 0x0083, "text": "\x08Wähle aus, indem Du \x05\x44ª \x05\x40nach\x01links oder rechts bewegst.\x01\x1B\x05\x42Mit dem Verkäufer sprechen\x01Zurück\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x0084, "text": "\x08Vielen Dank!\x09\x0A\x02", "box_type": 0},
    {"id": 0x0085, "text": "\x08Deine Rubine reichen nicht aus!\x09\x0A\x02", "box_type": 0},
    {"id": 0x0086, "text": "\x08Das kannst Du jetzt nicht kaufen.\x09\x0A\x02", "box_type": 0},
    {"id": 0x0087, "text": "\x08Deku-Nüsse   10 Stück  30 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
