    {"id": 0x0095, "text": "\x08Herz   10 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0096, "text": "\x08Tut mir leid... Du brauchst eine\x01leere Flasche, damit Du das hier\x01kaufen kannst.\x09\x0A\x02", "box_type": 0},
    {"id": 0x0097, "text": "\x13\x20\x08Du hast ein \x05\x41Irrlicht\x05\x40 in Deiner\x01Flasche gefangen!\x09\x01Dir wird Gutes widerfahren!\x02", "box_type": 2},
    {"id": 0x0098, "text": "\x13\x1A\x08Du hast\x05\x41 Milch \x05\x40erhalten!\x09\x01Diese Milch ist sehr gesund!\x01Benutze sie mit \x05\x46¡\x05\x40, um Deine\x01Energie aufzufrischen!\x04\x13\x1ADu erhältst \x05\x41fünf Herzen \x05\x40pro\x01Schluck. Du kannst zweimal\x01davon trinken.\x04\x13\x1AIm \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du sie auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren. Mit \x05\x46¡ \x05\x40nimmst Du\x01einen Schluck.\x02", "box_type": 2},
    {"id": 0x0099, "text": "\x1A\x13\x1B\x08Eine \x05\x41Flasche\x05\x40!\x09\x01Fülle etwas hinein und nutze\x01sie mit \x05\x46¡\x05\x40... Oh! Da ist ja\x01bereits etwas drin!\x02", "box_type": 2},
    {"id": 0x009A, "text": "\x1A\x13\x21\x08Ein \x05\x41seltsames Ei\x05\x40!\x09\x01Es scheint, als würde sich\x01darin etwas bewegen!\x01Warte ab, was passiert!\x04\x1A\x13\x21Im \x05\x46Gegenstands-Menü\x05\x40 kannst\x01Du es auf \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40plazieren.\x01Benutze es mit \x05\x46¡\x05\x40.\x02", "box_type": 2},
    {"id": 0x009B, "text": "\x08Pfeile   30 Stück   60 Rubine\x09\x01\x01\x1B\x05\x42Kaufen\x01Nicht kaufen\x05\x40\x02", "box_type": 0},
    {"id": 0x009C, "text": "Mein heißester Artikel ist zur Zeit\x01der \x05\x44Hylia-Schild\x05\x40. Aber für Dich ist\x01er wohl eine Nummer zu groß,\x01Kleiner!\x0B\x02", "box_type": 0},
    {"id": 0x009D, "text": "Die Zeiten sind hart, deshalb sind\x01wir von Hyrule hierher gezogen.\x01Ich würde mich freuen, wenn Du\x01bei uns Stammkunde wirst!\x0B\x02", "box_type": 0},
    {"id": 0x009E, "text": "\x08\x06\x46Willkommen!\x09\x0B\x02", "box_type": 0},
    {"id": 0x009F, "text": "\x08\x05\x41Deku-Schild   40 Rubine\x01\x05\x40Mit \x05\x44£\x05\x40 kannst Du ihn einsetzen,\x01um Angriffe abzuwehren. Bei einer\x01Feuerattacke verbrennt er!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A0, "text": "\x08\x05\x41Pfeile   10 Stück   20 Rubine\x01\x05\x40Du brauchst einen Bogen, um sie\x01abzuschießen. Du kannst sie nicht\x01kaufen, wenn Du noch keinen hast.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A1, "text": "\x08\x05\x41Deku-Stab  1 Stück  10 Rubine\x01\x05\x40Ein langer, starker Ast des\x01Deku-Baumes. Verwende ihn als\x01Waffe, bis er zerbricht!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A2, "text": "\x08\x05\x41Deku-Nüsse  10 Stück  30 Rubine\x01\x05\x40Betäube Deine Gegner damit! Du\x01kannst nur soviele kaufen, wie Du\x01zur Zeit tragen kannst.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A3, "text": "\x08\x05\x41Bomben   5 Stück   25 Rubine\x01\x05\x40Benutze sie mit \x05\x46¡\x05\x40. Du kannst\x01sie nur kaufen, wenn Du eine\x01Bombentasche besitzt.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A4, "text": "\x1A\x13\x3B\x08Das \x05\x42Kokiri-Schwert\x05\x40!\x09\x01Wähle es mit \x05\x43\x05\x40 im\x01\x05\x43Ausrüstungs-Menü\x05\x40 aus.\x04\x1A\x13\x3BDies ist eine wertvolle Waffe\x01der Kokiri. Trainiere gut,\x01bevor Du Deine Mission\x01beginnst!\x02", "box_type": 2},
    {"id": 0x00A5, "text": "\x08\x05\x41Rotes Elixier   30 Rubine\x01\x05\x40Damit füllst Du Deine Energieleiste\x01vollständig auf. Zur einmaligen\x01Anwendung!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A6, "text": "\x08\x05\x41Grünes Elixier   30 Rubine\x01\x05\x40Damit füllst Du Deine Magieleiste\x01vollständig auf. Zur einmaligen\x01Anwendung!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00A7, "text": "\x1A\x13\x01\x08Jetzt kannst Du\x01insgesamt \x05\x4630\x05\x41 Deku-Nüsse\x01\x05\x40tragen!\x09\x02", "box_type": 2},
    {"id": 0x00A8, "text": "\x1A\x13\x01\x08Jetzt kannst Du\x01insgesamt \x05\x4640\x05\x40 \x05\x41Deku-Nüsse\x01\x05\x40tragen!\x09 \x02", "box_type": 2},
    {"id": 0x00A9, "text": "\x08\x05\x41Hylia-Schild   80 Rubine\x01\x05\x40Ein großer, schwerer Schild der\x01hylianischen Ritter. Er hält sogar\x01Feuerattacken stand!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00AA, "text": "\x08\x05\x41Goronen-Rüstung   200 Rubine\x01\x05\x40Eine starke Rüstung der Goronen,\x01die nur Erwachsenen paßt.\x01Schützt auch vor großer Hitze!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00AB, "text": "\x08\x05\x41Zora-Rüstung   300 Rubine\x01\x05\x40Eine praktische Rüstung der Zoras,\x01die nur Erwachsenen paßt. Mit ihr\x01kann man unter Wasser atmen!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00AC, "text": "\x08\x05\x41Herz   10 Rubine\x01\x05\x40Damit füllst Du ein Herz\x01Deiner Energieleiste auf.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00AD, "text": "\x1A\x13\x05\x08\x05\x41Dins Feuerinferno\x05\x40!\x09\x01Dieser Feuerball entflammt die\x01Umgebung! Du setzt diese\x01Magie-Attacke mit \x05\x46¡\x05\x40 ein.\x02", "box_type": 2},
    {"id": 0x00AE, "text": "\x1A\x13\x0D\x08\x05\x42Farores Donnersturm\x05\x40!\x09\x01Ein magischer Teleporter, den\x01Du mit \x05\x46¡\x05\x40 einsetzt. Nutze\x01ihn, wenn Gefahr droht!\x04\x1A\x13\x0DMit dieser Magie legst Du\x01einen \x05\x42Teleporterpunkt\x05\x40 an.\x01Rufst Du Farores Kraft erneut an,\x01gelangst Du dorthin zurück.\x04\x1A\x13\x0DDu kannst den Teleporter\x01aber auch wieder aufheben\x01und anderswo setzen, wenn\x01Du Farores Magie beschwörst.\x02", "box_type": 2},
    {"id": 0x00AF, "text": "\x1A\x13\x13\x08\x05\x43Nayrus Umarmung\x05\x40!\x09\x01Setze diese kraftvolle,\x01magische Schutzaura\x01mit \x05\x46¡\x05\x40 ein.\x02", "box_type": 2},
    {"id": 0x00B0, "text": "\x08\x05\x41Pfeile  50 Stück  90 Rubine\x01\x05\x40Du brauchst einen Bogen, um sie\x01abzuschießen. Du kannst sie nicht\x01kaufen, wenn Du noch keinen hast.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00B1, "text": "\x08\x05\x41Bomben  10 Stück  50 Rubine\x01\x05\x40Benutze sie mit \x05\x46¡\x05\x40. Du kannst\x01sie nur kaufen, wenn Du eine\x01Bombentasche besitzt.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00B2, "text": "\x08\x05\x41Deku-Nüsse  5 Stück  15 Rubine\x01\x05\x40Betäube Deine Gegner damit! Du\x01kannst nur soviele kaufen, wie Du\x01zur Zeit tragen kannst.\x09\x0A\x02", "box_type": 0},
