    {"id": 0x00B7, "text": "\x08\x05\x41Fee   50 Rubine\x01\x05\x40Dafür brauchst Du eine leere\x01Flasche. Begib Dich nie ohne\x01Fee in ein Labyrinth!\x09\x0A\x02", "box_type": 0},
