    {"id": 0x00B9, "text": "\x08\x05\x41Blaues Feuer   300 Rubine\x01\x05\x40Dafür brauchst Du eine leere\x01Flasche. Benutze es, um Eis\x01zu schmelzen.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00BA, "text": "\x08Käfer   50 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x00BB, "text": "\x08\x05\x41Käfer    50 Rubine\x01\x05\x40Dafür brauchst Du eine leere\x01Flasche. Sieht eigentlich wie\x01ein gewöhnlicher Käfer aus...\x09\x0A\x02", "box_type": 0},
    {"id": 0x00BC, "text": "\x08\x05\x41Krabbelmine  10 Stück  100 Rubine\x01\x05\x40Das ist eine praktische Zeitbombe,\x01die Du als Distanzwaffe\x01einsetzen kannst!\x09\x0A\x02", "box_type": 0},
    {"id": 0x00BD, "text": "\x08\x05\x41Das haben wir im Augenblick\x01nicht auf Lager.\x05\x40\x09\x0A\x02", "box_type": 0},
    {"id": 0x00BE, "text": "Hey, Mann! Aus dem Alter\x01bist Du doch heraus!\x0B\x02", "box_type": 0},
    {"id": 0x00BF, "text": "\x06\x3DUaah... Waas?!\x04\x08\x06\x5AHey!\x09\x04\x08\x06\x46Ein Kunde!\x09\x0B\x02", "box_type": 0},
    {"id": 0x00C0, "text": "Zzzzzzzz...\x0B\x02", "box_type": 0},
    {"id": 0x00C1, "text": "\x08\x05\x41Pfeile   30 Stück   60 Rubine\x01\x05\x40Du brauchst einen Bogen, um sie\x01abzuschießen. Du kannst sie nicht\x01kaufen, wenn Du noch keinen hast.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00C2, "text": "\x13\x73\x08Ein \x05\x41Herzteil\x05\x40!\x09\x01Hast Du vier Teile gesammelt,\x01wird die Energieleiste um\x01einen Herzcontainer erhöht!\x02", "box_type": 2},
