    {"id": 0x00C4, "text": "\x13\x73\x08Ein \x05\x41Herzteil\x05\x40!\x09\x01Finde noch ein Herzteil, dann\x01erhöht sich die Energieleiste\x01um einen Herzcontainer!\x02", "box_type": 2},
    {"id": 0x00C5, "text": "\x13\x73\x08Ein \x05\x41Herzteil\x05\x40!\x09\x01Jetzt hast Du einen weiteren\x01Herzcontainer! Deine\x01Energieleiste erweitert sich!\x02", "box_type": 2},
    {"id": 0x00C6, "text": "\x13\x72\x08Ein \x05\x41Herzcontainer\x05\x40!\x09\x01Die Energieleiste erweitert\x01sich um ein Herz. Deine\x01Energie wird aufgefüllt!\x02", "box_type": 2},
    {"id": 0x00C7, "text": "\x13\x74\x08Der \x05\x41Master-Schlüssel\x05\x40!\x09\x01Jetzt kannst Du endlich jenen\x01Raum betreten, in dem der\x01Endgegner lauert.\x02", "box_type": 2},
    {"id": 0x00C8, "text": "Verschwinde, Deine\x01Rubine reichen nicht aus!\x0B\x02", "box_type": 0},
    {"id": 0x00C9, "text": "\x08\x06\x39Okay, das war's!\x09\x01Bitte warte draußen, damit ich das\x01nächste Spiel vorbereiten kann!\x0B\x02", "box_type": 0},
    {"id": 0x00CA, "text": "\x08Bomben   5 Stück   35 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x00CB, "text": "\x08\x05\x41Bomben   5 Stück   35 Rubine\x01\x05\x40Benutze sie mit \x05\x46¡\x05\x40. Du kannst\x01sie nur kaufen, wenn Du eine\x01Bombentasche besitzt.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00CC, "text": "\x08Du hast \x05\x435 Rubine\x05\x40 erhalten!\x09\x02", "box_type": 2},
    {"id": 0x00CD, "text": "\x1A\x13\x53\x08Die \x05\x43Silberne Schuppe\x05\x40!\x09\x01Begib Dich ins Wasser und\x01drücke \x05\x43\x05\x40. Jetzt kannst Du\x01tiefer tauchen als zuvor!\x02", "box_type": 2},
    {"id": 0x00CE, "text": "\x1A\x13\x54\x08Die \x05\x43Goldene Schuppe\x05\x40!\x09\x01Begib Dich ins Wasser und\x01drücke \x05\x43\x05\x40. Jetzt kannst Du\x01sehr tief tauchen!\x02", "box_type": 2},
    {"id": 0x00CF, "text": "\x08\x05\x44Es sieht ganz so aus, als würde\x01dieser Gegenstand hier nicht\x01benötigt...\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x00D0, "text": "\x08\x05\x44Geht nicht auf!\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x00D1, "text": "\x1A\x06\x51Du hast\x01\x06\x49\x05\x42Salias Lied\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x00D2, "text": "\x1A\x06\x51Du hast\x01\x06\x46\x05\x41Eponas Lied\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x00D3, "text": "\x1A\x06\x47Du hast die\x01\x06\x38\x05\x46Hymne der Sonne\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x00D4, "text": "\x1A\x06\x51Du hast\x01\x06\x37\x05\x43Zeldas Wiegenlied\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x00D5, "text": "\x1A\x06\x47Du hast die\x01\x06\x3D\x05\x44Hymne der Zeit\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x00D6, "text": "\x1A\x06\x47Du hast die\x01\x06\x34\x05\x45Hymne des Sturms\x01\x05\x40\x06\x50erlernt!\x02", "box_type": 2},
    {"id": 0x00D7, "text": "\x1AHallo mein süßer \x0F!\x01Ich bin die Fee der Fähigkeiten!\x04\x1AIch verleihe Dir mit meiner Macht\x01eine \x05\x42neue Schwert-Technik\x05\x40!\x04\x1ASei bereit!\x02", "box_type": 0},
    {"id": 0x00D8, "text": "\x1AHallo mein süßer \x0F!\x01Ich bin die Fee der Weisheit!\x04\x1AIch werde Deine \x05\x42magische Kraft\x05\x40\x01erhöhen!\x04\x1ASei bereit!\x02", "box_type": 0},
    {"id": 0x00D9, "text": "\x1AHallo mein süßer \x0F!\x01Ich bin die Fee des Mutes!\x04\x1AIch verstärke Deine \x05\x44Abwehrkraft\x05\x40\x01gegenüber feindlichen Attacken!\x04\x1ASei bereit!\x02", "box_type": 0},
    {"id": 0x00DA, "text": "Wenn Du vom Kampf erschöpft\x01bist, kannst Du mich jederzeit\x01wieder besuchen!\x0B\x02", "box_type": 0},
    {"id": 0x00DB, "text": "Hallo mein süßer \x0F!\x01Ich werde Deine Wunden heilen.\x0B\x02", "box_type": 0},
    {"id": 0x00DC, "text": "\x13\x58\x08\x05\x41Deku-Kerne\x05\x40!\x09\x01Es sind kleine, harte Kerne.\x01Du kannst sie als Munition\x01für Deine Schleuder einsetzen.\x02", "box_type": 2},
    {"id": 0x00DD, "text": "\x08\x1ADu beherrschst die kraftvolle\x01\x05\x41Wirbelattacke\x05\x40!\x09\x04\x1AHalte \x05\x42 \x05\x40 gedrückt, um Dein\x01Schwert aufzuladen. Laß \x05\x42 \x05\x40\x01los, um einen energiegeladenen\x01Rundumschlag auszuführen!\x04\x1ABewegst Du \x05\x44ª einmal im Kreis\x05\x40\x01und drückst dann \x05\x42 \x05\x40, kannst Du\x01die Wirbelattacke sofort und ohne\x01Wartezeit ausführen.\x02", "box_type": 2},
    {"id": 0x00DE, "text": "\x08Deku-Kerne  30 Stück  30 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x00DF, "text": "\x08\x05\x41Deku-Kerne  30 Stück  30 Rubine\x01\x05\x40Du brauchst erst eine Schleuder,\x01um sie kaufen und als Munition\x01dafür einsetzen zu können.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00E0, "text": "\x05\x44Willst Du mit Salia sprechen?\x01\x05\x40\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x00E1, "text": "\x05\x44Willst Du dann mit mir sprechen? \x01\x01\x05\x40\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x00E2, "text": "\x06\x2AHallo \x0F!\x01\x06\x37Ich bin es, \x05\x42Salia\x05\x40.\x01\x06\x3BHörst Du mich?\x0B\x02", "box_type": 2},
    {"id": 0x00E3, "text": "\x05\x44Willst Du nochmal mit ihr reden?\x05\x40\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 2},
    {"id": 0x00E4, "text": "\x1A\x08Deine \x05\x42magische Kraft\x05\x40 wurde erhöht!\x09\x02", "box_type": 2},
    {"id": 0x00E5, "text": "\x1A\x08Deine \x05\x44Abwehrkraft\x05\x40 wurde verstärkt!\x09\x02", "box_type": 2},
    {"id": 0x00E6, "text": "\x1A\x08Du hast neue \x05\x46Pfeile\x05\x40 erhalten!\x09\x02", "box_type": 2},
    {"id": 0x00E7, "text": "\x1ASammelst Du Kraft für eine\x01Wirbelattacke, verbrauchst Du\x01magische Energie. Achte also auf\x01Deine \x05\x42grüne Magieleiste\x05\x40!\x04\x1ASag mal, Du bist doch ein Bote\x01der königlichen Familie, oder?\x04\x1AWenn Du wieder dort bist, dann\x01schau in der Nähe des Schlosses\x01bei einer guten Freundin von mir\x01vorbei!\x04\x1ASie hat bestimmt auch etwas für\x01Dich, um Deine Fähigkeiten\x01zu verbessern!\x02", "box_type": 0},
    {"id": 0x00E8, "text": "\x1ADeine magischen Kräfte wurden\x01verstärkt! Du hast nun \x05\x41doppelt\x01soviel magische Energie\x05\x40!\x02", "box_type": 0},
    {"id": 0x00E9, "text": "\x1ADeine Abwehrkraft wurde\x01verstärkt! Gegnerische Angriffe\x01fügen Dir ab jetzt nur noch\x01\x05\x41halb soviel Schaden \x05\x40zu!\x02", "box_type": 0},
    {"id": 0x00EA, "text": "\x1AHallo mein süßer \x0F!\x01Ich bin die Fee der Magie!\x04\x1AIch habe einen \x05\x41mächtigen Zauber\x05\x40\x01für Dich. Bitte nimm ihn an.\x02", "box_type": 0},
    {"id": 0x00EB, "text": "\x08Tut mir leid, aber Du kannst diese\x01Maske jetzt noch nicht ausleihen.\x09\x0A\x02", "box_type": 0},
    {"id": 0x00EC, "text": "\x1A\x05\x41Dins Feuerinferno\x05\x40 kannst Du nicht\x01nur für Attacken nutzen.\x01Du kannst damit auch manches in\x01Brand setzen!\x02", "box_type": 0},
    {"id": 0x00ED, "text": "\x1AVergiß nicht: \x05\x42Farores Donnersturm\x05\x40\x01kannst Du nur in einem Labyrinth\x01einsetzen, in dem auch eine Karte\x01versteckt ist. Alles klar?\x02", "box_type": 0},
    {"id": 0x00EE, "text": "\x1A\x05\x43Nayrus Umarmung\x05\x44 \x05\x40kannst Du nur\x01für begrenzte Zeit nutzen. Wende\x01diesen Zauber also mit Bedacht an.\x02", "box_type": 0},
    {"id": 0x00EF, "text": "Bist Du vom Kampf erschöpft,\x01besuche mich einfach wieder.\x02", "box_type": 0},
    {"id": 0x00F0, "text": "\x08Du hast \x05\x4120 Rubine\x05\x40 erhalten!\x09\x02", "box_type": 2},
    {"id": 0x00F1, "text": "\x08Du hast \x05\x4550 Rubine\x05\x40 erhalten!\x09\x02", "box_type": 2},
    {"id": 0x00F2, "text": "\x08Du hast \x05\x46200 Rubine\x05\x40 erhalten!\x09\x02", "box_type": 2},
    {"id": 0x00F3, "text": "\x13\x77\x08Ein \x05\x41Schlüssel\x05\x40!\x09\x01Damit gelangst Du in den\x01nächsten Raum. Wähle dort\x01eine neue Schatzkiste aus!\x02", "box_type": 2},
    {"id": 0x00F4, "text": "\x05\x44Dumm gelaufen!\x05\x40\x04\x08Du hast \x05\x42einen Rubin\x05\x40 gefunden.\x01Vielleicht hättest Du doch besser\x01die andere Kiste geöffnet...\x09\x02", "box_type": 2},
    {"id": 0x00F5, "text": "\x05\x44Dumm gelaufen!\x05\x40\x04\x08Du hast nur\x05\x43 5 Rubine\x05\x40 gefunden.\x01Du hättest besser die Truhe\x01geöffnet, in der sich der\x01Schlüssel befindet...\x09\x02", "box_type": 2},
    {"id": 0x00F6, "text": "\x05\x44Dumm gelaufen!\x05\x40\x04\x08Du hast nur \x05\x4120 Rubine\x01\x05\x40gefunden.\x01Das ist heute wohl nicht so ganz\x01Dein Tag, oder?\x09\x02", "box_type": 2},
    {"id": 0x00F7, "text": "\x05\x41Gratuliere!\x05\x40\x04\x08Du hast\x05\x46 50 Rubine\x05\x40 gefunden.\x01Du bist ja wirklich ein Glückspilz!\x09\x02", "box_type": 2},
    {"id": 0x00F9, "text": "\x13\x1E\x08Du hast den \x05\x41Nachtschwärmer\x01\x05\x40in Deiner Flasche gefangen!\x09\x01Gehe in den \x05\x41Gespenstermarkt\x05\x40\x01und verkaufe ihn!\x02", "box_type": 2},
    {"id": 0x00FA, "text": "\x06\x53\x05\x41SUPER!\x05\x40\x04\x13\x73\x08Du hast ein \x05\x41Herzteil\x05\x40 gefunden!\x09\x01Hast Du vier Herzteile gesammelt,\x01erhöht sich Deine Energieleiste\x01um einen Herzcontainer!\x02", "box_type": 2},
    {"id": 0x00FB, "text": "\x06\x53\x05\x41SUPER!\x05\x40\x04\x13\x73\x08Du hast ein \x05\x41Herzteil\x05\x40 gefunden!\x09\x01Du besitzt jetzt zwei Herzteile.\x01Mit zwei weiteren erhältst Du\x01einen neuen Herzcontainer.\x02", "box_type": 2},
    {"id": 0x00FC, "text": "\x06\x53\x05\x41SUPER!\x05\x40\x04\x13\x73\x08Du hast ein \x05\x41Herzteil\x05\x40 gefunden!\x09\x01Du besitzt nun drei Herzteile!\x01Finde ein weiteres, und Deine\x01Energieleiste erhöht sich!\x02", "box_type": 2},
    {"id": 0x00FD, "text": "\x06\x53\x05\x41SUPER!\x05\x40\x04\x13\x73\x08Du hast ein \x05\x41Herzteil\x05\x40 gefunden!\x09\x01Jetzt besitzt Du einen weiteren\x01Herzcontainer! Die Energieleiste\x01erhöht sich um ein Herz!\x02", "box_type": 2},
    {"id": 0x00FE, "text": "Suche nach den Skulltulas nicht\x01nur im Freien, sondern auch in\x01den Labyrinthen.\x04Aber natürlich ist es nur ein\x01Wunsch von uns... Wenn Du das\x01nicht tun willst, zwingen wir\x01Dich nicht.\x07\x00\x27\x02", "box_type": 0},
    {"id": 0x0100, "text": "\x05\x44Was mag das sein?\x05\x40\x02", "box_type": 0},
    {"id": 0x0101, "text": "\x1A\x05\x44Schau doch, \x0F!\x01Wenn Du \x05\x46¥\x05\x44 drückst, dann\x01kannst Du durch das \x05\x40Netz\x01\x05\x44nach unten sehen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0102, "text": "\x1A\x05\x44Sieh Dir diese Wand an!\x01Vielleicht kannst Du ja an\x01den Pflanzen hinaufklettern?\x05\x40\x02", "box_type": 0},
    {"id": 0x0103, "text": "\x1A\x05\x44Um eine \x05\x40Tür\x05\x44 zu öffnen, stelle\x01Dich genau davor und drücke \x05\x43\x05\x44.\x05\x40\x04\x1A\x05\x44Achte auf das\x01\x05\x43blaue Aktions-Symbol\x05\x44.\x01Es befindet sich am\x01\x05\x43oberen Bildrand\x05\x44!\x05\x40\x02", "box_type": 0},
    {"id": 0x0104, "text": "\x1A\x05\x44Schau! Dort oben hängt etwas!\x01Sieht aus wie eine alte \x05\x40Leiter\x05\x44!\x05\x40\x02", "box_type": 0},
    {"id": 0x0105, "text": "\x1A\x05\x44Hey...\x01Sieht das hier nicht aus\x01wie das Symbol am \x05\x40Zeitportal\x05\x44?\x05\x40\x02", "box_type": 0},
    {"id": 0x0106, "text": "\x1A\x05\x44Sieht so aus, als habe diese\x01Fackel vor kurzem noch gebrannt...\x05\x40\x02", "box_type": 0},
    {"id": 0x0107, "text": "\x1A\x05\x44Ab hier wird es ziemlich eng!\x05\x40\x01\x05\x44Sei vorsichtig, damit Dich\x01keine miesen Typen erwischen!\x04\x05\x40\x1A\x05\x44Drücke \x05\x40¤ \x05\x44und stelle Dich gleich\x05\x40 \x01\x05\x44in die richtige Richtung.\x01So schaust Du sofort den Gang\x01hinab, wenn Du um die Ecke gehst.\x04\x05\x40\x1A\x05\x44Hast Du Dich richtig hingestellt,\x01halte \x05\x40¤\x05\x44 gedrückt und laufe\x01\x05\x40seitwärts\x05\x44 um die Ecke. So kann\x01Dir niemand auflauern!\x05\x40\x02", "box_type": 0},
    {"id": 0x0108, "text": "\x1A\x05\x44Stelle Dich vor den \x05\x40Steinblock\x01\x05\x44und halte \x05\x43 \x05\x44gedrückt.\x01So kannst Du ihn ziehen oder \x01schieben.\x04\x05\x40\x1A\x05\x44Auch zum Hinaufklettern mußt\x05\x40\x01\x05\x44Du Dich vor den Block stellen.\x05\x40\x01\x05\x44Drücke erst\x05\x40 ª \x05\x44in Richtung des\x01\x05\x40Blocks\x05\x44 und dann\x05\x40 \x05\x43\x05\x44.\x04\x05\x40\x1A\x05\x44Achte auf das\x01\x05\x43blaue Aktions-Symbol\x05\x44!\x05\x40\x02", "box_type": 0},
    {"id": 0x010C, "text": "\x1A\x05\x44Befindest Du Dich im Wasser,\x01kannst Du tauchen, indem Du\x05\x40\x01\x05\x43 \x05\x44gedrückt hältst! Wetten,\x01Du findest etwas Interessantes?\x05\x40\x02", "box_type": 0},
    {"id": 0x0114, "text": "\x1A\x05\x44Wow! Schau Dir all die\x01\x05\x40Donnerblumen \x05\x44an!\x05\x40\x04\x1A\x05\x44Meinst Du, Du kannst sie\x01alle auf einmal zünden?\x05\x40\x02", "box_type": 0},
    {"id": 0x0115, "text": "\x1A\x05\x44Sieht aus, als wären hier jede\x01Menge \x05\x40Lavagruben\x05\x44! Paß auf, wo\x01Du hintrittst!\x05\x40\x02", "box_type": 0},
    {"id": 0x0116, "text": "\x1A\x05\x44Betätige den Schalter, damit sich\x01die \x05\x40Plattform\x05\x44 hebt. So erreichst\x01Du leicht ein höheres Stockwerk!\x05\x40\x02", "box_type": 0},
    {"id": 0x0119, "text": "\x1A\x05\x44In diesen schmalen Gängen weiß\x01man nie, was sich hinter der \x01nächsten Ecke befindet...\x04\x05\x44\x1ADrücke \x05\x40¤\x05\x44, um immer in die\x01richtige Richtung zu schauen.\x01Praktisch, nicht wahr?\x05\x40\x02", "box_type": 0},
    {"id": 0x011F, "text": "\x1A\x05\x44\x0F, wohin schaust Du\x01eigentlich?\x05\x40\x02", "box_type": 0},
    {"id": 0x0124, "text": "\x1A\x05\x44Der Wüstenkoloss! Das Gesicht\x01sieht wirklich bösartig aus!\x05\x40\x02", "box_type": 0},
    {"id": 0x0126, "text": "\x1A\x05\x44Ich höre in diesem Raum\x01geisterhafte Stimmen flüstern...\x04\x05\x40\x1A\x05\x44Sie flüstern mir zu: \x05\x40\"Suche\x01nach dem Auge der Wahrheit...\"\x02", "box_type": 0},
    {"id": 0x0128, "text": "\x1A\x05\x44Ich höre die Geister in\x01diesem Raum flüstern...\x04\x05\x44Sie flüstern mir zu:\x04\x05\x40\x1A\"Jener, dessen\x01\x05\x41Schritte heilig\x05\x40 sind, möge sich vom\x01Wind treiben lassen. Er führt\x01ihn über den verborgenen Pfad.\"\x02", "box_type": 0},
    {"id": 0x0129, "text": "\x1A\x05\x44Diese Mauer...\x01Hier heißt es...\x01\x05\x40\"Gefahr von oben...\"\x02", "box_type": 0},
    {"id": 0x012A, "text": "\x1A\x05\x44Diese Mauer...\x01Hier heißt es...\x01\x05\x40\"Gefahr aus der Tiefe...\"\x02", "box_type": 0},
    {"id": 0x012B, "text": "\x1A\x05\x44Das Wasser dieser Statue\x01flutet das gesamte Stockwerk.\x05\x40\x02", "box_type": 0},
    {"id": 0x012F, "text": "\x1A\x05\x44Vorsicht, \x0F!\x01Dieses \x05\x42grüne, schleimige Ding\x05\x44 ist\x01voller elektrischer Energie!\x05\x40\x02", "box_type": 0},
    {"id": 0x0131, "text": "\x1A\x05\x44Vorsicht, \x0F!\x01Dieses \x05\x41rote, schleimige Ding\x05\x44 ist\x01voller elektrischer Energie!\x05\x40\x02", "box_type": 0},
    {"id": 0x0132, "text": "\x1A\x05\x44Vorsicht, \x0F!\x01Dieses \x05\x43blaue, schleimige Ding\x05\x44 ist\x01voller elektrischer Energie!\x05\x40\x02", "box_type": 0},
    {"id": 0x0133, "text": "\x1A\x05\x44Der \x05\x40Schalter\x05\x44...\x01Sieht so aus, als könntest Du ihn\x01nicht betätigen, da Du allein zu \x01leicht bist...\x05\x40\x02", "box_type": 0},
    {"id": 0x0137, "text": "\x1A\x05\x44Das \x05\x41rote, schleimige Ding \x05\x44ist fort!\x01Es verschwand, als Du den\x01Tentakel zerstört hast! Ob das\x01bei den anderen auch funktioniert?\x05\x40\x02", "box_type": 0},
    {"id": 0x0139, "text": "\x1A\x05\x44Hinter dieser Wand befindet sich\x01ein Schalter!\x05\x40\x02", "box_type": 0},
    {"id": 0x013A, "text": "\x1A\x05\x44Sieht so aus, als befände sich auf\x01dieser Plattform etwas!\x05\x40\x02", "box_type": 0},
    {"id": 0x013D, "text": "\x1A\x06\x49\x05\x44WAAAAS!?\x04\x05\x40\x1A\x05\x44Schau Dir all die \x05\x40Flaggen\x05\x44 an!\x01Finde heraus, welche davon\x01echt ist!\x05\x40\x02", "box_type": 0},
    {"id": 0x0140, "text": "\x05\x44Der Weg zum \x05\x40Deku-Baum \x05\x44befindet\x01sich im Osten des Dorfes!\x01Wir sollten uns beeilen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0141, "text": "\x05\x44Also los! Sei mutig!\x01Laß uns den\x01Deku-Baum betreten!\x05\x40\x02", "box_type": 0},
    {"id": 0x0142, "text": "\x05\x44Der Deku-Baum wollte, daß wir\x01die Prinzessin im \x05\x40Schloß von\x01Hyrule\x05\x44 besuchen... Sollten wir\x01uns nicht etwas beeilen?\x05\x40\x02", "box_type": 0},
    {"id": 0x0143, "text": "\x05\x44Das Mädchen von der Farm wollte,\x01daß wir ihren \x05\x40Vater\x05\x44 suchen...\x01Wo er wohl sein mag?\x05\x40\x02", "box_type": 0},
    {"id": 0x0144, "text": "\x05\x44Wie sollen wir in diesem großen\x01Schloß die \x05\x40Prinzessin\x05\x44 finden?\x05\x40\x02", "box_type": 0},
    {"id": 0x0145, "text": "\x05\x44Was \x05\x40Salia\x05\x41 \x05\x44wohl sagen würde, wenn\x01sie wüßte, daß wir Hyrule retten?\x05\x40\x02", "box_type": 0},
    {"id": 0x0146, "text": "Impa \x05\x44sagte, daß sich der\x01Heilige Stein des Feuers\x01irgendwo im \x05\x40Todesberg\x05\x44 befindet.\x05\x40\x02", "box_type": 0},
    {"id": 0x0147, "text": "\x05\x44Nimm eine \x05\x40Donnerblume\x05\x44, um in\x01Dodongos Höhle zu gelangen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0148, "text": "\x05\x44Wenn ich mich richtig erinnere,\x01sagte Darunia, daß auf dem Gipfel\x01des Todesbergs eine \x05\x40Fee\x05\x44 lebt!\x05\x40\x02", "box_type": 0},
    {"id": 0x0149, "text": "\x05\x44Ich frage mich, ob \x05\x40Salia\x05\x44 etwas\x01über den anderen Heiligen Stein\x01weiß...\x05\x40\x02", "box_type": 0},
    {"id": 0x014A, "text": "\x05\x44Es scheint, als sei \x05\x40Prinzessin\x01Ruto \x05\x44irgendwie im Bauch von\x01Lord Jabu-Jabu verschwunden!\x05\x40\x02", "box_type": 0},
    {"id": 0x014B, "text": "\x05\x44Du besitzt nun die\x01drei Heiligen Steine!\x01Laß uns nach \x05\x40Hyrule \x05\x44gehen!\x05\x40\x02", "box_type": 0},
    {"id": 0x014C, "text": "\x05\x44Die beiden auf dem weißen Pferd...\x01Das waren doch Zelda und Impa!\x01Sah aus, als hätten sie etwas in\x01den \x05\x40Wassergraben\x05\x44 geworfen!\x05\x40\x02", "box_type": 0},
    {"id": 0x014D, "text": "\x05\x44Laß uns in die\x01\x05\x40Zitadelle der Zeit\x05\x44 gehen.\x05\x40\x02", "box_type": 0},
    {"id": 0x014E, "text": "\x05\x44Sollen wir Shiek glauben und \x01nach \x05\x40Kakariko \x05\x44gehen?\x05\x40\x02", "box_type": 0},
    {"id": 0x0150, "text": "\x05\x44Ich frage mich, was in Kokiri\x01gerade passiert... Auch um \x05\x40Salia\x05\x44\x01mache ich mir Sorgen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0151, "text": "\x05\x44Diese Wolke über dem\x01\x05\x40Todesberg\x05\x44... Sie bedeutet\x01nichts Gutes...\x05\x40\x02", "box_type": 0},
    {"id": 0x0152, "text": "\x05\x44Spürst Du das? Ein eisiger Wind\x01weht vom \x05\x40Zora-Fluß \x05\x44herüber!\x05\x40\x02", "box_type": 0},
    {"id": 0x0153, "text": "\x05\x44Diese \x05\x40Eisenstiefel\x05\x44 sehen furchtbar\x01schwer aus! Wenn Du sie trägst,\x01kannst Du vielleicht am Grund des\x01Sees herumlaufen.\x05\x40\x02", "box_type": 0},
    {"id": 0x0154, "text": "\x05\x44Laß uns jemanden suchen,\x01der uns etwas über die\x01anderen \x05\x40Weisen \x05\x44erzählen\x01kann!\x05\x40\x02", "box_type": 0},
    {"id": 0x0155, "text": "\x05\x44Dieser Dämon! Er kam\x01aus dem \x05\x40Brunnen im Dorf\x05\x44!\x01Laß uns mal dorthin gehen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0156, "text": "\x05\x44Ich frage mich, wer wohl\x01den \x05\x40Geistertempel\x05\x44 gebaut\x01hat? Und aus welchem Grund?\x05\x40\x02", "box_type": 0},
    {"id": 0x0157, "text": "\x05\x44Du hast die \x05\x45Nocturne des\x01Schattens\x05\x44 von Shiek erlernt.\x01Warum spielst Du sie nicht?\x05\x40\x02", "box_type": 0},
    {"id": 0x0158, "text": "\x05\x44In der \x05\x40Wüste\x05\x44 wurde Ganondorf,\x01der Großmeister des Bösen,\x01geboren.\x01Vielleicht finden wir dort etwas...\x05\x40\x02", "box_type": 0},
    {"id": 0x015A, "text": "\x05\x44Verwende die \x05\x40Krafthandschuhe\x05\x44,\x01um Dinge anzuheben, die Du\x01zuvor nicht bewegen konntest!\x05\x40\x02", "box_type": 0},
    {"id": 0x015B, "text": "\x05\x44Jemand wartet in der Zitadelle\x01der Zeit auf uns... Ist es...\x05\x40\x02", "box_type": 0},
    {"id": 0x015C, "text": "\x05\x44Los doch! Zu Ganons\x05\x40 \x05\x44Schloß! Wir\x01müssen Prinzessin Zelda befreien!\x05\x40\x02", "box_type": 0},
    {"id": 0x015F, "text": "\x05\x44\x0F...\x01Los! Beeile Dich!\x05\x40\x02", "box_type": 0},
    {"id": 0x0160, "text": "Ich unterhalte mich gern auf\x01telepathische Weise mit Dir.\x01Doch jetzt würde ich Dich lieber\x01persönlich sprechen!\x0B\x02", "box_type": 2},
    {"id": 0x0161, "text": "Dieser Wald ist mit vielen Orten\x01verbunden. Wenn Du mein Lied\x01irgendwo hörst, muß es von dort\x01einen Weg hierher geben!\x0B\x02", "box_type": 2},
    {"id": 0x0162, "text": "Ich habe mich sehr gefreut, daß\x01Darunia mein Lied gefallen hat!\x04Noch schöner finde ich, daß es\x01Dir bei Deiner Mission geholfen\x01hat, \x0F!\x0B\x02", "box_type": 2},
    {"id": 0x0163, "text": "Sammelst Du die Heiligen Steine?\x01Du mußt noch einen finden? Den\x01\x05\x43Heiligen Stein des Wassers\x05\x40, oder?\x04Der Deku-Baum erzählte mir einst,\x01daß ihn \x05\x43König Zora\x05\x40 besitzt...\x0B\x02", "box_type": 2},
    {"id": 0x0164, "text": "Sammelst Du die Heiligen Steine?\x01Du mußt noch einen finden? Den\x01\x05\x41Heiligen Stein des Feuers\x05\x40, oder?\x04Der Deku-Baum erzählte mir einst,\x01daß ihn \x05\x41Darunia\x05\x40, der Gebieter über\x01Goronia, besitzt...\x0B\x02", "box_type": 2},
    {"id": 0x0165, "text": "\x0F...\x01Ich weiß nicht, was geschieht...\x01Ich fühle eine Bedrohung...\x04Das Schloß...\x01Dort geschieht Furchtbares!\x0B\x02", "box_type": 2},
    {"id": 0x0166, "text": "Nanu? Deine Okarina klingt...\x01irgendwie anders...\x01Du hast wohl kräftig geübt,\x01\x0F?\x0B\x02", "box_type": 2},
    {"id": 0x0167, "text": "Suchst Du nach einem Tempel?\x01Ein seltsamer Vogel erzählte\x01mir einst...\x04\"\x05\x44Augen, deren Blick die Dunkelheit\x01durchdringt, sehen weit mehr.\x05\x40\"\x01Kannst Du Dir vorstellen, was er\x01damit wohl gemeint hat?\x0B\x02", "box_type": 2},
    {"id": 0x0168, "text": "Wo bist Du, \x0F?\x01Suchst Du einen Tempel?\x01Ich hörte einst einen\x01seltsamen Vogel sagen...\x04\"\x05\x44Geh, junger Held. Besuche die\x01Wüstengöttin mit Deiner Okarina.\x05\x40\"\x01Kannst Du Dir vorstellen, was er\x01damit wohl gemeint hat?\x0B\x02", "box_type": 2},
    {"id": 0x0169, "text": "Hast Du schon alle\x01Tempel besucht?\x0B\x02", "box_type": 2},
    {"id": 0x016A, "text": "Großartig! Du hast es geschafft!\x01Ich wußte, daß ich wieder von Dir\x01hören würde!\x04Ich bin im \x05\x42Waldtempel\x05\x40!\x01Die Geister des Waldes haben um\x01Hilfe gerufen, also bin ich\x01dorthin geeilt...\x04Aber hier lauern überall bösartige\x01Kreaturen!\x01Hilf mir, \x0F!\x0B\x02", "box_type": 2},
    {"id": 0x016B, "text": "\x0F...\x01Erst wollte ich nicht zur\x01\x05\x42Weisen des Waldes\x05\x40 werden...\x04Doch nun bin ich glücklich!\x04Jetzt kann ich Dir helfen,\x01Hyrule zu retten, \x0F!\x0B\x02", "box_type": 2},
    {"id": 0x016C, "text": "Sind alle sechs \x05\x41Weisen\x05\x40 vereint,\x01können wir Ganondorf, den\x01Großmeister des Bösen,\x01ins Höllenreich verbannen.\x04Doch um ein machtvolles Siegel zu\x01erschaffen, benötigen wir die\x01Kraft des \x05\x41Siebten Weisen\x05\x40.\x04Dies ist jemand,\x01den Du kennst, \x0F...\x04Du mußt zwischen\x01Vergangenheit und Zukunft\x01hin- und herreisen, um die\x01anderen Weisen zu erwecken!\x04Sei weiterhin so mutig,\x01\x0F!\x0B\x02", "box_type": 2},
    {"id": 0x016D, "text": "Wir, die Sechs Weisen, übertragen\x01Dir all unsere Kraft!\x04Das Schicksal Hyrules liegt nun\x01in Deinen Händen!\x0B\x02", "box_type": 2},
    {"id": 0x0180, "text": "\x1A\x05\x44Ich höre eine Stimme von\x01irgendwo...\x05\x40\x04\x1A\x05\x44Sie flüstert mir zu:\x01\x01\x05\x40\x06\x11\"Sammle fünf silberne Steine...\"\x02", "box_type": 0},
    {"id": 0x0181, "text": "\x1A\x05\x44Diese Mauer... Sie teilt mir\x01etwas mit!\x05\x40\x04\x1A\x05\x44Sie flüstert mir zu:\x01\x05\x40\x06\x1AWillst Du mit einer Fähre\x01\x06\x1Ein fremde Gefilde reisen,\x01\x06\x35so tritt näher...\x02", "box_type": 0},
    {"id": 0x0183, "text": "\x1A\x05\x44Sei vorsichtig, wenn Du \x05\x40an Bord\x05\x44\x01gehst! Es sieht ganz schön alt\x01aus... Wer weiß, wann es sinkt?\x05\x40\x02", "box_type": 0},
    {"id": 0x0184, "text": "\x1A\x05\x44Hier drüben befindet sich eine \x05\x40Tür\x05\x44...\x01Gibt es irgendeinen Weg herüber?\x05\x40\x02", "box_type": 0},
    {"id": 0x0186, "text": "\x1ARotes Eis\x05\x44... Das ist\x01seltsam...\x05\x40\x02", "box_type": 0},
    {"id": 0x0189, "text": "\x1A\x05\x44Das ist \x05\x40blaues Feuer\x05\x44... Es\x01wirkt übernatürlich. Aber vielleicht\x01kannst Du es ja für irgendetwas\x01gebrauchen?\x05\x40\x02", "box_type": 0},
    {"id": 0x018C, "text": "\x1A\x05\x44Das \x05\x40Feuer der Fackeln\x05\x44 ist\x01erloschen. Es scheint, als wäre es\x01von Geistern genommen worden!\x05\x40\x02", "box_type": 0},
    {"id": 0x018D, "text": "\x1A\x05\x44Sieh doch, \x0F! Eine\x01\x05\x40Fackel\x05\x44 brennt wieder! Es liegt\x01daran, daß Du einen Geist\x01erlöst hast, oder?!\x05\x40\x02", "box_type": 0},
    {"id": 0x018F, "text": "\x1A\x05\x44Auf diesem Boden sind\x01\x05\x40Pfeile\x05\x44 aufgemalt!\x05\x40\x02", "box_type": 0},
    {"id": 0x0190, "text": "\x1A\x05\x44Dieser \x05\x40Korridor \x05\x44ist\x01völlig verdreht!\x05\x40\x02", "box_type": 0},
    {"id": 0x0191, "text": "\x1A\x05\x44Achte auf die\x01\x05\x40Schatten der Kreaturen\x05\x44,\x01die an der Decke hängen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0192, "text": "\x1A\x05\x44Hier befindet sich\x01eine \x05\x40Schatzkiste!\x02", "box_type": 0},
    {"id": 0x0194, "text": "\x1A\x05\x44Das ist die gleiche \x05\x40Fackel\x05\x44,\x01die wir auch am Eingang dieses\x01Tempels gesehen haben, oder?\x05\x40\x02", "box_type": 0},
    {"id": 0x0195, "text": "\x1A\x05\x44Die\x05\x40 Fackel\x05\x44 brennt... Das bedeutet...\x05\x40\x02", "box_type": 0},
    {"id": 0x0197, "text": "\x1A\x05\x44Dieser \x05\x40Schalter\x05\x44 ist eingefroren!\x05\x40\x02", "box_type": 0},
    {"id": 0x0198, "text": "\x1A\x05\x44\x0F, paß auf!\x01Die Decke fällt herab!\x05\x40\x02", "box_type": 0},
    {"id": 0x01A3, "text": "\x1A\x05\x44\x0F, ich kann unter\x01uns \x05\x40Stimmen von\x01Goronen\x05\x44 hören.\x05\x40\x02", "box_type": 0},
    {"id": 0x01A5, "text": "\x1A\x05\x44Schau hier herunter...\x01Ist das nicht der Raum, in dem\x01wir \x05\x40Darunia\x05\x44 getroffen haben?\x05\x40\x02", "box_type": 0},
    {"id": 0x01A7, "text": "\x1A\x05\x44Diese \x05\x40Statue\x05\x44... Haben wir sie\x01nicht schon an anderem Orte \x01gesehen?\x05\x40\x02", "box_type": 0},
    {"id": 0x01A9, "text": "\x1A\x05\x44Der\x05\x40 Schalter\x05\x44 sieht verrostet aus.\x05\x40\x02", "box_type": 0},
    {"id": 0x01AB, "text": "\x1A\x05\x44\x0F! Sei vorsichtig!\x01Laß Dich nicht von\x01den Strudeln erfassen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0200, "text": "\x06\x0FHi! Ich bin die sprechende Tür!\x02", "box_type": 0},
    {"id": 0x0201, "text": "\x06\x19\x05\x44Komisch... Diese Tür läßt sich\x01\x05\x40\x06\x41\x05\x44nicht öffnen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0202, "text": "\x06\x04\x05\x44Dicke \x05\x40Eisenstangen \x05\x44blockieren die\x01\x05\x40\x06\x21\x05\x44Tür. Finde einen Weg, sie\x01\x05\x40\x06\x31\x05\x44dennoch zu öffnen!\x05\x40\x02", "box_type": 0},
    {"id": 0x0203, "text": "\x06\x03\x05\x44Du benötigst einen \x05\x40Schlüssel,\x05\x44 um \x01\x05\x40\x06\x01\x05\x44eine solche Tür öffnen zu können!\x05\x40\x02", "box_type": 0},
    {"id": 0x0204, "text": "\x06\x27\x05\x44Hier fehlt Dir wohl ein\x05\x40\x01\x06\x2E\x05\x44spezieller\x05\x40 Schlüssel!\x02", "box_type": 0},
    {"id": 0x0205, "text": "\x08RUHE!\x09\x04Es ist erst \x1F Uhr!\x01\x05\x41Boris\x05\x40, der Totengräber,\x01schläft noch!\x04Genieße einen Spaziergang auf \x01dem Friedhof und komm \x01später wieder!\x02", "box_type": 2},
    {"id": 0x0206, "text": "Es ist jetzt \x1F Uhr!\x01Die \x05\x41Grabgrusel-Tour\x05\x40\x01ist vorüber!\x04\x05\x41Boris\x05\x40, der Totengräber,\x01schläft jetzt!\x04Unterhalte Dich mit den Geistern \x01der Toten und komm \x01später wieder!\x02", "box_type": 2},
    {"id": 0x0207, "text": "\x08\x05\x44Maskenhändler\x01\x05\x40Bitte das Schild lesen!\x09\x04\x08\x05\x41So funktioniert dieser Handel:\x01\x05\x40Die Masken werden nicht verkauft.\x01Wir \x05\x41leihen\x05\x40 sie Dir nur.\x09\x04\x08Du verkaufst die Masken.\x09\x04\x08Das so verdiente \x05\x41Geld \x05\x40gibst Du uns\x01und wir leihen Dir ein aktuelleres\x01Modell.\x09\x04\x08Du kannst auch eine bereits\x01verkaufte Maske nochmals leihen,\x01aber Du kannst sie nur einmal\x01verkaufen.\x09\x04\x08Probiere es einfach mal aus!\x01\x06\x63Der Maskenhändler\x02", "box_type": 2},
    {"id": 0x0208, "text": "Der Schattentempel...\x01Hier ruhen Hyrules blutige Zeugnisse\x01von großer Gier und\x01blindem Hass...\x0B\x02", "box_type": 2},
    {"id": 0x0209, "text": "In der Dunkelheit verborgen...\x01Das bloße Auge listig täuschend...\x01Bleibt der rechte Weg verhüllt...\x0B\x02", "box_type": 2},
    {"id": 0x020A, "text": "Jenem mit dem \x05\x41Auge der Wahrheit\x01\x05\x40wird sich manches offenbaren, was\x01noch von Dunkelheit umgeben...\x0B\x02", "box_type": 2},
    {"id": 0x020B, "text": "\x05\x44Eine seltsame Magie versperrt Dir\x01den Zugang. Löse das \x05\x40Rätsel\x05\x44\x01dieses Raumes und Du erhältst\x01Zutritt!\x05\x40\x02", "box_type": 0},
    {"id": 0x020C, "text": "\x08Der riesige Schädel...\x01Leuchten seine Augen rot,\x01öffnet sich ein neuer Weg!\x09\x02", "box_type": 2},
    {"id": 0x020D, "text": "\x06\x34\x05\x44Schatzkisten-Poker\x01\x05\x40\x06\x17Vorübergehend geschlossen! \x01\x06\x29Erst abends geöffnet!\x02", "box_type": 2},
    {"id": 0x020E, "text": "\x06\x47\x05\x44Magie-Laden\x01\x05\x40\x06\x0FBis morgen früh geschlossen!\x02", "box_type": 2},
    {"id": 0x020F, "text": "\x06\x43\x05\x44Schießbude\x01\x05\x40\x06\x23Nur tagsüber geöffnet!\x02", "box_type": 2},
    {"id": 0x0210, "text": "\x06\x3E\x05\x44Maskenhändler\x01\x05\x40\x06\x15Reisender Händler gesucht!\x01\x06\x12Bewerbungen bitte tagsüber!\x02", "box_type": 2},
    {"id": 0x0211, "text": "\x06\x51\x05\x44Basar\x01\x05\x40\x06\x20Nur tagsüber geöffnet!\x02", "box_type": 2},
    {"id": 0x0212, "text": "Hast Du Feuer?\x02", "box_type": 2},
    {"id": 0x0213, "text": "\x08Jenen mit dem \x05\x41Auge der Wahrheit\x05\x40\x01wird ein hilfsbereites Phantom\x01zum Geistertempel führen.\x09\x02", "box_type": 2},
    {"id": 0x0214, "text": "\x08Jener, der den Zugang auf dem\x01Grund des Sees öffnen will, möge\x01ein \x05\x41Schlaflied aus königlicher\x01Überlieferung \x05\x40spielen.\x09\x02", "box_type": 2},
    {"id": 0x0215, "text": "\x08Jener, der das Tor in großer\x01Höhe öffnen will, möge\x01ein \x05\x41Schlaflied aus königlicher\x01Überlieferung \x05\x40spielen.\x09\x02", "box_type": 2},
    {"id": 0x0216, "text": "Wer den \x05\x41Schlüssel\x05\x40 findet, der\x01darf den nächsten Raum betreten.\x01Wer versagt, kann gehen!\x02", "box_type": 2},
    {"id": 0x0217, "text": "Wer Audienz wünscht, der möge\x01von der Plattform aus\x01zu mir sprechen.\x0B\x02", "box_type": 0},
    {"id": 0x0218, "text": "\x1A\x12\x68\x6D\x08Hi \x0F!\x09\x01Schau zu mir herauf!\x04Mit \x05\x44¤ \x05\x40schaust Du mich an, und\x01mit \x05\x43 \x05\x40kannst Du mit mir reden.\x02", "box_type": 0},
    {"id": 0x0219, "text": "Schau mir in die Augen und wisse, \x01es ist \x05\x41\x1F \x05\x40Uhr.\x02", "box_type": 0},
    {"id": 0x021A, "text": "Erleuchte die lebenden Toten...\x02", "box_type": 2},
    {"id": 0x021B, "text": "\x05\x41Flatternde Schatten \x05\x40lauern im\x01Dunkel! Solange sie existieren,\x01versperren sie den Weg.\x02", "box_type": 2},
    {"id": 0x021C, "text": "Hey, Kleiner! Dich meine ich!\x01Schau hierher, in die Zelle!\x0B\x02", "box_type": 0},
    {"id": 0x021D, "text": "Mein Sohn ist gerade nicht\x01zuhause...\x01Vielleicht spielt er ja auf dem\x01Friedhof...\x02", "box_type": 0},
    {"id": 0x021E, "text": "Oh, mein Sohn schläft gerade.\x01Bitte komm doch später wieder,\x01wenn Du mit ihm spielen willst!\x02", "box_type": 0},
    {"id": 0x021F, "text": "\x08Wenn das Wasser den See ausfüllt,\x01ziele auf die Morgensonne.\x09\x02", "box_type": 2},
    {"id": 0x0220, "text": "\x08Wer in die Zukunft reist, der\x01möge aus der Vergangenheit\x01kommen und die \x05\x43Kraft des Silbers\x05\x40\x01tragen.\x09\x02", "box_type": 2},
    {"id": 0x0221, "text": "\x08Komme in der Vergangenheit hierher\x01mit dem reinen Herzen eines Kindes.\x09\x02", "box_type": 2},
    {"id": 0x0222, "text": "\x08Diese Tür wird zur Zeit\x01verschönert.\x09\x02", "box_type": 2},
    {"id": 0x0223, "text": "\x08Sieht aus, als hätte hier jemand\x01etwas weggenommen...\x09\x02", "box_type": 2},
    {"id": 0x0224, "text": "\x08\x06\x1BDrehe meinen Schnabel zum\x01\x06\x2C\x05\x41Schädel der Wahrheit\x05\x40.\x09\x04\x08\x06\x24Andernfalls stürzt Du in\x01\x06\x29unendliche Dunkelheit!\x09\x0B\x02", "box_type": 2},
    {"id": 0x0225, "text": "\x05\x44Das ist nicht der rechte \x05\x40Schlüssel!\x05\x44\x01Die Tür bleibt Dir verschlossen...\x05\x40\x02", "box_type": 0},
    {"id": 0x0226, "text": "\x08\x06\x3A\x05\x44Asas Hexenladen\x01\x05\x40\x06\x46Geschlossen\x09\x04\x08\x06\x28Bin auf Kräutersuche!\x01\x06\x2BKomm später wieder...\x01\x06\x26...wenn Du es wagst!\x09\x02", "box_type": 2},
    {"id": 0x0227, "text": "\x08Wer ist da? Schon wieder so ein\x01Rattengesicht, das durch die\x01Hintertür kommen will!\x09\x04\x14\x02Rattengesicht...\x14\x00\x01Ich muß Dir ein paar interessante\x01Neuigkeiten erzählen!\x04Der Chef der Zimmerleute hat\x01einen Sohn...\x01Es ist der Typ, der jeden Abend\x01beim Baum herumlungert...\x04Erzähl dem Chef bloß nicht, daß\x01ich Dir das gesagt habe!\x02", "box_type": 0},
    {"id": 0x0228, "text": "\x05\x44Schau Dir das an!\x05\x40\x02", "box_type": 0},
    {"id": 0x0229, "text": "Malon ist zu Bett gegangen!\x01Ich geh jetzt auch schlafen.\x01Komm wieder, wenn es hell ist!\x02", "box_type": 0},
    {"id": 0x022A, "text": "\x08\x05\x41Bestleistungen von \x0F!\x01\x05\x40Skulltula-Symbole: \x19\x01Größter Fang: \x1E\x02 Pfund\x09\x04\x08Bestzeit beim Marathon: \x1E\x04\x01Bestzeit beim Pferderennen: \x1E\x03\x01Bogenschießen: \x1E\x00 Punkte\x09\x02", "box_type": 2},
    {"id": 0x022B, "text": "\x08\x06\x25Hier steht die Inschrift\x01\x06\x39aus dem Wappen\x01\x06\x17der Königsfamilie von Hyrule.\x09\x02", "box_type": 2},
    {"id": 0x022C, "text": "\x08\x06\x53R.I.P.\x01\x06\x0DHier ruhen die Seelen derer, die\x01\x06\x19der Königsfamilie von Hyrule\x01\x06\x12ewige Treue geschworen haben.\x09\x04\x08\x06\x23Über ihre Seelen wachen\x01\x06\x24in Ewigkeit die Shiekah,\x01\x06\x18Beschützer der Königsfamilie\x01\x06\x28und Erbauer Kakarikos.\x09\x02", "box_type": 2},
    {"id": 0x022D, "text": "\x08\x06\x2E\x05\x43Rastloser Wasserfall\x01\x05\x40\x06\x04Diese rastlosen Wasser dienen dem\x01\x06\x1DKönig von Hyrule. Schläft er, so\x01\x06\x36rasten auch sie...\x09\x02", "box_type": 2},
    {"id": 0x022E, "text": "Unter Wasser gibt es Frösche, die\x01Dich neugierig beobachten...\x02", "box_type": 2},
    {"id": 0x022F, "text": "Du stehst auf einem weichen\x01Teppich, den nur Darunias\x01Gäste betreten dürfen...\x02", "box_type": 2},
    {"id": 0x0230, "text": "Nur wenn Du die \x05\x41Prüfungen\x05\x40 in den\x01verschiedenen Räumen bestehst,\x01wirst Du unseren streng gehüteten\x01Schatz erhalten!\x02", "box_type": 2},
    {"id": 0x0231, "text": "Bemühe Dich mit ganzer Kraft, \x01alle \x05\x41Schlüssel\x05\x40 zu erhalten, \x01damit Du Dir unseren streng\x01gehüteten Schatz verdienst!\x02", "box_type": 2},
    {"id": 0x0232, "text": "Du hast nur \x05\x41begrenzt Zeit\x05\x40, um\x01alle Gegner zu beseitigen!\x02", "box_type": 2},
    {"id": 0x0233, "text": "Sammle \x05\x41alle silbernen Steine\x05\x40 ein,\x01die Du im Wasser finden kannst!\x02", "box_type": 2},
    {"id": 0x0234, "text": "Überquere den \x05\x41feurigen\x05\x40 \x05\x41See\x05\x40!\x02", "box_type": 2},
    {"id": 0x0235, "text": "Finde den \x05\x41geheimen Durchgang\x05\x40\x01in diesem Raum!\x02", "box_type": 2},
    {"id": 0x0236, "text": "Blende die \x05\x41Augen der Statue\x05\x40!\x02", "box_type": 2},
    {"id": 0x0237, "text": "Der mit den \x05\x41Händen aus Silber\x05\x40\x01wird den großen Block verschieben\x01können!\x02", "box_type": 2},
    {"id": 0x0238, "text": "Ohne die rechten Hilfsmittel\x01wirst Du vor unlösbaren Aufgaben\x01stehen!\x02", "box_type": 2},
    {"id": 0x0239, "text": "Sammle die \x05\x41weißen Juwelen, \x05\x40jedoch\x01umgehe alle Fallen und Gefahren!\x02", "box_type": 2},
    {"id": 0x023A, "text": "\x08\x06\x46\x05\x44Fischweiher\x05\x40\x01\x06\x26Heute beißen die Fische\x01\x06\x3Awirklich gut!\x09\x02", "box_type": 1},
    {"id": 0x023B, "text": "\x06\x4D\x05\x44???\x05\x40\x02", "box_type": 0},
