    {"id": 0x0326, "text": "\x08\x06\x12Nur der, der die Augen der \x01\x06\x0EWahrheit besitzt, wird Schutz\x01\x06\x03vor den tödlichen Stacheln finden.\x09\x02", "box_type": 1},
    {"id": 0x0327, "text": "\x08\x06\x08Nur der, dessen \x05\x41Schritte heilig \x01\x05\x40\x06\x0Esind, wird das Tal des Todes\x05\x41 \x01\x05\x40\x06\x3Edurchqueren.\x09\x02", "box_type": 1},
    {"id": 0x0328, "text": "\x08Viele haben sich schon mit mir\x01gemessen. Die beste Zeit bisher:\x01\x05\x44\x1E\x06\x05\x40\x01Boris, der Totengräber\x09\x02", "box_type": 1},
    {"id": 0x0329, "text": "\x08\x06\x43\x05\x44Schießbude\x01Ein Spiel kostet 20 Rubine.\x01\x05\x40Es gibt \x05\x4110 Ziele\x05\x40. Du hast \x05\x4115\x01Versuche\x05\x40. Nutze Deine Chance!\x09\x04\x0810 Treffer: Überraschungspreis\x018-9 Treffer: Zweite Chance\x010-7 Treffer: Chance vertan\x09\x04\x08\x05\x44Dies haßt der Betreiber:\x01\x05\x40Leute, die an der Theke lehnen.\x01Leute, die andere belästigen.\x09\x02", "box_type": 1},
    {"id": 0x032A, "text": "\x08\x06\x3C\x05\x44Truhenlotterie\x05\x40\x01\x06\x0FDen Glücklichen erwartet ein \x01\x06\x31wertvoller Preis...\x09\x02", "box_type": 1},
