    {"id": 0x0335, "text": "\x08\x06\x17\x05\x44Grausige Grabgrusel-Tour!\x01\x05\x40\x06\x14Alle Touren sind \x05\x41gestrichen,\x05\x40\x01bis ein neuer Totengräber gefunden\x01\x06\x0Aist. Wir bitten um Verständnis.\x09\x02", "box_type": 1},
    {"id": 0x0336, "text": "\x08\x06\x40\x05\x45Stoßattacke\x01\x05\x40Um mit dem Schwert zuzustoßen,\x01drücke\x05\x44 ª\x05\x40 in Zielrichtung und halte \x01\x05\x44¤ \x05\x40gedrückt. Drücke dann \x05\x42 \x05\x40.\x09\x02", "box_type": 1},
    {"id": 0x0337, "text": "\x08\x06\x3F\x05\x45Enge Passagen\x01\x05\x40Versuche, durch den schmalen Spalt\x01zu kriechen!\x09\x04\x08Stelle Dich vor die Öffnung und\x01drücke den \x05\x44ª \x05\x40in Richtung Eingang. \x01Zeigt das\x05\x43 blaue Aktions-Symbol\x05\x40\x01\"Kriechen\" an, drücke\x05\x43 \x05\x40.\x09\x04\x08Achte immer auf die Anzeige des\x05\x43\x01Aktions-Symbols!\x05\x40\x09\x02", "box_type": 1},
    {"id": 0x0338, "text": "\x08\x06\x13\x05\x45Trainiere Deine Schwertkunst!\x01\x05\x40Drücke \x05\x42 \x05\x40, um Dein Schwert \x01horizontal\x05\x41 \x05\x40zu schwingen. Hältst Du\x01\x05\x44¤, \x05\x40schwingst Du es\x05\x44 \x05\x40vertikal.\x09\x02", "box_type": 1},
