    {"id": 0x0340, "text": "\x08\x06\x10\x05\x45Verändern der Blickrichtung\x01\x05\x40Du hast jederzeit die Möglichkeit,\x01Deine Blickrichtung mit \x05\x44¤ \x05\x40zu\x01verändern.\x09\x04\x08Bleib stehen und verändere dann\x01die Richtung, in die Du schaust,\x01oder \x05\x44halte ¤ \x05\x40während des\x01Laufens gedrückt.\x09\x04\x08Dies wird Dir helfen,\x01Dich zu orientieren!\x09\x04\x08\x05\x44Hältst Du ¤ gedrückt\x05\x40, kannst Du\x01Dich\x05\x41 seitlich\x05\x40 bewegen und dabei\x01nach vorn schauen.\x09\x04\x08Die \x05\x41seitliche Fortbewegung \x05\x40\x01macht sich besonders in Labyrinthen\x01bezahlt. Probier es aus! Du wirst \x01sehen, wie praktisch dies ist.\x09\x02", "box_type": 1},
    {"id": 0x0341, "text": "\x08\x06\x14\x05\x41Springe von Stein zu Stein \x01\x05\x40Du springst automatisch, sobald \x01Du auf einen Vorsprung oder einen\x01Abgrund zuläufst.\x09\x04\x08Probier es bei den Steinen aus.\x01Du wirst sehen, es macht Spaß!\x09\x02", "box_type": 1},
    {"id": 0x0342, "text": "\x08\x06\x19\x05\x41Klippenspringen verboten!\x01\x05\x40\x06\x14Es schadet der Gesundheit!\x09\x02", "box_type": 1},
    {"id": 0x0343, "text": "\x08\x06\x41\x05\x45Zielerfassung\x01\x05\x40Siehst Du einen\x05\x42 ©\x05\x40 über einem \x01Objekt, kannst Du es mit \x05\x44¤\x01\x05\x40anpeilen.\x09\x04\x08Vor dem Spiel kannst Du zwischen\x01zwei Optionen wählen:\x01Du mußt entweder \x05\x44¤\x05\x40 gedrückt\x01halten, um Dein Ziel anzupeilen...\x09\x04\x08...oder Du mußt kurz \x05\x44¤\x05\x40 drücken,\x01um Dein Ziel solange anzuvisieren,\x01bis Du erneut \x05\x44¤\x05\x40 betätigst. Danach\x01kannst Du ein neues Ziel erfassen!\x09\x04\x08Drückst Du \x05\x44¤\x05\x40 und dann \x05\x43\x05\x40,\x01kannst Du übrigens auch mit\x01Personen reden, die sich außerhalb\x01Deiner Reichweite aufhalten.\x09\x04\x08Willst Du fliehen, bewege den \x05\x44ª\x01\x05\x40einfach nach hinten.\x01Visiere zur Übung die \x05\x41Steine\x01\x05\x40hier an!\x09\x02", "box_type": 1},
    {"id": 0x0344, "text": "\x08\x06\x44\x05\x42Waldbühne\x05\x40\x09\x04\x08Wir warten darauf, daß Du uns\x01Deine häßlichste Fratze zeigst!\x01Einzigartige Preise zu gewinnen!\x09\x02", "box_type": 1},
    {"id": 0x0345, "text": "\x08\x06\x05Öffne jede Truhe! Du findest darin\x01\x06\x10wertvolle Schätze, praktische\x01\x06\x06Gegenstände, hilfreiche Schlüssel\x01\x06\x32und vieles mehr!\x09\x02", "box_type": 1},
    {"id": 0x0400, "text": "Dies ist der \x05\x41Mythen-Stein\x05\x40!\x02", "box_type": 2},
    {"id": 0x0401, "text": "Es heißt, man könne schneller\x01schwimmen, wenn man \x01\x05\x42  \x05\x40drückt...\x02", "box_type": 2},
    {"id": 0x0402, "text": "Man erzählt sich, daß nahe des \x01einsamen Baumes im Nordwesten\x01der Steppe ein Geheimnis\x01verborgen läge...\x02", "box_type": 2},
    {"id": 0x0403, "text": "Man erzählt sich, daß der Weg\x01zum Hylia-See ein Geheimnis\x01verbärge...\x02", "box_type": 2},
    {"id": 0x0404, "text": "Man erzählt sich, Biggorons \x01Schwert wäre unzerbrechlich...\x02", "box_type": 2},
    {"id": 0x0405, "text": "Man erzählt sich, daß Medigoron \x01nie über seine Größe nachgedacht \x01habe und deshalb seinen eigenen\x01Laden in Schutt und Asche legte...\x02", "box_type": 2},
    {"id": 0x0406, "text": "Man erzählt sich, daß Malon den\x01Springparcours auf der Farm wie\x01keine Zweite beherrsche...\x02", "box_type": 2},
    {"id": 0x0407, "text": "Man erzählt sich, daß Malon von \x01einem Ritter in glänzender \x01Rüstung träume, der sie auf \x01einem Roß hinfortträgt...\x02", "box_type": 2},
    {"id": 0x0408, "text": "Man erzählt sich, daß sich\x01die Zora-Prinzessin Ruto in \x01einen blonden Jüngling verliebt \x01habe...\x02", "box_type": 2},
    {"id": 0x0409, "text": "Man erzählt sich, daß die \x01Informationen des Mythen-\x01Steins nicht besonders\x01interessant wären...\x02", "box_type": 2},
    {"id": 0x040A, "text": "Man erzählt sich, daß nahe des\x01Baumes vor Kakariko ein\x01Geheimnis verborgen wäre...\x02", "box_type": 2},
    {"id": 0x040B, "text": "Man erzählt sich, daß Prinzessin \x01Zelda trotz ihres eleganten \x01Äußeren ein echter Wildfang wäre... \x02", "box_type": 2},
    {"id": 0x040C, "text": "Man erzählt sich, daß Zeldas\x01Kindermädchen eine Shiekah sei. \x01Viele dachten, dieses Geschlecht \x01wäre längst ausgestorben...\x02", "box_type": 2},
    {"id": 0x040D, "text": "Man erzählt sich, daß es in\x01Hyrule einen Mann gäbe, der\x01ständig am Rennen sei...\x02", "box_type": 2},
    {"id": 0x040E, "text": "Man erzählt sich, daß es verboten \x01wäre, die Truhen beim\x01Schatzkisten-Poker als Toiletten\x01zu mißbrauchen...\x02", "box_type": 2},
    {"id": 0x040F, "text": "Man erzählt sich, daß das Hühner- \x01mädchen oft zum Labor am See\x01ginge, um dort eine Methode zur\x01Zwerghuhnzucht zu erforschen...\x02", "box_type": 2},
    {"id": 0x0410, "text": "Man erzählt sich, daß die \x01Gerudo-Kriegerinnen sich oft nach \x01Hyrule begäben, um dort nach \x01Männern Ausschau zu halten.\x02", "box_type": 2},
    {"id": 0x0411, "text": "Man erzählt sich, die \x01Diebesprinzessin Naboru wäre\x01eine Gerudo-Kriegerin...\x02", "box_type": 2},
    {"id": 0x0412, "text": "Man erzählt sich, daß einem\x01Gutes widerführe, wenn man in\x01der Nähe eines Schmetterlings\x01einen Deku-Stab in die Luft halte.\x02", "box_type": 2},
    {"id": 0x0413, "text": "Man erzählt sich, daß man in\x01bereits bewältigten Labyrinthen\x01später neue Dinge fände...\x02", "box_type": 2},
    {"id": 0x0414, "text": "Man erzählt sich, die Gerudo-\x01Kriegerinnen würden Ganondorf \x01nahezu als Gott verehren...\x02", "box_type": 2},
    {"id": 0x0415, "text": "Man erzählt sich, daß sich am  \x01Eingang des Gerudotals ein \x01Geheimnis verbärge...\x02", "box_type": 2},
    {"id": 0x0416, "text": "Man erzählt sich, daß eine Eule\x01namens Methusa die Reinkarnation \x01eines Weisen wäre...\x02", "box_type": 2},
    {"id": 0x0417, "text": "Man erzählt sich, daß die Eule\x01zwar unheimlich aussähe, aber \x01einen sehr gutmütigen Charakter \x01habe.\x02", "box_type": 2},
    {"id": 0x0418, "text": "Man erzählt sich, Ganondorfs\x01schwarzer Hengst wäre ein Bote\x01aus der Hölle.\x02", "box_type": 2},
    {"id": 0x0419, "text": "Man erzählt sich, Ganondorf \x01strebe die Herrschaft über\x01ganz Hyrule an...\x02", "box_type": 2},
    {"id": 0x041A, "text": "Man erzählt sich, daß der Schatz,\x01den man in der Kampfarena der\x01Gerudos erringen könne, nicht\x01sehr wertvoll sei...\x02", "box_type": 2},
    {"id": 0x041B, "text": "Man erzählt sich, es gäbe Schalter,\x01die man mit der Wirbelattacke\x01des Schwertes aktivieren könne...\x02", "box_type": 2},
    {"id": 0x041C, "text": "Man erzählt sich, es wären in \x01Hyrule genau 100 goldene\x01Skulltulas verborgen...\x02", "box_type": 2},
    {"id": 0x041D, "text": "Man erzählt sich, wer die\x01Verlorenen Wälder beträte, würde\x01zu einem Waldschrat - es sei \x01denn, er wäre ein Kokiri!\x02", "box_type": 2},
    {"id": 0x041E, "text": "Man erzählt sich, daß die\x01unterirdischen Höhlen, die man an\x01verschiedenen Stellen findet, die\x01idealen Brutstätten für Käfer wären.\x02", "box_type": 2},
    {"id": 0x041F, "text": "Man erzählt sich, daß ein Kokiri \x01stets von einer Fee begleitet \x01würde...\x02", "box_type": 2},
    {"id": 0x0420, "text": "Man erzählt sich, daß etwas\x01Wundersames geschähe, wenn\x01man während des Spiels den\x01Reset-Knopf drückt...\x02", "box_type": 2},
    {"id": 0x0600, "text": "\x08\x05\x41Was ist das denn?\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0601, "text": "\x08Das ist Gohma!\x01\x05\x44Färbt sich das \x05\x40Auge\x05\x44 dieser\x01Parasiten-Kreatur rot, ist es\x01verletzbar!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0602, "text": "\x08Ein Gohma-Ei!\x01\x05\x44Wenn es aufplatzt, schlüpfen\x01bissige Gohma-Babys aus.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0603, "text": "\x08Ein Gohma-Baby!\x01\x05\x44Paß auf, daß es Dich nicht\x01anspringt!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0604, "text": "\x08Eine Skulltula!\x01\x05\x44Die weiche \x05\x40Bauchseite\x05\x44 ist ihre\x01schwache Stelle!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0605, "text": "\x08Die Riesen-Skulltula!\x01\x05\x44Die weiche \x05\x40Bauchseite\x05\x44 ist ihre\x01schwache Stelle!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0606, "text": "\x08Ein Zangengeiferer!\x01\x05\x44Triff sein verletzliches\x01\x05\x40Schwanzende\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0607, "text": "\x08Ein Dekuranha!\x01\x05\x44Zerschlage ihn, bevor er nach Dir\x01schnappt. Du erhältst eine\x01\x05\x40Deku-Nuß\x05\x44 oder einen \x05\x40Deku-Stab\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0608, "text": "\x08Ein großer Dekuranha!\x01\x05\x44Schlage zu, bevor er nach Dir\x01schnappt!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0609, "text": "\x08Ein verwelkter Dekuranha!\x01\x05\x44Er sieht zwar ganz schön alt aus,\x01aber wenn Du ihm zu nahe\x01kommst, schnappt er zu!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x060A, "text": "\x08Vorsicht, ein Laubkerl!\x01\x05\x44Näherst Du Dich, verschwindet er.\x01Lenke die Nüsse, die er spuckt,\x01mit Deinem Schild auf ihn zurück!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x060C, "text": "\x08Das ist King Dodongo!\x01\x05\x44Wirf dem Vielfraß etwas Explosives\x01in den Rachen und schlage ihn mit\x01Deinem \x05\x40Schwert\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x060D, "text": "\x08Ein Dodongo greift an!\x01\x05\x44Achte auf seinen feurigen Atem!\x01Benutze im Kampf am besten\x01die Zielerfassung mit \x05\x40¤\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x060E, "text": "\x08Ein Baby-Dodongo!\x01\x05\x44Vorsicht, er springt Dich an! Hast\x01Du ihn bezwungen, explodiert er!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x060F, "text": "\x08Ein Echsodorus! \x01\x05\x44Setze Deinen Schild geschickt ein\x01und benutze \x05\x40¤\x05\x44, um Deine\x01Schwerthiebe exakt zu plazieren!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0610, "text": "\x08Ein Dinodorus! \x01\x05\x44Setze Deinen Schild geschickt ein\x01und benutze \x05\x40¤\x05\x44, um Deine\x01Schwerthiebe exakt zu plazieren!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0611, "text": "\x08Der Feuerflatterer!\x01\x05\x44Beseitige ihn, bevor er Dich\x01erreicht! Wenn Du eine \x01Distanzwaffe hast, setze sie\x01ein!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0612, "text": "\x08Ein Flederbeißer!\x01\x05\x44Benutze \x05\x40¤\x05\x44, um ihn effektiv zu\x01treffen. Du kannst ihn auch noch\x01anvisieren, wenn er davonfliegt.\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0613, "text": "\x08Ein Armos-Ritter!\x01\x05\x44Stoppe ihn und zerstöre ihn dann!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0614, "text": "\x08Die Riesenqualle Barinade!\x01\x05\x44Benutze erst Deinen Bumerang, um\x01die Riesenqualle zu betäuben, und\x01schlage dann mit dem Schwert zu!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0615, "text": "\x08Ein Parasiten-Tentakel!\x01\x05\x44Die dünne Stelle ist der schwache\x01Punkt. Benutze eine Distanzwaffe!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0616, "text": "\x08Eine Blubberblase greift Dich an!\x01\x05\x44Diese Dinger zerplatzen wie\x01Seifenblasen!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0617, "text": "\x08Eine Zappelqualle!\x01\x05\x44Sie verteilt Stromschläge - willst\x01Du sie zerstören, benutze keinen\x01metallischen Gegenstand!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0618, "text": "\x08Eine große Zappelqualle!\x01\x05\x44Sie verteilt Stromschläge - willst\x01Du sie zerstören, benutze keinen\x01metallischen Gegenstand!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0619, "text": "\x08Ein Elektromanta!\x01\x05\x44Zerstöre ihn, bevor er Dich\x01erreicht!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061A, "text": "\x08Phantom-Ganon greift Dich an!\x01\x05\x44Das reitende Unheil des Waldtempels!\x01Ziele mit Pfeilen auf ihn, wenn er\x01aus dem Bild herauskommt!\x04\x05\x44Schlage seine magischen Feuerbälle\x01mit dem Schwert zurück und\x01attackiere ihn, wenn er am\x01Boden liegt!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061B, "text": "\x08Der Stalfos-Ritter!\x01\x05\x44Locke ihn an und schlage zu, wenn\x01sich eine gute Gelegenheit bietet!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061C, "text": "\x08Eine blaue Knochenfratze!\x01\x05\x44Wehre ihren Angriff mit Deinem\x01\x05\x40Schild\x05\x44 ab!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061D, "text": "\x08Eine bleiche Knochenfratze!\x01\x05\x44Greife sie an, wenn sie sich nicht\x01mehr bewegt!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061E, "text": "\x08Dort ist eine grüne Knochenfratze!\x01\x05\x44Greife an, sowie das grüne Feuer\x01verschwunden ist!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x061F, "text": "\x08Vorsicht, hier sind Skullwandulas!\x01\x05\x44Benutze eine Distanzwaffe, um\x01sie zu beseitigen!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0620, "text": "\x08Eine goldene Skulltula!\x01\x05\x44Diese Biester sind als \"Symbole\x01des Fluchs\" bekannt. Zerstöre sie,\x01und Du erhältst etwas!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0621, "text": "\x08Der Lavadrachoid Volvagia!\x01\x05\x44Dies ist der gefürchtete Wächter\x01des Feuertempels. Erweckt vom \x01Großmeister des Bösen!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0622, "text": "\x08Ein Flammenderwisch!\x01\x05\x44Lösche zunächst seine \x05\x40flammende\x01Rüstung\x05\x44...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0623, "text": "\x08Der Lavaschleim kriecht heran!\x01\x05\x44Wenn Du das Feuer auf seinem\x01Rücken gelöscht hast, zerstöre ihn,\x01bevor er wieder entflammt!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0624, "text": "\x08Roter Tod!\x01\x05\x44Wehre seine Angriffe mit Deinem\x01\x05\x40Schild\x05\x44 ab!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0625, "text": "\x08Das Wassertentakel Morpha!\x01\x05\x44Dieses Monster ist Wächter des\x01Wassertempels. Sein eigentlicher\x01Körper ist der rot wabernde \x05\x40Kern\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0626, "text": "\x08Der schwarze \x0F\x01\x05\x44Besiege Deine schwarze Seele!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0627, "text": "\x08Vorsicht vor der Killermuschel!\x01\x05\x44Ihr \x05\x40innenliegender Klappmuskel\x01\x05\x44scheint der empfindliche Punkt zu\x01sein. Benutze eine Distanzwaffe!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0628, "text": "\x08Der Stachelstein!\x01\x05\x44Ziele mit einer Distanzwaffe auf\x01ihn, wenn er wie ein harmloser\x01Stein aussieht!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0629, "text": "\x08Das ist Bongo Bongo!\x01\x05\x44Diese Schattenbestie ist aus den\x01Tiefen der Hölle auferstanden. \x01Nutze das \x05\x40Auge der Wahrheit\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x062A, "text": "\x08Ein Zombie!\x01\x05\x44Sein Blick paralysiert Dich. Wenn\x01er Dich anspringt, versuche durch\x01\x05\x40einen Knopfdruck\x05\x44 zu flüchten!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x062B, "text": "\x1A\x08Phantom-Ganon!\x01\x05\x44Attackiere ihn, wenn er\x05\x40 aus\x01dem Bild \x05\x44reitet! Achte auf\x01sein Trugbild!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x062D, "text": "\x08Ein Wickel-Zombie!\x01\x05\x44Sein Blick paralysiert Dich. Wenn\x01er Dich anspringt, versuche durch\x01\x05\x40einen Knopfdruck\x05\x44 zu flüchten!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x062E, "text": "\x08Die Hirnsauger-Hände!\x01\x05\x44Wenn sie Dich erwischen, versuche\x01mit \x05\x40einem Knopfdruck \x05\x44zu flüchten!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x062F, "text": "\x08Der große Hirnsauger!\x01\x05\x44Zerschlage alle seine\x01Diener, um ihn zu beseitigen!\x01Triff den Kopf!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0630, "text": "\x08Der Deckengrapscher!\x01\x05\x44Du siehst seinen \x05\x40Schatten\x05\x44 auf dem\x01Boden, bevor er angreift! Zerstöre\x01ihn, bevor er wieder entschwindet!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0631, "text": "\x08Ein bösartiger Bodengrapscher!\x01\x05\x44Sobald er sich aufteilt, zerstöre die\x01kleinen Grapscher, bevor sie sich\x01wieder vereinigen!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0632, "text": "\x08Die Killaohma Koume!\x01\x05\x44Ganondorfs höllische Ersatzmama,\x01Hexerin der Flammen! Sie scheint\x01durch \x05\x40Kälte\x05\x44 verletzbar zu sein!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0633, "text": "\x08Die Killaohma Kotake!\x01\x05\x44Ganondorfs eiskalte Ersatzmama,\x01Hexerin des Eises. Sie scheint\x01durch \x05\x40Hitze\x05\x44 verletzbar zu sein!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0634, "text": "\x08Das ist ein Eisenprinz!\x01\x05\x44Moment... Irgendwas stimmt nicht...\x01Das ist kein gewöhnlicher Gegner!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0635, "text": "\x08Der Eisenprinz!\x01\x05\x44Nimm Dich vor seiner schweren\x01Axt in acht! Schlage zu, wenn er\x01seine Deckung vernachlässigt!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0636, "text": "\x08Ein Horror-Kid!\x01\x05\x44So etwas passiert also Kids,\x01die nachts im Wald unterwegs \x01sind...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0637, "text": "\x08Der Raubschleim!\x01\x05\x44Er frißt \x05\x40Rüstungen\x05\x44 und \x05\x40Schilde\x05\x44!\x01Zerstöre ihn schnell, damit Du\x01Deine Sachen wiederbekommst!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0639, "text": "\x08Vorsicht vor Strahlzyklopen!\x01\x05\x44Achte auf den tödlichen Strahl\x01und benutze am besten eine\x01\x05\x40explosive Distanzwaffe\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x063A, "text": "\x08Der Feuerfuchs Anubis!\x01\x05\x44Dieser Gegner ist besonders\x01anfällig für \x05\x41Feuer\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x063B, "text": "\x08Ein Eisatmer!\x01\x05\x44Achte auf seinen eisigen Atem und\x01zerschlage seine eisige Hülle so\x01schnell wie möglich!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x063D, "text": "\x08Ganondorf, Großmeister des Bösen!\x01\x05\x44Ich habe keine Ahnung, wo sein\x01schwacher Punkt liegt...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x063E, "text": "\x08Ganon!\x01\x05\x44Ich habe keine Ahnung, wo sein\x01schwacher Punkt liegt...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x063F, "text": "\x08Ein Horror-Kid!\x01\x05\x44Das passiert also Kids, die\x01sich im Wald verlaufen? Könnten\x01wir uns wohl mit ihm anfreunden?\x05\x40\x02", "box_type": 2},
    {"id": 0x0640, "text": "\x08Ein Horror-Kid!\x01\x05\x44Das passiert also Kids, die sich\x01im Wald verlaufen? Sieht\x01traurig aus ohne sein Gesicht...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0641, "text": "\x08Ein Horror-Kid!\x01\x05\x44Das passiert also Kids, die sich im\x01Wald verlaufen. Sieht mit dem\x01Totenschädel ganz zufrieden aus...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0642, "text": "\x08Ein Oktorok!\x01\x05\x44Schlage die Steine, die er spuckt,\x01mit Deinem Schild zurück!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0643, "text": "\x08Ein Irrlicht auf dem Friedhof!\x01\x05\x44Starre es lange genug mit \x05\x40¤ \x05\x44an,\x01dann wird es wohl verschwinden...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0644, "text": "\x08Ein Irrlicht!\x01\x05\x44Starre es lange genug mit \x05\x40¤\x05\x44 an,\x01dann wird es wohl verschwinden...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0645, "text": "\x08Ein roter Arachno!\x01\x05\x44Erfasse ihn mit \x05\x40¤\x05\x44, wenn er\x01springt, und schlage mit dem\x01Schwert zu!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0646, "text": "\x08Ein blauer Arachno!\x01\x05\x44Im Wasser hast Du kaum eine\x01Chance, ihn zu erwischen. Locke\x01ihn an Land!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0647, "text": "\x08Widerliche Sandkiller!\x01\x05\x44Achte darauf, wo sie auftauchen\x01und weiche ihnen geschickt aus!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0648, "text": "\x08Eine riesige Killeranas!\x01\x05\x44Versuche, ihre \x05\x40Wurzel\x05\x44 zu\x01erwischen - das ist ihre\x01schwache Stelle!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0649, "text": "\x08Eine Larve der Killeranas!\x01\x05\x44Verteidige Dich mit Deinem \x05\x40Schild\x05\x44!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x064C, "text": "\x08Ein bissiger Wolfsheimer!\x01\x05\x44Laß ihn herankommen, achte auf\x01seine Bewegungen und schlage\x01ihn, wenn er unvorsichtig wird...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x064D, "text": "\x08Ein verrückter Laubkerl!\x01\x05\x44Kommst Du zu nahe, verschwindet\x01er im Laub. Setze Deine\x01Ausrüstung sinnvoll ein!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x064E, "text": "\x08Ein reicher Laubkerl!\x01\x05\x44Kommst Du zu nahe, verschwindet\x01er im Laub. Aber bist Du geschickt,\x01hat er etwas für Dich...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x064F, "text": "\x08Das ist der Geist von Boris!\x01\x05\x44Der Geist des Totengräbers!\x01Gewinnst Du den Wettlauf mit ihm,\x01hat er vielleicht ein \x05\x40Andenken\x05\x44...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0650, "text": "\x08Betti - eine der Irrlicht-Schwestern!\x01\x05\x44Wenn sie sich aufteilt, mußt Du\x01herausfinden, welche die \x05\x40Echte\x05\x44 ist!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0651, "text": "\x08Hetti - eine der Irrlicht-Schwestern!\x01\x05\x44Ziele auf sie, sobald sie erscheint!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0652, "text": "\x08Netti - eine der Irrlicht-Schwestern!\x01\x05\x44Ziele auf sie, sobald sie erscheint!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0653, "text": "\x08Etti - eine der Irrlicht-Schwestern!\x01\x05\x44Ziele auf sie, sobald sie erscheint!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0654, "text": "\x08Eine Gerudo-Kriegerin!\x01\x05\x44Attackiere sie, sowie sie ihre\x01Deckung vernachlässigt und hüte\x01Dich vor ihrer Spezialattacke!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0655, "text": "\x08Ein Knochengänger!\x01\x05\x44Laß Dir von ihm keine Angst\x01einjagen, schwinge einfach Dein\x01Schwert!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0656, "text": "\x08Ein Polarflatterer!\x01\x05\x44Zerstöre diese eiskalten Widerlinge,\x01bevor sie Dich einfrieren können!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0657, "text": "\x08Ein weißer Wolfsheimer!\x01\x05\x44Laß ihn herankommen, achte auf\x01seine Bewegungen und schlage\x01ihn, wenn er unvorsichtig wird...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0658, "text": "\x08Eine schwarze Wüstenkrähe!\x01\x05\x44Zerstöre diese krächzenden\x01Widerlinge, bevor sie auf Dich\x01einhacken können!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x0659, "text": "\x08Hier wartet ein Grozokto!\x01\x05\x44Gib ihm mit dem Bumerang eins\x01auf die Nase und attackiere sein\x01Hinterteil!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x065A, "text": "\x08Ein Nachtschwärmer!\x01\x05\x44Dieser Geist ist hartnäckig und\x01sehr schnell!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x065B, "text": "\x08Die... Killaohma?!\x01\x05\x44Die vereinigten und attraktiv\x01verjüngten Kotake und Koume!\x01Wirf die \x05\x40Magie-Attacken\x05\x44 zurück!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x065C, "text": "\x08Ein Irrlicht!\x01\x05\x44Dieses Irrlicht flüchtet nicht,\x01wenn Du versuchst, es mit \x05\x40¤\x05\x44\x01anzustarren. Ganz im Gegenteil...\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x086D, "text": "\x08\x06\x38Spiele die Melodien\x01\x06\x3Bmit \x05\x43\x05\x40 und \x05\x46¡\x05\x40.\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x086E, "text": "\x08\x06\x29Spiele mit \x05\x43\x05\x40 und \x05\x46¡\x05\x40.\x01\x06\x1BDrücke\x05\x42  \x05\x40, um zu beenden.\x01\x01\x01\x09\x10\x02", "box_type": 3},
