    {"id": 0x0874, "text": "\x08Spiele die \x05\x45Nocturne des Schattens\x05\x40.\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0875, "text": "\x08Spiele die \x05\x44Kantate des Lichts\x05\x40.\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0876, "text": "\x08Spiele geschwind \x05\x42Salias Lied\x05\x40!\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0877, "text": "\x08Okay? Hier ist \x05\x41Eponas Lied\x05\x40...\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0878, "text": "\x08Präge Dir \x05\x43Zeldas Wiegenlied\x05\x40 ein...\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x0879, "text": "\x08Spiele die \x05\x46Hymne der Sonne\x05\x40!\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x087A, "text": "\x08\x05\x44Dies Lied\x05\x40 öffnet das Zeitportal...\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x087B, "text": "\x08Nie werde ich \x05\x45dies Lied\x05\x40 vergessen!\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x087C, "text": "\x08Spiele mit \x05\x43\x05\x40 und \x05\x46¡\x05\x40;\x01\x05\x42 \x05\x40 zum Beenden.\x01\x01\x01\x09\x10\x02", "box_type": 3},
    {"id": 0x088B, "text": "\x15\x00\x20\x00\x0A\x02", "box_type": 3},
    {"id": 0x088C, "text": "\x08\x06\x13\x05\x41Hier kannst Du nicht warpen!\x05\x40\x09\x0E\x28\x02", "box_type": 0},
    {"id": 0x088D, "text": "\x08\x05\x42Zu den Verlorenen Wäldern!\x05\x40\x09\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x088E, "text": "\x08\x05\x41Zum Todeskrater!\x05\x40\x09\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x088F, "text": "\x08\x05\x43Zum Hylia-See!\x05\x40\x09\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x0890, "text": "\x08\x05\x46Zum Wüstenkoloss!\x05\x40\x09\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x0891, "text": "\x08\x05\x45Zum Friedhof!\x05\x40\x09\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x0892, "text": "\x08\x05\x44Zur Zitadelle der Zeit!\x05\x40\x09\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x0893, "text": "\x08\x05\x42Menuett des Waldes \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0894, "text": "\x08\x05\x41Bolero des Feuers \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0895, "text": "\x08\x05\x43Serenade des Wassers \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0896, "text": "\x08\x05\x46Requiem der Geister \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0897, "text": "\x08\x05\x45Nocturne des Schattens \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0898, "text": "\x08\x05\x44Kantate des Lichts \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x0899, "text": "\x08\x05\x42Salias Lied \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089A, "text": "\x08\x05\x41Eponas Lied \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089B, "text": "\x08\x05\x43Zeldas Wiegenlied\x05\x40 gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089C, "text": "\x08\x05\x46Hymne der Sonne\x05\x40 gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089D, "text": "\x08\x05\x44Hymne der Zeit \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089E, "text": "\x08\x05\x45Hymne des\x05\x40 \x05\x45Sturms \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x089F, "text": "\x08\x05\x46Vogelscheuchen-Polka \x05\x40gespielt!\x01\x01\x01\x09\x02", "box_type": 3},
    {"id": 0x1000, "text": "\x1A\x05\x44Na endlich bist Du aufgewacht.\x01Ich bin \x05\x41Navi\x05\x44!\x05\x40\x04\x1A\x05\x44Der Deku-Baum bat mich, Dich\x01ab jetzt zu \x05\x41begleiten\x05\x44.\x01Schön, Dich kennenzulernen!\x05\x40\x02", "box_type": 0},
    {"id": 0x1001, "text": "\x1A\x06\x10Guten Morgen, \x0F!\x02", "box_type": 0},
    {"id": 0x1002, "text": "\x1AHey! Eine Fee!\x04\x1AEndlich hast Du auch eine Fee,\x01\x0F!\x07\x10\x0F\x02", "box_type": 0},
    {"id": 0x1003, "text": "Ich werde hier auf Dich warten.\x01Geh nun, denn der Deku-Baum\x01hat Dich gerufen!\x02", "box_type": 0},
    {"id": 0x1004, "text": "Mit\x05\x43  \x05\x40kannst Du Dinge heben!\x04Dieser arrogante\x05\x41 Mido\x05\x40... Er will,\x01daß die Steine hier verschwinden.\x01Und jetzt soll ich für ihn die\x01Arbeit machen!\x02", "box_type": 0},
    {"id": 0x1005, "text": "\x1AOh, Du besitzt endlich eine \x05\x44Fee\x05\x40?!\x01Das ist cool, \x0F!\x04\x1AWas?\x04\x1ADer \x05\x41Deku-Baum\x05\x40 hat Dich zu sich\x01gerufen? Das ist eine große Ehre!\x04\x1AEs kommt selten vor, daß der\x01Deku-Baum jemanden zu sich ruft.\x04\x1AEr ist der Hüter der Wälder und\x01hat uns Kokiri erschaffen!\x02", "box_type": 0},
    {"id": 0x1006, "text": "Ich frage mich, ob der \x05\x41Deku-Baum \x05\x40\x01der Schöpfer allen Lebens ist...\x02", "box_type": 0},
    {"id": 0x1007, "text": "Laß uns an Deinen Kampftechniken\x01arbeiten!\x04Hältst Du \x05\x44¤\x05\x40 gedrückt und\x01läufst dabei nach rechts oder\x01links, kannst Du mit \x05\x43\x05\x40 \x05\x41Sprünge\x01zur Seite \x05\x40ausführen.\x04Hältst Du \x05\x44¤\x05\x40 gedrückt und läufst\x01rückwärts, kannst Du mit \x05\x43\x05\x40\x01einen \x05\x41Rückwärtssalto\x05\x40 ausführen.\x04Eine \x05\x41Rollattacke\x05\x40 führst Du aus,\x01indem Du \x05\x44¤\x05\x40 gedrückt hältst und\x01dann \x05\x43\x05\x40 betätigst. Während der\x01Attacke bist Du nicht verwundbar.\x04Hast Du Dein Schwert in der\x01Hand und hältst \x05\x44¤\x05\x40 gedrückt, \x01kannst Du mit \x05\x43\x05\x40 eine effektive\x01\x05\x41Sprungattacke\x05\x40 ausführen.\x04Die\x05\x44 Zielerfassung mit ¤\x05\x40\x01kannst Du an diesem \x05\x41Stein\x05\x40 \x01ausprobieren!\x02", "box_type": 0},
    {"id": 0x1008, "text": "\x1ADu hast nicht die Erlaubnis, das\x01Dorf zu verlassen!\x07\x10\x09\x02", "box_type": 0},
    {"id": 0x1009, "text": "Der Deku-Baum sprach, daß jeder\x01Kokiri, der das Dorf verläßt, \x01zum Sterben verdammt ist!\x02", "box_type": 0},
    {"id": 0x100A, "text": "\x1ADieser großmäulige\x05\x41 Mido\x05\x40!\x01Ich muß für ihn das Unkraut vor\x01Salias Haus entfernen.\x04\x1AEr hat Salia erzählt, daß ER das\x01für sie erledigen würde. Und nun\x01muß ich es tun!\x07\x10\x0B\x02", "box_type": 0},
    {"id": 0x100B, "text": "\x05\x41Salia\x05\x40 und Du, Ihr seid doch gute\x01Freunde. Hilfst Du mir bei meiner \x01Arbeit?\x04Du darfst auch alles behalten, was \x01Du findest.\x02", "box_type": 0},
    {"id": 0x100C, "text": "\x1AGut gemacht! Dies war mit Hilfe\x01Deiner \x05\x44Fee\x05\x40 möglich!\x04\x1AWie schön, daß auch Du endlich\x01eine ständige Begleiterin hast!\x04\x1AIch werde Dich lehren, ihre\x01Kräfte richtig zu nutzen!\x07\x10\x0D\x02", "box_type": 0},
    {"id": 0x100D, "text": "Fliegt Deine Fee zu einem Objekt  \x01oder einer Person, drücke \x05\x44¤\x05\x40, um \x01\x05\x41dorthin zu schauen\x05\x40.\x04Drückst Du \x05\x44¤\x05\x40 und dann \x05\x43\x05\x40,\x01kannst Du mit weiter entfernten\x01Personen sprechen.\x04Wenn Du kein Ziel erfaßt,\x01kannst Du \x05\x44¤\x05\x40 nutzen, um\x01\x05\x41geradeaus\x05\x40 \x05\x41zu schauen\x05\x40.\x01Versuch es!\x02", "box_type": 0},
    {"id": 0x100E, "text": "\x1AAh, Du besitzt endlich eine \x05\x44Fee\x05\x40!\x04\x1ANun gibt es viel zu lernen!\x07\x10\x19\x02", "box_type": 0},
    {"id": 0x100F, "text": "\x1A\x12\x68\x63Wow! \x08Das ist cool!\x09\x01Ich freue mich für Dich!\x04\x1ANun bist Du ein wahrer Kokiri,\x01\x0F!\x07\x10\x10\x02", "box_type": 0},
    {"id": 0x1010, "text": "\x1AIst es wirklich wahr? \x01Der Deku-Baum möchte, daß Du\x01zu ihm kommst?\x04\x1AEs ist eine große Ehre, vor den\x01Deku-Baum treten zu dürfen!\x07\x10\x03\x02", "box_type": 0},
    {"id": 0x1011, "text": "\x1AOh, Du verläßt uns?\x02", "box_type": 0},
    {"id": 0x1012, "text": "\x1ASicher hast Du Deine Gründe.\x01Versprich mir, daß wir immer \x01Freunde bleiben, ja?\x02", "box_type": 0},
    {"id": 0x1013, "text": "\x1AIch möchte, daß Du meine\x01Okarina an Dich nimmst.\x02", "box_type": 0},
    {"id": 0x1014, "text": "Sie bedeutet mir sehr viel...\x01Wann immer Du sie spielst, sollst\x01Du an mich denken...\x02", "box_type": 0},
    {"id": 0x1015, "text": "\x1AOh... Navi...\x01Du hast Deinen Auftrag\x01also erfüllt!\x04\x1ASei willkommen, \x0F!\x04\x1AHöre nun die Worte, die ich,\x01der\x05\x41 Deku-Baum\x05\x40, Dir zu sagen habe.\x04\x1ADie vergangenen Nächte müssen\x01für Dich ruhelos und von finsteren\x01Träumen geprägt gewesen sein.\x04\x1AIn diesen Tagen, da die Diener\x01des Bösen zu neuer Stärke\x01gelangen, werden die Auserwählten\x01von Alpträumen geplagt.\x04\x1ADies ist auch Dir widerfahren!\x04\x1A\x0F... \x01Nun ist die Zeit gekommen, da es\x01gilt, Deinen Mut zu prüfen!\x07\x10\x16\x02", "box_type": 0},
    {"id": 0x1016, "text": "Ein \x05\x41Fluch\x05\x40 lastet auf mir!\x01Deine Jugend und Kraft sollen mir\x01helfen, den Fluch zu brechen.\x04Hast Du den Mut, diese Prüfung\x01auf Dich zu nehmen?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x1017, "text": "\x1ASo sei es! Tritt ein, tapferer \x01\x0F, und auch Du, \x01Navi.\x04\x1ANavi, holde Fee...  \x01Unterstütze \x0F!\x04\x1AUnd Du \x0F, höre mit\x01\x05\x46¥\x05\x40 \x05\x44Navis\x05\x40 Worte, denn es\x01sind Worte der Weisheit.\x02", "box_type": 0},
    {"id": 0x1018, "text": "Womöglich fehlt Dir das Vertrauen \x01in Deine eigenen Fähigkeiten.\x01Kehre in den Kokiri-Wald zurück\x01und übe Deine Kampfeskunst!\x04Fühlst Du, daß Deine Zeit \x01gekommen ist, tritt mir erneut \x01gegenüber und drücke\x05\x44 ¤\x05\x40.\x02", "box_type": 0},
    {"id": 0x1019, "text": "Der beste Ort, um zu lernen,\x01Fähigkeiten richtig einzusetzen,\x01ist das \x05\x42Kokiri Trainingslager\x01\x05\x40hier auf dem Hügel.\x02", "box_type": 0},
    {"id": 0x101A, "text": "\x1A\x12\x38\x82\x08Vergebung, Herr!\x09\x01Läßt Du mich gehen, wenn ich\x01Dir ein Geheimnis anvertraue?\x04\x1A\x12\x38\x80Springst Du aus großer\x01Höhe und drückst bei der Landung\x01den \x05\x44ª \x05\x40nach vorn, rollst Du Dich\x01ab und linderst so den Aufprall.\x04\x1A\x12\x38\x80Allerdings kann ich nicht\x01wirklich garantieren, daß dies\x01bei jeder Absprunghöhe klappt...\x04\x1A\x12\x38\x80Probier es einfach aus, wenn\x01Du Mut hast!\x01\x08Ich verschwinde!\x09\x0B\x02", "box_type": 0},
    {"id": 0x101B, "text": "Hey!\x01Du da, unter der Maske. Bist Du\x01nicht der junge Kokiri?\x02", "box_type": 0},
    {"id": 0x101C, "text": "Eine coole Maske hast Du da, echt\x01groovy! Mit dem Teil würde ich\x01sicher einige Leute schocken.\x04Hey, gibst Du mir die Maske?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x101D, "text": "Blöd, ich hätte sie gerne gehabt...\x02", "box_type": 0},
    {"id": 0x101E, "text": "Cool! Ich werde sie immer tragen!\x02", "box_type": 0},
    {"id": 0x101F, "text": "\x1A\x12\x48\x07Er hat Dir nur \x05\x4110 Rubine\x05\x40 \x01für die 20 Rubine teure Maske\x01gegeben!\x01Ein schlechtes Geschäft!\x04\x1AGeh zurück zum Maskenhändler \x01und gib ihm seine \x05\x4120 Rubine\x05\x40.\x01Den Verlust mußt Du aus Deiner \x01eigenen Tasche bezahlen.\x02", "box_type": 2},
    {"id": 0x1020, "text": "Ich bin ein Zombie! Du mußt\x01schreiend davonlaufen!\x02", "box_type": 0},
    {"id": 0x1021, "text": "Du hier? Ich dachte, Du hättest \x01den Wald verlassen...\x02", "box_type": 0},
    {"id": 0x1022, "text": "Wußtest Du, daß Du Dich mit dem \x01\x05\x44ª \x05\x40abrollen kannst, wenn Du aus\x01großer Höhe herabspringst?\x01Das lindert Deinen Aufprall.\x04Ist es allerdings zu hoch, wirst\x01Du dennoch Schaden nehmen...\x02", "box_type": 0},
    {"id": 0x1023, "text": "Salia sagte, sie erwarte Dich\x01am üblichen Ort.\x02", "box_type": 0},
    {"id": 0x1024, "text": "\x1AHab Dank, \x0F!\x02", "box_type": 0},
    {"id": 0x1025, "text": "Hey, eine prächtige Feen-Schleuder\x01hast Du da...\x04Hältst Du \x05\x46¡ \x05\x40gedrückt, kannst Du\x01mit ihr zielen. Läßt Du den Knopf\x01los, schießt Du einen Deku-Kern.\x05\x46.\x05\x40\x01Bist Du ein guter Schütze?\x04Hältst Du die Schleuder in der\x01Hand und drückst \x05\x44¤\x05\x40, kannst Du\x05\x44 \x01\x05\x40sogar schießen, \x05\x41während Du Dich\x01bewegst\x05\x40.\x02", "box_type": 0},
    {"id": 0x1026, "text": "Du mußt, \x0F!\x01Mir bleibt nur wenig Zeit!\x02", "box_type": 0},
    {"id": 0x1027, "text": "\x1AHöre, was ich zu sagen habe.\x01Ein \x05\x41Diener des Bösen, der aus der \x01Wüste kam\x05\x40, hat mich verflucht!\x02", "box_type": 0},
    {"id": 0x1028, "text": "Falls Du Salia suchst: Sie ist in \x01den \x05\x42Verlorenen Wäldern\x05\x40.\x04Der Eingang? Der ist irgendwo\x01hier im Dorf!\x04Sicher wird einer wie Du sich im\x01Wald verlaufen. Da nützt Dir auch\x01Deine Fee nichts!\x04\x06\x24\x08Und jetzt verschwinde!\x09\x02", "box_type": 0},
    {"id": 0x1029, "text": "\x1ANiemals darf es dem Teufel \x01aus der Wüste gelingen, die\x01Macht des Triforce zu erringen.\x04\x1ANie darf der, der Böses in\x01seinem Herzen trägt, das \x01Heilige Reich betreten!\x04\x1ADer Dämon, der den Fluch auf \x01mich legte und mir die Kraft\x01raubte!\x04\x1AMein Ende naht, das Böse nagt\x01an meinen Wurzeln...\x04\x1AObwohl Du den Fluch gebrochen\x01hast, kommt Deine Hilfe zu spät...\x01Ich bin zum Sterben verdammt.\x04\x1AMeine Zeit ist vorüber...\x01\x1ADoch trauere nicht um mich!\x04\x1AMein Auftrag war, Dich einzuweihen \x01in die Geschehnisse um Hyrule...\x04\x1ADu bist des Landes letzte \x01Hoffnung!\x02", "box_type": 0},
    {"id": 0x102A, "text": "\x1ADie Zukunft liegt in Deinen \x01Händen, \x0F...\x01Ich weiß, Du hast die Kraft...\x04\x1ANavi...\x01Hilf \x0F, meinen letzten \x01Willen zu verwirklichen...\x04\x1A\x14\x02Ich ersuche Dich... Navi...\x14\x00\x01\x14\x03So... lebt... denn... wohl...\x14\x00\x02", "box_type": 0},
    {"id": 0x102B, "text": "\x1A\x05\x44Du hast die Worte des \x01Deku-Baumes gehört! Nur Du kannst\x01Hyrule retten! Laß uns also zum\x01Schloß aufbrechen, \x0F!\x05\x40\x02", "box_type": 0},
    {"id": 0x102C, "text": "\x1A\x14\x01\x05\x44Leb wohl... \x05\x40\x14\x00\x05\x44weiser Deku-Baum...\x05\x40\x02", "box_type": 0},
    {"id": 0x102D, "text": "Wie schade...\x02", "box_type": 0},
    {"id": 0x102E, "text": "Spielst Du mit uns?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x102F, "text": "\x1AHey Du \x05\x44feenloser Versager\x05\x40!\x01Was hast Du mit dem Deku-Baum\x01zu bereden?\x04\x1AOhne Fee bist Du nicht mal\x01ein richtiger Mann!\x07\x10\xD0\x02", "box_type": 0},
    {"id": 0x1030, "text": "Wenn Du passieren willst, solltest\x01Du wenigstens mit einem \x05\x42Schwert \x01\x05\x40und einem \x05\x44Schild \x05\x40ausgerüstet sein!\x04\x06\x51\x08Verschwinde!\x09\x02", "box_type": 0},
    {"id": 0x1031, "text": "\x06\x57\x08Was?!\x09\x04\x1A\x05\x41Mido \x05\x40läßt Dich nicht zum \x01Deku-Baum?\x07\x10\xC8\x02", "box_type": 0},
    {"id": 0x1032, "text": "Das \x05\x42Schwert\x05\x40 ist irgendwo\x01verborgen, sagt man. Es ist das\x01einzige Schwert in Kokiri! Den\x01\x05\x44Schild\x05\x40 kannst Du im Laden kaufen.\x02", "box_type": 0},
    {"id": 0x1033, "text": "\x1ABevor Du zum Deku-Baum darfst, \x01mußt Du Dich zunächst mit einem\x01\x05\x42Schwert\x05\x40 und einem \x05\x44Schild\x05\x40 \x01ausrüsten!\x07\x10\xD2\x02", "box_type": 0},
    {"id": 0x1034, "text": "Ich werde Dich niemals als einen \x01der Unseren akzeptieren!\x04Wie nur kann es sein, daß erst\x01Salia und nun auch der Deku-Baum\x01so viel Vertrauen zu Dir haben? \x01Grummel... Grummel...\x02", "box_type": 0},
    {"id": 0x1035, "text": "Ich kann Dir erklären, was die\x01Bildschirm-Symbole bedeuten.\x01\x1B\x05\x42Die gelben Symbole\x01Das blaue Symbol\x05\x40\x02", "box_type": 0},
    {"id": 0x1036, "text": "Die drei gelben Symbole am \x01rechten oberen Bildrand sind die \x01\x05\x46Gegenstands-Symbole\x05\x40.\x04Sie zeigen Dir die Gegenstände an,\x01die Du mit \x05\x46§\x05\x40,\x05\x46 ¦ \x05\x40und\x05\x46 ¨ \x01\x05\x40einsetzen kannst.\x04Hast Du einen \x05\x46¡-Gegenstand\x05\x40 \x01erhalten, begib Dich ins \x01\x05\x46Gegenstands-Menü \x05\x40und plaziere \x01ihn auf einem der \x05\x46¡-Knöpfe\x05\x40.\x02", "box_type": 0},
    {"id": 0x1037, "text": "Das blaue Symbol ist das \x05\x43Aktions-\x01Symbol\x05\x40.\x04Dieses Symbol gibt an, welche \x01Aktion Du ausführst, wenn Du\x01\x05\x43 \x05\x40betätigst.\x04An bestimmten Stellen hast Du die\x01Möglichkeit, verschiedene Aktionen\x01auszuführen.\x02", "box_type": 0},
    {"id": 0x1038, "text": "Wenn Du etwas über die \x05\x41Karte\x05\x40\x01oder die\x05\x41 Gegenstände \x05\x40erfahren\x01möchtest, kann ich Dir \x01weiterhelfen.\x04Was interessiert Dich?\x01\x1C\x05\x42Karte\x01Gegenstände\x01Zurück\x05\x40\x02", "box_type": 0},
    {"id": 0x1039, "text": "Ein \x05\x41Kartenausschnitt\x05\x40 wird am\x01rechten unteren Bildrand angezeigt.\x04Der \x05\x46gelbe Pfeil\x05\x40 zeigt Deine\x01derzeitige Position und\x01Deine Blickrichtung. Der \x05\x41rote\x01Pfeil\x05\x40 symbolisiert den Eingang.\x04Mit \x05\x44¢ \x05\x40kannst Du die Anzeige\x01ein- und ausblenden.\x04Drückst Du \x05\x41START, \x05\x40kannst Du\x01Deinen derzeitigen Aufenthaltsort\x01feststellen.\x04Neben anderen Menüs findest Du\x01hier den \x05\x41Karten-Bildschirm\x05\x40.\x04Dieser zeigt Dir eine Karte des\x01Landes Hyrule oder des Labyrinths,\x01in dem Du Dich gerade befindest.\x02", "box_type": 0},
    {"id": 0x103A, "text": "Es gibt drei Arten von Gegenständen:\x01\x05\x43Ausrüstungs-\x05\x40, \x05\x46¡-Knopf- \x05\x40und\x05\x46 \x01\x05\x44Missions-Gegenstände\x05\x40.\x04\x05\x43Ausrüstungs-Gegenstände\x05\x40 sind \x01Dinge wie Schwert, Schild oder \x01Rüstung. Wähle sie mit dem Cursor\x01aus und bestätige mit \x05\x43\x05\x40.\x04\x05\x46¡-Knopf-Gegenstände \x05\x40kannst Du \x01auf die Knöpfe \x05\x46§\x05\x40, \x05\x46¦\x05\x40 oder \x05\x46¨\x01\x05\x40legen und sie durch diese auch\x01einsetzen.\x04\x05\x44Missions-Gegenstände \x05\x40sammelst Du \x01während Deines Abenteuers. Du\x01mußt sie nicht speziell auswählen,\x01damit Du sie nutzen kannst.\x04Willst Du Deine Ausrüstung\x01verändern oder auch nur Dein \x01Inventar begutachten, drücke\x01\x05\x41START\x05\x40.\x04Mit \x05\x44¤\x05\x40 oder \x05\x44£ \x05\x40kannst Du\x05\x44\x01\x05\x40zwischen den verschiedenen\x01Menüs hin- und herwechseln.\x04Mit Cursor und \x05\x43 \x05\x40wählst Du einen \x01\x05\x43Ausrüstungs-Gegenstand\x05\x40, mit \x05\x46§,\x01¦ \x05\x40oder\x05\x46 ¨ \x05\x40wählst Du einen \x01\x05\x46¡-Knopf-Gegenstand\x05\x40.\x04Das waren eine Menge\x01Erklärungen, nicht wahr?\x02", "box_type": 0},
    {"id": 0x103B, "text": "Willst Du Deinen Spielstand \x01\x05\x42sichern\x05\x40, drücke \x05\x41START\x05\x40, um zu\x01den Menüs zu gelangen und dann\x01\x05\x42 \x05\x40, um zu sichern.\x02", "box_type": 0},
    {"id": 0x103C, "text": "Meine Schwester hat einige \x01Rubine genommen und ist zum\x01Kokiri-Laden gegangen, um\x01dort einzukaufen!\x04Apropos \x05\x41Rubine\x05\x40: Je größer Deine\x01Börse ist, desto mehr Rubine\x01kannst Du tragen...\x02", "box_type": 0},
    {"id": 0x103D, "text": "Manche Dinge in diesem Laden\x01findest Du auch im Wald. Den\x01Deku-Schild jedoch nicht! Ihn mußt\x01Du kaufen!\x04Weißt Du, wie man den \x05\x41Deku-\x01Schild \x05\x40richtig einsetzt?\x04Hast Du den Schild erhalten,\x01drücke\x05\x41 START\x05\x40, um zu den Menüs\x01zu gelangen. Begib Dich nun \x01zum \x05\x43Ausrüstungs-Menü\x05\x40.\x04Hier wählst Du mit dem Cursor \x01den Schild, mit dem Du Dich\x01ausrüsten willst, und drückst\x05\x43 \x05\x40,\x05\x43\x01\x05\x40um Deine Wahl zu bestätigen.\x04Ist der Schild gewählt, kannst Du\x01ihn mit \x05\x44£ \x05\x40einsetzen und mit \x05\x44ª\x01\x05\x40seinen Winkel verändern.\x02", "box_type": 0},
    {"id": 0x103E, "text": "Willst Du wissen, wie man \x05\x46¥ \x01\x05\x40verwendet?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x103F, "text": "Drückst Du \x05\x46¥\x05\x40, kannst Du die\x01Kameraperspektive verändern.\x04In geschlossenen Räumen wie \x01diesem wechselst Du zur Vogel-\x01perspektive, unter freiem Himmel\x01zur Ego-Perspektive.\x04Ist \x05\x46Navi\x05\x40 dort zu lesen, will Dir\x01Deine Fee etwas mitteilen.\x01Ihre Botschaft kannst Du \x01dann mit \x05\x46¥\x05\x40 abrufen.\x02", "box_type": 0},
    {"id": 0x1040, "text": "Na gut, dann finde es selbst \x01heraus!\x02", "box_type": 0},
    {"id": 0x1041, "text": "Das klingt nicht wie Salias Lied...\x02", "box_type": 0},
    {"id": 0x1042, "text": "Mido\x05\x41 \x05\x40ist sehr aufgebracht!\x01Ich frage mich, was er hat?\x02", "box_type": 0},
    {"id": 0x1043, "text": "Was?! Wo gehst Du hin?\x04Zum Schloß?\x01Wo liegt das Schloß?\x02", "box_type": 0},
    {"id": 0x1044, "text": "Kokiri, die das Dorf verlassen,\x01sind zum Sterben verdammt!\x04Du hast doch nicht etwa vor,\x01es auszuprobieren?!\x02", "box_type": 0},
    {"id": 0x1045, "text": "\x1AHey, \x0F!\x01Was hast Du getan?!\x04\x1ADer Deku-Baum...\x01Ist er... tot?\x04\x1AWie konntest Du das nur tun?! \x01Es ist alles Deine Schuld!\x0B\x02", "box_type": 0},
    {"id": 0x1046, "text": "Der Deku-Baum ist tot... Ist damit\x01auch unser Ende nah?\x02", "box_type": 0},
    {"id": 0x1047, "text": "\x1AHallo \x0F!\x07\x10\x48\x02", "box_type": 0},
    {"id": 0x1048, "text": "Wir werden doch immer Freunde\x01bleiben, oder nicht?\x02", "box_type": 0},
    {"id": 0x1049, "text": "Ist etwas mit dem Deku-Baum \x01geschehen?\x02", "box_type": 0},
    {"id": 0x104A, "text": "Mir scheint, es ist kühler\x01geworden im Wald...\x02", "box_type": 0},
    {"id": 0x104B, "text": "\x0F, hast Du vor, uns\x01zu verlassen?\x02", "box_type": 0},
    {"id": 0x104C, "text": "Kommst Du wieder, wenn Du einen\x01neuen Schild brauchst?\x02", "box_type": 0},
    {"id": 0x104D, "text": "\x12\x38\x80Meine Brüder und ich sind uns\x01einig... Du siehst genauso aus \x01wie unser Heiliger Totem!\x04\x12\x38\x80Nimm diese \x05\x41Deku-Stäbe\x05\x40 als\x01Zeichen unserer Ehrfurcht.\x01Zudem werden wir dafür sorgen,\x01daß Du nun mehr tragen kannst!\x04Hobrobbel... Kadobbel...\x04\x12\x38\x80Kazabbarobbel!\x0B\x02", "box_type": 0},
    {"id": 0x104E, "text": "Seit der Deku-Baum uns nicht \x01mehr beschützt, treiben sich\x01unheimliche Kreaturen in den\x01Wäldern herum! Ich habe Angst...\x02", "box_type": 0},
    {"id": 0x104F, "text": "\x1AEin kalter, dämonischer Wind \x01weht aus der Richtung des \x01Waldtempels.\x04\x1A\x05\x41Salia\x05\x40 ist fort. Sie sagte, sie \x01wolle etwas dagegen unternehmen!\x07\x10\x50\x02", "box_type": 0},
    {"id": 0x1050, "text": "Der \x05\x42Waldtempel \x05\x40befindet sich bei \x01der Heiligen Lichtung, tief in\x01den Verlorenen Wäldern.\x02", "box_type": 0},
    {"id": 0x1051, "text": "Salia ging zum Waldtempel und\x01kam bisher nicht zurück...\x02", "box_type": 0},
    {"id": 0x1052, "text": "Sie können mit Sicherheit keinen\x01Deku-Schild mehr benutzen, dafür\x01sind Sie zu alt!\x02", "box_type": 0},
    {"id": 0x1053, "text": "Wo Salia ist? \x01Sie kennen Salia?\x01Das ist merkwürdig...\x07\x10\x54\x02", "box_type": 0},
    {"id": 0x1054, "text": "\x05\x41Mido\x05\x40 ist seit einiger Zeit\x01verschwunden... Wo er wohl \x01steckt?\x02", "box_type": 0},
    {"id": 0x1055, "text": "Sie haben mit Sicherheit keine \x01Probleme, den Tempel zu betreten,\x01mein Herr!\x04Wurden Sie von den Kreaturen\x01belästigt? Als der Deku-Baum uns \x01noch beschützte, haben sich keine\x01Dämonen hier herumgetrieben...\x07\x10\x56\x02", "box_type": 0},
    {"id": 0x1056, "text": "Weil es draußen so gefährlich \x01ist, habe ich das Haus nicht mehr \x01verlassen. Nun langweile ich mich\x01hier zu Tode...\x02", "box_type": 0},
    {"id": 0x1057, "text": "Wenn Sie einen \x05\x41Bogen\x05\x40 besitzen, \x01können Sie im Laden \x05\x41Pfeile\x05\x40 kaufen. \x01Haben Sie einen Bogen?\x02", "box_type": 0},
    {"id": 0x1058, "text": "\x1ASie scheinen viel in der Welt\x01herumgekommen zu sein...\x01Haben Sie jemals einen Jungen \x01namens \x0F getroffen?\x04\x1AMido behauptete damals, daß \x01dieser Junge Schuld am Tod des\x01Deku-Baumes hatte...\x04\x1ANur Salia hat \x0F \x01immer verteidigt...\x07\x10\x59\x02", "box_type": 0},
    {"id": 0x1059, "text": "Vielleicht hatte Mido Unrecht...\x02", "box_type": 0},
    {"id": 0x105A, "text": "Irgendwie kommen Sie mir bekannt\x01vor, mein Herr!\x02", "box_type": 0},
    {"id": 0x105B, "text": "\x1AKennen Sie einen Jungen namens \x01\x0F?\x04\x1AEr hat den Wald verlassen und \x01kehrte nie zurück...\x07\x10\x5C\x02", "box_type": 0},
    {"id": 0x105C, "text": "Ich frage mich, ob \x0F  \x01jemals zurückkommen wird?\x02", "box_type": 0},
    {"id": 0x105D, "text": "\x1AEs muß fantastisch sein, wenn \x01man so groß ist. Ich wäre auch \x01gerne so groß!\x04\x1ADas wäre mein Traum. Dann \x01könnte ich das Unkraut mit bloßen \x01Händen beseitigen...\x07\x10\x5E\x02", "box_type": 0},
    {"id": 0x105E, "text": "Doch dummerweise altern wir \x01Kokiri nicht...\x01Das ist schade!\x02", "box_type": 0},
    {"id": 0x105F, "text": "Warum folgt Ihnen eine Fee?\x01Sie sind kein Kokiri!\x02", "box_type": 0},
    {"id": 0x1060, "text": "\x1AWer sind Sie? Mich können Sie \x01nicht täuschen, auch wenn Sie  \x01Kokiri-Kleidung tragen!\x07\x10\x61\x02", "box_type": 0},
    {"id": 0x1061, "text": "Ich habe Salia versprochen, sie\x01vor allen Gefahren zu schützen.\x02", "box_type": 0},
    {"id": 0x1062, "text": "\x1ASei gegrüßt! Ich bin der \x05\x41Sproß \x01des Deku-Baumes\x05\x40!\x04\x1AWeil Du und Salia den Fluch\x01vom Waldtempel genommen haben,\x01kann ich wachsen und sprießen!\x04\x1AHab Dank!\x02", "box_type": 0},
    {"id": 0x1063, "text": "\x1AHast Du Deine alten Freunde\x01wiedergesehen? Wahrscheinlich \x01wird Dich von ihnen niemand \x01mehr wiedererkennen...\x04\x1ADas liegt daran, daß \x05\x42Kokiri\x05\x40 niemals\x01altern. Die vergangenen Jahre \x01gingen an ihnen spurlos vorüber!\x02", "box_type": 0},
    {"id": 0x1064, "text": "\x1ASicher fragst Du Dich, warum Du\x01gealtert bist!\x04\x1ANun, Du hast es sicher schon \x01geahnt, Du bist kein Kokiri!\x01Du bist ein\x05\x44 Hylianer\x05\x40!\x04\x1AIch bin froh, Dir dieses Geheimnis\x01endlich offenbart zu haben!\x02", "box_type": 0},
    {"id": 0x1065, "text": "Vor langer Zeit fand in Hyrule\x01ein Krieg statt, der nahezu eine\x01halbe Dekade andauerte.\x0C\x5AUm diesem Krieg zu entkommen,\x01gab eine \x05\x41junge hylianische Mutter\x01\x05\x40ihr\x05\x41 Baby \x05\x40in die Obhut des Waldes.\x0C\x5AAls sich das Leben der Mutter \x01dem Ende zuneigte, vertraute sie\x01es dem \x05\x41Deku-Baum \x05\x40an...\x0C\x5ADer Deku-Baum ahnte bereits, daß\x01es sich bei dem Baby um ein Kind\x01des Schicksals handelte!\x0C\x5ADie\x05\x42 Kokiri \x05\x40zogen das Kind auf, und\x01es lebte dort bis zu jenem Tag, da\x01sich die Prophezeiung erfüllte.\x0E\x5A\x02", "box_type": 2},
    {"id": 0x1066, "text": "\x1ADu bist \x05\x44Hylianer\x05\x40. Es war immer\x01Deine Bestimmung, den Wald zu \x01verlassen.\x04\x1ADein Schicksal...\x01Nun hat es sich endlich erfüllt!\x01Du weißt, was Du zu tun hast...\x04\x1ADu mußt Hyrule vor dem Untergang \x01bewahren!\x04\x1ASo sei es, \x0F! Befreie\x01die Tempel von ihren Flüchen und\x01sorge für Frieden in Hyrule!\x02", "box_type": 0},
    {"id": 0x1067, "text": "\x1A\x06\x37Diese Melodie?!\x04\x1ASalia hat sie geschrieben! \x01Sie... Sie kennen Salia?\x04\x1ADas Lied...\x04\x1ASalia hat das Lied nur ihren \x01engsten Freunden beigebracht...\x07\x10\x6F\x02", "box_type": 0},
    {"id": 0x1068, "text": "Komisch... \x01Irgendwie erinnert er mich an\x01jemanden...\x02", "box_type": 0},
    {"id": 0x1069, "text": "\x1ADer, der von meinem Fluch gebannt,\x01im Reich zwischen Wirklichkeit und\x01Traum, kann sein leblos Gebein\x01schon jetzt begraben!\x02", "box_type": 2},
    {"id": 0x106A, "text": "\x1ADanke!\x01Dank Deiner Hilfe wurde ich in \x01den Kreis der Weisen\x01aufgenommen.\x04\x1ANun bin ich die\x01Weise des Waldtempels...\x02", "box_type": 0},
    {"id": 0x106B, "text": "\x1A\x06\x38Ich werde immer\x01\x06\x2DDeine Freundin sein...\x0E\x50\x02", "box_type": 5},
    {"id": 0x106C, "text": "\x1ADer Fluß der Zeit ist grausam...\x01Seine Geschwindigkeit scheint für\x01jede Person vorbestimmt. Niemand \x01hat die Möglichkeit, sie zu ändern...\x04\x1AEtwas, das sich nie verändern \x01wird, sind die Erinnerungen an \x01vergangene Tage. Genieße daher\x01jede Sekunde Deines Lebens...\x04\x1AMit dem \x05\x42Menuett des Waldes\x01\x05\x40kehrst Du zum Waldtempel zurück.\x02", "box_type": 0},
    {"id": 0x106D, "text": "\x1A\x0F...\x01Wir werden uns wiedersehen...\x02", "box_type": 0},
    {"id": 0x106E, "text": "Salia ist noch immer nicht zurück...\x01Doch ich weiß, eines Tages wird \x01sie wiederkommen...\x02", "box_type": 0},
    {"id": 0x106F, "text": "\x1ANun gut...\x01Ich vertraue Dir.\x07\x10\x68\x02", "box_type": 0},
    {"id": 0x1070, "text": "\x1AOh... Ich verstehe.\x04\x1ASalia wird nicht zurückkommen.\x04\x1AIch gab Salia das Versprechen, \x01daß...\x04\x1A...ich \x0F etwas mitteile,\x01falls er zurückkehrt. Salia sagte,\x01sie würde auf ihn warten...\x01Für immer...\x04\x1AIch glaube \x14\x03Salia... mochte...\x01ihn...\x14\x00\x07\x10\x71\x02", "box_type": 0},
    {"id": 0x1071, "text": "\x06\x4BFremder...\x04Falls Sie ihn irgendwo sehen,\x01lassen Sie es ihn wissen...\x07\x10\xD6\x02", "box_type": 0},
    {"id": 0x1072, "text": "Fremder, ich möchte von Ihnen \x01lernen. Können Sie mir ein paar\x01neue Kampftechniken beibringen?\x02", "box_type": 0},
    {"id": 0x1073, "text": "Ich glaube immer noch, daß ich\x01Sie irgendwoher kenne...\x02", "box_type": 0},
    {"id": 0x1074, "text": "So groß und kräftig wie Sie wäre\x01ich auch gerne. Hmmm, größer\x01werde ich bestimmt nicht. Vielleicht \x01klappt's ja mit der Kraft...\x02", "box_type": 0},
    {"id": 0x1075, "text": "\x0F...\x01Ich frage mich, ob er\x01jemals zurückkehrt...\x02", "box_type": 0},
    {"id": 0x1076, "text": "Es kommt mir so vor, als würde\x01ich Sie schon seit Jahren kennen!\x02", "box_type": 0},
    {"id": 0x1077, "text": "Nun, da der \x05\x41Sproß des Deku-Baumes\x01\x05\x40wächst und gedeiht, herrschen im\x01Wald wieder Ruhe und Frieden!\x02", "box_type": 0},
    {"id": 0x1078, "text": "Ich werde alles tun, um den Wald\x01zu beschützen!\x02", "box_type": 0},
    {"id": 0x1079, "text": "Das Klima hat sich wieder \x01verändert. Es ist nun angenehm\x01warm...\x02", "box_type": 0},
    {"id": 0x107A, "text": "Seit es im Wald wieder\x01sicher ist, glaube ich,\x01daß \x0F zurückkehren \x01wird!\x02", "box_type": 0},
    {"id": 0x107B, "text": "Ich frage mich, was aus Salia \x01geworden ist...\x02", "box_type": 0},
    {"id": 0x107C, "text": "Sicher wird \x0F eines \x01Tages zurückkommen...\x02", "box_type": 0},
    {"id": 0x107D, "text": "\x1A\x06\x2E\x05\x44Deku-Baum...\x01\x05\x40\x06\x22\x05\x44Ich bin zurückgekehrt!\x05\x40\x02", "box_type": 0},
    {"id": 0x107E, "text": "\x1ADas Böse in Menschengestalt\x01setzt seine diabolischen Kräfte\x01rücksichtslos ein, um Zugang\x01zum Heiligen Reich zu erlangen...\x04\x1AIn diesem Heiligen Reich ruht \x01das \x05\x44Triforce\x05\x40, ein mächtiges Relikt \x01der Götter, und wartet auf den,\x01der seine Kraft zu nutzen weiß...\x02", "box_type": 2},
    {"id": 0x107F, "text": "\x08Vor Tausenden von Jahren...\x09\x0E\x50\x02", "box_type": 4},
    {"id": 0x1080, "text": "\x08...stiegen drei Göttinnen aus dem\x01Chaos der Gezeiten empor...\x09\x0E\x63\x02", "box_type": 4},
    {"id": 0x1081, "text": "\x08\x06\x1ADin, die Göttin der Kraft...\x09\x0E\x3C\x02", "box_type": 4},
    {"id": 0x1082, "text": "\x08\x06\x08Nayru, die Göttin der Weisheit...\x09\x0E\x3C\x02", "box_type": 4},
    {"id": 0x1083, "text": "\x08\x06\x0CFarore, die Göttin des Mutes...\x09\x0E\x3C\x02", "box_type": 4},
    {"id": 0x1084, "text": "\x08\x06\x53Din...\x09\x0E\x1E\x02", "box_type": 4},
    {"id": 0x1085, "text": "\x08\x06\x11Mit dem feurigen Odem ihres\x01\x06\x11Körpers schuf sie unsere Welt.\x09\x0E\x63\x02", "box_type": 4},
    {"id": 0x1086, "text": "\x08\x06\x4CNayru...\x09\x0E\x1E\x02", "box_type": 4},
    {"id": 0x1087, "text": "\x08\x06\x28Sie schenkte der Welt\x01\x06\x26die Gabe der Weisheit.\x09\x0E\x63\x02", "box_type": 4},
    {"id": 0x1088, "text": "\x08\x06\x4BFarore...\x09\x0E\x1E\x02", "box_type": 4},
    {"id": 0x1089, "text": "\x08\x06\x13Sie spendete Leben und schuf\x01\x06\x38sämtliche Formen\x01\x06\x44des Daseins.\x09\x0E\x63\x02", "box_type": 4},
    {"id": 0x108A, "text": "\x08\x06\x1EAls ihr Tun vollendet war,\x01\x06\x30zogen die Göttinnen\x01\x06\x4Cgen Eden.\x09\x0E\x5A\x02", "box_type": 4},
    {"id": 0x108B, "text": "\x08\x06\x24Triforce-Symbole künden\x01\x06\x18noch heute von den Stätten,\x01\x06\x33die sie besuchten.\x09\x0E\x5A\x02", "box_type": 4},
    {"id": 0x108C, "text": "\x08\x06\x25Seither ist das Triforce\x01\x06\x46ein Zeichen\x01\x06\x24göttlicher Prophezeiung!\x09\x0E\x5A\x02", "box_type": 4},
    {"id": 0x108D, "text": "\x08\x06\x1DDas Relikt der Götter ruht\x01\x06\x2Bnun im Heiligen Reich.\x09\x0E\x63\x02", "box_type": 4},
    {"id": 0x108E, "text": "Du hast Dich tapfer geschlagen...\x01Es scheint, daß Du viel gelernt\x01hast! Jedoch...\x0C\x3CDu hast nur mein Phantom besiegt!\x01Trittst Du meinem wahren Ich\x01gegenüber, wirst Du vernichtet!\x0C\x3CIch werde die reitende Kreatur nun \x01in den Hades verbannen, denn sie\x01hat ihren Schöpfer enttäuscht!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x108F, "text": "\x1AIch habe stets gewußt, daß Du\x01zu Höherem berufen bist...\x04\x1AIch hege große Gefühle für Dich...\x0C\x1E\x1ADoch es ist Bestimmung, daß\x01wir verschiedene Wege gehen...\x04\x1ADu und ich... Wir können nicht \x01in derselben Welt leben.\x02", "box_type": 0},
    {"id": 0x1090, "text": "\x1AIch werde Dich als Weise des\x01Waldes stets unterstützen...\x04\x1ANimm dieses \x05\x42Amulett \x05\x40an Dich...\x02", "box_type": 0},
    {"id": 0x1091, "text": "\x1ADu hast Deinen Mut eindrucksvoll \x01unter Beweis gestellt.\x04\x1AIch wußte, daß Du mein Vertrauen\x01nicht enttäuschen würdest!\x02", "box_type": 0},
    {"id": 0x1092, "text": "Doch Du stehst erst am Anfang \x01Deiner Mission. Höre mich an...\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x1093, "text": "\x1A\x0F!\x01Begib Dich nun zum Schloß!\x04\x1ASuche dort die \x05\x41Prinzessin\x05\x40 auf,\x01denn sie teilt Dein Schicksal.\x04\x1ANimm \x05\x41diesen Stein\x05\x40 an Dich. Er\x01war das Begehr des Mannes, der\x01mich mit dem Fluch belegte.\x02", "box_type": 0},
    {"id": 0x1094, "text": "\x1AIch wußte, daß Du den Wald\x01eines Tages verlassen\x01würdest, \x0F.\x04\x1ADenn Du bist anders als meine\x01Freunde und ich...\x02", "box_type": 0},
    {"id": 0x1095, "text": "\x1A\x12\x68\x44\x05\x44Hallo \x08\x0F\x09!\x01Wach auf!\x05\x40\x04\x1A\x05\x44Der\x05\x41 Deku-Baum \x05\x44hat Dich zu\x05\x41 \x05\x44\x01sich gerufen!\x01\x08\x0F, wach auf!\x09\x05\x40\x02", "box_type": 0},
    {"id": 0x1096, "text": "\x1A\x12\x68\x5F\x05\x44Los! \x08Komm schon!\x09\x05\x40\x04\x1A\x05\x44Sollte die Zukunft Hyrules\x01wirklich in den Händen dieser\x01Schlafmütze liegen?\x05\x40\x02", "box_type": 0},
    {"id": 0x1097, "text": "Springen ist langweilig...\x01Ein\x05\x41 Rückwärtssalto\x05\x40 ist cooler!\x01Beherrschst Du diese Technik?\x02", "box_type": 0},
    {"id": 0x1098, "text": "\x1A\x05\x44Der\x05\x41 Deku-Baum \x05\x44hat Dich\x01zu sich befohlen...\x01Steh also endlich auf!\x05\x40\x02", "box_type": 0},
    {"id": 0x1099, "text": "\x1A\x06\x4BNavi...\x01\x06\x2ENavi, wo bist Du?\x01\x06\x39Erscheine...\x02", "box_type": 5},
    {"id": 0x109A, "text": "\x1A\x05\x44Navi, holde Fee\x05\x40...\x01Höre die Worte des \x01\x05\x41Deku-Baumes\x05\x40!\x04\x1ASpürst Du es?\x01Diabolische Kräfte bedrohen \x01unser Land.\x04\x1ADie Kreaturen der Nacht sammeln \x01sich, um das Schicksal Hyrules \x01zu besiegeln.\x04\x1AFür lange Zeit war ich es, der\x01die Schatten des Unheils daran\x01hinderte, das Land zu erobern.\x04\x1ADoch nun ist die Konzentration\x01des Bösen so stark, daß meine  \x01Kräfte nicht ausreichen, die \x01dunklen Mächte zu bannen...\x04\x1ADie Zeit scheint reif, da der \x01\x05\x41Junge ohne Fee \x05\x40seine Bestimmung \x01erfahren soll...\x04\x1ADie Jugend und Reinheit des\x01Jungen sollen Hyrule wieder auf\x01den Pfad des Lichtes führen...\x04\x1A\x05\x44Navi\x05\x40... Geh nun! Finde unseren\x01Freund und geleite ihn zu mir...\x04\x1AMeine Zeit ist fast vorüber...\x01Mir bleiben nur noch wenige\x01Stunden.\x04\x1AFlieg, Navi, flieg! Das Schicksal \x01des Dorfes, gar das der ganzen \x01Welt, liegt in den Händen dieses \x01Jungen...\x02", "box_type": 0},
    {"id": 0x109B, "text": "\x1A\x12\x38\x82Vergib mir, Herr! Ich werde \x01es nicht wieder tun! Laß mich frei,\x01und ich gebe ein Geheimnis preis.\x04\x1A\x12\x38\x80Nie wirst Du meine Brüder \x01bezwingen, wenn Du sie nicht in \x01richtiger Reihenfolge besiegst!\x04\x1A\x12\x38\x80Merke Dir... \x14\x05\x05\x442  3  1\x05\x40\x14\x00\x01\x1A\x12\x38\x80\x08\x05\x44Rechts vor links, aber\x01die goldene Mitte geht vor!\x05\x40\x09\x01Bin ich jetzt ein Verräter?\x0B\x02", "box_type": 0},
    {"id": 0x109C, "text": "\x1A\x12\x38\x82Woher kanntest Du unser Geheimnis?!\x01Bist Du ein \x08Hellseher?\x09\x04\x1A\x12\x38\x80So sei es denn. Ich werde\x01Dir das Geheimnis der Spinnenkönigin\x01verraten...\x04\x1A\x12\x38\x80Um sie zu vernichten, solltest Du\x01die Früchte des Baumes nutzen... \x01Ein Gegner, der sich \x05\x41nicht bewegt\x05\x40, \x01läßt sich leichter bezwingen...\x04\x1AVergebt mir, Königin...\x04\x12\x38\x80\x08Schande über mich!\x09\x0B\x02", "box_type": 0},
    {"id": 0x109D, "text": "Es war einst in einem fernen Land...\x0C\x28\x06\x0ASeit Anbeginn der Zeit wacht der\x01\x06\x18mächtige Deku-Baum über die\x01\x06\x30Kinder des Waldes!\x0E\x46\x02", "box_type": 4},
    {"id": 0x109E, "text": "\x06\x21Jedem der Kokiri schenkt\x01\x06\x29der Wächter eine Fee.\x0C\x3C\x06\x0DAls seine Abgesandten schützen\x01\x06\x22sie jene reinen Herzens.\x0E\x3C\x02", "box_type": 4},
    {"id": 0x109F, "text": "\x06\x11Das Schicksal hat jedoch einen\x01\x06\x08auserkoren, dessen Bestimmung es\x01\x06\x11ist, den Gesetzen vergangener\x01\x06\x2BZeiten zu entfliehen...\x0E\x3C\x02", "box_type": 4},
    {"id": 0x10A0, "text": "\x12\x38\x82Vergib mir... Darf ich Dir Deku-  \x01Nüsse anbieten?\x01\x05\x415 Stück   \x05\x40kosten\x05\x41  20 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10A1, "text": "\x12\x38\x82Du hast gesiegt. Laß mich Dir einen\x01Deku-Stab anbieten!\x01\x05\x411 Stück   \x05\x40kostet\x05\x41  15 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10A2, "text": "\x12\x38\x82Ich bin bezwungen. Verschone mich,\x01und ich werde Dir ein Herzteil zum \x01Kauf anbieten!\x01\x05\x411 Stück   \x05\x40kostet\x05\x41  10 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10A3, "text": "\x12\x38\x80\x08Laß uns ein Geschäft machen!\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x10A4, "text": "\x12\x38\x82\x08Ups!\x09\x01Dann verschwinde ich besser!\x02", "box_type": 0},
    {"id": 0x10A5, "text": "\x12\x38\x82Du hast zu wenig Rubine! \x01Komm später wieder!\x02", "box_type": 0},
    {"id": 0x10A6, "text": "\x12\x38\x82Du hast schon genug davon!\x01Komm später wieder!\x02", "box_type": 0},
    {"id": 0x10A7, "text": "\x12\x38\x80\x08\x06\x43Hab Dank!\x09\x0B\x02", "box_type": 0},
    {"id": 0x10A8, "text": "\x1AIch habe auf Dich gewartet,\x01\x0F!\x04\x1ADies ist die \x05\x41Heilige Lichtung\x05\x40,\x01mein Lieblingsort!\x01Ich spüre etwas...\x04\x1ADieser Ort wird für uns beide \x01von schicksalhafter Bedeutung sein.\x01Das kann ich fühlen...\x04\x1ASpielst Du hier die Okarina, \x01kannst Du zu den Geistern des \x01Waldes sprechen.\x07\x10\xA9\x02", "box_type": 0},
    {"id": 0x10A9, "text": "Machst Du mir die Freude und \x01spielst mit mir?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x10AA, "text": "\x1AVersuch, die Melodie, die ich\x01spiele, nachzuspielen...\x01Bist Du bereit?\x02", "box_type": 0},
    {"id": 0x10AB, "text": "\x1AWas?!\x01Du enttäuschst mich!\x01Komm schon, spiel mir nach!\x02", "box_type": 0},
    {"id": 0x10AC, "text": "\x1A\x12\x68\x63\x06\x2FWie wunderschön!\x04\x1ADu darfst dieses Lied nie \x01vergessen. Versprich es!\x07\x10\xAD\x02", "box_type": 0},
    {"id": 0x10AD, "text": "Willst Du meine Stimme hören, so \x01spiele \x05\x42Salias Lied\x05\x40. Du kannst \x01Dich jederzeit mit mir \x01unterhalten...\x02", "box_type": 0},
    {"id": 0x10AE, "text": "Paß gut auf meine Okarina \x01auf...\x02", "box_type": 0},
    {"id": 0x10AF, "text": "\x1A\x12\x38\x80Fantastisch!\x01Du hast dreimal ins Schwarze\x01getroffen!\x04\x1A\x12\x38\x80Dein Talent soll nicht ohne Lohn\x01bleiben! Hier, nimm dies an Dich!\x0B\x02", "box_type": 0},
    {"id": 0x10B0, "text": "Vielleicht weiß Mido, wo sich Salia\x01aufhält...\x04Er hat sich beleidigt in eines der \x01Häuser zurückgezogen.\x02", "box_type": 0},
    {"id": 0x10B1, "text": "\x06\x5A\x05\x44Hallo?\x01\x05\x40\x06\x35\x05\x44Er reagiert nicht!\x01\x05\x40\x06\x23\x05\x44Er scheint zu schlafen...\x05\x40\x02", "box_type": 0},
    {"id": 0x10B2, "text": "\x1AHenni?  Was?!\x01Ich dachte, nur ein netter Mensch\x01wie ich kann Dich zähmen...\x04\x1ADas bedeutet...\x04\x1A\x14\x01Du... \x14\x00Du mußt in Ordnung sein!\x01\x08Ja, ganz bestimmt!\x09\x01\x08Ich vertraue Dir!\x09\x01Tust Du mir einen Gefallen?\x04\x1ABring dies hier zum \x05\x41Laden der \x01Hexe Asa\x05\x40 in Kakariko!\x0B\x02", "box_type": 0},
    {"id": 0x10B3, "text": "Doch laß Dir nicht zuviel Zeit,\x01denn sonst löst es sich auf!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x10B4, "text": "Ach... \x08Na sowas...\x09\x01Du scheinst doch nicht so nett zu \x01sein, wie ich dachte!\x01\x08Du enttäuschst mich!\x09\x02", "box_type": 0},
    {"id": 0x10B5, "text": "Salia hat nach Dir gesucht...\x01Hat sie Dich schon gefunden?\x02", "box_type": 0},
    {"id": 0x10B6, "text": "Beeil Dich, mein Freund!\x01Bevor es sich auflöst, muß es bei\x01der Hexe sein...\x02", "box_type": 0},
    {"id": 0x10B7, "text": "\x1AEr ist nicht mehr hier...\x04\x1AJedes Wesen, das kein Kokiri ist,\x01ist in diesen Wäldern verloren.\x04\x1ASicher hat er sich inzwischen\x01auch in eine Pflanze verwandelt.\x01Alles, was von ihm übrig blieb,\x01ist diese Säge hier.\x07\x10\xB8\x02", "box_type": 0},
    {"id": 0x10B8, "text": "Die Medizin besteht aus \x01Waldpilzen! Gib sie mir! \x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x10B9, "text": "Wirst auch Du Dich verwandeln?\x02", "box_type": 0},
    {"id": 0x10BA, "text": "Wir verkaufen Schilde, aber keine \x01Schwerter!\x0B\x02", "box_type": 0},
    {"id": 0x10BB, "text": "\x1ADu kennst \x05\x42Salias Lied\x05\x40! Wir sollten \x01Freunde werden! Hier, nimm das...\x02", "box_type": 0},
    {"id": 0x10BC, "text": "Hi! Wie findest Du mein Outfit?\x01Ich gebe zu, es ist nicht \x01besonders aufregend...\x02", "box_type": 0},
    {"id": 0x10BD, "text": "Laß uns mal wieder spielen!\x02", "box_type": 0},
    {"id": 0x10BE, "text": "\x1AStimme in unser Lied mit Deiner \x01Okarina ein. Wir fangen an...\x02", "box_type": 0},
    {"id": 0x10BF, "text": "\x1ADas hat Spaß gemacht. Nimm dies\x01als Beweis unserer Freundschaft.\x02", "box_type": 0},
    {"id": 0x10C0, "text": "\x1AWillkommen!\x01Ich habe Dich erwartet!\x0C\x28\x1ASchön, Dich wiederzusehen, \x01\x0F. Hör mir gut zu!\x07\x10\xC1\x02", "box_type": 0},
    {"id": 0x10C1, "text": "Hier in den Verlorenen Wäldern \x01wirst Du die \x05\x42Heilige Lichtung\x05\x40 \x01finden.\x04Dies ist ein Ort, den bisher nur\x01wenige Leute betreten haben.\x04Still... Ich höre etwas...\x01Ich höre eine fremde Melodie!\x04Kannst Du sie auch hören?\x0B\x02", "box_type": 0},
    {"id": 0x10C2, "text": "Muß ich mich noch einmal \x01wiederholen?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x10C3, "text": "\x1ABeweise Dein Geschick und finde\x01den Weg durch den Wald...\x04\x1AVerlasse Dich auf Dein Gehör\x01und Du wirst schon bald Dein\x01Ziel erreichen!\x02", "box_type": 0},
    {"id": 0x10C4, "text": "\x1A\x0F...!\x0C\x28\x1AHat Salia Dir ihr Lied \x01beigebracht?\x04\x1ADas Lied scheint geheimnisvolle\x01Kräfte zu haben.\x04\x1AIch hörte, daß an anderen \x01Orten ebenfalls die Möglichkeit\x01besteht, Lieder zu lernen. Zum \x01Beispiel in Hyrule...\x07\x10\xC5\x02", "box_type": 0},
    {"id": 0x10C5, "text": "Plazierst Du die Okarina auf \x05\x46¡\x05\x40\x01und wählst sie aus, werden\x01\x05\x41Notenlinien\x05\x40 erscheinen.\x04Ich empfehle Dir, hier eines der\x01Lieder zu spielen, die Du erlernt \x01hast.\x04Du kannst natürlich auch ohne\x01Notenlinien spielen. Auch das \x01macht Spaß!\x0B\x02", "box_type": 0},
    {"id": 0x10C6, "text": "Muß ich alles nochmal sagen?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x10C7, "text": "\x1AAlle Lieder, die Du lernst, \x01werden Dir im \x05\x44Status-Menü \x01\x05\x40angezeigt. Lerne sie, denn Du \x01wirst sie häufig brauchen.\x02", "box_type": 0},
    {"id": 0x10C8, "text": "\x1ADieser Mido! Ich frage mich, was \x01er sich dabei denkt...\x04\x1ADennoch ist das, was er sagte, \x01wahr.\x07\x10\xC9\x02", "box_type": 0},
    {"id": 0x10C9, "text": "\x1AIm Wald gehen in letzter Zeit\x01merkwürdige Dinge vor sich...\x04\x1AWir müssen auf alles vorbereitet \x01sein. Du solltest Dir eine Waffe \x01suchen!\x07\x10\x32\x02", "box_type": 0},
    {"id": 0x10CA, "text": "\x12\x38\x82Hab Gnade! Ich kann Dir \x01\x05\x41Deku-Kerne \x05\x40anbieten!\x01\x05\x4130 Stück   \x05\x40kosten\x05\x41   40 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10CB, "text": "\x12\x38\x82Ich gebe auf! Wie wär's, wenn ich\x01Dir einen \x05\x41Deku-Schild\x05\x40 verkaufen \x01würde! Er kostet \x05\x4150 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10CC, "text": "\x12\x38\x82 Hab Erbarmen! Ich kann Dir \x01einige\x05\x41 Bomben \x05\x40verkaufen!\x01\x05\x415 Stück   kosten    40 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10CD, "text": "\x12\x38\x82Halte ein! Laß mich gehen und \x01ich verkaufe Dir \x05\x41Pfeile\x05\x40!\x01\x05\x4130 Stück   kosten   70 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10CE, "text": "\x12\x38\x82Vergib mir! Laß mich laufen, und \x01ich verkaufe Dir \x05\x41Rotes Elixier\x05\x40 für \x01nur \x05\x4140 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10CF, "text": "\x12\x38\x82Hab Gnade! Verschone mich und \x01ich verkaufe Dir \x05\x42Grünes Elixier\x05\x40 für \x01nur \x05\x4140 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10D0, "text": "\x1AWas?! Du hast eine Fee?!\x01Und der Deku-Baum hat Dich zu \x01sich gerufen?\x07\x10\xD1\x02", "box_type": 0},
    {"id": 0x10D1, "text": "\x1AWas muß ich da hören?!\x04\x1AWieso sollte er DICH und nicht \x01den großen\x05\x41 Mido \x05\x40zu sich rufen?\x04\x1ADas kann nicht sein...\x04\x1AIch glaube es einfach nicht!\x01Du bist nicht einmal richtig\x01ausgerüstet!\x04\x1AWie willst Du dem Deku-Baum \x01denn ohne \x05\x42Schwert\x05\x40 und \x05\x44Schild\x05\x40\x01gegenübertreten?\x04Was? Das stimmt, ich bin auch \x01nicht ausgerüstet, aber das ist\x01etwas anderes...\x07\x10\x30\x02", "box_type": 0},
    {"id": 0x10D2, "text": "\x1A\x06\x2BHey, was ist das?!\x04\x1ADu besitzt einen \x05\x44Deku-Schild\x05\x40...\x04\x1AUnd... Und auf Deinem Rücken\x01trägst Du ein Schwert!\x04\x1AUnglaublich! Es ist in der\x01Tat das \x05\x42Kokiri-Schwert\x05\x40!\x04\x1AHEILIGER DEKU!\x07\x10\xD3\x02", "box_type": 0},
    {"id": 0x10D3, "text": "\x1AWie dem auch sei, ein Weichling \x01bleibt immer ein Weichling!\x07\x10\x34\x02", "box_type": 0},
    {"id": 0x10D4, "text": "\x12\x38\x82Laß mich laufen und ich verkaufe \x01Dir einen \x05\x41Deku-Stab\x05\x40 für nur \x01\x05\x4115 Rubine!\x05\x40\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10D5, "text": "\x12\x38\x82Verzeih mir! Ich kann Dir \x05\x41Deku-\x01Nüsse\x05\x40 zum Kauf anbieten!\x01\x05\x415 Stück   kosten    20 Rubine!\x05\x40\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10D6, "text": "Noch etwas...\x04\x08\x06\x08Es tut mir leid, daß ich gemein \x01\x06\x3Czu ihm war.\x09\x04\x06\x14Sagen Sie ihm das bitte auch!\x02", "box_type": 0},
    {"id": 0x10D7, "text": "Du hast einen beschwerlichen Weg\x01hinter Dir...\x01Du scheinst ein wahrer Held zu \x01sein!\x07\x10\xD8\x02", "box_type": 0},
    {"id": 0x10D8, "text": "Sieh doch nur, ist die Aussicht \x01nicht wunderschön? Wechsle den \x01Blickwinkel mit \x05\x46¥ \x05\x40und nutze\x05\x46 \x05\x44ª\x05\x40,\x01um die Sicht zu genießen.\x02", "box_type": 0},
    {"id": 0x10D9, "text": "Was hast Du mit dem Deku-Baum \x01gemacht?\x02", "box_type": 0},
    {"id": 0x10DA, "text": "Bevor Du Dich in die Verlorenen \x01Wälder begibst, solltest Du Dich \x01besser ausrüsten!\x02", "box_type": 0},
    {"id": 0x10DB, "text": "\x12\x38\x82Meine Brüder und ich sind uns\x01einig...\x01Du bist potthäßlich!\x04\x12\x38\x82Zum Trost werden wir Dich mit \x01einigen \x05\x41Deku-Nüssen \x05\x40versorgen.\x04\x12\x38\x82Außerdem werden wir dafür \x01sorgen, daß Du von nun an mehr \x01Nüsse tragen kannst!\x04Hobrobbel... Kadobbel...\x04\x12\x38\x80Wazakamobbel!\x0B\x02", "box_type": 0},
    {"id": 0x10DC, "text": "\x12\x38\x82Hab Gnade!\x04\x12\x38\x80Verschone mich und ich sorge\x01dafür, daß Du von nun an mehr\x01\x05\x41Deku-Stäbe \x05\x40tragen kannst!\x01Es kostet Dich nur \x05\x4140 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10DD, "text": "\x12\x38\x82Verschone mich!\x04\x12\x38\x80Gewähr mir Gnade und ich sorge\x01dafür, daß Du von nun an mehr\x01\x05\x41Deku-Nüsse \x05\x40tragen kannst!\x01Es kostet Dich nur \x05\x4140 Rubine\x05\x40!\x07\x10\xA3\x02", "box_type": 0},
    {"id": 0x10DE, "text": "\x12\x38\x82Tut mir leid, aber Du kannst das \x01jetzt nicht kaufen!\x02", "box_type": 0},
    {"id": 0x10DF, "text": "Der, den Du suchst,\x01ist nicht mehr hier...\x04Jeder, der diesen Wald betritt und \x01kein Kokiri ist, ist verdammt...\x04Jeder...\x01Sicher hat er sich schon längst in \x01eine Pflanze verwandelt...\x02", "box_type": 0},
    {"id": 0x2000, "text": "\x1AVielen Dank nochmal für \x01die Hilfe... Ich weiß nicht\x01einmal Deinen Namen...\x04\x1A\x14\x02Sagst Du ihn mir?\x14\x00\x04\x1AWirklich?\x01\x0F!\x04\x1A\x08Hab ich's doch gewußt!\x09\x01Du bist der Feen-Junge aus dem\x01Wald! Es war vor vielen Jahren.\x01Erinnerst Du Dich an mich?\x04\x1ATatsächlich? Ich dachte mir schon,\x01daß Du es bist. Epona hat Dich\x01gleich wiedererkannt!\x04\x1AOh, ich muß Dir etwas über \x05\x41Basil\x01\x05\x40erzählen...\x04\x1AEr hatte Angst, daß Ganondorf\x01dahinterkommen würde, daß er Epona\x01gehen ließ. Diese Furcht hat aus\x01ihm einen anderen Menschen gemacht!\x04\x1ANun ist er wieder \x05\x41so wie früher\x05\x40.\x01Daher kehrte auch mein Vater auf\x05\x41\x01\x05\x40die Farm zurück!\x04\x1AEndlich wird alles wieder, wie\x01es einmal war. Ist das nicht\x01schön?!\x04\x1ADas alles haben wir Dir zu\x01verdanken! Wir stehen tief in\x01Deiner Schuld!\x04\x1AVielen Dank, \x0F!\x02", "box_type": 0},
    {"id": 0x2001, "text": "Wie geht es \x05\x41Epona\x05\x40?\x04Spielst Du \x05\x41Eponas Lied \x05\x40auf Deiner\x01Okarina, wird sie immer zu Dir\x01kommen.\x04Wann immer Du mit Epona \x01\x05\x41trainieren\x05\x40 möchtest, kannst Du \x01gern zur Farm zurückkehren!\x02", "box_type": 0},
    {"id": 0x2002, "text": "\x1AEpona\x05\x41 \x05\x40sieht prächtig aus!\x01Es scheint Dir gelungen zu sein,\x01sie zu zähmen!\x07\x20\x03\x02", "box_type": 0},
    {"id": 0x2003, "text": "Warum versuchst Du Dich nicht mit\x01Epona an dem \x05\x41Hindernisparcours\x05\x40?\x04Du mußt \x05\x41zwei Runden\x05\x40 reiten und \x01darfst dabei kein Hindernis \x01auslassen. Das ist eine große\x01Herausforderung!\x04Wie sieht's aus?\x01Möchtest Du es versuchen? \x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x2004, "text": "Nun, Deine Zeit war \x05\x41\x17\x05\x40.\x01Nicht besonders gut...\x04Vergiß nicht, Du brauchst nur zu\x01beschleunigen, um über die hohen \x01Hindernisse zu springen. Die\x01niedrigen nimmt Epona auch so.\x02", "box_type": 0},
    {"id": 0x2005, "text": "\x0F, kannst Du mich\x01hören? Ich bin es, Zelda...\x0E\x3C\x02", "box_type": 5},
    {"id": 0x2006, "text": "\x12\x28\xDFMuuuuuuuuuuuuuuuuuuuuuuuuuuuuh!\x04Welch ein schönes Lied...\x01Es erinnert mich ans Melken...\x04Muh, nach diesem Lied könnte\x01ich literweise Milch geben...\x0B\x02", "box_type": 0},
    {"id": 0x2007, "text": "Hier, nimm etwas von der \x01erfrischenden und nahrhaften \x01Milch!\x0B\x02", "box_type": 0},
    {"id": 0x2008, "text": "\x0F, nun, da Du die \x01Okarina in Händen hältst...\x0C\x3C...bin ich schon weit entfernt...\x0C\x3CIch versuchte, auf Dich zu warten,\x01doch die Zeit drängte...\x0C\x3CZumindest konnte ich Dir die \x01Okarina übergeben...\x01Und diese \x05\x44Melodie\x05\x40...\x0E\x3C\x02", "box_type": 2},
    {"id": 0x2009, "text": "\x1AWohlan, \x0F.\x01Spiele diese Melodie in der\x01Zitadelle der Zeit vor dem \x01Zeitaltar!\x02", "box_type": 5},
    {"id": 0x200A, "text": "\x1AHa! Denkst Du wirklich, daß ich \x01Dich nicht erkenne?\x04\x1A\x06\x1EHey?!\x04\x1AIst das nicht eine Fuchs-Maske?\x01So etwas ist doch zur Zeit sehr \x01angesagt!\x04\x1AMein Sohn ist ganz verrückt\x01danach! \x01Wie wäre es, wenn...\x07\x20\x0B\x02", "box_type": 0},
    {"id": 0x200B, "text": "Würdest Du sie mir verkaufen?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x200C, "text": "Schade, doch ich gebe nicht auf!\x01Ich habe sehr viel Geduld. Sonst\x01würde ich hier auch nicht den\x01ganzen Tag herumstehen!\x0B\x02", "box_type": 0},
    {"id": 0x200D, "text": "\x1AGähn...\x01Schon gut, ich bin wach...\x04\x1AWas?\x04\x1AAch, Du bist es! Hallo!\x04\x1AIch erinnere mich an Dich...\x01Malon war damals ziemlich sauer\x01auf mich...\x04\x1ADu hast uns sehr geholfen. \x01Deshalb möchte ich, daß Du diese \x01\x05\x41Milch\x05\x40 an Dich nimmst. Du kannst\x01auch die Flasche behalten!\x02", "box_type": 0},
    {"id": 0x200E, "text": "Das Passieren ist \x05\x41nur mit \x01königlicher Erlaubnis\x05\x40 möglich!\x04Hast Du das Schild nicht gelesen?\x01Oh, Du bist ja noch ein Kind,\x01sicher kannst Du gar nicht lesen...\x02", "box_type": 0},
    {"id": 0x200F, "text": "Was soll ich damit?!\x02", "box_type": 0},
    {"id": 0x2010, "text": "\x1AOh, das scheint...\x01In der Tat, es ist Zeldas \x01Handschrift! Laß mal sehen... \x01\x1AHmmm... Na gut...\x04\"\x05\x45Dies ist \x0F.\x01 Er hat den Auftrag, Hyrule\x01 vor dem Untergang zu bewahren.\x05\x40\"\x01\x06\x5APrinzessin Zelda\x04\x1AHa!\x01Was ist denn das für ein \x01seltsames Vorhaben...\x04\x1AWie dem auch sei, Du kannst \x01passieren, Zwergenheld!\x01\x14\x01Hahaha!\x14\x00\x0B\x02", "box_type": 0},
    {"id": 0x2011, "text": "Ah, unser Held!\x01Vielen Dank für Deine Bemühungen!\x01\x14\x01Hahaha!\x14\x00!\x02", "box_type": 0},
    {"id": 0x2012, "text": "Wow! Nicht schlecht!\x01Deine Zeit war \x05\x41\x17\x05\x40!\x01Epona und Du, Ihr seid ein\x01gutes Team!\x02", "box_type": 0},
    {"id": 0x2013, "text": "Oh, das ist schade...\x01Du hast keine leere Flasche, sonst \x01hätte ich Dir etwas von meiner \x01Milch gegeben...\x0B\x02", "box_type": 0},
    {"id": 0x2014, "text": "Ich bin \x05\x41Basil\x05\x40... für Dich natürlich\x01\"Herr Basil\". Du bist mir im Weg,\x01Kleiner! Verschwinde!\x02", "box_type": 0},
    {"id": 0x2015, "text": "\x1AAch, Herr Nachwuchsheld...\x04\x1AFalls Du planst, den Todesberg zu \x01besteigen, solltest Du Dich mit\x01einem \x05\x44starken Schild\x05\x40 ausrüsten!\x01Der Vulkan ist noch immer aktiv!\x04\x1AAuf dem Marktplatz in Hyrule\x01wirst Du sicher fündig, wenn Du\x01Ausrüstungsgegenstände kaufen\x01möchtest!\x04\x1AWenn Du ihnen sagst, daß ich \x01Dich geschickt habe, machen sie \x01Dir sicher einen Sonderpreis!\x04\x1ADenkst Du aber, Deine\x01Ausrüstung würde genügen, dann\x01laufe ruhig weiter.\x04\x1AÜbrigens: Kann ich Dich um\x01einen Gefallen bitten? Du mußt es\x01nicht tun, aber immerhin habe ich\x01Dir eben einen guten Tip gegeben.\x04\x1AWarst Du schon beim \x01\x05\x41Maskenhändler\x05\x40 in Hyrule? Über \x01diesen Laden spricht zur Zeit \x01jeder!\x04\x1AMein Sohn drängt mich schon die \x01ganze Zeit, ihm eine Maske zu \x01kaufen. Doch leider fehlt mir die \x01Zeit...\x04\x1AKönntest Du mir eine Maske aus\x01dem Laden besorgen? Ich meine, \x01nur wenn Du zufällig mal nach \x01Hyrule kommen solltest...\x04\x1AWie gesagt, ich kann hier nicht \x01weg. Mein Job...\x04\x1A\x06\x4CSeufz...\x0B\x02", "box_type": 0},
    {"id": 0x2016, "text": "Ich wünschte, ich könnte zum \x01\x05\x41Maskenhändler\x05\x40 gehen und meinem \x01Sohn eine Maske kaufen...\x04\x06\x4CSeufz...\x02", "box_type": 0},
    {"id": 0x2017, "text": "Oh nein... Er atmet nicht mehr...\x02", "box_type": 2},
    {"id": 0x2018, "text": "\x0F!?\x02", "box_type": 0},
    {"id": 0x2019, "text": "\x1A\x08\x06\x1EVerdammt!\x09 Sie ist fort!\x02", "box_type": 0},
    {"id": 0x201A, "text": "\x1A\x06\x4ADu da! \x01\x06\x39\x08Kleiner Wicht!\x09\x02", "box_type": 0},
    {"id": 0x201B, "text": "\x1A\x06\x41\x14\x0A\x08Ha\x09 \x08Ha\x09 \x08Ha\x09...\x14\x00\x01\x06\x3ADu hast Mut!\x01\x06\x17Doch Mut kann manchmal...\x01\x06\x39...tödlich sein!\x02", "box_type": 0},
    {"id": 0x201C, "text": "\x1A\x08\x06\x36Armseliger Tropf!\x09\x01\x06\x32Weißt Du, wem Du \x01\x06\x33gegenüberstehst?!\x02", "box_type": 0},
    {"id": 0x201D, "text": "\x1A\x06\x2DIch bin \x05\x41Ganondorf\x05\x40!\x01\x08\x06\x1EDer König der Gerudos!\x09\x02", "box_type": 0},
    {"id": 0x201E, "text": "\x1A\x06\x22Du mußt das weiße Pferd\x01\x06\x20gesehen haben! In welche\x01\x06\x10Richtung sind sie entkommen?!\x01\x06\x39\x08Antworte mir!\x09\x02", "box_type": 0},
    {"id": 0x201F, "text": "Wenn die Zeit abgelaufen ist,\x01sage ich Dir Bescheid...\x02", "box_type": 0},
    {"id": 0x2020, "text": "Mein Sohn wird sich sehr über die\x01Maske freuen! Vielen Dank,\x01mein Freund!\x0B\x02", "box_type": 0},
    {"id": 0x2021, "text": "\x1A\x12\x48\x07Du hast die Maske, für die Du\x0110 Rubine bezahlen mußt, für \x05\x4115 \x01Rubine \x05\x40weiterverkauft. Du hast \x01einen Gewinn erwirtschaftet!\x04\x1AGeh nun zum Maskenhändler\x01zurück und gib ihm seine\x01\x05\x4110 Rubine\x05\x40.\x0B\x02", "box_type": 2},
    {"id": 0x2022, "text": "Kleine Kinder dürfen an der \x01\x05\x41Grausigen Grabgrusel-Tour\x05\x40\x01leider nicht teilnehmen...\x04Deshalb treibe ich mich hier herum\x01und spiele Grausige Grabgrusel-\x01Tour...\x04Allerdings sehe ich nicht \x01besonders grausig aus, oder?\x02", "box_type": 0},
    {"id": 0x2023, "text": "\x08Oh Graus!\x09 Es ist Boris, der \x01Totengräber!\x04\x06\x51Nanu...?\x04Oh, es ist nur eine Maske! Wow, \x01ich bin ganz schön \x01erschrocken!\x04Gibst Du mir die Maske?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x2024, "text": "Ich habe auch Geld, ich kann\x01sie bezahlen!\x02", "box_type": 0},
    {"id": 0x2025, "text": "Hey! Runter vom Pferd!\x01Die Zeit ist abgelaufen!\x01Du hast nur 10 Rubine gezahlt!\x0B\x02", "box_type": 0},
    {"id": 0x2026, "text": "Mit dieser Maske sehe ich fast \x01wie Boris aus! Cool! \x01Hier ist das Geld!\x02", "box_type": 0},
    {"id": 0x2027, "text": "\x1A\x12\x48\x07Du hast die Maske, die Dich\x0130 Rubine gekostet hat, zum \x01gleichen Preis weiterverkauft!\x04\x1AGeh nun zurück zum \x01Maskenhändler und zahl ihm seine\x01\x05\x4130 Rubine \x05\x40zurück. Dabei kannst \x01Du eine neue Maske leihen.\x02", "box_type": 2},
    {"id": 0x2028, "text": "Ich fange jetzt zu graben an! \x01Genau wie Boris!\x02", "box_type": 0},
    {"id": 0x2029, "text": "Früher hoppelten noch viele Hasen\x01durch die hylianische Steppe. Nun\x01sind sie fort, denn sie waren \x01sehr schmackhaft... Hoppeldihö...\x04Wie gern wäre ich ein Hase... Wie \x01gern hätte ich lange Ohren, die \x01bei jeder Bewegung mitwippen\x01würden... Hoppeldihö...\x04Findest Du mich merkwürdig?\x02", "box_type": 0},
    {"id": 0x202A, "text": "Ich wette, mit diesen Ohren kannst \x01Du die Stimmen hören... Das sind\x01die Ohren, die der Große Kürbis\x01prophezeit hat... Hoppeldihö...\x07\x20\x2B\x02", "box_type": 0},
    {"id": 0x202B, "text": "Mir ist egal, wie teuer sie sind!\x01Ich muß sie haben! Verkauf sie mir!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x202C, "text": "Das ist nicht das, was ich hören \x01wollte! Hoppeldinö!\x02", "box_type": 0},
    {"id": 0x202D, "text": "Mein Traum geht in Erfüllung! Ich\x01habe Hasenohren! Hoppeldihö!\x01Füttert mich mit Möhren!\x0B\x02", "box_type": 0},
    {"id": 0x202E, "text": "\x1A\x12\x48\x07Für die Maske hast Du 50\x01Rubine bezahlt. Der durchgeknallte \x01Kerl hat Dir jedoch mehr dafür \x01gegeben, als Du zählen kannst!\x04\x1AGeh zurück zum Maskenhändler \x01und gib ihm seine \x05\x4150 Rubine\x05\x40 \x01wieder.\x02", "box_type": 2},
    {"id": 0x202F, "text": "\x1A\x06\x11Glaubst Du im Ernst, daß Du\x01\x06\x0Fsie vor mir schützen kannst?\x01\x06\x47Du Narr!\x02", "box_type": 0},
    {"id": 0x2030, "text": "\x1AEinige Leute verbreiten das \x01Gerücht, ich hätte Talon um die\x01Farm betrogen, aber...\x04\x1A\x08\x06\x2DDas ist lächerlich!\x09\x04\x1ATalon hat alles herunter- \x01gewirtschaftet! Ich, der hart \x01arbeitende \x05\x41Basil\x05\x40, habe meine ganze\x01Kraft in die Farm gesteckt!\x04\x1ANiemand darf deshalb schlecht\x01über mich sprechen!\x04\x1AIm Vertrauen... Eigentlich war\x01es der \x05\x41mächtige Ganondorf\x05\x40, der \x01meine Talente erkannte und mir die\x01Farm überließ...\x04\x1AAls Dank werde ich ihm das beste\x01Pferd meiner Züchtung als Präsent\x01überreichen!\x04\x1ASag mal, hättest Du nicht Lust, \x01eines meiner Pferde zu reiten?\x07\x20\x31\x02", "box_type": 0},
    {"id": 0x2031, "text": "Für nur \x05\x4110 Rubine \x05\x40lasse ich \x01Dich reiten.\x01\x1B\x05\x42Reiten!\x01Nicht reiten!\x05\x40\x02", "box_type": 0},
    {"id": 0x2032, "text": "Na gut, dann verschwinde von \x01meiner Farm!\x02", "box_type": 0},
    {"id": 0x2033, "text": "Du hast zu wenig Rubine!\x01Komm wieder, wenn Du ein bißchen \x01mehr in der Tasche hast!\x02", "box_type": 0},
    {"id": 0x2034, "text": "Soll ich Dir erklären, wie man \x01reitet?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x2035, "text": "Nähere Dich dem Pferd langsam \x01und stell Dich an seine Seite.\x01Mit \x05\x43\x05\x40 steigst Du auf.\x04Nutze den \x05\x44ª\x05\x40, um mit Epona zu \x01traben. Galoppierst Du, kannst Du \x01mit\x05\x43 \x05\x40 die Peitsche aktivieren, \x01um sie noch mehr anzutreiben!\x04Willst Du über ein Hindernis \x01springen, galoppiere darauf zu\x01und setze vor der Hürde die\x01Peitsche ein!\x04Ist der Winkel, in dem Du auf das\x01Hindernis zureitest, zu spitz,\x01verweigert das Pferd.\x04Um wieder abzusteigen, halte \x01das Pferd an und drücke \x05\x43\x05\x40.\x01Viel Spaß beim Reiten!\x0B\x02", "box_type": 0},
    {"id": 0x2036, "text": "Setzt Du die \x05\x44Zielerfassung\x05\x40 ein,\x01kannst Du mit mir sprechen,\x01während Du auf dem Pferd sitzt.\x04Willst Du jetzt schon gehen?\x01\x01\x1B\x05\x42Nein, ich will reiten!\x01Ja, es ist genug!\x05\x40\x02", "box_type": 0},
    {"id": 0x2037, "text": "Willst Du absteigen, halte an und \x01drücke \x05\x43\x05\x40.\x04Hab ich Dich nicht schon mal\x01irgendwo gesehen? Du kommst mir\x01so bekannt vor...\x07\x20\x36\x02", "box_type": 0},
    {"id": 0x2038, "text": "Du reitest nicht schlecht!\x01Wie wäre es mit einem kleinen\x01Rennen? Eine Runde um die \x01Koppel!\x04Der Gewinner erhält, sagen wir,\x01\x05\x4150 Rubine\x05\x40?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x2039, "text": "Übe lieber noch ein wenig!\x01Dann kannst Du auch gegen \x01mich antreten!\x02", "box_type": 0},
    {"id": 0x203A, "text": "\x1A\x06\x39Ver\x08maledeit!\x09\x04\x1AIch hoffe nur, der mächtige\x01Ganondorf erfährt nicht von dieser\x01Demütigung... Hey, Du! Wie wäre es\x01mit einer Revanche? Gewinnst Du,...\x04\x1A...gehört das Pferd Dir!\x0B\x02", "box_type": 0},
    {"id": 0x203B, "text": "\x1AWie kann das sein?!\x01Ist das wirklich \x05\x41Epona\x05\x40?\x04\x1AWie ist es Dir gelungen, das Pferd\x01hinter meinem Rücken zu zähmen?!\x04\x1AIch wollte Epona dem mächtigen\x01Ganondorf zum Geschenk machen!\x01Nun habe ich sie beim Pferderennen \x01verloren! Vermaledeit!\x0B\x02", "box_type": 0},
    {"id": 0x203C, "text": "\x1A\x06\x1ANun gut, so sei es denn!\x04\x1AIch halte mein Versprechen, das \x01Pferd möge Dir gehören...\x04\x1A\x06\x52Nur...\x04\x1ADie Farm darfst Du mit ihr nicht \x01verlassen!\x0B\x02", "box_type": 0},
    {"id": 0x203D, "text": "Ha! Hattest Du wirklich gedacht,\x01mich bezwingen zu können? \x01Danke für die 50 Rubine.\x0B\x02", "box_type": 0},
    {"id": 0x203E, "text": "Ha! Im ersten Rennen habe ich nur\x01geblufft. Wie könnte ich gegen Dich\x01verlieren? Komm wieder, wenn Du\x01es erneut versuchen willst...\x02", "box_type": 0},
    {"id": 0x203F, "text": "\x1AWas?! Wer hat Dir erlaubt, Dich  \x01hier herumzutreiben?\x01Armseliger Wicht!\x04\x1AIch bin \x05\x41Basil\x05\x40. Diese Farm liegt \x01mir sehr am Herzen.\x04\x1AIch arbeite schon verdammt lange \x01hier. Talon, der faule Sack, ist \x01mein Chef!\x04\x1AHeute zum Beispiel wollte er nur\x01schnell Milch im Schloß abliefern,\x01doch er ist noch immer\x01nicht zurück!\x04\x1ASo ist es fast jeden Tag!\x01Ich habe die ganze Arbeit\x01am Hals!\x07\x20\x40\x02", "box_type": 0},
    {"id": 0x2040, "text": "Seufz... Man hat es nicht leicht\x01als rechtschaffener Arbeiter.\x02", "box_type": 0},
    {"id": 0x2041, "text": "\x1AWow! Deine Kleidung...\x01Wo trägt man denn sowas...\x01Du scheinst nicht von hier zu \x01sein, oder?\x04\x1A\x14\x02Woher...\x14\x00 kommst Du?\x04\x1AOh, Du bist ein Feen-Junge aus \x01dem Wald! Ich bin \x05\x41Malon\x05\x40.\x01Meinem Vater gehört die \x01Lon Lon-Farm!\x07\x20\x42\x02", "box_type": 0},
    {"id": 0x2042, "text": "Vater ist zum Schloß gegangen,\x01um dort Milch abzuliefern, doch\x01bisher kam er nicht zurück...\x02", "box_type": 0},
    {"id": 0x2043, "text": "\x1AGehst Du zufällig auch zum\x01Schloß? Wenn ja, tust Du mir einen \x01Gefallen? Würdest Du dort meinen\x01\x05\x41Vater\x05\x40 für mich suchen?\x04\x1A\x12\x68\x6DSicher ist er eingeschlafen \x01und macht irgendwo ein Nickerchen! \x01Es ist immer das gleiche mit ihm!\x04\x1AAch, wenn Du ihn suchst, nimm \x01dies hier an Dich!\x04\x1ABewahre es warm und sorgsam auf,\x01Du wirst es gebrauchen können...\x01Hihihi...\x0B\x02", "box_type": 0},
    {"id": 0x2044, "text": "Lege das Ei auf \x05\x46¡\x05\x40, um es \x01einzusetzen!\x04Für einen Erwachsenen ist mein \x01Vater ganz schön anstrengend, \x01oder? Hihihi...\x02", "box_type": 0},
    {"id": 0x2045, "text": "\x1AManchmal glaube ich einfach nicht,\x01daß ich, \x05\x41der fantastische Basil\x05\x40, \x01auf einer dämlichen Farm wie \x01dieser arbeite!\x04\x1AWeil der Farmbesitzer ein\x01Faulpelz ist, muß ich die \x01gesamte Arbeit erledigen!\x07\x20\x46\x02", "box_type": 0},
    {"id": 0x2046, "text": "Ich, \x05\x41der einzigartige Basil\x05\x40, sollte \x01diese Farm leiten und nicht der \x01faule Talon!\x02", "box_type": 0},
    {"id": 0x2047, "text": "\x1AAh, der Junge aus dem Wald!\x04Ich hörte, Du hast meinen Vater \x01gefunden! Wie hat Dir das Schloß \x01gefallen? Und die Prinzessin? Hast \x01Du sie gesehen? Hihihi...\x04\x1A\x12\x68\x6DDaddy hatte es ganz schön eilig,\x01nachdem Du ihn geweckt hast...\x04\x1AOh, ich muß Dir jemanden \x01vorstellen, Feen-Junge!\x04\x1ADas Pferd hier heißt\x01\x05\x41Epona\x05\x40. Süß, nicht wahr?\x02", "box_type": 0},
    {"id": 0x2048, "text": "Wie es scheint, hat Epona Angst \x01vor Dir...\x02", "box_type": 0},
    {"id": 0x2049, "text": "Dieses Lied hat meine Mutter \x01geschrieben. Es ist wunderschön. \x01Laß es uns zusammen singen!\x02", "box_type": 0},
    {"id": 0x204A, "text": "Oh, Epona! Sie hat an Dir Gefallen\x01gefunden, Feen-Junge.\x02", "box_type": 0},
    {"id": 0x204B, "text": "\x14\x02S C H N A R C H...\x14\x00\x02", "box_type": 0},
    {"id": 0x204C, "text": "Oh... Ein Besucher!\x01Es ist lange her, seit wir Besuch \x01hier hatten...\x01Wo kommst Du her?\x04Seit Ganondorf hier sein Unwesen\x01treibt, sind die Menschen auf der\x01Flucht, die einstigen Städte Ruinen,\x01und überall lauern böse Kreaturen.\x04Basil hat die Farm im Namen von\x01Ganondorf übernommen...\x04Jeder scheint vom Bösen besessen.\x04Und Vater...\x01Er wurde von Basil von der Farm\x01verbannt...\x04Falls ich Basil nicht gehorche,\x01hat er gedroht, die Pferde zu\x01quälen...\x04Du siehst...\x01Es gibt nichts, was ich tun kann...\x02", "box_type": 0},
    {"id": 0x204D, "text": "Ich wette, es gibt niemanden, der\x01schneller als ich laufen kann... \x01Das Problem dabei ist nur, daß\x01ich nicht aufhören kann, zu laufen.\x02", "box_type": 0},
    {"id": 0x204E, "text": "\x14\x02Zzzzzzzz...\x14\x00\x01Ruhe... ich... muß...\x01Kühe... Hühner...\x02", "box_type": 0},
    {"id": 0x204F, "text": "\x1ARichte Deine Augen gen Osten.\x01Dies ist der \x05\x41Todesberg\x05\x40, das\x01Reich der Goronen. Sie hüten \x01den Heiligen Stein des Feuers.\x02", "box_type": 0},
    {"id": 0x2050, "text": "Bitte erzähl Basil nicht, daß \x01ich dieses Lied singe...\x02", "box_type": 0},
    {"id": 0x2051, "text": "\x1ADu...\x01Du kennst das Lied \x05\x41meiner Mutter\x05\x40?\x04\x1AAlle haben dieses Lied geliebt...\x01Mein Vater... Sogar Basil...\x04\x1ADoch seit Ganondorf aufgetaucht \x01ist, hat sich Basil völlig verändert.\x04\x1AWenn ich es singe und die Augen \x01dabei schließe, denke ich an\x01vergangene Zeiten...\x07\x20\x52\x02", "box_type": 0},
    {"id": 0x2052, "text": "Auch\x05\x41 Epona\x05\x40 liebte dieses Lied.\x01Damit konnte ich sie zähmen.\x01Basil ist dies nie gelungen...\x04Hihihi...\x02", "box_type": 0},
    {"id": 0x2053, "text": "Die steinerne Statue scheint Dir \x01etwas sagen zu wollen...\x02", "box_type": 2},
    {"id": 0x2054, "text": "Da Du nun die Maske trägst,\x01beginnt die Statue mit Dir zu  \x01sprechen...\x04Höre ihre Worte...\x02", "box_type": 2},
    {"id": 0x2055, "text": "Von nun an werde ich jeden Tag\x01hart arbeiten. Das habe ich Malon\x01versprochen!\x02", "box_type": 0},
    {"id": 0x2056, "text": "Basil... Mir scheint, er war von\x01bösen Mächten besessen.\x01Im Grunde ist er ein gutmütiger \x01Mensch.\x02", "box_type": 0},
    {"id": 0x2057, "text": "S C H N A R C H...\x01Grummel... Wie schön, daß mir\x01Talon vergeben hat...\x02", "box_type": 0},
    {"id": 0x2058, "text": "Es ist lange her...\x01Lust auf ein Rennen?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x2059, "text": "Falls Du Deine Meinung änderst,\x01kannst Du jederzeit zurückkommen!\x02", "box_type": 0},
    {"id": 0x205A, "text": "Na gut, dann verschwinde hier,\x01Du grüner Wichtel!\x0B\x02", "box_type": 0},
    {"id": 0x205B, "text": "Du bist sauer, weil Du verloren\x01hast? Kein Problem, wie wäre\x01es mit einem weiteren Rennen?\x04Setze \x05\x4150 Rubine \x05\x40und versuch's \x01nochmal!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x205C, "text": "Die Farm dankt, hehehe...\x0B\x02", "box_type": 0},
    {"id": 0x205D, "text": "Wenn ich Dir noch mehr umsonst\x01gebe, wird Basil ziemlich sauer\x01werden. Deshalb verkaufe ich sie\x01Dir zum regulären Preis.\x02", "box_type": 0},
    {"id": 0x205E, "text": "Möchtest für \x05\x4130 Rubine \x05\x40Milch\x01kaufen?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x205F, "text": "Hallo! Wie geht's Dir?\x01Sorry, wenn ich in letzter Zeit\x01etwas merkwürdig war. Fühl Dich\x01hier wie zu Hause!\x02", "box_type": 0},
    {"id": 0x2060, "text": "\x1ADu tapferer Jüngling...\x01Wir müssen Hyrule vor der \x01drohenden Apokalypse bewahren!\x02", "box_type": 0},
    {"id": 0x2061, "text": "\x1AOh, eine hübsche Okarina!\x01Wirst Du das Lied auf der \x01Okarina spielen?\x02", "box_type": 0},
    {"id": 0x2062, "text": "\x1AAm Fuße des Todesberges wirst\x01Du\x05\x41 Kakariko \x05\x40finden. Es ist die \x01Stadt, die ich gegründet habe, um\x01Verfolgten Obdach zu bieten.\x04\x1ABevor Du zum Berg aufbrichst, \x01solltest Du Dich mit einigen\x01Bewohnern unterhalten.\x02", "box_type": 0},
    {"id": 0x2063, "text": "\x1ADas Lied, das ich Dich gelehrt\x01habe, besitzt geheimnisvolle Kräfte.\x01Nur Angehörige der Königsfamilie\x01dürfen es erlernen und spielen.\x04\x1AVergiß nicht: Du kannst damit\x01beweisen, daß Du in königlicher\x01Mission unterwegs bist.\x04\x1AGeh nun, die Prinzessin und ich \x01warten auf Dich und die Heiligen\x01Steine im Schloß! Enttäusche uns\x01nicht!\x02", "box_type": 0},
    {"id": 0x2064, "text": "\x1A\x08Sei willkommen!\x09\x01Bist Du bereit, \x0F?\x0C\x28\x1AEs scheint, daß nun die Zeit \x01gekommen ist, da Dein Abenteuer \x01beginnen soll.\x04\x1ADas, was hinter Dir liegt, war\x01ein Spaziergang im Vergleich zu\x01dem, was Dich erwartet... Doch sei\x01tapfer und verliere nie den Mut!\x07\x20\x65\x02", "box_type": 0},
    {"id": 0x2065, "text": "Folgst Du diesem Weg, so \x01gelangst Du zum \x05\x41Schloß von Hyrule\x05\x40.\x01Dort sei es Dir bestimmt, die \x01\x05\x41Prinzessin\x05\x40 zu treffen...\x04Weichst Du ab von Deinen Pfaden, \x01und wandelst auf unbekannten \x01Wegen, so nutze Deine\x05\x41 Karte\x05\x40.\x04Die Orte, die Du bereits erforscht\x01hast, mögen wie von Geisterhand\x01in Deine Karte gezeichnet werden.\x04Drücke \x05\x41START\x05\x40, um ins Menü zu \x01gelangen, und \x05\x44¤\x05\x40 oder \x05\x44£\x05\x40, um den \x01\x05\x41Karten-Bildschirm\x05\x40 einsehen zu \x01können.\x04Auf dem \x05\x41Karten-Bildschirm\x05\x40 findest\x01Du außerdem einen \x05\x41Hinweis\x05\x40, welchen\x01Ort Du als nächsten aufsuchen \x01solltest.\x07\x20\x66\x02", "box_type": 0},
    {"id": 0x2066, "text": "Hast Du alles verstanden?\x01\x01\x1B\x05\x42Nein!\x01Ja!\x05\x40\x02", "box_type": 0},
    {"id": 0x2067, "text": "\x1ASo sei es! Setze Deinen Weg nun \x01fort! Wir sehen uns wieder...\x02", "box_type": 0},
    {"id": 0x2068, "text": "\x1A\x0F! Hier entlang!\x0C\x28\x1ADie Prinzessin befindet sich \x01im Schloß! Doch hüte Dich vor den \x01Wachen. Sie dürfen Dich nicht\x01sehen...\x0B\x02", "box_type": 0},
    {"id": 0x2069, "text": "Wisse, hier auf diesem Grund, \x01nimmt die Zeit ihren gewohnten \x01Lauf...\x04Besuchst Du jedoch eine Stadt \x01oder die Ranch, steht die Zeit still.\x04Wenn Du möchtest, daß die \x01Tageszeit sich ändert, mußt Du die \x01Stadt verlassen und zu späterer \x01Stunde wiederkehren...\x04Geh nun und hüte Dich vor den \x01Wachen...\x0B\x02", "box_type": 0},
    {"id": 0x206A, "text": "Muß ich meine Worte wiederholen?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x206B, "text": "\x1ADu scheinst die Gabe der\x01Weisheit zu besitzen...\x01Viel Glück...\x02", "box_type": 0},
    {"id": 0x206C, "text": "Sei willkommen, \x0F! \x01Halte ein, mein Freund!\x04Du befindest Dich vor den Toren \x01\x05\x41Kakarikos\x05\x40. Hast Du die Prinzessin \x01bereits besucht? Wenn nicht, so \x01rate ich Dir, sie aufzusuchen.\x0B\x02", "box_type": 0},
    {"id": 0x206D, "text": "Sei gegrüßt, \x0F! \x01Schau hierher!\x0C\x28\x1ADu befindest Dich vor den Toren \x01\x05\x41Kakarikos\x05\x40. Die Treppen führen\x01Dich in die Stadt!\x0B\x02", "box_type": 0},
    {"id": 0x206E, "text": "\x1A\x0F! Nur Du hast die\x01Macht, den Lauf des Schicksals zu\x01ändern!\x02", "box_type": 0},
    {"id": 0x206F, "text": "\x0F! Ich habe Dich \x01erwartet! Wohin werden Dich Deine\x01Schritte als nächstes lenken?\x0C\x28Begibst Du Dich gen Süden, so \x01kannst Du dort die ruhigen \x01Wasser des \x05\x41Hylia-Sees\x05\x40 erkunden.\x04Im Westen hingegen liegt das \x01\x05\x41Gerudotal\x05\x40. Auf der anderen Seite\x01dieses Tales befindet sich die \x01Gerudo-Festung.\x04Welchen Weg Du auch immer wählst,\x01die Macht des Triforce möge Dich\x01begleiten!\x0B\x02", "box_type": 0},
    {"id": 0x2070, "text": "\x1AWas auch immer das Schicksal Dir \x01bescheren mag, laß Dich niemals \x01entmutigen...\x02", "box_type": 0},
    {"id": 0x2071, "text": "Vor Dir liegt der Hylia-See.\x01Sein Wasser ist rein und klar...\x0C\x28Die \x05\x43Zoras\x05\x40, die im Osten des Landes\x01leben, sind die Hüter des Tempels,\x01der sich auf dem Grund des Sees\x01befindet...\x04Willst Du Dir den Ort auf Deiner\x01Karte betrachten, so drücke \x01\x05\x41START\x05\x40 und begib Dich mit\x05\x41 \x05\x44¤\x05\x40 \x01oder \x05\x44£\x05\x40 zum \x05\x43Karten-Bildschirm\x05\x40.\x04Alle Orte, an denen Du schon \x01einmal warst, werden Dir auf der\x01Karte angezeigt...\x0B\x02", "box_type": 0},
    {"id": 0x2072, "text": "\x1AGeh nun!\x02", "box_type": 0},
    {"id": 0x2073, "text": "\x1AWie lautet Dein Name?\x0B\x02", "box_type": 0},
    {"id": 0x2074, "text": "\x1A\x14\x01Ich fühle etwas...\x14\x00\x04\x1A\x05\x42\x0F\x05\x40...\x04\x1ASeltsam... Er kommt mir so... \x01vertraut vor.\x0B\x02", "box_type": 0},
    {"id": 0x2075, "text": "\x1ASo sei es, \x0F...\x04\x1AIch werde Dich nun in das\x01Geheimnis des Heiligen Reiches\x01einweihen, das seit Generationen\x01von meiner Familie gehütet wird.\x0B\x02", "box_type": 0},
    {"id": 0x2076, "text": "\x06\x23Die Okarina der Zeit!\x0B\x02", "box_type": 0},
    {"id": 0x2077, "text": "Hast Du die Geschichte, die ich\x01Dir anvertraute, verstanden?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x2078, "text": "\x1AIch habe gerade durch dieses\x01Fenster hier geschaut...\x04\x1AEines der Elemente aus meinem\x01Traum... Die\x05\x43 dunklen Wolken\x05\x40...\x01Ich glaube, sie symbolisieren...\x01...diesen Mann dort!\x04Möchtest Du ihn Dir anschauen?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x2079, "text": "\x1A\x14\x01Ich weiß...\x14\x00 Er ist es!\x04\x1ANatürlich erzählte ich meinem Vater \x01von dem Traum.\x04\x1ADoch er glaubte mir nicht, daß der\x01Traum eine Prophezeiung sei!\x04\x1ADoch glaube mir... Ich spüre die \x01böse Aura dieses Mannes!\x0B\x02", "box_type": 0},
    {"id": 0x207A, "text": "\x1AGanondorf hat es auf nichts\x01anderes als das \x05\x41Triforce\x05\x40 des \x01Heiligen Reiches abgesehen...\x04\x1ANur das scheint sein Begehr!\x04\x1AUm sein Ziel zu erreichen, muß\x01er Hyrule, nein, die gesamte Welt\x01unterwerfen!\x0B\x02", "box_type": 0},
    {"id": 0x207B, "text": "\x1A\x0F... Wir sind die \x01einzigen, die Ganondorfs Pläne\x01durchkreuzen können!\x0B\x02", "box_type": 0},
    {"id": 0x207C, "text": "\x1AWir müssen verhindern, daß \x01Ganondorf in den Besitz des\x01Triforce gelangt!\x04\x1AIch werde die \x05\x44Okarina der Zeit\x01\x05\x40mit all meiner Kraft schützen! \x01Niemals soll er sie erhalten!\x04\x1ADeine Aufgabe sei es, die\x01verbliebenen Heiligen Steine zu\x01finden! Sie sind der Schlüssel zum\x01Heiligen Reich...\x04\x1ALaß uns das Triforce suchen und\x01mit dessen Kraft Ganondorf \x01bezwingen!\x0B\x02", "box_type": 0},
    {"id": 0x207D, "text": "\x1AEines noch...\x01Nimm diesen \x05\x41Brief \x05\x40an Dich.\x01Ich bin sicher, Du wirst ihn \x01brauchen können...\x0B\x02", "box_type": 0},
    {"id": 0x207E, "text": "\x1AGähn...\x01Was?! Bin ich schon wach?\x04\x1AEs scheint so...\x04\x1AHey, wenn das nicht der Junge\x01aus den Wäldern ist!\x01Vielen Dank nochmal, daß Du\x01mich geweckt hast!\x04\x1AEs hat ganz schön lange gedauert, \x01bis ich Malon beruhigt hatte.\x04\x1AWas hast Du denn heute so vor?\x01Nichts besonderes? Nun, wie wäre\x01es dann mit einem kleinen\x01Spielchen? Hast Du Lust?\x04\x1ADie drei Hühner hier sind\x01\x05\x41Super-Hühner\x05\x40!\x04\x1AIch werde sie nun mit den\x01anderen, herkömmlichen Hühnern\x01vermischen...\x04\x1AGelingt es Dir, sie innerhalb einer\x01bestimmten Zeit aus allen anderen \x01herauszupicken, werde ich Dich\x01mit \x05\x41etwas Nützlichem \x05\x40belohnen!\x04Ein Spiel kostet 10 Rubine!\x01Machst Du mit?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x207F, "text": "Gähn...\x01Schon gut... Ich bin ja wach!\x04Was?!\x04Hey, der Kokiri-Junge!\x01Hast Du ein bißchen Zeit?\x01Dann laß uns spielen!\x04Ich vermische diese drei \x05\x41Super-\x01Hühner\x05\x40 mit den herkömmlichen \x01Hühnern...\x04Gelingt es Dir, sie innnerhalb einer \x01bestimmten Zeit aus allen anderen\x01Hühnern herauszupicken, belohne \x01ich Dich mit \x05\x41etwas Nützlichem\x05\x40!\x04Ein Spiel kostet 10 Rubine!\x01Willst Du es versuchen?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x2080, "text": "Du hast 30 Sekunden!\x01Jetzt geht's los!\x01Hier sind die Super-Hühner!\x04\x06\x42FINDE SIE!\x0B\x02", "box_type": 0},
    {"id": 0x2081, "text": "Die Zeit ist um!\x01Oh, wie schade!\x04Die Super-Hühner sind genial!\x01Jetzt bringen sie mir sogar noch\x01Geld ein!\x04Kommt zu Daddy, ihr Süßen!\x0B\x02", "box_type": 0},
    {"id": 0x2082, "text": "Das ist eins von ihnen!\x01Such weiter! Schnell!\x01\x05\x41Zwei\x05\x40 mußt Du noch finden!\x0B\x02", "box_type": 0},
    {"id": 0x2083, "text": "Wieder eins!\x01Jetzt kommt's drauf an! \x05\x41Eins\x05\x40\x01fehlt noch!!\x0B\x02", "box_type": 0},
    {"id": 0x2084, "text": "Wow! Unglaublich!\x01Du hast ein gutes Gespür!\x04Du hast sie tatsächlich\x01alle gefunden!\x01Komm her zu mir!\x0B\x02", "box_type": 0},
    {"id": 0x2085, "text": "Willst Du es nochmal versuchen?\x01Ein junger Kerl wie Du hat doch\x01sicher Hummeln im Hintern!\x04Du mußt nur in 30 Sekunden \x01die richtigen drei Hühner finden.\x04Willst Du es für 5 Rubine\x01versuchen?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x2086, "text": "Hey, Junge!\x01Du hast das Zeug dazu, ein \x01verdammt guter Farmer zu \x01werden!\x04Ich würde mich freuen, wenn Du \x01Malon heiraten würdest! Na?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x2087, "text": "\x1AHahaha, war doch nur Spaß!\x04\x1AOh, hier, nimm diese Flasche\x01\x05\x41Lon Lon-Milch \x05\x40an Dich. Sie gibt \x01Dir neue Energie, sobald Du sie \x01trinkst!\x04\x1AHast Du die \x05\x41Flasche\x05\x40 geleert,\x01kannst Du jederzeit zurückkommen\x01und sie Dir gegen ein geringes\x01Entgelt auffüllen lassen!\x0B\x02", "box_type": 0},
    {"id": 0x2088, "text": "Hey Partner, Du bist echt in \x01Ordnung!\x04Wenn Du einmal erwachsen bist, \x01könntest Du auf der Farm \x01arbeiten...\x01Wir warten auf Dich!\x0B\x02", "box_type": 0},
    {"id": 0x2089, "text": "Hier, nimm diese leckere\x01\x05\x41Lon Lon-Milch \x05\x40an Dich!\x0B\x02", "box_type": 0},
    {"id": 0x208A, "text": "Hier! Nimm etwas von der\x01frischen Milch...\x04Oh? Schade...\x01Du hast leider keine leere\x01Flasche, oder?\x02", "box_type": 0},
    {"id": 0x208B, "text": "Gähn...\x01Ich bin wach!\x04Was?\x04Hey, \x0F!\x01Wenn Du Malon suchst, die ist\x01draußen! Oder bist Du zum \x01Spielen hergekommen?\x04Dann laß uns \x05\x41Super-Huhn-Suchen \x01\x05\x40spielen!\x05\x41 \x05\x40Oder willst Du nur \x01frische \x05\x41Lon Lon-Milch\x05\x40?\x04Was darf es sein?\x01\x1C\x05\x42Lon Lon-Milch - 30 Rubine\x01Super-Huhn-Suchen - 10 Rubine\x01Zurück\x05\x40\x02", "box_type": 0},
    {"id": 0x208C, "text": "\x08\x05\x41Du hast verloren!\x05\x40\x01Du hättest über alle Hindernisse\x01springen müssen!\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x208D, "text": "\x08\x05\x41Eine Runde noch!\x05\x40\x09\x0E\x14\x02", "box_type": 0},
    {"id": 0x208E, "text": "Du mußt auf die Hindernisse \x01frontal zureiten. Ist der Winkel zu \x01spitz, verweigert das Pferd!\x04Wenn Du es erneut versuchen \x01möchtest, steig auf und mach Dich \x01bereit!\x02", "box_type": 0},
    {"id": 0x208F, "text": "\x1ADu hast es geschafft!\x01\x05\x41\x17\x05\x40 ist neuer Parcours-Rekord!\x04\x1AFür diese herausragende Leistung \x01gebührt Dir eine Belohnung!\x04\x1AMein Präsent ist ein bißchen zu\x01unhandlich, um es Dir hier geben zu\x01können. Deshalb hab ich es direkt\x01in Dein Haus liefern lassen! Hihihi...\x02", "box_type": 0},
    {"id": 0x2090, "text": "Der bisherige Rekord beträgt \x01\x05\x4150 Sekunden\x05\x40.\x01Deine Bestzeit ist \x05\x41\x1E\x03\x05\x40.\x04Gelingt es Dir, den Rekord zu \x01brechen, bekommst Du ein \x01Geschenk von mir!\x01Also, gib Dein Bestes!\x04Los geht's!\x0B\x02", "box_type": 0},
    {"id": 0x2091, "text": "Deine Bestzeit beträgt \x05\x41\x1E\x03\x05\x40!\x01Kannst Du das noch unterbieten?\x01Komm schon, versuch es!\x0B\x02", "box_type": 0},
    {"id": 0x2092, "text": "Der bisherige Rekord beträgt\x01\x05\x4150 Sekunden\x05\x40. Brichst Du ihn, \x01erhältst Du mein Geschenk!\x04Also, streng Dich an und gib\x01alles!\x04Okay, es geht los!!\x0B\x02", "box_type": 0},
    {"id": 0x3000, "text": "\x1AEine große Ehre, Blutsbrüderschaft\x01mit einem Goronen zu schließen... \x01Du besitzt nun zwei Heilige Steine!\x01Suche nach dem Dritten!\x02", "box_type": 2},
    {"id": 0x3001, "text": "\x1AEine große Ehre, Blutsbrüderschaft \x01mit einem Goronen zu schließen... \x01Du besitzt nun alle Heiligen Steine!\x01Suche Prinzessin Zelda auf!\x02", "box_type": 2},
    {"id": 0x3002, "text": "Hallo... Das habe ich gegen das\x01\x05\x41Zertifikat\x05\x40 eingetauscht...\x02", "box_type": 0},
    {"id": 0x3003, "text": "Ich gebe es Dir als Geschenk...\x02", "box_type": 0},
    {"id": 0x3004, "text": "\x1AIch mag Dich, Kleiner!\x04\x1AWas hältst Du davon, wenn Du \x01und ich Blutsbrüder werden?!\x04\x1AKeine Angst, keine große Feier!\x01Nimm dies als Zeichen meiner\x01Freundschaft an Dich!\x02", "box_type": 0},
    {"id": 0x3005, "text": "\x06\x16Meine Hochachtung!\x0E\x1E\x02", "box_type": 0},
    {"id": 0x3006, "text": "Laß mich Dich in die Arme \x01schließen, Bruder!\x0E\x1E\x02", "box_type": 0},
    {"id": 0x3007, "text": "\x06\x51Oh...\x0C\x1E\x06\x51Wow!\x0C\x28\x06\x3F\x08Das groovt!\x09\x0C\x1E\x06\x2EYeah! Yeah! \x08Yeah!\x09\x0C\x28\x06\x34\x08Ein heißer Beat!\x09\x0C\x1E\x06\x4BGroovy!\x0C\x28\x06\x3ELet's dance!\x0C\x28\x06\x46\x08YEEEEAH!\x09\x0C\x28\x06\x44\x08YAHOOO!\x09\x02", "box_type": 0},
    {"id": 0x3008, "text": "\x1AIch bin ein \x05\x41Gorone\x05\x40, wir sind\x01Steinfresser und leben auf dem\x01Todesberg.\x04\x1ASiehst Du den riesigen Fels\x01dort drüben?\x04\x1AEr versperrt den Eingang zu\x01\x05\x41Dodongos Höhle\x05\x40. Die Höhle ist für\x01uns Goronen sehr wichtig, denn\x01dort lagert unsere Nahrung...\x04\x1AVor kurzem sind einige Dodongos\x01in der Höhle aufgetaucht. Seither  \x01war die Höhle für uns ein äußerst\x01gefährlicher Ort!\x04\x1AÜber dem Eingang der Höhle\x01sah ich einen \x05\x41Gerudo in schwarzer\x01Rüstung\x05\x40, der den Fels mit magischer\x01Kraft vor dem Eingang plazierte!\x07\x30\x2A\x02", "box_type": 0},
    {"id": 0x3009, "text": "Ich wünschte, ich könnte den \x01Eingang zu Dodongos Höhle\x01rechtzeitig mit einer \x05\x41Donnerblume\x01\x05\x40erreichen! Und...\x04\x08\x06\x44\x05\x41...BUMMS...\x05\x40\x09\x04...wäre der Höhleneingang wieder\x01frei und ich ein gefeierter Held!\x02", "box_type": 0},
    {"id": 0x300A, "text": "Ich stehe hier, um den\x01\x05\x41Donnerblumen \x05\x40Schatten zu\x01spenden.\x04Möchtest Du mich etwas \x01fragen?\x01\x1B\x05\x42Über die Donnerblumen\x01Über Dodongos Höhle\x05\x40\x02", "box_type": 0},
    {"id": 0x300B, "text": "Die Blumen, die dort wachsen, sind \x01\x05\x41Donnerblumen\x05\x40. Es sind explosive\x01Höhlenpflanzen, die nur auf diesem\x01Berg wachsen.\x04Die Blüte der Blume dient als \x01Material zur Bombenherstellung.\x04Jemand, der die Blumen nicht \x01kennt, sollte sich davor hüten, sie\x01zu pflücken!\x04Normalerweise wachsen sie nur in \x01dunklen Höhlen. Daher ist \x01dieses Exemplar hier\x01sehr selten.\x02", "box_type": 0},
    {"id": 0x300C, "text": "Die Blumen, die dort wachsen, sind \x01\x05\x41Donnerblumen\x05\x40. Es sind explosive\x01Höhlenpflanzen, die nur auf diesem\x01Berg wachsen.\x04Normalerweise wachsen sie nur in \x01dunklen Höhlen. Daher ist \x01dieses Exemplar hier\x01sehr selten.\x04Mit einem \x05\x41Goronen-Armband \x05\x40könnte \x01selbst ein kleines Kind wie\x01Du die Blumen mit \x05\x43 \x05\x40pflücken.\x02", "box_type": 0},
    {"id": 0x300D, "text": "Ist Dir auf Deinem Weg hierher \x01die Höhle aufgefallen? Dies ist \x01\x05\x41Dodongos Höhle\x05\x40.\x04Weil es im Inneren nur wenig Licht \x01gibt, wachsen dort sehr viele\x01\x05\x41Donnerblumen\x05\x40!\x02", "box_type": 0},
    {"id": 0x300E, "text": "\x1ANanu?\x04\x1ANur selten verirren sich Leute\x01hierher! Woher kommst Du?\x04\x1AAus dem Wald?\x04\x1AWas ist das, \"Wald\"?\x04\x1AWas?\x04\x1ADort wachsen \"Bäume\" und \x01\"Pflanzen\"?\x04\x1ADas verwirrt mich... \x01Hier oben wächst außer den \x01\x05\x41Donnerblumen\x05\x40 gar nichts...\x04\x1AWir haben hier auch weder\x01Deku-Kerne noch Deku-Nüsse.\x04\x1AUnd selbst Deku-Stäbe findet man\x01hier höchst selten.\x07\x30\x22\x02", "box_type": 0},
    {"id": 0x300F, "text": "Ich hatte den Eingang versiegelt,\x01da ich nicht sehr viel zu \x01verkaufen habe... Du aber scheinst\x01sehr hartnäckig zu sein. Nun gut.\x0B\x02", "box_type": 0},
    {"id": 0x3010, "text": "Tut mir leid... Die Bombe hier ist \x01nur eine Attrappe. Die echten \x01sind \x05\x41ausverkauft\x05\x40.\x0B\x02", "box_type": 0},
    {"id": 0x3011, "text": "Hey, warum hast Du mich \x01aufgehalten? Das mag ich gar \x01nicht!\x04Ich war gerade so schön in Fahrt!\x04Auf diese Weise kann man \x01wunderbar Streß abbauen!\x04Laß mich jetzt weiterrollen!\x01Rock'n'Roll!\x02", "box_type": 0},
    {"id": 0x3012, "text": "\x1ADu bist mutig! Das soll belohnt \x01werden! Nimm dies als Zeichen \x01meiner Anerkennung!\x0B\x02", "box_type": 0},
    {"id": 0x3013, "text": "Hab Dank! An meinem Downhill-Roll \x01kannst Du erkennen, wie sehr ich \x01mich freue!\x02", "box_type": 0},
    {"id": 0x3014, "text": "\x1A\x06\x21Oh... Ich bin so hungrig...\x04\x1AJeder hier muß Hunger leiden,\x01weil der Eingang zur Höhle \x01verschlossen ist. Wir sind vom  \x01Aussterben bedroht!\x04\x1AWenn es nur eine Möglichkeit\x01gäbe,\x05\x41 Dodongos Höhle \x05\x40zu öffnen.\x04\x1ASeit Wochen ist sie verschüttet.\x01Es ist so tragisch...\x04\x1AIn der Höhle lagern die besten \x01und köstlichsten Steinvorräte. \x01Doch wie es scheint, müssen wir \x01nun auf diesen Genuß verzichten.\x04\x1ADabei sind wir Goronen \x01Feinschmecker, die sich nur\x01schwerlich an andere Nahrung\x01gewöhnen können!\x07\x30\x15\x02", "box_type": 0},
    {"id": 0x3015, "text": "Seufz... Wie gern würde ich jetzt \x01ein Stück Steinfilet aus \x05\x41Dodongos\x01Höhle \x05\x40genießen...\x02", "box_type": 0},
    {"id": 0x3016, "text": "\x1AHey!\x04\x1AEin kleines Kind wie Du muß \x01einen guten Grund haben, um \x01diesen Ort aufzusuchen!\x04\x1AIch hatte also recht! Du bist\x01hier, um den \x05\x41Roten Stein\x05\x40 zu \x01fressen! Nun, da kommst Du zu \x01spät! Er ist fort!\x04\x1AWas? Das ist gar nicht der \x01Grund, der Dich herführte?\x04\x1ADu suchst einen Heiligen\x01Stein? Damit mußt Du den \x01leckeren Roten Stein meinen, der\x01vor kurzem noch hier lag!\x04\x1AIch war so hungrig, daß ich \x01dachte, es wäre in Ordnung, nur \x01ein kleines Stückchen davon zu \x01essen. Als ich kam, war er fort!\x04\x1AVielleicht hat ihn Darunia\x01weggenommen...\x04\x1AEr sagte, es gefällt ihm nicht, daß\x01alle immer so gierig schauen,\x01wenn sie den Roten Stein \x01betrachten.\x07\x30\x17\x02", "box_type": 0},
    {"id": 0x3017, "text": "Darunia hat sich in seinem Raum\x01eingeschlossen. Er sprach:\x01\"\x05\x41Ich werde hier auf den Boten \x01der Königsfamilie warten!\x05\x40\"\x02", "box_type": 0},
    {"id": 0x3018, "text": "\x1AIch bin so hungrig, ich kann an \x01nichts anderes mehr denken...\x04\x1ASuche Darunia auf, um Antwort\x01auf Deine Fragen zu finden.\x04\x1AZur Zeit ist er sehr schlecht \x01gelaunt... Dann kann er sehr \x01abweisend sein...\x04\x1ADoch ich weiß, wie man ihn\x01aufheitern kann...\x04\x1AEr mag zwar nicht so aussehen,\x01doch er liebt Musik! Wann immer \x01er ein Lied hört, muß er tanzen...\x07\x30\x19\x02", "box_type": 0},
    {"id": 0x3019, "text": "Ich kann mich erinnern, daß\x01Darunia besonders die \x05\x42Musik\x01des Waldes \x05\x40mochte...\x04Das waren noch Zeiten...\x01Die Musik weckt in mir \x01Erinnerungen an vergangene Tage...\x07\x30\x2C\x02", "box_type": 0},
    {"id": 0x301A, "text": "\x1AWas?! Wer bist Du?!\x04\x1AAls ich \x05\x43das Lied der Königsfamilie\x01\x05\x40hörte, dachte ich, ein Abgesandter \x01sei eingetroffen...\x01Stattdessen sehe ich ein Kind!\x04\x1AHat \x05\x41Darunia\x05\x40, der Führer der \x01Goronen, es wirklich verdient,\x01so behandelt zu werden?\x04\x1AIch kann es nicht glauben!\x01Geh zurück ins Schloß und sag\x01dem König, er solle mir einen\x01richtigen Mann schicken!\x04\x1ADu fragst, warum ich so schlecht\x01gelaunt bin?\x04\x1A\x08Dämonische Kreaturen sind in \x01Dodongos Höhle eingedrungen...\x09\x04\x1A\x08Die Donnerblumen-Ernte war\x01schlecht...\x09\x04\x1A\x08Und zudem leidet mein Volk\x01Hunger...\x09\x04\x1A\x06\x1CDoch wie dem auch sei...\x07\x30\x1B\x02", "box_type": 0},
    {"id": 0x301B, "text": "\x08\x06\x11Dies ist Sache der Goronen!\x09\x04\x08\x06\x0BWir sind zu stolz, um die Hilfe\x01\x06\x06Fremder in Anspruch zu nehmen!\x09\x02", "box_type": 0},
    {"id": 0x301C, "text": "\x1A\x08\x06\x27Wow! Cooler Sound!\x09\x04\x1AMeine schlechte Laune ist \x01verflogen! Ich konnte mich nicht\x01mehr halten, ich mußte einfach \x01tanzen!\x04\x1A\x06\x3CIch bin \x05\x41Darunia\x05\x40!\x04\x1AIch bin der Anführer der Goronen!\x01Gibt es etwas, das ich für Dich\x01tun kann?\x04\x1A\x06\x50Wie?\x04\x1ADu suchst den \x05\x41Heiligen Stein\x01des Feuers\x05\x40?\x04\x1ADer Heilige Stein des Feuers, auch \x01als Goronen-Opal bekannt, ist das \x01wertvollste Relikt meines Volkes...\x04\x1AIch kann ihn Dir erst geben, \x01wenn Du meinem Volk beweist, \x01daß Du seiner würdig bist...\x04\x1ABeweise Dich, indem Du die \x01Kreaturen in Dodongos Höhle \x01vertreibst!\x04\x1ABestehst Du diese Prüfung, ist  \x01Dir der Dank meines Volkes gewiß.\x01Der Lohn für Deine Mühe soll der\x01Heilige Stein sein!\x04\x1ABevor Du gehst, nimm dies\x01an Dich. Es ist ein Gastgeschenk\x01der Goronen, ein Zeichen der\x01Freundschaft.\x04\x1ATrägst Du es, kannst sogar Du \x01schwere Dinge wie \x05\x41Donnerblumen\x05\x40 \x01mit\x05\x41 \x05\x43 \x05\x40heben.\x02", "box_type": 0},
    {"id": 0x301D, "text": "Vernichte die Kreaturen in \x01\x05\x41Dodongos Höhle \x05\x40und beweise, daß \x01Du meiner Freundschaft würdig \x01bist! Denk an den Heiligen Stein!\x02", "box_type": 0},
    {"id": 0x301E, "text": "Hey, Bruder! Komm mal wieder\x01vorbei und spiele ein paar Lieder!\x02", "box_type": 0},
    {"id": 0x301F, "text": "Egal, wie oft ich dieses Lied höre, \x01es wird nie langweilig!\x02", "box_type": 0},
    {"id": 0x3020, "text": "Hmmm, ganz gut... Aber nicht\x01genau das, was ich hören wollte...\x04Ich mag Melodien... Wie soll ich \x01sagen... Von außerhalb... etwas\x01Natürliches... Grünes... aus dem \x01Wald...\x04Das ist meine Art von Musik!\x02", "box_type": 0},
    {"id": 0x3021, "text": "Dank Deiner Hilfe können wir \x01wieder in die Höhle. Du bist ein \x01wahrer Held!\x02", "box_type": 0},
    {"id": 0x3022, "text": "Ich verrate Dir etwas! Willst Du\x01einen brennenden Stab löschen, \x01so drücke \x05\x43\x05\x40, bevor er ganz\x01abgebrannt ist!\x04Apropos... Ich habe hier irgendwo\x01einen Stab versteckt...\x02", "box_type": 0},
    {"id": 0x3023, "text": "\x1AIch bin es, \x05\x41Darunia\x05\x40!\x01Du hast Deine Prüfung bestanden!\x04\x1ADank Deiner Hilfe können wir\x01nun wieder die schmackhaften\x01Steine aus der Höhle verspeisen!\x02", "box_type": 0},
    {"id": 0x3024, "text": "\x1AIch habe solchen Hunger, daß \x01ich nur ans Essen denken kann!\x04\x1AHeiliger Stein?\x01Du meinst sicher den \x05\x41Roten Stein\x05\x40, \x01der einst in unserer Stadt\x01erstrahlte?\x04\x1A\x05\x41Darunia\x05\x40 nahm ihn an sich...\x01Danach schloß er sich in seinem\x01Raum ein und hat ihn seitdem\x01nicht mehr verlassen.\x04\x1ASeit dieser Zeit ist es dunkel\x01in Goronia. Die Dunkelheit macht\x01uns depressiv. Alles erscheint so \x01sinnlos...\x07\x30\x25\x02", "box_type": 0},
    {"id": 0x3025, "text": "Ich wünschte, jemand würde die \x01Fackeln bei der Goronenstatue \x01entzünden. Ich glaube, in Darunias\x01Kammer findet man \x05\x41Feuer\x05\x40...\x02", "box_type": 0},
    {"id": 0x3026, "text": "Ah, ich verstehe...\x01Wir hätten die Bombe von der \x01Klippe aus werfen sollen...\x02", "box_type": 0},
    {"id": 0x3027, "text": "Du hast alle Dodongos vernichtet! \x01Das ist unglaublich! Laß mich Dich \x01Bruder nennen!\x02", "box_type": 0},
    {"id": 0x3028, "text": "Dank Deiner Bemühungen ist alles \x01wieder wie früher! Nun kann ich \x01Dir auch Bomben anbieten!\x0B\x02", "box_type": 0},
    {"id": 0x3029, "text": "Sollte ich jemals ein Kind haben, \x01werde ich es nach Dir benennen!\x02", "box_type": 0},
    {"id": 0x302A, "text": "Wenn Du schon hier bist, solltest\x01Du auch \x05\x41Goronia\x05\x40 besuchen!\x04Die Stadt liegt weiter oben auf\x01dem Berg. Es ist gar nicht mehr\x01weit bis dorthin.\x02", "box_type": 0},
    {"id": 0x302B, "text": "Mit \x05\x43\x05\x40 nimmst Du die \x01Donnerblumen auf. Drückst Du \x01erneut \x05\x43\x05\x40, legst Du sie wieder ab.\x02", "box_type": 0},
    {"id": 0x302C, "text": "Die Fackeln sind ein Symbol des\x01Lebens in Goronia. Würden sie\x01alle brennen, wäre es hier\x01sicher wieder schöner!\x02", "box_type": 0},
    {"id": 0x302D, "text": "Du hast vor, die Dodongos zu \x01vertreiben? Das ist Sache der \x01Goronen und keine Angelegenheit\x01für kleine Kinder!\x04Andererseits wären wir froh, wenn \x01unser Problem gelöst würde. Dann \x01könnten wir endlich wieder Bomben \x01produzieren...\x04Dennoch solltest Du Dich vor den\x01Dodongos hüten! Diese Kreaturen \x01fressen alles, was sich ihnen in \x01den Weg stellt!\x04Wenn Du nicht aufpaßt, endest Du \x01im Magen eines Dodongo!\x0B\x02", "box_type": 0},
    {"id": 0x302E, "text": "Ich hatte es Dir doch schon \x01gesagt! Bomben sind ausverkauft!\x01Wenn ich nur nicht solchen Hunger\x01hätte!\x0A\x02", "box_type": 0},
    {"id": 0x302F, "text": "Wie fühlt sich Darunia?\x01Oh, ich verstehe...\x04Übrigens... Kennst Du die\x01Melodie, die durch diesen Tunnel\x01in unser Reich dringt? Wir mögen\x01sie sehr!\x02", "box_type": 0},
    {"id": 0x3030, "text": "Mich wirst Du nicht kriegen! \x01Sicher bist Du einer von \x01Ganondorfs Schergen!\x02", "box_type": 0},
    {"id": 0x3031, "text": "\x1AWie konnte Dir das gelingen?\x01Du bist einer von Ganondorfs \x01Leuten...\x04\x1AHöre meinen Namen und neige \x01Dein Haupt in Ehrfurcht!\x04\x1AIch bin \x05\x41\x0F\x05\x40! \x01Der größte Krieger der Goronen!\x02", "box_type": 0},
    {"id": 0x3032, "text": "\x1AWas?\x04\x1AAuch Dein Name ist\x01\x0F?\x04\x1ADann mußt Du der legendäre\x01Dodongo-Jäger sein, der mächtige \x01\x0F!\x04\x1A\x05\x41Darunia \x05\x40ist mein Vater...\x01Kennst Du ihn?\x04\x1AEr\x05\x41 \x05\x40benannte mich nach Dir,\x05\x41\x01\x05\x40weil Du tapfer bist und viel für\x01uns getan hast!\x04\x1AMir gefällt der Name!\x01Ich könnte mir keinen besseren \x01vorstellen!\x04\x1A\x0F, für uns bist Du \x01ein echter Volksheld! \x01Ich bin stolz, Dich kennengelernt \x01zu haben!\x04\x1AGib mir bitte ein Autogramm!\x01Schreib:\x01\x06\x05\"Für meinen Freund \x01\x06\x05\x0F, den Goronen!\"\x04\x1AOh...\x04\x1AEs mag ein schlechter Zeitpunkt \x01sein, Dich erneut um Hilfe zu \x01bitten, doch hör mich an...\x04\x1AMein Vater Darunia begab sich \x01zum \x05\x41Feuertempel\x05\x40! Dort lebt ein \x01Höllendrache!\x04\x1AWenn wir uns nicht beeilen,\x01ist mein Vater verloren!\x07\x30\x33\x02", "box_type": 0},
    {"id": 0x3033, "text": "Heul... Schnüff... Daddy...\x0B\x02", "box_type": 0},
    {"id": 0x3034, "text": "Du solltest ihn beruhigen, wenn\x01Du kannst...\x01Am besten Du fragst ihn einfach \x01etwas!\x04Worüber willst Du ihn befragen?\x01\x01\x1B\x05\x42Über den Drachen\x01Über die Goronen\x05\x40\x02", "box_type": 2},
    {"id": 0x3035, "text": "\x1AVor langer Zeit lebte eine\x01diabolische Kreatur namens \x01\x05\x41Volvagia \x05\x40in den Höhlen dieses \x01Berges.\x04\x1ADiese Drachenkreatur wütete\x01auf grausamste Art. Sie fraß \x01Goronen bei lebendigem Leib...\x04\x1AMit Hilfe eines legendären\x01Hammers gelang es schließlich,\x01Volvagia zu vernichten!\x04\x1ASo erzählt die Legende aus \x01vergangenen Zeiten.\x01Ich weiß, daß sie wahr ist!\x04\x1AEiner der Vorfahren meines\x01Vaters war nämlich derjenige,\x01der die Kreatur vernichtete!\x07\x30\x33\x02", "box_type": 0},
    {"id": 0x3036, "text": "\x1AVater war gerade nicht hier, \x01als alle von Ganondorf in den\x05\x41 \x01Feuertempel \x05\x40verschleppt wurden.\x04\x1AEs war schrecklich!\x01Ganondorfs Leute fielen in unsere\x01Stadt ein und nahmen alle \x01gefangen...\x04\x1AJetzt sollen sie \x05\x41Volvagia \x05\x40geopfert \x01werden!\x04\x1AVater sagte, daß Ganondorf die\x01Drachenkreatur wiedererweckt hat.\x04\x1AAls Warnung an alle, die sich\x01ihm widersetzen, will der Tyrann\x01die Goronen dem Drachen Volvagia \x01zum Fraß vorwerfen!\x04\x1AAlso brach Vater ganz allein\x01zum Tempel auf, um sie \x01zu befreien...\x04\x1ABitte hilf ihm, \x0F!\x01Möge diese \x05\x41Goronen-Rüstung \x05\x40zum\x01Gelingen Deiner Mission beitragen!\x02", "box_type": 0},
    {"id": 0x3037, "text": "\x1AVater sagte mir, ich solle nicht\x01zulassen, daß ihm irgendjemand \x01folgt...\x04\x1ADoch bei Dir, \x0F, ist\x01das etwas anderes! Ich bin mir \x01sicher, daß nur Du uns helfen \x01kannst!\x04\x1ASicher hilft Dir auch der \x01Ladenbesitzer weiter. Er hat sich\x01irgendwo versteckt...\x04\x1ALaß mich Dir nun den geheimen\x01Pfad zum Feuertempel zeigen!\x07\x30\x38\x02", "box_type": 0},
    {"id": 0x3038, "text": "Versuche, die \x05\x41Statue \x05\x40in Vaters \x01Raum zu verschieben!\x02", "box_type": 0},
    {"id": 0x3039, "text": "\x1AWer ist da? Bist Du es,\x01\x0F?\x04\x1ATatsächlich! \x0F!\x04\x1ADu bist erwachsen geworden, ein\x01richtiger Mann!\x04\x1AGerne würde ich mich länger mit\x01Dir unterhalten, doch die Zeit \x01drängt...\x04\x1AErneut hat Ganondorf Chaos\x01gesät! Er hat die infernalische\x01Drachenkreatur Volvagia aus dem \x01Reich der Toten zurückgeholt!\x04\x1AZudem will er die gefangenen\x01Goronen der Bestie zum Fraß\x01vorwerfen. Als Warnung an alle,\x01die ihm trotzen...\x04\x1AWenn das feuerspeiende Ungetüm\x01aus den Höhlen des Tempels \x01entkommt, wird Hyrule in einem \x01flammenden Inferno versinken!\x04\x1AIch werde vorgehen und \x01versuchen, die Kreatur zu \x01bezwingen...\x04\x1ADas wird nicht leicht, denn\x01mir fehlt die Waffe, die in der\x01alten Sage Erwähnung findet.\x01Doch mir bleibt keine Wahl...\x04\x1A\x0F... Als Dein Bruder \x01bitte ich Dich um diesen Gefallen...\x04\x1AWährend ich die Bestie fordere,\x01sollst Du meine Leute retten!\x04\x1ADie Zellen, in die man sie \x01gesperrt hat, sind über den\x01gesamten Tempel verteilt!\x01Hilf mir, \x0F!\x02", "box_type": 0},
    {"id": 0x303A, "text": "Ich bin gerettet!\x01Hab Dank!\x01Bitte, nimm dies!\x02", "box_type": 0},
    {"id": 0x303B, "text": "\x1A\x0F... Schnell... \x01Ich kann die Last nicht\x01länger tragen...\x04\x1ARaus hier!\x02", "box_type": 0},
    {"id": 0x303C, "text": "\x1ADank sei Dir, mein Bruder!\x01Ich weiß das, was Du getan hast,\x01sehr zu schätzen. Hab Dank, auch\x01im Namen meines Volkes!\x04\x1ADu hast Dich als würdiger Streiter\x01erwiesen! Ich habe nie an Dir \x01gezweifelt...\x02", "box_type": 0},
    {"id": 0x303D, "text": "\x06\x47Vergiß nie...\x01\x06\x0CDu und ich, wir sind nun Brüder!\x0E\x50\x02", "box_type": 5},
    {"id": 0x303E, "text": "\x1AWahre Freundschaft wächst, je\x01länger sie besteht. \x01Sie wächst im Herzen und wird \x01mit jeder Minute stärker...\x04\x1ADie leidenschaftliche Blüte \x01der Freundschaft, die jetzt schon\x01in Dir reift, wird Dir weisen den\x01richtigen Weg...\x04\x1ADiese Melodie sei der Kraft \x01der Freundschaft gewidmet!\x01Lausche nun dem \x05\x41Bolero des \x01Feuers\x05\x40!\x02", "box_type": 0},
    {"id": 0x303F, "text": "\x1A\x0F... Bis bald...\x02", "box_type": 0},
    {"id": 0x3040, "text": "\x08\x05\x44\x0F, in dieser Höhle \x01herrscht extreme Hitze! \x01Lange können wir hier nicht \x01bleiben!\x05\x40\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x3041, "text": "\x1ABruder \x0F!\x01Daddy ist zurück!\x01Und auch die anderen!\x04\x1AVater und Du, ihr habt den\x01Drachen gemeinsam bezwungen!\x07\x30\x42\x02", "box_type": 0},
    {"id": 0x3042, "text": "Wenn ich groß bin, möchte\x01ich genauso werden wie Du, \x01\x0F!\x02", "box_type": 0},
    {"id": 0x3043, "text": "Danke, \x0F!\x02", "box_type": 0},
    {"id": 0x3044, "text": "Dank sei Dir, denn Du hast uns \x01gerettet!\x0A\x02", "box_type": 0},
    {"id": 0x3045, "text": "\x1AIch, Darunia, offenbare mich\x01Dir als einer der Sieben Weisen... \x01Der \x05\x41Weise des Feuers\x05\x40...\x04\x1AHättest Du das erwartet?\x01Ich denke das ist es, was\x01man Schicksal nennt...\x04\x1AWenn ich Dir helfen kann, das\x01Böse in seine Schranken zu \x01weisen, laß es mich wissen.\x02", "box_type": 0},
    {"id": 0x3046, "text": "\x1ANimm dies an Dich, Bruder!\x01Dieses \x05\x41Amulett \x05\x40enthält die Kräfte\x01der Geister des Feuers... und der\x01Freundschaft.\x02", "box_type": 0},
    {"id": 0x3047, "text": "Alle sind verschwunden!\x01Dennoch, der Shop bleibt \x01geöffnet!\x0A\x02", "box_type": 0},
    {"id": 0x3048, "text": "\x1AWelch aufregendes Abenteuer...\x01Es liefert Stoff für eine \x01Legende...\x04\x1ANoch immer kann ich nicht \x01glauben, daß die Dodongos, die wir \x01für ausgestorben hielten, in so\x01großer Anzahl zurückkehrten...\x04\x1AUnd der Fels, der den Eingang \x01der Höhle versperrte...\x04\x1AFür all dies war \x05\x41Ganondorf\x05\x40,\x05\x41\x01\x05\x40der Gerudokönig, verantwortlich.\x04\x1AEr sprach: \x01\"\x05\x44Gebt mir den Heiligen Stein und\x01ich werde eure Höhle wieder \x01öffnen!\x05\x40\"\x04\x1ADu hast Dein Leben für uns \x01riskiert...\x02", "box_type": 0},
    {"id": 0x3049, "text": "\x06\x4BPaßt genau...\x02", "box_type": 0},
    {"id": 0x304A, "text": "Ich arbeite gerade an etwas sehr \x01Interessantem! Doch ich denke, es\x01wird noch eine Weile dauern...\x07\x30\x4B\x02", "box_type": 0},
    {"id": 0x304B, "text": "Ich schätze, in fünf oder sechs\x01Jahren dürfte es fertig sein!\x02", "box_type": 0},
    {"id": 0x304C, "text": "Ich habe eine Waffe fertiggestellt.\x01Wie wär's damit?\x07\x30\x4F\x02", "box_type": 0},
    {"id": 0x304D, "text": "Das Schwert ist doch kunstvoll\x01geschmiedet, nicht wahr?\x02", "box_type": 0},
    {"id": 0x304E, "text": "Oh, es scheint da ein Problem mit \x01der Stabilität zu geben.\x01Aber warte mal...\x07\x30\x4F\x02", "box_type": 0},
    {"id": 0x304F, "text": "Möchtest Du vielleicht DIESE\x01Waffe für 200 Rubine kaufen?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x3050, "text": "Nun gut, komm später wieder.\x02", "box_type": 0},
    {"id": 0x3051, "text": "Bitte... Bitte friß mich nicht!\x01Wenn Du mich frißt, wird Dir \x01ganz schlecht werden!\x04Du würdest es bereuen!\x02", "box_type": 0},
    {"id": 0x3052, "text": "Ah, sicher hat Darunia Dich um\x01Hilfe gebeten! Du hast etwas bei\x01mir gut!\x04Hilf Darunia!\x02", "box_type": 0},
    {"id": 0x3053, "text": "Mein Bruder...\x01Er hat einen neuen Laden...\x01Es ist Medigorons \x01Waffengeschäft...\x04Er ist gut... \x01Aber ich schmiede bessere\x01Klingen.\x04Die hylianischen Zimmerleute\x01wissen meine Arbeit zu schätzen.\x01Glaub mir...\x02", "box_type": 0},
    {"id": 0x3054, "text": "\x1AZweifelsohne eine Waffe aus \x01meiner Schmiede!\x01Ich würde sie reparieren...\x04\x1ADoch beim letzten Erdbeben ist mir \x01Lavastaub in die Augen geraten.\x01Seitdem sehe ich schlecht!\x04\x1AIn Zoras Reich gibt es wundersame\x01Augentropfen. Wende Dich an \x01\x05\x41König Zora\x05\x40...\x07\x30\x55\x02", "box_type": 0},
    {"id": 0x3055, "text": "Bitte, bringe mir die Augentropfen!\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x3056, "text": "Ich bitte Dich! Mir geht es gar \x01nicht gut... Meine Augen brennen!\x01Bitte...\x02", "box_type": 0},
    {"id": 0x3057, "text": "Oh nein! Alle sind verschwunden!\x01Ich blieb als einziger zurück!\x0B\x02", "box_type": 0},
    {"id": 0x3058, "text": "Ich warte hier auf Dich,\x01mit tränenden Augen...\x01Bitte grüße König Zora von mir!\x02", "box_type": 0},
    {"id": 0x3059, "text": "\x1ADu... Du bringst die Augentropfen!\x01Du bist meine Rettung! Ich werde\x01sie gleich ausprobieren!\x0B\x02", "box_type": 0},
    {"id": 0x305A, "text": "\x1A\x06\x59\x05\x41Wow!\x05\x40\x04\x1AUnglaublich! Grandios!\x01Ich kann wieder sehen!\x04\x1AEndlich kann ich wieder\x01schmieden! Hier, nimm dies und \x01schau in ein paar Tagen wieder \x01vorbei!\x07\x30\x5C\x02", "box_type": 0},
    {"id": 0x305B, "text": "Sie sind alle wieder da!\x01Es ist wieder wie früher!\x0B\x02", "box_type": 0},
    {"id": 0x305C, "text": "Noch einige Tage...\x01Gut Ding will Weile haben...\x01Gedulde Dich noch...\x02", "box_type": 0},
    {"id": 0x305D, "text": "Nein, noch immer nicht...\x01Es ist noch nicht fertig...\x01Du bist sehr ungeduldig...\x02", "box_type": 0},
    {"id": 0x305E, "text": "Hier ist es... Endlich!\x02", "box_type": 0},
    {"id": 0x305F, "text": "\x08\x05\x44Du hast Deinen \x05\x40Schild \x05\x44verloren!\x05\x40\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x3060, "text": "\x08\x05\x44Du hast Deine \x05\x40Rüstung \x05\x44verloren!\x05\x40\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x3061, "text": "\x08\x05\x44Du hast Deinen \x05\x40Schild \x05\x44verloren!\x05\x40\x01\x05\x44Du hast Deine \x05\x40Rüstung \x05\x44verloren!\x05\x40\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x3062, "text": "\x1ADu hast Dich bisher gut \x01geschlagen, \x0F. \x01Dies ist der Gipfel des \x01Todesberges!\x04\x1AMan sagt, die Wolken, die den \x01Gipfel umgeben, spiegeln den\x01Zustand des Berges wider. Sind\x01sie weiß, herrscht Friede.\x04\x1ADein Aufstieg zum Gipfel hat\x01mir bewiesen, wie tapfer Du bist!\x01Diese Tapferkeit soll nun erneut\x01geprüft werden...\x04\x1AEine mächtige \x05\x41Fee\x05\x40 lebt \x01hier oben. Sie ist die\x01Mutter aller Feen! Suche sie auf,\x01und sie wird Dich belohnen...\x04\x1AIch werde hier auf Dich warten.\x01Willst Du zurück zum Fuß des\x01Berges, so werde ich Dir helfen.\x01Geh nun!\x02", "box_type": 0},
    {"id": 0x3063, "text": "Du siehst erwachsener aus,\x01seit Du die Fee besucht hast...\x04Doch noch wirkst Du nicht wie \x01der prophezeite Retter Hyrules!\x01Hierfür fehlt Dir noch einiges!\x04Wenn Du \x05\x41zum Fuß des Berges\x05\x40 \x01zurück möchtest, kann ich Dich \x01mitnehmen. Komm her und halte \x01Dich an meinen Krallen fest!\x02", "box_type": 0},
    {"id": 0x3064, "text": "Man sagt, daß auf dem Gipfel des \x01Todesberges eine \x05\x41wunderschöne\x01Fee\x05\x40 lebt!\x04Wirst Du sie besuchen?\x02", "box_type": 0},
    {"id": 0x3065, "text": "Ich hörte, daß auf dem Gipfel des\x01Todesberges eine \x05\x41Fee\x05\x40 lebt.\x04Wenn Du dorthin möchtest, \x01solltest Du Dich mit einem\x01großen \x05\x44Schild\x05\x40 ausrüsten...\x02", "box_type": 0},
    {"id": 0x3066, "text": "\x08\x05\x44Wow! Du hast ein\x05\x40 Ei \x01\x05\x44ausgebrütet!\x01Ein \x05\x40Küken \x05\x44ist geschlüpft!\x05\x40\x09\x0E\x63\x02", "box_type": 2},
    {"id": 0x3067, "text": "Besitzt Du den Roten Stein? Laß \x01mich ein Stückchen probieren!\x04Nein? Buh!\x02", "box_type": 0},
    {"id": 0x3068, "text": "\x1ABruder! Du solltest stets daran\x01denken, Deine Kräfte zu erhöhen!\x04\x1ADie \x05\x41Fee\x05\x40 auf dem Gipfel des\x01Todesberges hilft Dir dabei!\x04\x1AFreunde, laßt uns unseren Bruder\x01verabschieden!\x02", "box_type": 0},
    {"id": 0x3069, "text": "\x1ADa Du mich befreit hast, verrate\x01ich Dir ein Geheimnis!\x04\x1AIn diesem Tempel gibt es \x05\x41Türen\x05\x40,\x01\x05\x41die Dich\x05\x40 beim Versuch, sie zu \x01öffnen, \x05\x41erschlagen\x05\x40! Sei gewarnt!\x04\x1ABesitzt Du das Relikt der Goronen,\x01kannst Du sie zerschmettern!\x02", "box_type": 0},
    {"id": 0x306A, "text": "\x1ADu hast mich gerettet! Dafür\x01offenbare ich Dir ein Geheimnis!\x04\x1AHast Du Feuer gefangen, so \x01schwinge Dein Schwert oder rolle\x01Dich über den Boden. So löschst\x01Du es schneller...\x02", "box_type": 0},
    {"id": 0x306B, "text": "\x1AHab Dank! Du bist mein Retter!\x01Höre meinen Ratschlag...\x04\x1AIn diesem Tempel wirst Du auf\x01Kreaturen treffen, die Dich \x01attackieren, während sie tanzen.\x01Gegen Pfeile sind sie immun...\x04\x1AFinde das Relikt der Goronen,\x01und Du wirst auch diese Gegner\x01bezwingen!\x02", "box_type": 0},
    {"id": 0x306C, "text": "\x1ALaß mich Dir als Dank\x01dafür etwas verraten!\x04\x1AEinige Schalter dieses Tempels\x01lassen sich nur mit Gewalt \x01aktivieren. Das Relikt der Goronen\x01kann Dir dabei behilflich sein!\x02", "box_type": 0},
    {"id": 0x306D, "text": "\x1AAls Dank für meine Befreiung \x01verrate ich Dir etwas!\x04\x1AFindest Du auf der Karte einen\x01Ort, den Du nicht erreichen \x01kannst, versuche es mit der \x01Okarina!\x02", "box_type": 0},
    {"id": 0x306E, "text": "\x1AAls Dank für meine Rettung\x01verrate ich Dir ein Geheimnis!\x04\x1AUm zu der Tür zu gelangen, hinter\x01der Darunia verschwunden ist,\x01mußt Du den Pfeiler, der aus der \x01Decke ragt, nach unten befördern!\x04\x1AFinde einen Weg, der Dich in\x01die oberen Stockwerke bringt!\x02", "box_type": 0},
    {"id": 0x306F, "text": "\x1ADu hast mich gerettet! Dafür\x01vertraue ich Dir etwas an!\x04\x1AIn der Eingangshalle des Tempels\x01befindet sich eine Statue.\x01Sie verbirgt eine Tür...\x04\x1AMit dem Relikt der Goronen\x01kannst Du auch dieses Problem\x01lösen!\x02", "box_type": 0},
    {"id": 0x3070, "text": "\x1ADanke! Laß mich Dir ein Geheimnis\x01anvertrauen...\x04\x1AWände, die Du mit dem Relikt\x01der Goronen zerstören kannst, \x01klingen hohl, wenn Du mit dem\x01Schwert dagegen schlägst.\x02", "box_type": 0},
    {"id": 0x3071, "text": "Die Qualen haben ein Ende!\x01Ich bin frei!\x0B\x02", "box_type": 0},
    {"id": 0x4000, "text": "\x1ADiese Augen schmecken göttlich!\x01Endlich kann ich mal wieder\x01gebratene Augäpfel in Sahnesoße\x01essen! Mmmmh...!\x04\x1AGroßartig! Richte König Zora\x01meinen Dank aus!\x01Bitte? Was willst Du?\x0B\x02", "box_type": 0},
    {"id": 0x4001, "text": "\x1ADu willst, daß ich \x05\x41Augentropfen\x05\x40 \x01\x05\x41für Biggoron\x05\x40 herstelle? Oh, wie\x01außerordentlich schade! Das\x01hättest Du gleich sagen sollen!\x0B\x02", "box_type": 0},
    {"id": 0x4002, "text": "\x1A\x0F!\x01Hier entlang!\x0C\x28\x1AIch frage mich, was \x05\x41Salia\x01\x05\x40gerade macht. Warum gehst Du\x01nicht mal wieder zu ihr?\x02", "box_type": 0},
    {"id": 0x4003, "text": "\x1AWas machst Du denn? Du hast\x01ja ganz schön lange gebraucht...\x0C\x28\x1AVielleicht solltest Du ab und zu\x01auf die \x05\x41Karte \x05\x40schauen.\x04\x1A\x0F, das hier ist ein \x01ruhiger See mit kristallklarem,\x01kühlem Wasser.\x04\x1AAuf seinem Grund befindet sich\x01der Zugang zum \x05\x43Wassertempel\x05\x40.\x01Die \x05\x43Zoras \x05\x40wachen über ihn.\x04\x1ADie Zoras sind Angehörige von\x01Zoras Reich im Nordosten Hyrules.\x01Sie sind stolze Amphibienwesen und\x01seit Urzeiten der Königsfamilie treu.\x04\x1AIch hörte, nur einem Angehörigen\x01der königlichen Familie würde der\x01Zutritt zu Zoras Reich gestattet!\x04\x1AIch bin übrigens gerade auf dem\x01Weg zum \x05\x41Schloß\x05\x40. Wenn Du mit mir\x01kommen möchtest, halte Dich an\x01meinen Krallen fest!\x02", "box_type": 0},
    {"id": 0x4004, "text": "Ich bin übrigens gerade auf dem\x01Weg zum \x05\x41Schloß\x05\x40. Wenn Du mit mir\x01kommen möchtest, halte Dich an\x01meinen Krallen fest!\x02", "box_type": 0},
    {"id": 0x4005, "text": "\x1A\x06\x56Nanu?\x04\x1ASieht aus, als wäre da etwas in\x01der Flasche drin...\x01Oh, es ist ein \x05\x41Brief\x05\x40:\x04\x1A\x08\x06\x39\x05\x45Hilf mir!\x01\x05\x40\x06\x2C\x05\x45Ich bin im Bauch von\x01\x05\x40\x06\x20\x05\x46Lord Jabu-Jabu\x05\x45 gefangen!\x01\x05\x40\x06\x5A\x05\x46Ruto\x05\x40\x09\x04\x1A\x08\x06\x34\x05\x45PS: Verrate bitte \x01\x05\x40\x06\x2D\x05\x45meinem Daddy nichts!\x05\x40\x09\x02", "box_type": 2},
    {"id": 0x4006, "text": "\x1AWer seid Ihr?\x04\x1AWir sind die \x05\x43Zoras\x05\x40, das stolze\x01hylianische Amphibiengeschlecht!\x04\x1ASo... Ihr behauptet, ein\x01Angehöriger von Hyrules\x01königlicher Familie zu sein... \x01Nun denn, was wollt Ihr von uns?\x02", "box_type": 0},
    {"id": 0x4007, "text": "Wir sind gewandte Taucher!\x01Wie steht es mit Euch?\x04Wollt Ihr ebenso meisterlich\x01tauchen, macht mit bei unserem\x01\x05\x41Tauchspiel\x05\x40 am höchsten Punkt des\x01Wasserfalls! Schon ausprobiert?\x02", "box_type": 0},
    {"id": 0x4008, "text": "\x1AAus Zoras Quelle entspringt\x01der Fluß.\x01Die Quelle ist auch die Residenz\x01von \x05\x41Lord Jabu-Jabu\x05\x40.\x07\x40\x09\x02", "box_type": 0},
    {"id": 0x4009, "text": "Lord Jabu-Jabu ist Schutzheiliger\x01der Zoras. \x05\x41Prinzessin Ruto\x05\x40 sorgt\x01täglich für seine Nahrung.\x02", "box_type": 0},
    {"id": 0x400A, "text": "Wir Zoras dienen dem mächtigen \x01\x05\x41König Zora\x05\x40.\x02", "box_type": 0},
    {"id": 0x400B, "text": "Der mächtige König Zora befindet\x01sich derzeit im \x05\x41Königsgemach\x05\x40.\x02", "box_type": 0},
    {"id": 0x400C, "text": "Habt Ihr bereits Lord Jabu-Jabu\x01kennengelernt?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x400D, "text": "Nach den Legenden unseres Volkes\x01wird dem Gutes zuteil, der Lord\x01Jabu-Jabu einen \x05\x41Fisch\x05\x40 kredenzt.\x02", "box_type": 0},
    {"id": 0x400E, "text": "Oh, wie bedauerlich.\x04Jeder, der unser Reich besucht,\x01sollte wenigstens einmal\x01um eine Audienz bei\x01\x05\x41Lord Jabu-Jabu\x05\x40 ersuchen!\x04Direkt hinter dem Thron des\x01mächtigen König Zora befindet sich\x01Zoras Quelle. Dort lebt\x01Lord Jabu-Jabu.\x04Fehlt Euch aber König Zoras\x01Erlaubnis, könnt Ihr die\x01Quelle nicht betreten.\x02", "box_type": 0},
    {"id": 0x400F, "text": "\x1AWir haben \x05\x41Prinzessin Ruto\x01\x05\x40immer noch nicht gefunden, obwohl\x01wir sogar am \x05\x43Hylia-See\x05\x40 suchten...\x02", "box_type": 0},
    {"id": 0x4010, "text": "Wenn Ihr einen Hinweis auf den\x01Verbleib von \x05\x41Prinzessin Ruto \x05\x40habt,\x01teilt es bitte König Zora mit!\x02", "box_type": 0},
    {"id": 0x4011, "text": "Alles Wasser in Hyrule entspringt\x01\x05\x43Zoras Quelle\x05\x40.\x04Das Wasser fließt durch den\x01Zora-Fluß und schließlich in den\x01\x05\x43Hylia-See \x05\x40im Süden Hyrules.\x02", "box_type": 0},
    {"id": 0x4012, "text": "\x1AOh, ich fühle mich wie neugeboren!\x04\x1ASeid Ihr es, der mich vom Eis\x01befreit hat? Ich danke Euch!\x04\x1AMir scheint, Ihr könnt Euch nicht\x01sehr lange unter Wasser aufhalten.\x04\x1AAls Zeichen meines Dankes nehmt\x01bitte diese \x05\x41Rüstung\x05\x40. Mit ihr könnt\x01Ihr nun auch unter Wasser atmen!\x02", "box_type": 0},
    {"id": 0x4013, "text": "Prinzessin Ruto hat sich zum\x01Hylia-See begeben...\x01Ich mache mir erneut große Sorgen\x01um sie...\x02", "box_type": 0},
    {"id": 0x4014, "text": "\x1AOoh...\x01Das ist eine... Nun... Hmmm...\x01Hmmm... \x05\x41Augentropfen\x05\x40...\x04\x1ANun, wir haben in jedem Fall die\x01erforderlichen Zutaten dafür.\x04\x1ABringt diese \x05\x41Zutaten \x05\x40zum\x01Labor am See. Dort werden die\x01Augentropfen für Euch zubereitet.\x04\x1ADoch eilt, denn die Zutaten\x01müssen frisch sein...\x07\x40\x15\x02", "box_type": 0},
    {"id": 0x4015, "text": "Werdet Ihr es schaffen,\x01\x05\x41bevor sie verderben\x05\x40?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4016, "text": "Ihr glaubt, nicht schnell genug zu\x01sein? Nun, auf dem Rücken eines\x01flinken Pferdes könnt Ihr die\x01Wegstrecke schneller zurücklegen...\x02", "box_type": 0},
    {"id": 0x4017, "text": "\x1ASei gegrüßt!\x0C\x28\x1A\x0F, es sieht aus, als\x01würdest Du Dich langsam an Dein\x01Abenteuerleben gewöhnen!\x04\x1AIch glaube, Prinzessin Zelda wartet\x01darauf, daß Du sie wieder besuchst.\x04\x1ADu besitzt doch schon den\x01\x05\x41Goronen-Opal\x05\x40, oder nicht?\x02", "box_type": 0},
    {"id": 0x4018, "text": "Hallo! Ich bin gerade dabei,\x01das Wasser aus dem Hylia-See\x01mit einigen seltsamen Substanzen\x01zu vermischen.\x04Vielleicht hast Du ja schon mal mit\x01Asa, der alten Frau in Kakarikos\x01Hexenladen gesprochen... Sie hat\x01viel von mir gelernt...\x02", "box_type": 0},
    {"id": 0x4019, "text": "\x08Oh, wow!\x09\x04\x1AIch habe keinen \x05\x41Glotzfrosch\x05\x40 \x01mehr gesehen, seit Zoras Reich\x01vom Eis überzogen wurde!\x0B\x02", "box_type": 0},
    {"id": 0x401A, "text": "Oh, meine liebste, teuerste\x01\x05\x41Prinzessin Ruto\x05\x40...\x01Wo mag sie sein?\x01Ich mache mir solche Sorgen...\x02", "box_type": 0},
    {"id": 0x401B, "text": "\x1ADieser Brief! \x01Er ist von \x05\x41Prinzessin Ruto\x05\x40!\x04\x1AHmmm... Laßt mich lesen...\x01Sie ist im Bauch von\x01Lord Jabu-Jabu?\x01Das ist doch nicht möglich!\x04\x1A\x05\x41Lord Jabu-Jabu \x05\x40ist unser\x01Schutzheiliger und würde\x01Prinzessin Ruto niemals\x01verspeisen!\x04\x1ADoch seit dieser seltsame\x01Fremdling namens \x05\x41Ganondorf\x05\x40 unser\x01Reich besucht hat, benimmt sich\x01Lord Jabu-Jabu etwas sonderbar...\x04\x1ADer Brief scheint echt zu sein. Ihr\x01dürft Prinzessin Ruto suchen, wenn\x01Ihr mögt. Passiert das Tor\x01hinter mir!\x04\x1AIch behalte diesen Brief. Nehmt Ihr\x01die \x05\x41Flasche\x05\x40, in der er sich befand.\x01Ihr werdet sie bestimmt gut\x01nutzen können!\x07\x40\x1C\x02", "box_type": 0},
    {"id": 0x401C, "text": "Bitte findet meine liebste\x01\x05\x41Prinzessin Ruto\x05\x40\x01so schnell Ihr könnt!\x02", "box_type": 0},
    {"id": 0x401D, "text": "\x08\x05\x44Du kannst unter Wasser nicht\x01atmen! Wird Dir die Luft knapp,\x01ziehe diese \x05\x40Stiefel \x05\x44aus!\x05\x40\x09\x0E\x3C\x02", "box_type": 2},
    {"id": 0x401E, "text": "\x08\x06\x42Ooooh neiiiin!\x09\x02", "box_type": 0},
    {"id": 0x401F, "text": "\x1AOh, ich bin wieder frei...\x01Seid Ihr es, der mich vom Eis\x01befreit hat? Ich danke Euch!\x04\x1AAls Zeichen meines Dankes nehmt\x01bitte diese \x05\x43Zora-Rüstung\x05\x40. Damit\x01könnt Ihr... Wie bitte?!\x04\x1AIhr habt sie bereits? Mir scheint,\x01Ihr seid auf alles vorbereitet!\x04\x1ALaßt mich Euch dennoch herzlich\x01danken... Wie wäre es mit einem \x01königlichen KUSS?! Ihr mögt das\x01nicht? Nun denn...\x04\x1AWenn Ihr meinen Dank nicht wollt,\x01dann lauscht wenigstens meinen\x01Sorgen...\x07\x40\x13\x02", "box_type": 0},
    {"id": 0x4020, "text": "Ich bin ein \x05\x43Zora\x05\x40. Habt Ihr nicht\x01irgendwo ein hübsches\x01Zora-Mädchen gesehen?\x02", "box_type": 0},
    {"id": 0x4021, "text": "Ich bin ein \x05\x43Zora\x05\x40. Habt Ihr nicht\x01manch Seltsames in diesem See\x01gefunden?\x01Der Fluß trägt vieles hierher!\x02", "box_type": 0},
    {"id": 0x4022, "text": "\x1ADu... \x08Du bist spät dran!\x09\x01\x08Warum hat es so lange gedauert?\x09\x01Du \x08bist eine ziemlich lahme Ente!\x09\x04\x1ANa gut... Ich hab mich ein bißchen\x01einsam gefühlt, das ist alles...\x01Aber nur ein bißchen!\x02", "box_type": 0},
    {"id": 0x4023, "text": "\x1A\x08Ich hatte Angst...\x09\x01\x08Aber nur ein wenig!\x09\x01Nur ein wenig!\x02", "box_type": 0},
    {"id": 0x4024, "text": "\x1A\x0F!\x01\x0F!\x02", "box_type": 5},
    {"id": 0x4025, "text": "\x1A\x08Hey, Du!\x09\x01Du bist cool...\x01Ein bißchen mehr als andere... \x01\x08Aber nur ein bißchen!\x09\x04\x1ANaja, egal, Du hast mich gerettet.\x01Ich denke, ich kann Dir eine\x01Belohnung dafür geben.\x04\x1AWas möchtest Du? Sag's mir...\x01\x01\x1B\x05\x42Ich möchte den Heiligen Stein!\x01Eigentlich nichts...\x05\x40\x02", "box_type": 0},
    {"id": 0x4026, "text": "\x1ADu sprichst vom Heiligen Stein des\x01Wassers, dem \x05\x43Zora-Saphir\x05\x40?\x07\x40\x27\x02", "box_type": 0},
    {"id": 0x4027, "text": "\x1AIch habe ihn von meiner Mama\x01bekommen und darf ihn nur dem\x01geben, der mich heiratet. Es ist so\x01eine Art Verlobungsring der Zoras!\x04\x1A\x06\x54\x08Okay!\x09\x04\x1AIch gebe Dir meinen wertvollsten\x01Schatz: Den Zora-Saphir!\x02", "box_type": 0},
    {"id": 0x4028, "text": "Sag's bloß nicht meinem Daddy...\x02", "box_type": 0},
    {"id": 0x4029, "text": "\x1AHihihi... Sei nicht so schüchtern!\x04\x1AIch weiß genau, was Du gerade\x01denkst...\x07\x40\x27\x02", "box_type": 0},
    {"id": 0x402A, "text": "Ich wollte eigentlich einen Fisch\x01kaufen, aber er ist ein bißchen zu\x01teuer...\x04Da muß ich wohl einen der\x01Fische fangen, die hier\x01herumschwimmen.\x02", "box_type": 0},
    {"id": 0x402B, "text": "Oh, \x0F!\x01Ihr habt also\x01Prinzessin Ruto gerettet?\x01Ich bin sehr froh darüber!\x02", "box_type": 0},
    {"id": 0x402C, "text": "Ich hoffe, mein wertvollster\x01Schatz wird Dir bei Deiner Mission\x01helfen. Das wäre super!\x02", "box_type": 0},
    {"id": 0x402D, "text": "Oh, hallo \x0F!\x01Prinzessin Ruto spricht in der\x01letzten Zeit nur noch über Euch!\x02", "box_type": 0},
    {"id": 0x402E, "text": "Oh, Ihr seid es, \x0F!\x01Dank Euch ist Lord Jabu-Jabu\x01endlich wieder der alte!\x02", "box_type": 0},
    {"id": 0x402F, "text": "\x1AWir Zoras achten den mächtigen\x01König Zora sehr. Er hat wahrlich\x01königliche Würde!\x04\x1ADer mächtige König Zora hat eine\x01Tochter, Prinzessin \x05\x41Ruto\x05\x40. Sie ist\x01sein einziges Kind.\x04\x1ASie ist ziemlich wild und\x01sorgt für ordentlichen Wirbel\x01hier in Zoras Reich.\x07\x40\x0B\x02", "box_type": 0},
    {"id": 0x4030, "text": "\x1ABitte sehr.\x04\x1ADiese Medizin ist \x05\x41nicht lange\x01haltbar\x05\x40!\x04\x1AEile so schnell wie möglich zu\x01den Goronen. Du bist ja noch jung\x01und hast flinke Beine!\x02", "box_type": 0},
    {"id": 0x4031, "text": "\x1AHallo! Es sieht aus, als wärest Du\x01erfahrener und kräftiger geworden,\x01\x0F!\x04\x1ADirekt vor Dir liegt \x05\x43Zoras Reich\x05\x40.\x01Die Zoras dienen der königlichen\x01Familie von Hyrule und bewachen\x01dieses Gewässer.\x04\x1ADas Tor zu ihrem Reich öffnet\x01sich nur einem Abgesandten der \x01königlichen Familie.\x04\x1ASpiele vor dem Portal ein\x01\x05\x41Schlaflied\x05\x40 aus der Überlieferung\x01der königlichen Familie!\x02", "box_type": 0},
    {"id": 0x4032, "text": "Wenn Du wieder mal vorbeikommst,\x01bring mir doch ein Souvenir mit!\x02", "box_type": 0},
    {"id": 0x4033, "text": "\x1ADu hast Prinzessin Ruto gefunden!\x01Jetzt wird Dir König Zora sicher\x01den \x05\x43Heiligen Stein des Wassers\x01\x05\x40geben...\x04\x1AOder etwa nicht?\x02", "box_type": 2},
    {"id": 0x4034, "text": "\x1APrinzessin Ruto hat Dir ihren\x01wertvollsten Schatz gegeben!\x01Du besitzt nun zwei Heilige Steine!\x01Jetzt fehlt nur noch einer!\x02", "box_type": 2},
    {"id": 0x4035, "text": "\x1APrinzessin Ruto hat Dir\x01ihren wertvollsten Schatz gegeben!\x01Nun besitzt Du die\x01drei Heiligen Steine!\x04\x1AJetzt schnell zu Prinzessin Zelda!\x02", "box_type": 2},
    {"id": 0x4036, "text": "\x1ASei gegrüßt, \x0F...\x02", "box_type": 0},
    {"id": 0x4037, "text": "\x1ADieses Eis wurde von einer bösen\x01Macht erschaffen... Das Ungeheuer\x01im \x05\x43Wassertempel\x05\x40 ist der Urheber\x01dieses Unheils.\x04\x1ADu mußt das Übel beseitigen,\x01sonst wird dieses Eis nie mehr\x01schmelzen...\x04\x1AHast Du Mut, den Gefahren im\x01Tempel zu trotzen und die Zoras\x01zu retten, dann erlerne nun die\x01Melodie, die Dich zum Tempel führt.\x02", "box_type": 0},
    {"id": 0x4038, "text": "\x1AZeit entschwindet, Menschen\x01scheiden...\x01In ewig wie des Wassers Fluß...\x04\x1AZu königlichem Streben reift des\x01Kindes Mut... Junger Liebe Knospen\x01erblühen groß und stark... Des\x01Wassers Kraft allein dies schafft!\x04\x1ALausche der \x05\x43Serenade des Wassers\x01\x05\x40und trage sie in Deinem Herzen...\x02", "box_type": 0},
    {"id": 0x4039, "text": "\x1AWenn Du hierher kamst, um die\x01Zoras zu retten, hast Du den\x01ersten Schritt getan. Doch mehr\x01findest Du hier nicht...\x04\x1AMit einer Ausnahme sind alle\x01Zoras unter einer dicken \x01Eisschicht gefangen...\x04\x1AIch konnte nur ihre Prinzessin\x01retten, aber sie lief in Richtung \x01des\x05\x43 Wassertempels \x05\x40davon!\x02", "box_type": 0},
    {"id": 0x403A, "text": "Wenn Du einen Fisch kaufen willst,\x01dann brauchst Du etwas, worin Du\x01ihn aufbewahren kannst.\x0B\x02", "box_type": 0},
    {"id": 0x403B, "text": "Du willst die \x05\x43Zora-Rüstung\x05\x40 kaufen?\x01Sie ist aus edelstem Material und\x01daher enorm teuer!\x04Ich schätze, nur \x05\x41diese sehr\x01reiche Familie in Kakariko\x05\x40 kann\x01sie sich leisten.\x0B\x02", "box_type": 0},
    {"id": 0x403E, "text": "\x1AOh... Wenn ich mich recht\x01entsinne... \x0F?!\x04\x1ADu bist \x0F, oder?\x04\x1AIch bin es! \x05\x43Ruto\x05\x40, Deine Braut!\x01Die Prinzessin der Zoras!\x04\x1AIch werde nie vergessen, was\x01wir uns vor Jahren\x01geschworen haben!\x04\x1AEs war grauenvoll von Dir,\x01mich sieben lange Jahre\x01warten zu lassen!\x04\x1ADoch jetzt ist nicht die Zeit,\x01über Liebe zu sprechen. Es ist\x01etwas Furchtbares geschehen!\x04\x1AZoras Reich ist eingefroren!\x01Alles ist über und über mit\x01Eis bedeckt!\x04\x1AEin junger Mann namens \x05\x41Shiek\x01\x05\x40hat mich aus dem Eis gerettet...\x04\x1AAber die anderen Zoras wurden\x01\x14\x02... noch nicht...\x14\x00\x04\x1AIch will sie retten. Alle!\x01Ich will Zoras Reich retten!\x04\x1ADu mußt mir helfen! Du mußt\x01es für mich tun - für die Frau, die\x01Du heiraten wirst!\x04\x1A\x0F, hilf mir, das\x01bösartige Ungeheuer zu\x01vernichten, das in diesem Tempel\x01lauert. Wirst Du das tun?\x04\x1AIm Wassertempel gibt es \x05\x41drei\x01Stellen\x05\x40, an denen Du den\x01Wasserstand verändern kannst.\x04\x1AIch zeige Dir den Weg.\x01Folge mir! Und beeile Dich!\x02", "box_type": 0},
    {"id": 0x403F, "text": "\x1A\x0F! Vorsicht!\x01Das hier sieht nicht aus wie\x01gewöhnliches Wasser...\x01Irgendetwas lauert hier!\x02", "box_type": 0},
    {"id": 0x4041, "text": "\x1A\x0F...\x04\x1AIch hätte nichts anderes von\x01jemandem erwartet, den ich zu\x01meinem Ehemann auserkoren habe!\x04\x1AZoras Reich und seine Bewohner\x01können dank Deiner Hilfe\x01wieder in Freiheit leben.\x02", "box_type": 0},
    {"id": 0x4042, "text": "\x1AWenn Du Shiek triffst, danke\x01ihm von mir, okay?\x0E\x5A\x02", "box_type": 5},
    {"id": 0x4043, "text": "\x1ARuto wollte sich bei mir \x01bedanken?\x04\x1AIch verstehe...\x04\x1AAuch in ihrem Namen müssen wir\x01Hyrule den Frieden wiederbringen!\x02", "box_type": 0},
    {"id": 0x4045, "text": "Ah, ich verstehe...\x01Prinzessin Ruto ist zum\x01Wassertempel gegangen...\x02", "box_type": 0},
    {"id": 0x4046, "text": "\x1AAls meinen Lohn... gewähre\x01ich Dir meine ewige Liebe!\x04\x1AÄh, naja, das würde ich gern,\x01aber ich merke, daß Du an eine \x01andere denkst...\x02", "box_type": 0},
    {"id": 0x4047, "text": "\x1APrinzessin Zelda... Sie ist am\x01Leben! Ich spüre es. Also laß\x01Dich nicht entmutigen!\x02", "box_type": 0},
    {"id": 0x4048, "text": "\x08\x06\x48Iiiihhhh!!!\x01\x06\x31Was ist das denn?!\x01\x06\x3DEin Oktopus?!\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x4049, "text": "\x1AAls \x05\x43Weise des Wassers\x01\x05\x40ist es meine Aufgabe, den \x01Wassertempel zu bewachen...\x04\x1AUnd Du... Du suchst nach\x01Prinzessin \x05\x41Zelda\x05\x40?\x04\x1AGib es zu! Du kannst nichts\x01vor mir verheimlichen!\x02", "box_type": 0},
    {"id": 0x404A, "text": "\x1AIch weiß, Dich wird nichts\x01aufhalten in Deinem Kampf für den\x01Frieden... Nimm daher dieses\x01\x05\x43Amulett\x05\x40 und trage es mit Würde!\x02", "box_type": 0},
    {"id": 0x404B, "text": "\x1AHey, Du! Wer bist Du?!\x04\x1AIch bin \x05\x41Ruto\x05\x40, Prinzessin der Zoras.\x04\x1A\x08Was?!\x09\x01Mein Daddy hat Dich geschickt,\x01um mich zu retten?\x04\x1AIch würde \x08niemals\x09 jemanden\x01um so etwas bitten!\x04\x1AFlaschenpost? Ich weiß\x01\x08überhaupt nicht\x09, wovon Du redest!\x04\x1AMein Daddy hat Angst um mich?\x04\x1AIst mir \x08total\x09 egal!\x04\x1AAußerdem kann ich jetzt sowieso\x01nicht heim. Und Du... \x08Verschwinde!\x09\x01\x08Kapiert?!\x09\x02", "box_type": 0},
    {"id": 0x404C, "text": "\x1ABist Du immer noch hier? Du bist\x01ja schlimmer als eine Klette!\x04\x1AIch bin okay. Schon seit ich eine\x01kleine Zora-Prinzessin war, laufe\x01ich hin und wieder in Lord\x01Jabu-Jabus Bauch herum. Aber...\x04\x1ALord Jabu-Jabu ist heute ziemlich\x01seltsam...\x04\x1AHier sind auf einmal elektrisch \x01geladene Quallen und seltsame\x01Löcher...\x04\x1AObendrein habe ich meinen\x01wertvollsten Stein...\x01\x08Aber das geht Dich gar nichts an!\x09\x01Egal...\x04\x1ADu! \x08Verschwinde!\x09\x01\x08Kapiert?!\x09\x0B\x02", "box_type": 0},
    {"id": 0x404D, "text": "\x1ADu machst Dir echt solche Sorgen\x01um mich?\x04\x1ADann wird Dir eine besondere Ehre\x01zuteil: Du darfst mich tragen!\x04\x1A\x08Und übrigens\x09... Ich bleibe bei Dir,\x01bis ich gefunden habe, wonach ich\x01suche! Kein Witz! Ich mein's ernst!\x0B\x02", "box_type": 0},
    {"id": 0x404E, "text": "\x08Wie unaufmerksam von Dir!\x09\x01Warum läßt Du mich sitzen?!\x01Wenn Du ein Mann sein willst,\x01dann verhalte Dich auch so!\x0B\x02", "box_type": 0},
    {"id": 0x404F, "text": "\x1A\x08Da ist er ja!\x09\x01Danach habe ich gesucht!\x01Wirf mich auf die Plattform!\x02", "box_type": 0},
    {"id": 0x4050, "text": "\x1A\x08Prinzessin Ruto hat den \x01\x05\x43Heiligen Stein\x05\x40 wieder!\x09\x01\x14\x02Aber\x14\x00 warum Prinzessin Ruto?\x02", "box_type": 2},
    {"id": 0x4051, "text": "\x1AGott sei Dank!\x01Endlich... \x01Der Stein von meiner Mama...\x04\x1AAls ich Lord Jabu-Jabu gefüttert\x01habe, hat er wild um sich\x01geschlagen! Vor Schreck habe ich\x01den Stein fallen lassen!\x04\x1AUnd ganz plötzlich hat er mich\x01und den Stein verschluckt...\x04\x1AAber jetzt habe ich ihn wieder\x01und kann heimgehen!\x02", "box_type": 0},
    {"id": 0x4052, "text": "Bring mich jetzt schnell heim!\x02", "box_type": 0},
    {"id": 0x4053, "text": "Tauchspiel   20 Rubine\x01Macht Ihr mit?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4054, "text": "\x08\x06\x3FOkay!\x09\x04Sammelt alle Steine ein, die ich\x01nach unten werfe. Ihr habt dafür\x01nur begrenzt Zeit!\x04Sind alle eingesammelt, kommt\x01hierher zurück. Dann bekommt\x01Ihr etwas sehr Schönes!\x0B\x02", "box_type": 0},
    {"id": 0x4055, "text": "\x1A\x08Gratuliere!\x09\x01Ich habe etwas Tolles für Euch!\x01Holt es Euch ab!\x0B\x02", "box_type": 0},
    {"id": 0x4056, "text": "\x1AWie elegant Ihr getaucht seid!\x01Hier, nehmt dies als Lohn!\x04\x1ADies ist eine \x05\x41silberne Schuppe\x05\x40\x01der Zoras. Mit ihr kann man viel\x01tiefer tauchen!\x0B\x02", "box_type": 0},
    {"id": 0x4057, "text": "\x1ADas Wasser steigt, und das Böse\x01verläßt den See...\x01\x0F, Du hast\x01es geschafft!\x02", "box_type": 0},
    {"id": 0x4058, "text": "\x1AIch... bin nun überzeugt, daß Du\x01diese Welt retten wirst...\x02", "box_type": 0},
    {"id": 0x4059, "text": "\x1ASchau, \x0F...\x04\x1ADu und Prinzessin Ruto, ihr habt\x01gemeinsam das bösartige Monster\x01besiegt!\x04\x1ADer See füllt sich mit reinem\x01Wasser, und alles ist wie zuvor.\x02", "box_type": 0},
    {"id": 0x405A, "text": "\x08\x06\x42\x05\x41START!\x05\x40\x09\x0B\x02", "box_type": 0},
    {"id": 0x405B, "text": "Spring den Wasserfall hinab,\x01um Zeit zu sparen.\x0B\x02", "box_type": 0},
    {"id": 0x405C, "text": "Nehmt soviel Ihr wollt für\x0120 Rubine. Macht Ihr mit?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x405D, "text": "\x08Gratuliere!\x09\x0B\x02", "box_type": 0},
    {"id": 0x405E, "text": "\x1AEin paar \x05\x41Wundererbsen\x05\x40 gefällig?\x01Sie gehen nicht besonders gut...\x04Wie wäre es mit...\x01\x05\x4110 Rubine\x05\x40 das Stück?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x405F, "text": "\x1AEin paar \x05\x41Wundererbsen\x05\x40 gefällig?\x01Sie sind noch nicht so beliebt.\x04Wie wäre es mit...\x01\x05\x4120 Rubine\x05\x40 das Stück?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4060, "text": "\x1AEin paar \x05\x41Wundererbsen\x05\x40 gefällig?\x01Sie werden langsam beliebter...\x04\x05\x4130 Rubine\x05\x40 das Stück.\x01Wie wäre es?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4061, "text": "\x1AEin paar \x05\x41Wundererbsen\x05\x40 gefällig?\x01Sie gehen weg wie warme Semmeln!\x04\x05\x4140 Rubine\x05\x40 das Stück.\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4062, "text": "\x1AHier gibt's die tollen \x05\x41Wundererbsen\x05\x40!\x01Wer sie nicht kauft, der wird es\x01wirklich bereuen!\x04\x05\x4150 Rubine\x05\x40 das Stück.\x01(Aber nur jetzt!)\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4063, "text": "\x1ADie weltberühmten \x05\x41Wundererbsen\x05\x40!\x01Sie sind absolut beliebt und sicher\x01schon bald ausverkauft!\x04Ein Superpreis!\x01\x05\x4160 Rubine\x05\x40 das Stück!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4064, "text": "\x1AHier gibt es die seltenen\x01\x05\x41Wundererbsen\x05\x40! Dies könnte die\x01letzte Chance sein!\x04Mein Spezial-Preis!\x01\x05\x4170 Rubine\x05\x40 das Stück!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4065, "text": "\x1AWir haben die legendären \x01\x05\x41Wundererbsen\x05\x40! Ich verkaufe sie\x01normalerweise an niemanden!\x04Mein Super-Preis!\x01\x05\x4180 Rubine\x05\x40 das Stück!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4066, "text": "\x1A\x05\x41Wundererbsen\x05\x40?! Die sind sehr\x01teuer, aber... ich verkaufe\x01sie gern!\x04Aber ich muß mindestens\x01\x05\x4190 Rubine\x05\x40 für eine haben!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4067, "text": "\x1AWir verkaufen... \x05\x41Wundererbsen\x05\x40! \x01Du willst sie kaufen... Na gut!\x04\x05\x41100 Rubine\x05\x40 für eine!\x01Juhuuu!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4068, "text": "Na gut...\x02", "box_type": 0},
    {"id": 0x4069, "text": "Das ist zu wenig Geld.\x01Ich kann sie nicht verkaufen.\x02", "box_type": 0},
    {"id": 0x406A, "text": "Plaziere eine Wundererbse auf \x05\x46¡\x01\x05\x40und pflanze sie hier in die Erde.\x02", "box_type": 0},
    {"id": 0x406B, "text": "Oh, wie schade! Die Wundererbsen\x01sind ausverkauft! Wie bitte?\x01Oh, diese hier sind unverkäuflich!\x02", "box_type": 0},
    {"id": 0x406C, "text": "Es gibt eine Menge Orte, an denen\x01man  Wundererbsen pflanzen kann.\x01Suche nach einem quadratischen\x01Fleckchen Erde!\x02", "box_type": 0},
    {"id": 0x406D, "text": "Du hast es vielleicht nicht bemerkt,\x01aber ich habe Dich beobachtet. Du\x01bist nur \x05\x411 Meter\x05\x40 tief getaucht. Das\x01würde ich nicht \"Tauchen\" nennen...\x02", "box_type": 0},
    {"id": 0x406E, "text": "Du hast es vielleicht nicht bemerkt,\x01aber ich habe Dich beobachtet. Du\x01bist nur \x05\x412 Meter\x05\x40 tief getaucht. Das\x01würde ich nicht \"Tauchen\" nennen...\x02", "box_type": 0},
    {"id": 0x406F, "text": "Du hast es vielleicht nicht bemerkt,\x01aber ich habe Dich beobachtet. Du\x01bist nur \x05\x413 Meter\x05\x40 tief getaucht. Das\x01würde ich nicht \"Tauchen\" nennen...\x02", "box_type": 0},
    {"id": 0x4070, "text": "Du hast es vielleicht nicht bemerkt,\x01aber ich habe Dich beobachtet. Du\x01bist nur \x05\x414 Meter\x05\x40 tief getaucht. Das\x01würde ich nicht \"Tauchen\" nennen...\x02", "box_type": 0},
    {"id": 0x4071, "text": "Du hast es vielleicht nicht bemerkt,\x01aber ich habe Dich beobachtet. Du\x01bist jetzt \x05\x415 Meter\x05\x40 tief getaucht. Das\x01ist noch nicht tief genug...\x02", "box_type": 0},
    {"id": 0x4072, "text": "Du hast es vielleicht nicht bemerkt,\x01aber ich habe Dich beobachtet. Du\x01bist jetzt \x05\x416 Meter\x05\x40 tief getaucht. Du\x01solltest tiefer tauchen können!\x02", "box_type": 0},
    {"id": 0x4073, "text": "Du hast es vielleicht nicht bemerkt,\x01aber ich habe Dich beobachtet. Du\x01bist jetzt \x05\x417 Meter\x05\x40 tief getaucht. Du\x01solltest tiefer tauchen können!\x02", "box_type": 0},
    {"id": 0x4074, "text": "\x1ADu hast es vielleicht nicht bemerkt,\x01aber ich habe Dich beobachtet. Du\x01hast den \x05\x41Grund des Sees\x05\x40 erreicht!\x01Super! Hier ist etwas für Dich!\x02", "box_type": 0},
    {"id": 0x4075, "text": "Du scheinst der beste Taucher \x01Hyrules zu sein! Warum tauchst\x01Du nicht mal auf den \x01Grund des Hylia-Sees?\x02", "box_type": 0},
    {"id": 0x4076, "text": "Ich bin \x05\x41Balzac\x05\x40, die Vogelscheuche.\x01Ich wünschte, ich könnte reisen,\x01um herzergreifende Lieder zu\x01hören. Aber ich stecke hier fest...\x02", "box_type": 0},
    {"id": 0x4077, "text": "Eine wunderschöne Melodie!\x01Sie geht richtig ans Herz!\x0B\x02", "box_type": 0},
    {"id": 0x4078, "text": "Wenn Dir ein schönes Lied einfällt,\x01komm her und spiel es mir vor!\x0B\x02", "box_type": 0},
    {"id": 0x4079, "text": "Es ist lange her, aber würdest Du\x01mir nochmal das schöne Lied von\x01damals vorspielen?\x0B\x02", "box_type": 0},
    {"id": 0x407A, "text": "Das Lied von damals werde ich\x01nie vergessen!\x0B\x02", "box_type": 0},
    {"id": 0x407B, "text": "Nun, willst Du für nur\x01\x05\x4120 Rubine\x05\x40 angeln?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x407C, "text": "Oh, nein! Dir fehlt ein \x05\x41Rumble \x01Pak\x05\x40! Damit würdest Du spüren,\x01wenn ein Fisch am Haken ist.\x04Pech für Dich!\x0B\x02", "box_type": 0},
    {"id": 0x407D, "text": "Wow! Du hast ein \x05\x41Rumble Pak\x05\x40!\x01Jetzt spürst Du, ob Du etwas an\x01der Angel hast, mein Junge!\x0B\x02", "box_type": 0},
    {"id": 0x407E, "text": "Mist! Du hast nicht genug Geld.\x02", "box_type": 0},
    {"id": 0x407F, "text": "Geh zum Rand des Sees und drücke\x01\x05\x44¤\x05\x40, um die Fische anzuschauen.\x01Wirf die Leine mit \x05\x42 \x05\x40 aus und\x01stoppe sie mit \x05\x43\x05\x40.\x04Laß Deinen Köder mit \x05\x44ª\x05\x40 im\x01Wasser zappeln. Als Anfänger\x01kannst Du auch \x05\x42 \x05\x40 benutzen.\x04Hole die Angelschnur mit \x05\x43\x05\x40 ein.\x01Wenn Du \x05\x43\x05\x40 und \x05\x44£ \x05\x40gedrückt\x01hältst, kannst Du den Fang\x01schneller einholen!\x04Spürst Du, daß etwas anbeißt,\x01drücke \x05\x43\x05\x42 \x05\x40und \x05\x44ª nach unten\x05\x40,\x01um den Haken festzusetzen. Dann\x01hole die Leine mit \x05\x43\x05\x40 ein.\x04Möchtest Du Deine Ergebnisse\x01beim Angeln festhalten, mußt Du\x01Deinen Fang wiegen lassen!\x04Angelst Du als Kind, wird Dein\x01Ergebnis auch in der Zukunft\x01festgehalten. Umgekehrt ist\x01dies nicht möglich.\x04Hast Du alles verstanden?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4080, "text": "Ich bin sehr großzügig. Du kannst\x01angeln, solange Du möchtest.\x04Der größte Fang an diesem See\x01wog \x05\x41\x1D Pfund\x05\x40.\x04Wenn Du Deine Angel ausgeworfen \x01hast, kannst Du die Blickrichtung\x01mit \x05\x44¤\x05\x40 ändern.\x04\x06\x4APetri Heil!\x0B\x02", "box_type": 0},
    {"id": 0x4081, "text": "Hahaha!\x01Hast Du den Haken nicht mit \x05\x43\x01\x05\x40und \x05\x44ª nach unten\x05\x40 angezogen?\x02", "box_type": 0},
    {"id": 0x4082, "text": "Hey, was ist passiert?\x01Du hast den Fisch verloren!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x4083, "text": "Naja... Der wiegt etwa \x05\x41\x1D Pfund\x05\x40. \x01Willst Du ihn behalten?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4084, "text": "Was möchtest Du?\x01\x1C\x05\x42Wiege meinen Fisch!\x01Laß uns ein wenig reden...\x01Mir reicht's!\x05\x40\x02", "box_type": 0},
    {"id": 0x4085, "text": "Du mußt Dich schon etwas  \x01gedulden, wenn Du einen guten\x01Fang machen willst! Ehrlich!\x02", "box_type": 0},
    {"id": 0x4086, "text": "\x06\x55WOW!!\x04Das ist ja ein Prachtkerl! Sieht\x01ganz nach einem neuen Rekord aus!\x01Er wiegt mindestens \x05\x41\x1D Pfund\x05\x40!\x01Okay, hier ist Dein Preis!\x0B\x02", "box_type": 0},
    {"id": 0x4087, "text": "Was? \x01Was machst Du mit mir?!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x4088, "text": "Hey, Junge! Hast Du nichts\x01Besseres zu tun?\x04Was? Du willst weiter hier\x01rumlungern?\x04Mit so einer Einstellung bringt man\x01es im Leben zu nichts, glaub mir!\x01Naja...\x02", "box_type": 0},
    {"id": 0x4089, "text": "\x08Der größte Fang an diesem See\x01wog \x1D Pfund.\x01Gefangen von: \x0F\x09\x02", "box_type": 2},
    {"id": 0x408A, "text": "Willst Du weiter angeln?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x408B, "text": "Naja, er wiegt \x05\x41\x1D Pfund\x05\x40...\x01Nicht schlecht, aber in diesem See\x01gibt es auch größere Brocken!\x0B\x02", "box_type": 0},
    {"id": 0x408C, "text": "Hey, Du hast doch gar keinen\x01Fisch gefangen! Weichei!\x0B\x02", "box_type": 0},
    {"id": 0x408D, "text": "Du willst einen anderen Köder?\x01Meinst Du, darauf kommt es an?\x01Man braucht Talent und Erfahrung!\x01Hör mir zu:\x04Ich habe den Sachsen das Angeln\x01beigebracht. Seitdem sind es die\x01Angelsachsen! Alles klar?\x02", "box_type": 0},
    {"id": 0x408E, "text": "Was? Du möchtest ein paar Tricks\x01erfahren? Die kann ich Dir nicht\x01verraten. Die sind geheim.\x01Ehrlich!\x02", "box_type": 0},
    {"id": 0x408F, "text": "Was? Du willst wissen, ob ich ein\x01guter Angler bin?\x04Klar doch! Ein echter Pro!\x01Weißt Du überhaupt, was das ist?\x01So wie du angelst, wohl kaum!\x02", "box_type": 0},
    {"id": 0x4090, "text": "\x08Verhaltensmaßregeln\x09\x01\x081. Benutzen Sie keine fremden\x01Köder.\x012. Nicht ins Wasser...\x09\x04\x083. Keine Hamster als Köder\x01verwenden!\x09\x02", "box_type": 1},
    {"id": 0x4091, "text": "Wow! Das ist ja ein echter\x01Brocken! Tatsächlich! Er wiegt\x01\x05\x41\x1D Pfund\x05\x40!\x04Willst Du ihn behalten?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4092, "text": "Komm wieder, wenn Du älter bist!\x01Dann sind auch die Fische größer...\x01Naja, oder auch nicht.\x02", "box_type": 0},
    {"id": 0x4093, "text": "\x1AHey, Typ! Wir kennen uns doch!\x01Ist aber schon lange her!\x04\x1AWieviel Jahre waren das?\x01Sieben Jahre?! Was hast Du denn\x01die ganze Zeit getrieben?!\x04\x1ADu bist mein einziger Kunde.\x01Ich mache fast kein Geschäft\x01mehr!\x01Obendrein werden meine Haare...\x04\x1ANaja, äh, egal...\x04\x1ANa gut, willst Du fischen gehen?\x01Es kostet nur \x05\x4120 Rubine\x05\x40!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x4094, "text": "Was?\x04Du willst woanders fischen\x01gehen?! Du bist wohl nicht\x01mehr ganz bei Trost?\x04Wenn Du hier nicht angelst, geh\x01ich ja völlig Pleite!\x01Ganz im Ernst!\x02", "box_type": 0},
    {"id": 0x4095, "text": "Was?\x04Du willst mit Fliegen fischen?\x01Glaubst, dann läuft's besser?\x04Bleib mal lieber bei den Würmern.\x01Ganz ehrlich!\x02", "box_type": 0},
    {"id": 0x4096, "text": "Was?\x04Was meinst Du damit, daß Du\x01keine Fische siehst, weil das\x01Wasser zu trüb ist?\x04So ein Schwachsinn!\x01An solchen Tagen macht Fischen\x01noch mehr Spaß!\x04Du erwischst einen Fisch, wenn\x01Du es am wenigsten erwartest!\x01Das ist doch richtig genial!\x04Ganz im Ernst!\x02", "box_type": 0},
    {"id": 0x4097, "text": "Hey, was soll das?\x01Paß doch auf!\x01Du bist ja total schusselig!\x01Dumpfbacke!\x04Gib mir meine Mütze wieder!\x01\x01\x1B\x05\x42Okay!\x01Auf keinen Fall!\x05\x40\x02", "box_type": 0},
    {"id": 0x4098, "text": "Was? Oh!\x01Du hast ja schon größere Viecher\x01an Land gezogen...\x04Willst Du ihn trotzdem behalten?\x01\x01\x1B\x05\x42Ich wil ihn nicht! \x01Ich behalte ihn!\x05\x40\x02", "box_type": 0},
    {"id": 0x4099, "text": "Hey! Was ist das denn für ein\x01komischer Fisch? Er wiegt auch\x01\x05\x41\x1D Pfund\x05\x40!\x04Was willst Du damit machen?\x01\x01\x1B\x05\x42Behalten!\x01Nicht behalten!\x05\x40\x02", "box_type": 0},
    {"id": 0x409A, "text": "Wow!\x04Hast Du tatsächlich...\x01Unglaublich!\x01Du hast einen \x05\x41fremden Köder\x01\x05\x40erwischt!\x04Was willst Du damit tun?\x01\x01\x1B\x05\x42Damit angeln!\x01Wegwerfen!\x05\x40\x02", "box_type": 0},
    {"id": 0x409B, "text": "Nun ja...\x04Wow! Welch ein seltener Fisch!\x01Eine \x05\x41hylianische Forelle\x05\x40!\x04Da kommt es nicht auf die Größe\x01an! Ich gebe Dir diesen Preis!\x0B\x02", "box_type": 0},
    {"id": 0x409C, "text": "In der letzten Zeit haben wir kaum\x01noch solche Fische gefangen. Ich \x01laß ihn lieber wieder schwimmen.\x0B\x02", "box_type": 0},
    {"id": 0x409D, "text": "\x08Verhaltensmaßregeln\x011. Keine fremden Köder benutzen.\x012. Keinen Dreck machen.\x013. Ruhe!\x09\x02", "box_type": 1},
    {"id": 0x409E, "text": "Hey! Hey!\x01Du kannst die Angel doch nicht\x01einfach mitnehmen!\x04Wenn Du aufhören willst, dann\x01bringe sie zum Angelverleih\x01zurück! Ganz im Ernst!\x02", "box_type": 0},
    {"id": 0x409F, "text": "Göttlich!!!\x01Dieser Fisch ist ja riesengroß!\x04Der paßt in keine Pfanne!\x01Er ist sogar für meine Waage\x01zu groß. Er wiegt\x01bestimmt \x05\x41\x1D Pfund\x05\x40!\x04Du willst ihn bestimmt behalten,\x01oder nicht?\x01\x1B\x05\x42Behalten!\x01Nicht behalten!\x05\x40\x02", "box_type": 0},
    {"id": 0x40A0, "text": "Hey, Süßer!\x01Ich bin \x05\x41Byron\x05\x40, die Vogelscheuche!\x01Du hast bestimmt schon von meinem\x01tollen Gedächtnis gehört!\x04Wenn Du ein neues Lied weißt -\x01raus damit!\x04Dies ist das Lied, das Du beim\x01letzten Mal geflötet hast!\x04Los dann!\x0B\x02", "box_type": 0},
    {"id": 0x40A1, "text": "Ich bin \x05\x41Byron\x05\x40, das musikalische\x01Vogelscheuchen-Genie! Wenn ich\x01ein Lied einmal gehört habe, \x01vergesse ich es nie mehr, Süßer!\x02", "box_type": 0},
    {"id": 0x40A2, "text": "Spiel das Lied, damit Du Balzac\x01rufen kannst!\x01Wenn er in der Nähe ist, dann\x01hilft er Dir, Süßer!\x02", "box_type": 0},
    {"id": 0x40A3, "text": "Hey! Bist Du nicht der Typ aus\x01dem Kokiri-Wald?\x01Mann, bist Du gewachsen!\x04Okay, das ist Dein Lied...\x04Was?\x04Ich hab eben ein Elefantenhirn!\x01Du hast eher ein Hirn wie ein Sieb,\x01mein Guter! Nimm Deine Okarina\x01und flöte das Lied, Süßer!\x02", "box_type": 0},
    {"id": 0x40A4, "text": "Whoa! Du hast eine Okarina!\x01Hey, warum flötest Du mir nicht\x01was vor, Süßer?!\x0B\x02", "box_type": 0},
    {"id": 0x40A5, "text": "Naja... Nicht so schlecht!\x01Ich werde die Melodie im Kopf\x01behalten!\x04Ich kann mir jedoch höchstens\x01acht Noten merken.\x01Also für heute laß gut sein,\x01Süßer.\x0B\x02", "box_type": 0},
    {"id": 0x40A6, "text": "Wenn Du so einen Unsinn flötest,\x01gewinnst Du keinen Blumentopf,\x01Süßer!\x0B\x02", "box_type": 0},
    {"id": 0x40A7, "text": "OH YEAHHH!!\x01Das ist es! Das geht ab!\x01Mir haut's den Vogel raus!\x04Ich hab das nie vergessen!\x01Ich hab ja kein Stroh im Hirn!\x01Ich glaube, Du hast Dir eine\x01Belohnung verdient, Süßer!\x04Ich hab eine prima Idee!\x04Mein Bruder Balzac reist in ganz\x01Hyrule herum. Wenn Du ihn rufen\x01willst, dann spiele dieses Lied!\x04Wenn er in der Nähe ist und es\x01hört, dann wird er Dir helfen!\x0B\x02", "box_type": 0},
    {"id": 0x40A8, "text": "Hey, die Okarina!\x01Spiel ein Lied damit,\x01Süßer!\x0B\x02", "box_type": 0},
    {"id": 0x40A9, "text": "\x12\x28\xE4Mein Freund, Du spielst die\x01Okarina gut... Mmmh...!\x01Eine nette Melodie... Wir sollten\x01sie alle üben!\x04Nimm dies hier als Lohn!\x01Wenn Dir mal wieder eine feine\x01Weise durch den Kopf schießt,\x01komm vorbei und spiel sie vor!\x0B\x02", "box_type": 0},
    {"id": 0x40AA, "text": "\x12\x28\xE3Wow, ein cooler Song,\x01Freund!\x04\"Siiiiingin' in the raaaaaain...\"\x01Wirklich schön! \x04Steck Dir das hier als Gage\x01für den abgefahrenen Gig ein!\x01Alles klar, wir sehen uns!\x0B\x02", "box_type": 0},
    {"id": 0x40AB, "text": "\x12\x28\xE4Hey, wir sind die Riesenfrösche!\x01Die berühmten, unerreichten\x01fünf fabulösen Froschtenöre!\x04Bring uns zum Springen, damit wir\x01die Fliegen über uns erwischen!\x04Okay?\x01Also los dann!\x0B\x02", "box_type": 0},
    {"id": 0x40AC, "text": "\x12\x28\xE3Junge, das war genial!\x01Perrrrrfekt!\x01Wir platzen gleich!\x04Das hier ist doch genug als Dank,\x01oder nicht?\x0B\x02", "box_type": 0},
    {"id": 0x40AD, "text": "Naja, an dieses Lied kann ich mich\x01aber gar nicht erinnern, Süßer!\x01Warum? Weiß ich auch nicht!\x02", "box_type": 0},
    {"id": 0x40AE, "text": "\x08Der größte Fang, der in diesem See \x01gemacht wurde, wog \x1D Pfund.\x01Gefangen vom Besitzer des Sees!\x09\x02", "box_type": 2},
    {"id": 0x40AF, "text": "Was?\x01Du willst einen anderen\x01Köder benutzen?\x01Hey, was ist das denn?\x04Das hast Du gerade erwischt?\x01Nach den Regeln darfst Du sowas\x01ja eigentlich nicht benutzen.\x01Aber, naja, was soll's...\x02", "box_type": 0},
    {"id": 0x40B0, "text": "WOW!\x01Der ist RIESIG! Ein neuer Rekord!\x01Der... Der wiegt ganze...\x01\x05\x41\x1D Pfund\x05\x40!\x04Aaaaaaber! Der fremde Köder war\x01ein Verstoß gegen die Regeln!\x01Also gibt es auch keinen Preis!\x01Hehe!\x0B\x02", "box_type": 0},
    {"id": 0x40B1, "text": "\x08Größter Fang: \x1D Pfund.\x01Gefangen von: \x0F\x01(HINWEIS: Disqualifiziert wegen\x01Benutzung eines fremden Köders!)\x09\x02", "box_type": 2},
    {"id": 0x40B2, "text": "Du bist ein netter Junge!\x01Aber erzähl es nicht weiter.\x01Ehrenwort?\x0B\x02", "box_type": 0},
    {"id": 0x40B3, "text": "WAAAS!?\x04Warum machst Du das mit mir?\x01Was denkst Du Dir eigentlich?\x04So leicht kommst Du nicht davon!\x01Du zahlst Strafe, und zwar \x01\x05\x4150 Rubine\x05\x40!\x01Garantiert!\x0B\x02", "box_type": 0},
    {"id": 0x5000, "text": "\x08AARGH!\x09\x01\x14\x02\x08Du\x09 \x08hast mich\x09 \x08bezwungen!\x09\x14\x00\x01Wie? Ach, Du bist es.\x04Hast Du mal die \x05\x46Hymne der Sonne\x05\x40\x01gespielt?\x04Ich habe Dir ja schon \x01erzählt, daß Du damit die Nacht \x01zum Tag und den Tag zur Nacht\x01machst - wann immer Du willst.\x04Wenn alles um Dich herum dunkel\x01ist, kannst Du damit wieder Licht\x01in die Welt bringen. Probier's!\x02", "box_type": 0},
    {"id": 0x5001, "text": "\x08Ich habe beim Graben einen Schatz\x01gefunden - der wird lang und kurz\x01und macht \"KLING\"!\x01Den behalt ich!\x09\x02", "box_type": 2},
    {"id": 0x5002, "text": "Des \x05\x41Totengräbers\x05\x40 Tagebuch.\x01Willst Du es lesen?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 2},
    {"id": 0x5003, "text": "\x08Wer immer dies liest, der möge\x01mein Grab betreten. Ihm gebe ich\x01meinen langen, kurzen \x05\x41Schatz\x05\x40.\x09\x04\x08Ich warte!\x01Boris\x09\x02", "box_type": 2},
    {"id": 0x5004, "text": "\x08Das ist auch besser so!\x09\x02", "box_type": 2},
    {"id": 0x5005, "text": "Du hast einen Geist vernichtet!\x04Willst Du ihn in einer\x01Flasche aufbewahren?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 2},
    {"id": 0x5006, "text": "Du willst ihn aufbewahren, besitzt\x01aber keine leere Flasche.\x02", "box_type": 2},
    {"id": 0x5007, "text": "Für den Augenblick läßt Du\x01ihn gehen.\x02", "box_type": 2},
    {"id": 0x5008, "text": "Du hast ein Irrlicht gefangen!\x02", "box_type": 2},
    {"id": 0x5009, "text": "\x1A\x08Das Sonnenlicht, es schwindet\x01bei Nacht...\x01Erst am Tag ist wieder sein Feuer\x01entfacht.\x09\x04\x1A\x08Von Sonne zu Mond und zu Sonne\x01erneut...\x09\x04\x1A\x08Ewige Ruhe die lebenden Toten\x01erfreut.\x09\x04\x1AZiemlich schöne Lyrik, nicht wahr?\x02", "box_type": 2},
    {"id": 0x500A, "text": "\x08Ruhelose Seelen wandern ohne Wonne.\x01Gib Frieden mit der \x05\x46Hymne der Sonne\x05\x40.\x09\x02", "box_type": 2},
    {"id": 0x500B, "text": "\x1ADa ist eine Inschrift auf diesem\x01Grabstein...\x04\x1AEine \x05\x46geheime Weise\x05\x40 der\x01Gebrüder Brahmstein!\x02", "box_type": 2},
    {"id": 0x500C, "text": "Das weltbeste Elixier! Sagen wir\x01\x05\x41100 Rubine\x05\x40!\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x500D, "text": "Wenn Du Deine Meinung änderst,\x01kannst Du ja wieder herkommen.\x01Hihihihi!\x02", "box_type": 0},
    {"id": 0x500E, "text": "Du hast nicht genügend Rubine!\x01Hihihihi!\x02", "box_type": 0},
    {"id": 0x500F, "text": "\x1A\x08AARGH!\x09\x01\x14\x02\x08DU\x09 \x08HAST MICH\x09 \x08BEZWUNGEN!\x09\x14\x00\x01\x08Unglaublich!\x09\x04\x1AWie?\x01Du bist doch nicht einer von\x01Ganondorfs Schergen, oder?\x04\x1AAls Gespenst muß ich mich so\x01komisch benehmen. Tut mir leid.\x04\x1AAlsdann, ich glaube, ich stelle\x01mich mal vor!\x01Ähem...\x07\x50\x10\x02", "box_type": 0},
    {"id": 0x5010, "text": "Ich bin einer der geisterhaften\x01Komponisten-Brüder von Kakariko.\x04Wie alle Hylianer, so dienten auch\x01wir dem König dieses Landes.\x04Wir, die Gebrüder Brahmstein,\x01waren beauftragt, die mystische\x01Macht der königlichen Familie zu\x01untersuchen.\x04Wir haben bis jetzt die Macht des\x01Triforce nicht erklären können.\x04Aber unsere \"\x05\x41Studien zur Macht\x01über die Zeit mittels Tönen\x01einer Okarina\x05\x40\" haben wir\x01fast abgeschlossen!\x04Um ehrlich zu sein...\x04Wir haben unsere Studien dazu\x01bereits beendet!\x04Wir wären berühmt geworden, wenn\x01dieser widerliche Ganondorf nicht\x01versucht hätte, die Aufzeichnungen \x01zu stehlen.\x04Wir konnten es nicht zulassen, daß\x01er die Früchte unserer Arbeit an\x01sich reißt!\x04Daher haben wir unser Leben\x01riskiert, um diese Geheimnisse zu\x01bewahren.\x07\x50\x11\x02", "box_type": 0},
    {"id": 0x5011, "text": "Möchtest Du unsere Geschichte\x01noch einmal hören?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x5012, "text": "\x1A\x08AARGH!\x09\x01\x14\x02\x08ICH BIN\x09 \x08WIEDER\x09 \x08BESIEGT!\x09\x14\x00\x01Was? Du schon wieder?\x04\x1AWenn ich Dich so ansehe, muß ich\x01an Prinzessin Zelda denken.\x04\x1ADa Du offenbar mit der\x01Königsfamilie in Kontakt stehst,\x01kann ich Dir ein wenig mehr über\x01uns erzählen.\x04\x1ADamals nannten uns die Leute\x01überall \"Die tadellosen Tonsetzer\",\x01da wir viele Meisterwerke\x01komponiert haben.\x04\x1AAber wir waren nicht nur\x01Komponisten!\x04\x1AWir hatten auch einen Auftrag!\x01Wir sollten die geheimnisvollen\x01Kräfte der hylianischen \x01Königsfamilie untersuchen.\x04\x1AUnsere Namen wären in die\x01Geschichte Hyrules eingegangen,\x01wenn wir unsere Studien beendet\x01hätten.\x04\x1AWir haben diese Studien natürlich\x01stets streng geheim gehalten!\x07\x50\x14\x02", "box_type": 0},
    {"id": 0x5013, "text": "\x1A\x08AARGH!\x09\x01\x14\x02\x08ICH BIN\x09 \x08SCHON WIEDER\x09 \x08TOT!\x09\x14\x00\x01Was? Du schon wieder?\x04\x1AWenn ich Dich so anschaue, muß\x01ich an Prinzessin Zelda denken...\x04\x1AWenn Du mit der Königsfamilie\x01näher bekannt bist, kann ich Dir\x01ja etwas mehr über uns erzählen.\x07\x50\x14\x02", "box_type": 0},
    {"id": 0x5014, "text": "Mein Bruder und ich studierten\x01verschiedene Melodien: Eine, den\x01\x05\x41Mond zu beschwören\x05\x40, und eine\x01andere, die \x05\x41Sonne herbeizurufen\x05\x40!\x04Da Du von einem Angehörigen des\x01Königshauses geschickt wurdest,\x01will ich Dir von den Ergebnissen\x01unserer Untersuchungen berichten.\x04Sie stehen geschrieben auf dem\x01\x05\x41königlichen Grabstein\x05\x40.\x04Zeige auf musikalische Weise, daß\x01Du in königlichem Auftrag\x01unterwegs bist, wenn Du auf dem\x01Triforce vor dem Grab stehst.\x07\x50\x11\x02", "box_type": 0},
    {"id": 0x5015, "text": "Zzzzzzzz...\x04Malon... geht es gut...\x01Grummel... Murmel...\x01Tut mir leid, wenn Du Dir Sorgen\x01machst...\x02", "box_type": 0},
    {"id": 0x5016, "text": "Die Lon Lon-Farm wurde von Basil\x01übernommen und heißt jetzt\x01\x05\x41Basil-Farm\x05\x40.\x04Mich hat man hinausgeworfen -\x01schau mich nur an! Meine Tochter\x01Malon arbeitet noch immer dort.\x04Ich mache mir Sorgen...\x02", "box_type": 0},
    {"id": 0x5017, "text": "Du hast Malon gerettet? Danke!\x01Dann kann ich ja wieder\x01auf die Farm zurück.\x02", "box_type": 0},
    {"id": 0x5018, "text": "\x1A\x08Hey, Kleiner!\x09\x01Was hast Du hier zu suchen?\x04\x1AIch bin \x05\x41Boris, der Totengräber\x05\x40!\x01Ich sehe vielleicht zum Fürchten\x01aus, aber ich bin ganz harmlos...\x04\x1ALaß mich Dir ein bißchen von\x01meinem Nebenjob erzählen:\x04\x1AIch, der \x05\x41Totengräber Boris\x05\x40,\x01lade ein zur...\x01\x05\x44Grausigen Grabgrusel-Tour\x05\x40!\x04\x1AWas kommt dabei raus?!\x01Was kommt dabei raus?!\x01Lasset uns graben und\x01wir finden's heraus!\x07\x50\x19\x02", "box_type": 0},
    {"id": 0x5019, "text": "Willst Du, daß ich hier grabe?\x01\x05\x4110 Rubine\x05\x40 für ein Loch.\x01\x1B\x05\x42Ja!\x01Laß mal bleiben!\x05\x40\x02", "box_type": 0},
    {"id": 0x501A, "text": "\x05\x41Nein, hier ist nichts!\x05\x40\x02", "box_type": 0},
    {"id": 0x501B, "text": "\x1A\x06\x23Zurück, \x0F!\x02", "box_type": 0},
    {"id": 0x501C, "text": "\x1A\x0F...\x01Etwas Schreckliches ist passiert!\x01Der \x05\x41Schattendämon\x05\x40 ist\x01aus seinem Gefängnis entkommen!\x04\x1A\x05\x41Impa\x05\x40, die Gründerin Kakarikos,\x01hatte den Schattendämon einst auf\x01den Grund des Brunnens verbannt\x01und dort eingeschlossen...\x04\x1ADoch die Kraft des Dämons wurde\x01in letzter Zeit immer stärker, so\x01daß das Siegel brach und er wieder\x01in die Oberwelt entkommen konnte!\x02", "box_type": 0},
    {"id": 0x501D, "text": "\x1AIch werde mich um das Dorf\x01kümmern!\x01Ich zähle auf Dich,\x01\x0F!\x02", "box_type": 0},
    {"id": 0x501E, "text": "\x08\x06\x25Gebrüder Brahmstein,\x01\x06\x2Ekönigliche Tonsetzer.\x01\x06\x33Johann, der Ältere\x01\x06\x50R.I.P.\x09\x0B\x02", "box_type": 2},
    {"id": 0x501F, "text": "\x08\x06\x25Gebrüder Brahmstein,\x01\x06\x2Ekönigliche Tonsetzer.\x01\x06\x30Ludwig, der Jüngere\x01\x06\x50R.I.P.\x09\x0B\x02", "box_type": 2},
    {"id": 0x5020, "text": "\x08\x06\x4AKönigsgrab\x09\x02", "box_type": 2},
    {"id": 0x5021, "text": "\x1A\x08Dieses Gedicht wurde im Gedenken\x01\x06\x0Aan die teuren Verstorbenen der\x01\x06\x14königlichen Familie verfasst.\x09\x0B\x02", "box_type": 0},
    {"id": 0x5022, "text": "\x1ADu hast die Kreatur des Bösen\x01bezwungen und den Fluch vom\x01Schattentempel genommen!\x01Hab Dank dafür, \x0F!\x04\x1ADenn ich bin nicht allein\x01Prinzessin Zeldas Vertraute,\x01sondern auch jene Weise, die\x01über den Tempel wacht!\x02", "box_type": 0},
    {"id": 0x5023, "text": "\x1A\x06\x1BBitte suche die Prinzessin!\x0E\x32\x02", "box_type": 5},
    {"id": 0x5024, "text": "\x1A\x0F, der Auserwählte!\x01Endlich!\x04\x1AAlle \x05\x41Sechs Weisen \x05\x40sind erweckt!\x01Es ist soweit: Der entscheidende\x01Kampf gegen den Großmeister des\x01Bösen soll nun beginnen!\x04\x1AZuvor jedoch sollst Du jene\x01treffen, die auf Dich wartet...\x04\x1ASie harrt Deiner in der\x01\x05\x44Zitadelle der Zeit\x05\x40...\x02", "box_type": 0},
    {"id": 0x5025, "text": "\x1ADie Shiekahs waren seit\x01Generationen die getreuen Diener\x01des Königsgeschlechts von Hyrule.\x01Jedoch...\x04\x1A...auf den Tag genau vor sieben\x01Jahren griff Ganondorf das Schloß\x01an... Nach kurzem Kampf\x01schon ergab sich Hyrules König.\x04\x1AGanondorf wollte den Schlüssel\x01zum Heiligen Reich, den\x01bestgehüteten Schatz der\x01Königsfamilie: Die Okarina der Zeit!\x04\x1AMeine Aufgabe war, Prinzessin \x01Zelda zu retten und sie vor dem\x01Zugriff Ganondorfs zu bewahren.\x04\x1AAls ich Dich damals bei unserer\x01Flucht aus dem Schloß sah, warst\x01Du nur ein kleiner Junge...\x04\x1AJetzt ist aus Dir ein stolzer\x01Held geworden!\x02", "box_type": 0},
    {"id": 0x5026, "text": "\x1AGehe nun! Stehe Prinzessin\x01Zelda an meiner Stelle zur Seite\x01und beschütze sie.\x04\x1AMeine Kraft soll Dich begleiten.\x01Ich lege sie in dieses \x05\x43Amulett\x05\x40!\x02", "box_type": 0},
    {"id": 0x5027, "text": "Nun? Ist Kiki fröhlich und\x01zufrieden? Soll ich sie mir\x01einmal anschauen?\x02", "box_type": 0},
    {"id": 0x5028, "text": "\x1A\x12\x68\x55Ich bin der \x05\x41Chef der Zimmerleute\x05\x40.\x01Impa hat uns angestellt, diesen\x01Ort in eine eindrucksvolle Stadt \x01zu verwandeln!\x04\x1AAber die jungen Kerle von heute\x01haben keinen Ehrgeiz mehr!\x01Weißt Du, was ich meine, Junge?\x04\x1AMeine Arbeiter rennen nur planlos\x01im Dorf herum und machen bei\x01ihrer Arbeit keinerlei Fortschritte!\x04\x1ASogar mein Sohn ist ein fauler\x01Sack und hängt den ganzen Tag\x01nur in der Gegend rum!\x07\x50\x29\x02", "box_type": 0},
    {"id": 0x5029, "text": "\x1AIch sage Dir: Die jungen\x01Leute sind zu nichts mehr \x01zu gebrauchen!\x02", "box_type": 0},
    {"id": 0x502A, "text": "Schau Dir die Kleine da drüben an.\x01Sie kümmert sich aufopferungsvoll\x01um ihre Hühner, und das, obwohl sie \x01gegen Federn allergisch ist.\x04Was für ein Mädchen! Ich würde\x01ihr gern helfen, ich fühle mich zur\x01Zeit wie ein Wohltäter! Geht's Dir\x01nicht auch so?\x02", "box_type": 0},
    {"id": 0x502B, "text": "\x1AWir müssen uns keine Sorgen\x01machen...\x01Die Prinzessin ist jetzt in\x01Sicherheit.\x02", "box_type": 0},
    {"id": 0x502C, "text": "\x1ASchon bald wirst Du Prinzessin\x01Zelda von Angesicht zu Angesicht\x01gegenübertreten. Sie wird Dir\x01alles erklären...\x04\x1ADann, wenn die Sechs Weisen den\x01Großmeister des Bösen verbannt\x01haben und wieder Frieden in \x01Hyrule eingekehrt ist!\x02", "box_type": 0},
    {"id": 0x502D, "text": "\x1AHehehe, Junge...\x01Du bist gut zu Fuß, was?\x04\x1AZur Belohnung werde ich Dir\x01meinen \x05\x41Fanghaken\x05\x40 anvertrauen.\x04\x1ADamit wirst Du nun an Orte\x01gelangen, die bisher außerhalb\x01Deiner Reichweite lagen.\x04\x1ABesuch mich doch mal wieder,\x01wenn Du in der Gegend bist. Dann\x01gebe ich Dir wieder etwas\x01Wertvolles!\x04\x1ANoch etwas: Sei auf Deinem\x01Rückweg sehr vorsichtig...\x02", "box_type": 0},
    {"id": 0x502E, "text": "Du bist ja wieder da, Junge...\x01Hat Dir mein Geschenk\x01etwas genützt?\x02", "box_type": 0},
    {"id": 0x502F, "text": "\x06\x3ADie Zeit beträgt\x01\x06\x4B\x17!\x0B\x02", "box_type": 0},
    {"id": 0x5030, "text": "\x1ASieht aus, als würdest\x01Du es überstehen...\x02", "box_type": 0},
    {"id": 0x5031, "text": "\x1AIch glaube, Impa ging zum \x01\x05\x45Schattentempel\x05\x40, um ihn wieder zu\x01versiegeln. Ohne Hilfe wird\x01sie dort in großer Gefahr sein!\x04\x1A\x0F!\x01Impa ist eine der Sechs Weisen.\x01Vernichte den Schattendämon und\x01rette Impa!\x04\x1AEs gibt einen Zugang zum\x01Schattentempel hinter dem\x01Friedhof von Kakariko.\x04\x1AAlles, was ich für Dich tun kann,\x01ist, Dich die Melodie zu lehren, die\x01Dich zum Schattentempel bringt...\x04\x1ADiese Melodie führt Dich in die\x01unendliche Dunkelheit, die sogar die\x01Zeit absorbiert... Höre nun\x01die \x05\x45Nocturne des Schattens\x05\x40!\x02", "box_type": 0},
    {"id": 0x5032, "text": "Ich mag es, im Rhythmus dieser\x01Mühle Musik zu machen!\x01Das macht Riesenspaß!\x04Ich liebe Musik!\x01Ich liebe diese Mühle!\x04Ich will selbst einmal etwas\x01komponieren. Vielleicht eine\x01Melodie, die von der Mühle\x01oder vom Wind erzählt!\x02", "box_type": 0},
    {"id": 0x5033, "text": "Das ist eine sehr schöne Melodie...\x01Huch! Jetzt geht es aber\x01doch zu schnell!\x02", "box_type": 0},
    {"id": 0x5034, "text": "Grrrrrrrrr!\x04Ich werde nie vergessen, was vor\x01sieben Jahren geschehen ist!\x01Grrrrrrrrr!\x04Daran ist nur dieser Typ\x01mit seiner Okarina schuld!\x01Wenn er sich nochmal sehen\x01läßt, kann er etwas erleben!\x02", "box_type": 0},
    {"id": 0x5035, "text": "\x1AWas?! Du besitzt eine Okarina!\x04\x1ADas darf doch nicht wahr sein!\x04\x1ADas erinnert mich an diesen\x01Tag vor genau sieben Jahren!\x04\x1ADamals kam so ein Rattengesicht\x01hier herein und hat ein \x05\x45seltsames\x05\x43\x01\x05\x45Lied\x05\x40 gespielt. Das hat alles \x01durcheinander gebracht!\x02", "box_type": 0},
    {"id": 0x5036, "text": "Was soll ich nur tun!?\x01Meine \x05\x41Hühner\x05\x40 sind alle\x01davongeflogen!\x04Bitte!\x01Hilf mir, die Hühner wieder\x01einzusammeln!\x02", "box_type": 0},
    {"id": 0x5037, "text": "Das machst Du sehr gut!\x01Bring doch bitte noch die\x01anderen vier zurück!\x02", "box_type": 0},
    {"id": 0x5038, "text": "Prima! Du bist ein echter\x01Hühnerfänger!\x01Bring doch auch die anderen\x01drei zurück!\x02", "box_type": 0},
    {"id": 0x5039, "text": "Klasse! Du bist richtig lieb!\x01Bring doch noch die anderen\x01zwei zurück! Bitte!\x02", "box_type": 0},
    {"id": 0x503A, "text": "Super! Jetzt hast Du fast alle!\x01Bring doch bitte noch das letzte\x01Huhn zurück!\x02", "box_type": 0},
    {"id": 0x503B, "text": "\x1ADanke, daß Du meine Hühner\x01eingesammelt hast. Ich bin nämlich\x01allergisch und bekomme einen\x01Ausschlag, wenn ich sie anfasse.\x04\x1ADafür, daß Du mir geholfen\x01hast, gebe ich Dir etwas\x01sehr Wertvolles!\x0B\x02", "box_type": 0},
    {"id": 0x503C, "text": "Hey, was machst Du denn da?!\x01Sammle sie ein oder zahle dafür!\x0B\x02", "box_type": 0},
    {"id": 0x503D, "text": "Ärgere die Hühner bitte nicht!\x02", "box_type": 0},
    {"id": 0x503E, "text": "\x1AIch habe ein neues Huhn\x01gezüchtet! Ich nenne es \x05\x41Kiki\x05\x40, und \x01ich bekomme keine Allergie, wenn\x01ich es anfasse.\x04\x1AEs paßt auch in die Hosentasche\x01und ist praktisch, um faule\x01Langschläfer aufzuwecken! Schon\x01mal was davon gehört?\x04\x1AEs hat Spaß dabei, richtig laut zu\x01gackern. Ganz besonders, wenn es\x01eine Schlafmütze aufwecken darf!\x04\x1AAber... so ganz zufrieden ist\x01Kiki im Augenblick noch nicht...\x04\x1ADu... Du siehst aus, als\x01hättest Du ein glückliches\x01Händchen für Hühner!\x04\x1AHier, nimm dieses Ei mit.\x01Ist Kiki ausgeschlüpft, dann bring\x01es irgendwann zu mir zurück und\x01ich schaue, wie es sich fühlt.\x07\x50\x3F\x02", "box_type": 0},
    {"id": 0x503F, "text": "Was hältst Du davon? \x01Willst Du es ausprobieren?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x5040, "text": "Oh, wie schade... Haben die Hühner\x01immer nach Dir gehackt, als Du\x01noch kleiner warst?\x0B\x02", "box_type": 0},
    {"id": 0x5041, "text": "Hehehe, Junge!\x01Bist Du gut zu Fuß?\x04Ich seh vielleicht nicht so aus,\x01aber ich bin ganz schön schnell!\x01Laß uns um die Wette laufen! \x01Wenn Du es Dir zutraust...\x02", "box_type": 0},
    {"id": 0x5042, "text": "Bitte sorge gut für Kiki!\x01Okay?\x02", "box_type": 0},
    {"id": 0x5043, "text": "\x1AOh, Kiki sieht ja sehr gesund und\x01fröhlich aus. Es muß eine arge\x01Schlafmütze geweckt haben!\x04\x1ADas hast Du gut gemacht!\x01Ich werde Dir ein sehr seltenes\x01Hühnchen mitgeben, wenn Du willst.\x04\x1AIch nenne es \x05\x41Henni\x05\x40, es hat einmal\x01meinem Bruder gehört. Die blauen \x01Federn sehen sehr schön aus,\x01nicht wahr? Es ist sooooo süß!\x04\x1ASeit mein Bruder verschwunden ist,\x01gackert Henni gar nicht mehr!\x07\x50\x44\x02", "box_type": 0},
    {"id": 0x5044, "text": "Möchtest Du \x05\x41Henni\x05\x40 behalten?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x5045, "text": "Also magst Du Kiki doch lieber.\x01Okay, dann behalte sie noch für\x01eine Weile!\x0B\x02", "box_type": 0},
    {"id": 0x5046, "text": "Eine alte Vettel betreibt den\x01Hexenladen hinter diesem Shop.\x01Nimm die Tür links neben der\x01Theke, wenn Du hinein willst!\x0B\x02", "box_type": 0},
    {"id": 0x5047, "text": "Mein Bruder muß sehr einsam\x01gewesen sein...\x02", "box_type": 0},
    {"id": 0x5048, "text": "Ich habe gehört, daß die\x01\x05\x42Verlorenen Wälder\x05\x40 ein mysteriöser\x01Ort mit vielen, noch seltsameren\x01Gewächsen sind.\x04Ich würde gern mal eine Medizin\x01mit einem der seltsamen Gewächse\x01zusammenbrauen, die es dort gibt.\x04Ich sehe vielleicht nicht mehr so\x01gut, aber meine Nase ist noch\x01sehr fein! Hihihi!\x02", "box_type": 0},
    {"id": 0x5049, "text": "Schnüffel...\x04Welch ein seltsamer Duft...\x04Du mußt etwas gefunden haben!\x02", "box_type": 0},
    {"id": 0x504A, "text": "Dieser Taugenichts! \x01Er mußte unbedingt in den Wald\x01gehen...\x01\x14\x01Hmmm...\x14\x00 Ich verstehe.\x07\x50\x4B\x02", "box_type": 0},
    {"id": 0x504B, "text": "Hey, gib das sofort her!\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x504C, "text": "Wie schade... Ich brauche nur\x01ein bißchen...\x02", "box_type": 0},
    {"id": 0x504D, "text": "\x1AWenn Du den Dummkopf siehst,\x01dann gib ihm dies. Es ist die\x01stärkste Medizin, die ich je \x01gebraut habe.\x04\x1AAber sie wirkt nicht bei jedem!\x0B\x02", "box_type": 0},
    {"id": 0x504E, "text": "Hey, Kleiner! Wenn Du die Medizin\x01mitnehmen möchtest, brauchst Du\x01etwas zum Aufbewahren!\x0B\x02", "box_type": 0},
    {"id": 0x504F, "text": "Es heißt, gegen Dummheit ist kein\x01Kraut gewachsen...\x01Ich glaube, das ist wahr...\x02", "box_type": 0},
    {"id": 0x5050, "text": "Ich komme nicht mehr vom Dach\x01herunter. Aber dafür kann ich\x01Tag und Nacht den \x05\x41Todesberg\x01\x05\x40anschauen!\x02", "box_type": 0},
    {"id": 0x5051, "text": "Ich komm hier nicht mehr runter.\x01Ich kann nur noch dauernd die\x01Sterne anschauen.\x02", "box_type": 0},
    {"id": 0x5052, "text": "Siehst Du das von hier aus? \x01Irgendetwas passiert auf dem\x01\x05\x41Todesberg\x05\x40!\x02", "box_type": 0},
    {"id": 0x5053, "text": "Siehst Du das von hier aus?\x01Auf dem \x05\x41Todesberg \x05\x40ist alles\x01wieder wie früher!\x02", "box_type": 0},
    {"id": 0x5054, "text": "Eigentlich will ich gar nicht mehr \x01von diesem Dach herunter!\x01Egal was passiert, ich schaue mir\x01lieber den Todesberg an.\x02", "box_type": 0},
    {"id": 0x5055, "text": "\x1AHey! Schön, Dich wiederzusehen!\x01Ich gebe Dir dieses\x01Erinnerungsstück.\x02", "box_type": 0},
    {"id": 0x5056, "text": "Für einen guten Überblick drückst\x01Du einfach \x05\x46¥\x05\x40 und schaust mit\x01\x05\x44ª\x05\x40 umher.\x02", "box_type": 0},
    {"id": 0x5057, "text": "\x1AHey! Betrittst Du fremde Häuser\x01immer unaufgefordert? Haben Dir \x01Deine Eltern keine Manieren\x01beigebracht?\x04\x1A\x06\x4ENa, egal...\x04\x1AHast Du die Frau hinter dem\x01Haus gesehen? Sie hat's zur Zeit\x01nicht leicht.\x04\x1A\x06\x4ENa, egal...\x07\x50\x58\x02", "box_type": 0},
    {"id": 0x5058, "text": "Sollte die Frau mal etwas über\x01Hühner erzählen, hör ihr gut zu.\x02", "box_type": 0},
    {"id": 0x5059, "text": "\x1AMacht es Dir Spaß, fremde Leute\x01zu so später Stunde noch zu\x01belästigen? Du hast wohl gar\x01keine Erziehung genossen.\x04\x1A\x06\x4ENa, egal...\x07\x50\x5A\x02", "box_type": 0},
    {"id": 0x505A, "text": "Die Frau kümmert sich um die\x01Hühner, reagiert aber allergisch\x01auf Federn.\x04\x06\x4ENa, egal...\x02", "box_type": 0},
    {"id": 0x505B, "text": "\x1AHey! Junge! Du bist fast\x01erwachsen und betrittst ein\x01fremdes Haus ohne Erlaubnis?!\x01Ich will mit Deinen Eltern reden!\x04\x1A\x06\x4ENa, egal...\x04\x1ADas hier ist sowieso nicht mein\x01Haus. Es ist das Haus\x01der \x05\x41mächtigen Impa\x05\x40!\x04\x1ADie mächtige Impa ging zum\x01\x05\x41Friedhof\x05\x40, um eine widerliche\x01Kreatur zu bezwingen.\x04\x1ASeit Ganondorf aufgetaucht ist,\x01wimmelt es nämlich von\x01ekligen Kreaturen!\x04\x1ANur die mächtige Impa hat für\x01Frieden in unserem Dorf sorgen\x01können. Merk Dir das gut, mein \x01Junge!\x04\x1A\x06\x50Nun gut.\x04\x1AApropos Impa: Sie ist noch immer \x01nicht zurück. Ich frage mich, was\x01da passiert ist!\x07\x50\x5C\x02", "box_type": 0},
    {"id": 0x505C, "text": "Ich habe gehört, daß der \x05\x41Geist\x01des Totengräbers\x05\x40 öfters noch\x01auf dem Friedhof hinter dem Dorf\x01herumspukt...\x04\x06\x14Aber das ist nicht so wichtig.\x02", "box_type": 0},
    {"id": 0x505D, "text": "\x1AHey, Kleiner! Bist Du zum ersten\x01Mal in Kakariko?\x04\x1ADie mächtige \x05\x41Impa\x05\x40, eine großartige\x01Frau, hat das Dorf für einfache\x01Leute wie uns erbauen lassen.\x07\x50\x5E\x02", "box_type": 0},
    {"id": 0x505E, "text": "Fühle Dich ganz wie zu Hause.\x01Das Essen ist allerdings\x01noch nicht fertig!\x02", "box_type": 0},
    {"id": 0x505F, "text": "Die mächtige Impa ist nicht hier.\x01Ob etwas passiert ist?\x02", "box_type": 0},
    {"id": 0x5060, "text": "\x1AWir alle haben Schweres\x01durchgemacht. Aber wir möchten\x01das lieber für uns behalten.\x07\x50\x61\x02", "box_type": 0},
    {"id": 0x5061, "text": "Schau Dir den Bärtigen auf dem\x01Bett an. Ich wette, sogar einer\x01wie er hat seine Probleme...\x02", "box_type": 0},
    {"id": 0x5062, "text": "Der Bärtige ist wieder zur Farm\x01zurück.\x01Er sah richtig glücklich aus!\x02", "box_type": 0},
    {"id": 0x5063, "text": "\x1AEs ist jetzt \x1F Uhr!\x01Die richtige Zeit, um Dir etwas\x01über das Dorf zu erzählen!\x04\x1AZeldas Dienerin, die mächtige\x01\x05\x41Impa\x05\x40, erbaute dieses Dorf für\x01einfache Leute wie uns.\x04\x1ANoch wohnen hier wenige,\x01aber eines Tages wird es genau\x01so lebhaft sein wie in Hyrule!\x01Oh ja, das wird es!\x04\x1ASteige die \x05\x41Stufen im Norden \x01des Dorfes\x05\x40 hinauf.\x01Dort gelangst Du zu dem Paß,\x01der zum Todesberg führt.\x04\x1AAber Du brauchst des Königs\x01Erlaubnis, um diesen Weg nehmen\x01zu können.\x02", "box_type": 0},
    {"id": 0x5064, "text": "Es ist jetzt genau \x1F Uhr.\x02", "box_type": 0},
    {"id": 0x5065, "text": "Es ist jetzt \x1F Uhr.\x01Ach, übrigens: Weißt Du, was im\x01Schloß passiert ist?\x02", "box_type": 0},
    {"id": 0x5066, "text": "\x1AHey, Junge, was treibst Du Dich\x01hier mitten in der Nacht herum?\x04\x1AAh, ich verstehe. Du willst Deinen\x01Mut testen! Du willst bestimmt...\x01auf den Friedhof!\x04\x1AMoment mal! Was rede ich\x01eigentlich mit so einem\x01Milchbubi? Ich muß Wache\x01stehen und meinen Mund halten!\x07\x50\x67\x02", "box_type": 0},
    {"id": 0x5067, "text": "Es ist jetzt \x1F Uhr.\x01Genau die richtige Zeit, um\x01Gräber zu besuchen!\x04Geh nach Osten zum \x05\x41Friedhof\x05\x40.\x01Legenden besagen, man könne die\x01ruhelosen Seelen mit einem\x01\x05\x43königlichen Schlaflied\x05\x40 besänftigen...\x02", "box_type": 0},
    {"id": 0x5068, "text": "Ein komischer Typ lebt in der \x01Windmühle. Warst Du schon bei\x01ihm, großer Held?\x02", "box_type": 0},
    {"id": 0x5069, "text": "Menschen sind widerlich. \x01Meine Eltern sind widerlich.\x01Du bist bestimmt auch widerlich!\x02", "box_type": 0},
    {"id": 0x506A, "text": "Wir arbeiten den ganzen Tag lang\x01auf verschiedenen Baustellen hier\x01im Dorf. Es dauert wohl noch eine\x01Weile, bis alles fertig ist.\x04Unser Chef ist ein ziemlicher\x01Sklaventreiber!\x02", "box_type": 0},
    {"id": 0x506B, "text": "Ich komme um vor Hunger!\x01Laß uns sofort etwas essen!\x02", "box_type": 0},
    {"id": 0x506C, "text": "Jeder von ihnen arbeitet nur halb\x01so viel, wie er sollte. Aber sie\x01wollen immer eine\x01doppelte Portion essen!\x02", "box_type": 0},
    {"id": 0x506D, "text": "\x08\x05\x41Irrlicht   30 Rubine\x01\x05\x40Dies ist ein Geist in einer Flasche. \x01Verkaufe ihn an jemanden, der\x01solch verrückte Dinge mag.\x09\x0A\x02", "box_type": 0},
    {"id": 0x506E, "text": "\x08Irrlicht  30 Rubine\x09\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x5070, "text": "Meine Hühner sind davongerannt!\x01Bitte fange noch sechs weitere!\x02", "box_type": 0},
    {"id": 0x5071, "text": "\x08\x05\x44\x0F!\x01Das Schiff sinkt!\x01Spring ab!\x01Rette Dich auf festen Boden!\x05\x40\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x5072, "text": "Ich habe noch nicht alle Hühner!\x01Bitte fange noch fünf ein!\x02", "box_type": 0},
    {"id": 0x5073, "text": "\x08Mach bloß keinen Ärger!\x01Ich sag's Boris!\x09\x0E\x3C\x02", "box_type": 0},
    {"id": 0x5074, "text": "Schau Dir das an, Kleiner!\x01Meine schönen, zarten Hände sind\x01von der Arbeit ganz rissig!\x01Schnief...\x02", "box_type": 0},
    {"id": 0x5075, "text": "Ein Job, bei dem Du viel Geld für\x01wenig Arbeit bekommst... Da fällt\x01mir nur Diebstahl ein... Du findest,\x01das wäre keine gute Idee?\x02", "box_type": 0},
    {"id": 0x5076, "text": "Ich habe gehört, das Haus\x01unseres Chefs liegt direkt hinter\x01diesem. Aber er will nicht, daß wir\x01es wissen.\x02", "box_type": 0},
    {"id": 0x5077, "text": "Hast Du \x05\x41Boris\x05\x40 gesehen, der auf\x01dem Friedhof lebt?\x04Es ist jetzt \x1F Uhr. Er schläft\x01wahrscheinlich in seiner Hütte.\x04Warum schlägst Du nicht ein\x01bißchen die Zeit tot, bis es\x01Abend wird?\x02", "box_type": 0},
    {"id": 0x5078, "text": "Ich komme um vor Hunger!\x01Ist das Essen schon fertig?\x01Es ist schon \x1F Uhr!\x02", "box_type": 0},
    {"id": 0x5079, "text": "\x1AIn diesem Haus lebte einst\x01die \x05\x41mächtige Impa\x05\x40.\x04\x1AEs ist nun für alle Dorfbewohner\x01geöffnet. Du kannst auch hinein!\x07\x50\x7A\x02", "box_type": 0},
    {"id": 0x507A, "text": "Dieses Dorf gehörte einst den\x01\x05\x43Shiekah\x05\x40, aber jetzt kann jeder\x01hier leben.\x02", "box_type": 0},
    {"id": 0x507B, "text": "Ich schwöre,\x01ich habe ihn gesehen!\x04Ich habe den Geist von Boris, dem\x01Totengräber, im Grab\x01verschwinden sehen! Man sagt, er\x01lagere viel \x05\x41Wertvolles\x05\x40 dort!\x02", "box_type": 0},
    {"id": 0x507C, "text": "Da ist er! Er ist es!\x01Er fiel vom Himmel, umgeben\x01von blauem Feuer!\x04Glaubst Du mir?\x02", "box_type": 0},
    {"id": 0x507D, "text": "Kein Mensch glaubt mir, was ich in\x01den letzten sieben Jahren erzählt\x01habe!\x02", "box_type": 0},
    {"id": 0x507E, "text": "Das Feuer hätte uns fast\x01vernichtet! Aber gemeinsam haben\x01wir es gelöscht! Gute Arbeit,\x01denkst Du nicht auch?\x02", "box_type": 0},
    {"id": 0x507F, "text": "Hahaha!\x04Schau Dir den an! Seit er aus\x01dem Schloß entkommen konnte,\x01ist er noch ängstlicher!\x02", "box_type": 0},
    {"id": 0x5080, "text": "Hahaha!\x04Er muß schlimme Sachen gesehen\x01haben!\x01Hahaha!\x02", "box_type": 0},
    {"id": 0x5081, "text": "Hahaha!\x01Das sind vielleicht komische\x01Klamotten, Mann!\x02", "box_type": 0},
    {"id": 0x5082, "text": "Hahaha!\x01Wenn die Zeiten hart sind, ist\x01Lachen die beste Medizin!\x01Das hat mein Alter immer gesagt!\x02", "box_type": 0},
    {"id": 0x5083, "text": "Schau her! Ich bin ganz oben!\x01Ich mag es gar nicht, wenn jemand\x01höher hinaus will! Ich muß immer\x01ganz oben sein!\x02", "box_type": 0},
    {"id": 0x5084, "text": "Wenn ich hier oben einschlafe,\x01falle ich bestimmt runter...\x02", "box_type": 0},
    {"id": 0x5085, "text": "Die Windmühle pumpt das Wasser\x01aus dem Brunnen nach oben.\x04Doch jetzt ist er ausgetrocknet.\x01Hmmm...\x02", "box_type": 0},
    {"id": 0x5086, "text": "Die Frau hier ist wirklich\x01großzügig. Sie hat sich sogar um\x01die Zimmerleute gekümmert, als \x01sie noch hier waren!\x02", "box_type": 0},
    {"id": 0x5087, "text": "Es ist lange her...\x01Da gab es hier einen Mann, von\x01dem man sagte, er besäße das \x01\x05\x45Auge der Wahrheit\x05\x40!\x04Heutzutage muß man schon selbst\x01ein ganz besonderes Gespür\x01entwickeln, um die Wahrheit zu\x01erkennen...\x04Aber der Typ hat das irgendwie\x01anders gemacht...\x04Sein Haus stand da, wo jetzt der\x01Brunnen ist...\x02", "box_type": 0},
    {"id": 0x5088, "text": "Die Leute in der Gegend\x01erzählen von einer\x01\x05\x41sagenhaft reichen Familie\x05\x40,\x01die einst hier lebte.\x04Aber die ganze Familie war\x01verflucht, sagt man...\x01Wegen ihrer unermeßlichen\x01Habsucht!\x04Wer weiß schon, was mit jenen\x01passiert, die von unstillbarer\x01Gier besessen sind!\x02", "box_type": 0},
    {"id": 0x5089, "text": "Hey...\x04Welch eine Nervensäge, die uns da \x01stört... Denkst Du das nicht\x01auch, meine Liebe?\x02", "box_type": 0},
    {"id": 0x508A, "text": "Hey...\x04Er verletzt unsere Privatsphäre...\x01Findest Du nicht auch, Liebling?\x02", "box_type": 0},
    {"id": 0x508B, "text": "\x1ASchau ihn an, den Bärtigen.\x01Ich glaube, sie haben ihn von der\x01Farm gejagt...\x07\x50\x8C\x02", "box_type": 0},
    {"id": 0x508C, "text": "Er hängt immer nur faul herum,\x01den ganzen Tag lang.\x01Das ist ziemlich gedankenlos in\x01derart schlimmen Zeiten!\x02", "box_type": 0},
    {"id": 0x508D, "text": "Der Bärtige erinnert\x01mich irgendwie an meinen\x01kleinen Richard...\x04Wie bitte? Du hast nie etwas von\x01meinem kleinen Richard gehört?\x01Er war so ein liebes Hundchen! Du\x01kennst ihn wirklich nicht?\x02", "box_type": 0},
    {"id": 0x508E, "text": "Oh nein! Deine verflixte Okarina\x01ist ein Instrument des Teufels!\x01Grrrrr!\x02", "box_type": 0},
    {"id": 0x508F, "text": "Du hast einen Nachtschwärmer\x01gefangen! Verkaufe ihn im\x01\x05\x41Gespenstermarkt \x05\x40zu einem\x01ordentlichen Preis!\x02", "box_type": 2},
    {"id": 0x6000, "text": "\x08Halt! Bleib, wo Du bist!\x09\x02", "box_type": 0},
    {"id": 0x6001, "text": "Nun, Kleiner?\x02", "box_type": 0},
    {"id": 0x6002, "text": "Hey, Kleiner! Warte eine Sekunde,\x01dann öffne ich Dir das Tor.\x02", "box_type": 0},
    {"id": 0x6003, "text": "\x08Unterschätz uns nicht!\x09\x02", "box_type": 0},
    {"id": 0x6004, "text": "\x1AIch bin beeindruckt. Um an unseren\x01Wachen vorbeizukommen, muß man\x01schon sehr geschickt sein.\x04\x1AIch habe immer gedacht, alle Typen\x01außer Ganondorf wären ziemliche\x01Waschlappen... Aber ich muß\x01meine Meinung ändern!\x04\x1A\x05\x41Unsere Anführerin Naboru\x05\x40\x01hat mir die Verantwortung für\x01diese Festung übertragen.\x04\x1ANaboru ist die Stellvertreterin\x01des mächtigen Ganondorf,\x01des Herrn der Gerudo-Kriegerinnen.\x04\x1ASie ist gerade auf dem Weg zum\x01\x05\x46Geistertempel\x05\x40, der sich jenseits\x01der Wüste befindet. Sie vermutet\x01dort ein wertvolles Relikt.\x04\x1ADu willst also einer von uns\x01werden, was? Na gut, Du hast\x01Deine Fähigkeiten bewiesen! \x01Du bist nun ein Gerudo!\x04\x1ANimm dies. Damit kannst Du Dich\x01in der Festung frei bewegen!\x0B\x02", "box_type": 0},
    {"id": 0x6005, "text": "Ab jetzt kannst Du das Tor zur\x01Wüste durchschreiten,\x01wann immer Du willst.\x04Dort findest Du den \x05\x46Geistertempel\x05\x40,\x05\x46 \x01\x05\x40in dem sich die herrliche Naboru\x01zur Zeit aufhält.\x02", "box_type": 0},
    {"id": 0x6006, "text": "\x08Weichei!\x09\x01Hinein mit Dir!\x01Und halt die Klappe!\x02", "box_type": 0},
    {"id": 0x6007, "text": "\x1AIch weiß zwar nicht, woher Du \x01kommst, aber Du mußt ganz schön \x01mutig sein, wenn Du Dich an den\x01Wachen vorbeitraust!\x04\x1AMeine anderen Kumpels sind\x01auch irgendwo eingesperrt.\x04\x1ABefreie uns bitte alle!\x04\x1AAber sei vorsichtig! Hier gibt's\x01\x14\x02\x08jede\x09 \x08Menge\x09\x14\x00\x01\x05\x41Gerudo-Wächterinnen\x05\x40!\x04\x1A\x08Hey!\x09 \x08Paß auf!\x09\x02", "box_type": 0},
    {"id": 0x6008, "text": "\x08\x06\x1CPortal in die Vergangenheit\x09\x02", "box_type": 1},
    {"id": 0x6009, "text": "\x08\x06\x25Portal in die Gegenwart\x09\x02", "box_type": 1},
    {"id": 0x600A, "text": "\x08\x06\x2DPortal in die Zukunft\x09\x02", "box_type": 1},
    {"id": 0x600B, "text": "\x12\x38\xECDen rechten Weg, den zeig ich Dir,\x01denn Du hast dafür kein Gespür.\x01Nun flott und folge mir sehr dicht.\x01Alleine überlebst Du's nicht!\x0E\x5A\x02", "box_type": 0},
    {"id": 0x600C, "text": "\x1AVergangenheit...\x01Gegenwart...\x01Zukunft...\x04\x1ADas Master-Schwert sei Dir ein\x01Ruder auf Deinem Weg hin und\x01zurück durch die Ströme der Zeit...\x04\x1ADer Hafen der Zeitwanderer liegt\x01in der Zitadelle der Zeit...\x04\x1AWillst Du den Wüstenkoloss\x01betreten und in den \x05\x46Geistertempel\x05\x40\x01eindringen, mußt Du wieder zurück\x01auf den Wellen der Zeiten...\x04\x1AHöre nun das \x05\x46Requiem der Geister\x05\x40!\x01Es wird Dich als Kind\x01in die Wüste zurückbringen!\x02", "box_type": 0},
    {"id": 0x600D, "text": "Ich bin die Gerudo-Meisterin im\x01berittenen Bogenschießen! Ach ja,\x01und ich bin obendrein die beste\x01Reiterin der Gerudos!\x04Willst Du gegen mich antreten?\x01Das kostet nur \x05\x4120 Rubine\x05\x40!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x600E, "text": "Du hast Mut! Typen wie Dich\x01mag ich! \x01Folge mir.\x02", "box_type": 0},
    {"id": 0x600F, "text": "Das kannst Du vergessen, wenn\x01Du kein Pferd hast!\x02", "box_type": 0},
    {"id": 0x6010, "text": "\x08Mit so einem Weichei will ich\x01nichts zu tun haben!\x09\x02", "box_type": 0},
    {"id": 0x6011, "text": "Na, so gut bist Du wohl doch\x01nicht! Vielleicht beim nächsten\x01Mal.\x02", "box_type": 0},
    {"id": 0x6012, "text": "Das ist ja super gelaufen!\x04Ich muß zugeben, Du hast mich\x01ganz schön abgezogen. \x01Ich muß wohl noch besser werden...\x02", "box_type": 0},
    {"id": 0x6013, "text": "Das ist die \x05\x41Trainingsarena\x05\x40 der\x01Gerudo-Kriegerinnen.\x04Ohne Gerudo-Paß kommst Du hier\x01nicht hinein!\x02", "box_type": 0},
    {"id": 0x6014, "text": "Das ist die \x05\x41Trainingsarena\x05\x40 der\x01Gerudo-Kriegerinnen.\x04Du hast den Gerudo-Paß?\x01Gut, dann darfst Du hinein.\x04Ein Versuch kostet 10 Rubine!\x01\x01\x1B\x05\x42Ich versuche es!\x01Ich lasse es bleiben!\x05\x40\x02", "box_type": 0},
    {"id": 0x6015, "text": "Okay, her mit den 10 Rubinen.\x01Schieß ordentlich!\x0B\x02", "box_type": 0},
    {"id": 0x6016, "text": "Du hast nicht genug Geld!\x01\x08Komm später wieder.\x09\x02", "box_type": 0},
    {"id": 0x6017, "text": "\x1AHey, Grünschnabel!\x04\x1AWillst Du Dich wirklich in\x01die Wüste begeben?\x01Na gut, ich öffne das Tor, aber...\x04\x1AEs ist nicht leicht, den\x05\x41\x01Geistertempel\x05\x40 zu erreichen!\x07\x60\x18\x02", "box_type": 0},
    {"id": 0x6018, "text": "Zunächst mußt Du den... \x05\x41Treibsand-\x01Graben\x05\x40 überqueren! Dann folge\x01auf dem richtigen Weg den Flaggen,\x01sonst schluckt Dich der Sand.\x04Die zweite Prüfung: Folge dem\x01\x05\x41Wüstengeist\x05\x40!\x04Ohne das \x05\x41Auge der Wahrheit \x05\x40aber\x01landest Du direkt wieder hier!\x04Du willst immer noch dorthin?\x01Ich halte Dich nicht auf...\x01Mach's gut!\x0B\x02", "box_type": 0},
    {"id": 0x6019, "text": "\x1AWarum bist Du schon wieder hier?\x01Was? Willst Du mich etwa noch\x01einmal dasselbe fragen?\x07\x60\x1A\x02", "box_type": 0},
    {"id": 0x601A, "text": "Naja, wenn Du sowieso schon da\x01bist, dann mach das Beste draus!\x02", "box_type": 0},
    {"id": 0x601B, "text": "Guter Junge! Vielen Dank!\x01Ich kann Dir zwar nichts derart \x01Wertvolles zum Tausch anbieten,\x01aber... vielleicht ist das ja okay!\x02", "box_type": 0},
    {"id": 0x601D, "text": "\x1AIch habe Dich noch nie gesehen,\x01Kleiner...\x04Was willst Du hier?\x01\x1C\x05\x42Den Tempel anschauen!\x01Ich suche die Weisen!\x01Eigentlich nichts!\x05\x40\x02", "box_type": 0},
    {"id": 0x601E, "text": "Du bist noch zu klein! Der Tempel\x01ist nicht der richtige Ort für\x01Kinder. Geh woanders spielen!\x02", "box_type": 0},
    {"id": 0x601F, "text": "Ein Weiser? Keine Ahnung! Ist\x01das jemand, der Vater und Mutter\x01verloren hat?\x02", "box_type": 0},
    {"id": 0x6020, "text": "\x1ADu hast nichts Besseres zu tun?\x01Du kommst wie gerufen! Kannst Du\x01mir einen Gefallen tun, Kleiner?\x04\x1AMoment mal, Du bist doch nicht\x01etwa einer von Ganondorfs...\x04Anhängern... Oder?\x01\x01\x1B\x05\x42Und wenn es so wäre?\x01Ich hasse Ganondorf!\x05\x40\x02", "box_type": 0},
    {"id": 0x6021, "text": "\x1AHahaha!\x01Gib nicht so an, Kleiner!\x04\x1AJemand wie Du könnte nie einer\x01von Ganondorfs Anhängern sein!\x04\x1ADiese Schurken sind aus\x01ganz anderem Holz geschnitzt...\x07\x60\x23\x02", "box_type": 0},
    {"id": 0x6022, "text": "\x1AAch was!\x04\x1ADu bist ganz schön mutig.\x01Ich glaube, ich mag Dich.\x07\x60\x23\x02", "box_type": 0},
    {"id": 0x6023, "text": "\x1AAber erst will ich mich vorstellen.\x01Ich bin die Gerudo-Kriegerin\x01\x05\x41Naboru\x05\x40. Ich gehe lieber allein\x01auf Beutetour.\x04\x1AUnd noch etwas solltest\x01Du wissen!\x04\x1AGanondorf und ich gehören\x01zwar demselben Volk an, doch wir\x01sind grundverschieden.\x04\x1AGanondorf und seine Anhänger\x01haben auch Frauen und Kinder\x01beraubt, ja sogar getötet!\x04\x1AWisse, das Gerudo-Geschlecht\x01besteht nur aus Frauen. Nur alle \x01100 Jahre wird ein Mann geboren...\x04\x1AAuch wenn es unser Gesetz so\x01will, daß dieser Mann der König\x01der Gerudo wird, so schwöre ich\x01Ganondorf niemals im Leben Treue!\x04\x1AAch, wie war eigentlich Dein \x01Name, Kleiner?\x04\x1A\x0F?!\x04\x1AWas ist das denn für ein\x01komischer Name?\x01Naja, egal...\x07\x60\x24\x02", "box_type": 0},
    {"id": 0x6024, "text": "\x1AIch möchte Dich um einen Gefallen\x01bitten...\x04\x1ASchaffst Du es, durch diesen\x01engen Durchlaß zu kriechen und\x01einen Schatz zu bergen?\x04\x1AEs handelt sich um ein uraltes\x01Diebesrelikt, die \x05\x43Krafthandschuhe\x05\x40.\x01Damit kann man sehr schwere\x01Dinge anheben!\x04\x1AHey, Kleiner! Denk nicht mal dran,\x01Dir die Handschuhe selbst unter\x01den Nagel zu reißen!\x04\x1ADie Krafthandschuhe würden Dir\x01sowieso nicht passen!\x01Sei anständig und bring sie mir!\x04\x1AGanondorf und seine Vasallen\x01nutzen den Geistertempel als\x01eines ihrer Verstecke.\x04\x1ANur mit den Krafthandschuhen\x01kann ich mich hier hineinstehlen!\x04\x1ADann kann ich nicht nur all ihr\x01Diebesgut an mich nehmen, sondern\x01auch ihre grauenvollen Pläne\x01durchkreuzen!\x04Also, wie ist es? Machst Du's?\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x6025, "text": "\x1ADanke, Kleiner!\x04\x1AWir beide werden Ganondorfs\x01Tyrannei beenden! Nicht wahr,\x01Kleiner?\x07\x60\x26\x02", "box_type": 0},
    {"id": 0x6026, "text": "Wenn Du die \x05\x43Krafthandschuhe\x01\x05\x40besorgst...\x04Dann werde ich mich bei Dir\x01revanchieren!\x02", "box_type": 0},
    {"id": 0x6027, "text": "Naja, was kann man von einem\x01Kind wie Dir schon erwarten?\x02", "box_type": 0},
    {"id": 0x6028, "text": "\x1AHey! Was macht Ihr miesen\x01alten Weiber mit mir?!\x02", "box_type": 0},
    {"id": 0x6029, "text": "\x1AHihihihi!\x01Sieht so aus, als hätten wir einen \x01ordentlichen Fang gemacht, Koume!\x02", "box_type": 0},
    {"id": 0x602A, "text": "\x1AHihihihi!\x01Sieht ganz so aus, Kotake!\x02", "box_type": 0},
    {"id": 0x602B, "text": "\x1AWie außergewöhnlich, daß sich\x01jemand so tief in unseren Tempel\x01hineintraut...\x01Hihihihi!\x02", "box_type": 0},
    {"id": 0x602C, "text": "\x1AWir sollten ihm eine ordentliche \x01Lektion erteilen!\x01Hihihihi!\x02", "box_type": 0},
    {"id": 0x602D, "text": "\x1AOh, treuer Vasall...\x02", "box_type": 0},
    {"id": 0x602E, "text": "\x1AZerstöre diesen Eindringling!\x02", "box_type": 0},
    {"id": 0x602F, "text": "\x1AGanondorfs... Feinde...\x01müssen sterben...\x02", "box_type": 0},
    {"id": 0x6030, "text": "\x1AUuhh...\x01Wo bin ich...?\x02", "box_type": 0},
    {"id": 0x6031, "text": "\x1AGrummel...\x01Sieht aus, als hätte sie sich\x01befreien können, Koume...\x02", "box_type": 0},
    {"id": 0x6032, "text": "\x1ASie ist noch jung, genießt aber\x01hohen Respekt unter den Gerudo-\x01Kriegerinnen, Kotake...\x02", "box_type": 0},
    {"id": 0x6033, "text": "\x1AVielleicht sollten wir sie etwas\x01länger zum Dienste des mächtigen\x01Ganondorf versklaven!\x01Hihihihi!\x02", "box_type": 0},
    {"id": 0x6034, "text": "\x1AWir sollten ihr Gehirn einer neuen\x01Behandlung unterziehen!\x01Hihihihi!\x02", "box_type": 0},
    {"id": 0x6035, "text": "\x1AKleiner, ich muß Dir danken.\x04\x1AHey... Sieh mal an, was aus Dir\x01geworden ist - ein talentierter\x01Schwertkämpfer!\x02", "box_type": 0},
    {"id": 0x6036, "text": "Du bist wirklich ein tapferer Held \x01geworden!\x0C\x50Dir gebührt eine ganz spezielle\x01Anerkennung...\x0E\x50\x02", "box_type": 5},
    {"id": 0x6037, "text": "\x1AHier, nimm \x05\x41dies\x05\x40...\x01Es ist ein wichtiges Dokument.\x01Unsere Kräfte im Bogenschießen\x01können wir auch später messen!\x02", "box_type": 0},
    {"id": 0x6038, "text": "\x1A\x0F... Wir sehen uns!\x02", "box_type": 0},
    {"id": 0x6039, "text": "\x1AAu weia...\x04\x1AIch bin völlig durcheinander...\x04\x1ADie beiden alten Weiber haben\x01mich verhext. Ich mußte für\x01Ganondorf tun, was er\x01verlangte...\x04\x1AAber bist Du nicht überrascht?\x01Jemand wie ich ist letztendlich die\x01\x05\x46Weise der Geister\x05\x40!\x04\x1AAb jetzt kämpfe ich als eine der\x01Weisen gegen das Böse!\x04\x1ANun werden sie für das bezahlen,\x01was sie mir angetan haben!\x02", "box_type": 0},
    {"id": 0x603A, "text": "\x1AKleiner...\x04\x1ANein...\x01\x0F, der strahlende\x01Wanderer durch die Zeiten!\x04\x1AAls Dank dafür, daß Du den\x01Fluch vom Geistertempel genommen\x01hast, übergebe ich Dir\x01dieses \x05\x46Amulett\x05\x40!\x04\x1ANimm es!\x02", "box_type": 0},
    {"id": 0x603B, "text": "\x1A\x08\x06\x2EAaargh!\x09 Laßt mich!\x02", "box_type": 0},
    {"id": 0x603C, "text": "\x1A\x06\x14Ihr \x08widerlichen alten Hexen!\x09\x01\x06\x03Ihr seid Ganondorfs eklige Sklaven!\x02", "box_type": 0},
    {"id": 0x603D, "text": "\x1A\x08\x06\x20Flüchte, \x0F!\x09\x01\x06\x51Schnell!\x02", "box_type": 0},
    {"id": 0x603E, "text": "\x1A\x06\x15Verdammte Hexen! Sie setzen\x01\x06\x0Dschwarze Magie gegen mich ein!\x02", "box_type": 0},
    {"id": 0x603F, "text": "Hey, Kleiner! Das ist die \x05\x41Arena\x01für Bogenschießen zu Pferde\x05\x40.\x04Wir treffen genau den Mittelpunkt\x01der Zielscheibe. Egal, wie wild wir\x01reiten!\x04Wenn Du reiten kannst, dann\x01komm zu uns und probier es auch\x01aus. Es ist gefährlich - aber ein\x01Riesenspaß!\x02", "box_type": 0},
    {"id": 0x6040, "text": "Hey, Junge, Du hast da aber ein\x01tolles Pferd!\x04Keine Ahnung, wo Du das geklaut\x01hast, aber...\x04...wie wäre es mit einer Runde\x01\x05\x41Bogenschießen\x05\x40 \x05\x41zu Pferde\x05\x40!?\x04Sowie Dein Pferd galoppiert,\x01schieße mit Deinen Pfeilen auf\x01die Zielscheiben.\x04Wir werden ja sehen, wie oft Du\x01triffst! Du bekommst 20 Pfeile.\x04Wenn Du \x05\x411.000 Punkte\x05\x40 erreichst,\x01erhältst Du einen genialen\x01Preis!\x0B\x02", "box_type": 0},
    {"id": 0x6041, "text": "Willst Du es versuchen?\x01Es kostet nur \x05\x4120 Rubine\x05\x40!\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x6042, "text": "Hey, Kleiner!\x01Das sieht gar nicht schlecht aus!\x01Zeig's mir nochmal!\x04Versuche doch jetzt,\x01\x05\x411.500 Punkte\x05\x40 zu erreichen!\x0B\x02", "box_type": 0},
    {"id": 0x6043, "text": "Was? Du willst es nochmal\x01versuchen?\x01Du gibst wohl so schnell nicht\x01auf, was?\x0B\x02", "box_type": 0},
    {"id": 0x6044, "text": "Donnerwetter! Du bist ja ein \x01wahrer Meister Deines Fachs!\x04Ich gebe Dir etwas, dessen nur\x01ein echter Meister würdig ist.\x04Es ist ein wertvoller Köcher,\x01den ich Dir überreiche. Er gehört\x01nun Dir. Behandle ihn gut!\x02", "box_type": 0},
    {"id": 0x6045, "text": "\x18 Punkte... Hmmm...\x01Hahaha! Da mußt Du wohl noch\x01ein bißchen üben!\x0B\x02", "box_type": 0},
    {"id": 0x6046, "text": "Großartig!\x01Du bist ja ein absoluter König\x01im Bogenschießen!\x04Hier, nimm dies.\x01Du kannst es bestimmt\x01gut gebrauchen!\x02", "box_type": 0},
    {"id": 0x6047, "text": "\x18 Punkte...\x01Ganz ordentlich!\x0B\x02", "box_type": 0},
    {"id": 0x6048, "text": "Sieh Dir diesen Dummkopf an!\x01Er kam freiwillig als Opfer\x01für den mächtigen Ganondorf...\x0E\x5A\x02", "box_type": 0},
    {"id": 0x6049, "text": "\x06\x2AMeine Flammen werden\x01\x06\x3Cihn bis auf die\x01\x06\x2EKnochen verbrennen!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x604A, "text": "\x06\x3FMein Eiszauber\x01\x06\x39wird seine Seele\x01\x06\x3Agefriertrocknen!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x604B, "text": "\x06\x28Verhext und zugenäht!\x01\x06\x25So ein widerliches Balg!\x01\x06\x1CAb jetzt machen wir Ernst!\x01\x06\x42Was, Kotake?\x0E\x5A\x02", "box_type": 0},
    {"id": 0x604C, "text": "\x06\x50Waaaas?\x0C\x14\x06\x15Hey, Koume! Was schwebt da\x01\x06\x32über Deinem Kopf?\x0E\x3C\x02", "box_type": 0},
    {"id": 0x604D, "text": "\x06\x17Weiß ich nicht, aber über Dir\x01\x06\x15schwebt auch etwas, Kotake!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x604E, "text": "\x06\x0BAber ich bin erst 400 Jahre alt!\x0E\x28\x02", "box_type": 0},
    {"id": 0x604F, "text": "\x06\x0FUnd ich bin erst 380 Jahre alt!\x0E\x28\x02", "box_type": 0},
    {"id": 0x6050, "text": "\x08\x06\x33Wir sind Zwillinge!\x01\x06\x10Mach Dich nicht jünger,\x01\x06\x3Eals Du bist!\x09\x0E\x28\x02", "box_type": 0},
    {"id": 0x6051, "text": "\x08\x06\x28Du bist ja völlig senil!\x09\x0E\x14\x02", "box_type": 0},
    {"id": 0x6052, "text": "\x08\x06\x1BWen nennst Du hier senil?!\x01\x06\x26Behandelt man so seine\x01\x06\x32ältere Schwester?\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x6053, "text": "\x08\x06\x30Wir sind Zwillinge! \x01\x06\x14Wie kannst Du da älter sein?\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x6054, "text": "\x08\x06\x4FIiihhhh!\x09\x01\x08\x06\x24Du herzloses Miststück!\x09\x0E\x14\x02", "box_type": 0},
    {"id": 0x6055, "text": "\x08\x06\x2ADu undankbares Weib!\x09\x0E\x0A\x02", "box_type": 0},
    {"id": 0x6056, "text": "\x08\x06\x3ADu bist herzlos!\x09\x0E\x04\x02", "box_type": 0},
    {"id": 0x6057, "text": "\x08\x06\x24Und Du bist undankbar...\x09\x0E\x04\x02", "box_type": 0},
    {"id": 0x6058, "text": "\x08\x06\x29Ich mach Dich fertig!\x09\x0E\x28\x02", "box_type": 5},
    {"id": 0x6059, "text": "\x08Okay, laß uns jetzt Ernst machen!\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x605A, "text": "\x06\x41\x08Okay, Koume.\x09\x0C\x14\x06\x2C\x08Kotakes\x09 und \x08Koumes\x09\x01\x06\x2D\x08Sexy\x09 Thermo \x08Hexy!\x09\x0E\x28\x02", "box_type": 0},
    {"id": 0x605B, "text": "\x1ABist Du hier, um mich zu retten? \x01Oh, das ist ja wirklich nett!\x01Ich bin \x05\x41John, der Zimmermann\x05\x40.\x04\x1AWir wollten uns eigentlich den\x01Gerudo-Kriegerinnen anschließen...\x01Aber dann haben sie uns\x01eingesperrt, weil wir Männer sind!\x04\x1AJetzt wollen wir aber lieber\x01wieder heim! Diese Gerudos sind\x01schrecklich ungehobelt!\x04\x1A\x05\x41Drei meiner Kumpels\x05\x40 sind hier\x01noch eingesperrt.\x01Befreie sie bitte!\x02", "box_type": 0},
    {"id": 0x605C, "text": "\x1ADas ist wirklich nett von Dir,\x01Kleiner! Danke für die Rettung!\x01Ich bin \x05\x41Paul, der Zimmermann\x05\x40.\x04\x1ADiese Frauen hier machen mir\x01Angst! Ich bleibe lieber weiter\x01Zimmermann, als mich ihnen\x01anzuschließen!\x04\x1AIch kann es kaum erwarten, wieder\x01daheim zu sein! \x05\x41Zwei meiner\x01Kumpels \x05\x40sind noch eingesperrt.\x01Hilfst Du ihnen?\x02", "box_type": 0},
    {"id": 0x605D, "text": "\x1ADanke, Junge! Du bist super!\x01Ich bin \x05\x41George, der Zimmermann\x05\x40.\x04\x1AHast Du unseren Chef gesehen?\x01Er hat vielleicht Angst um uns!\x01Ich muß \x08sofort\x09 zu ihm!\x04\x1A\x05\x41Einer von uns \x05\x40ist noch gefangen.\x01Bitte hilf auch ihm!\x02", "box_type": 0},
    {"id": 0x605E, "text": "\x1AIch habe schon gedacht, Du hättest\x01mich vergessen! Vielen Dank!\x01Ich bin \x05\x41Ringo, der Zimmermann\x05\x40.\x04\x1ADafür, daß Du mich befreit hast,\x01verrate ich Dir, was sich die\x01Gerudos über die Wüste erzählen:\x04\x1A\"Wer die Gespensterwüste\x01durchqueren will, braucht das \x05\x41Auge\x01der Wahrheit\x05\x40. Den Wüstenkoloss\x01findet man jenseits der Wüste...\"\x04\x1AIch gehe jetzt zu meinem \x05\x41Zelt in\x01der Nähe des Gerudotals\x05\x40. Schau\x01doch mal vorbei, vielleicht gibt es\x01dort etwas für Dich! Leb wohl!\x02", "box_type": 0},
    {"id": 0x605F, "text": "\x05\x41Naboru\x05\x40, die Anführerin der Gerudo-\x01Kriegerinnen, scheint Menschen\x01für ihre Zwecke zu versklaven...\x02", "box_type": 0},
    {"id": 0x6060, "text": "Oh, es war Ganondorf, der\x01Großmeister des Bösen, der hinter\x01allem steckte...?\x02", "box_type": 0},
    {"id": 0x6061, "text": "\x1AAls \x05\x41Naboru\x05\x40 noch zu den Diebinnen\x01gehörte, hat sie nie die Schwachen\x01und Armen bestohlen.\x07\x60\x62\x02", "box_type": 0},
    {"id": 0x6062, "text": "Jetzt aber sind sie und ihre\x01Diebinnen brutal und rücksichtslos\x01geworden. Sie behauptet, sie sei\x01edel, aber... Von wegen!\x02", "box_type": 0},
    {"id": 0x6063, "text": "Wie ich mir dachte: Naboru wurde\x01mit Hexerei von Ganondorfs\x01Schergen zu einer willenlosen\x01Sklavin gemacht...\x02", "box_type": 0},
    {"id": 0x6064, "text": "\x1ABei den Gerudo-Kriegerinnen\x01genießen besonders jene hohes\x01Ansehen, die gute Reiter und \x01Bogenschützen sind.\x07\x60\x65\x02", "box_type": 0},
    {"id": 0x6065, "text": "Wie wär's mit etwas Bogenschießen\x01zu Pferde?\x04Wenn Du ein Pferd besitzt, dann\x01findet sich in der Festung sicher\x01eine Gerudo, die Dich\x01herausfordert!\x02", "box_type": 0},
    {"id": 0x6066, "text": "Das hast Du großartig\x01gemacht, Junge!\x02", "box_type": 0},
    {"id": 0x6067, "text": "Wenn wir alle zusammen sind,\x01ist es ein Kinderspiel, eine\x01Brücke über den Abgrund\x01zu bauen!\x02", "box_type": 0},
    {"id": 0x6068, "text": "Ohne die widerlichen alten Hexen\x01machen mir die Gerudos nicht\x01mehr soviel Angst!\x02", "box_type": 0},
    {"id": 0x6069, "text": "Hinter diesem Tor befindet sich\x01die \x05\x41Gerudo-Festung\x05\x40. Kinder haben\x01hier nichts zu suchen.\x02", "box_type": 0},
    {"id": 0x606A, "text": "\x1A\x12\x68\x55Ich bin \x05\x41Handwerkermeister\x05\x40.\x01Es waren Gerudos, die die Brücke\x01zerstört haben.\x04\x1AIch will sie reparieren, aber meine\x01Leute sind verschwunden!\x04\x1ASie haben gesagt, ihr Job sei öde.\x01Sie wollten lieber in die \x05\x41Gerudo-\x01Festung \x05\x40gehen, um Diebe\x01zu werden...\x07\x60\x6B\x02", "box_type": 0},
    {"id": 0x606B, "text": "Hey, Du! Wenn Du schon in die\x01Festung gehst... Kannst Du\x01herausfinden, was meine Jungs\x01dort tun?\x02", "box_type": 0},
    {"id": 0x606C, "text": "Hey, ich habe gehört, daß Du\x01meine Leute gerettet hast.\x01Als Gegenleistung haben wir die\x01Brücke repariert!\x04Schau her! Ist sie nicht toll?\x04Meine Arbeiter sind ziemliche\x01Weicheier. Aber wenn sie alle\x01gemeinsam zulangen, dann ist so \x01ein Job schnell erledigt.\x02", "box_type": 0},
    {"id": 0x606D, "text": "\x1A\x12\x68\x55Oh, das ist ja meine Säge!\x04\x1AAber... Ich dachte, ich hätte sie\x01bei der alten Frau liegen gelassen...\x07\x60\x6E\x02", "box_type": 0},
    {"id": 0x606E, "text": "Ich besitze übrigens ein\x01zerbrochenes Biggoron-Schwert.\x01Du müßtest es nur von einem\x01Goronen reparieren lassen...\x04Ich würde es gegen die Säge\x01eintauschen! Gibst Du sie mir?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x606F, "text": "\x06\x53\x08Was?!\x01\x06\x03Du stinkender, widerlicher Dieb!\x09\x02", "box_type": 0},
    {"id": 0x6070, "text": "Dies ist die \x05\x41Trainingsarena \x05\x40der\x01Gerudos. Wer sie betreten will,\x01braucht ein besonderes\x01Dokument!\x02", "box_type": 0},
    {"id": 0x6071, "text": "Dies ist die \x05\x41Trainingsarena \x05\x40der \x01Gerudos.\x05\x41 \x05\x40Du darfst eintreten...\x01Trainiere Deine Fähigkeiten, so\x01lange Du willst.\x0B\x02", "box_type": 0},
    {"id": 0x6072, "text": "Dies ist die \x05\x41Trainingsarena \x05\x40der \x01Gerudos. Auch wenn Du sehr gut\x01bist: Sacke nicht alle Schätze\x01selbst ein!\x02", "box_type": 0},
    {"id": 0x6074, "text": "Oh, wie schade.\x04Das Zeichen, welches Euch zum\x01Geistertempel führt, ist die \x05\x41Flagge\x01zur Linken\x05\x40 außerhalb des Ladens.\x04Solltet Ihr es Euch anders\x01überlegen, dann kommt doch\x01bitte wieder!\x02", "box_type": 0},
    {"id": 0x6075, "text": "Oh, Ihr habt zu wenig Rubine.\x01Ich gebe keinen Nachlass,\x01nicht einen Rubin!\x02", "box_type": 0},
    {"id": 0x6076, "text": "Keuch...\x01Du bist doch schon mit etwas\x01anderem beschäftigt, oder?\x04Wenn Du mich herausfordern willst,\x01dann komm wieder, wenn Du den\x01Kopf dafür frei hast!\x02", "box_type": 0},
    {"id": 0x6077, "text": "\x06\x46Willkommen!\x04Ich verkaufe hier seltsame, seltene\x01Sachen aus der ganzen Welt. Mein\x01heutiges Angebot ist...\x04Ein bombiges, ferngesteuertes\x01Objekt! Furchterregend!\x01Ich erzähle Euch erst etwas davon,\x01wenn ich Geld sehe...\x04Wie wär's mit \x05\x41200 Rubinen\x05\x40?\x01\x01\x1B\x05\x42Kaufen!\x01Nicht kaufen!\x05\x40\x02", "box_type": 0},
    {"id": 0x6078, "text": "Vielen herzlichen Dank!\x04Ich verkaufe... \x14\x02\x05\x41Krabbelminen\x05\x40!\x14\x00\x04Das Zeichen, welches Euch zum\x01Geistertempel führt, ist die \x05\x41Flagge\x01zur Linken\x05\x40 außerhalb des Ladens.\x01Schaut mal wieder vorbei!\x02", "box_type": 0},
    {"id": 0x6079, "text": "\x1AHey, was ist, \x0F?\x01Überrascht, mich zu sehen?\x04\x1ALange Jahre in der Zukunft\x01bedeuten anscheinend gar\x01nichts. Hier sind nur wenige\x01Sekunden vergangen!\x04\x1ASogar ich hatte gedacht, daß\x01Reisen durch die Zeit eine reine\x01Legende seien.\x04\x1A\x0F, Du hast viel\x01Erfahrung gesammelt!\x07\x60\x7A\x02", "box_type": 0},
    {"id": 0x607A, "text": "Das Schicksal Hyrules liegt von\x01nun an in Deinen Händen.\x04Vielleicht ist meine Zeit jetzt\x01vorüber. Hier ist ein letzter Rat:\x04In diesem Tempel hausen zwei alte\x01Hexen. Um sie zu vernichten,\x01\x05\x41schlage sie mit ihren eigenen\x01magischen Waffen\x05\x40!\x07\x60\x7B\x02", "box_type": 0},
    {"id": 0x607B, "text": "Möchtest Du das, was ich gesagt\x01habe, noch einmal hören?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x607C, "text": "\x1AIch werde Dich\x01weiterhin beobachten...\x01Viel Glück!\x02", "box_type": 0},
    {"id": 0x607D, "text": "\x1AIch bin reisender Rennläufer!\x01Ich habe das ganze Land berannt...\x01ähh, bereist, um jemanden mit\x01echtem Sportsgeist zu finden!\x04\x1AOb Mensch oder Tier - ich habe\x01alle Herausforderer geschlagen.\x04\x1ADu siehst sportlich aus und hast\x01wohl auch den nötigen Biß!\x04\x1ADa jetzt die Brücke über den\x01Abgrund repariert wurde,\x01suche ich einen Herausforderer\x01für einen Marathon!\x07\x60\x7E\x02", "box_type": 0},
    {"id": 0x607E, "text": "Die Bestzeit von hier zur \x05\x42Brücke\x01nach Kokiri \x05\x40war:\x01\x05\x41\x1E\x04\x05\x40.\x01Das ist mein Rekord!\x04Willst Du versuchen, diesen\x01Rekord zu brechen?\x01\x1B\x05\x42Ja!\x01Nein! \x05\x40\x02", "box_type": 0},
    {"id": 0x607F, "text": "Ausgezeichnet!\x01Also...\x04Du fängst an.\x01Ich gebe Dir sogar Vorsprung.\x04\x14\x02Los geht's.\x14\x00\x02", "box_type": 0},
    {"id": 0x6080, "text": "Mit dieser Einstellung kommst Du\x01aber nicht sehr weit, mein Junge!\x02", "box_type": 0},
    {"id": 0x6081, "text": "Nun ja, nicht perfekt, aber Du\x01traust Dich was! Nur dumm,\x01daß Du mich nie schlagen wirst.\x01Dein Rekord ist schon vergessen!\x04Deine Zeit betrug \x05\x41\x1E\x04\x05\x40, oder?\x01Denkbar knapp, aber ich war um\x01eine Sekunde schneller!\x0B\x02", "box_type": 0},
    {"id": 0x6082, "text": "Hihihi...\x01Bitte! \x14\x02Lauf weiter!\x14\x00\x02", "box_type": 0},
    {"id": 0x6083, "text": "Oh, sieht aus, als würdest Du\x01aufgeben wollen. Hihihi...\x01Fast hättest Du Deine alte Form \x01wiedererlangt!\x0E\x3C\x02", "box_type": 0},
    {"id": 0x6084, "text": "Hihihi...\x01Du hast doch noch nicht den\x01rechten Biß, mein Lieber.\x04Du mußt härter trainieren.\x01\x08Mach's mal gut!\x09\x0B\x02", "box_type": 0},
    {"id": 0x6085, "text": "\x14\x01\x08Keuch...\x09 \x08Pust...\x09 \x08Hust...\x09\x14\x00\x04Keuch... Pust... Wow!\x01Das war sehr gut!\x04Doch Du hast mich noch nicht\x01geschlagen!\x01Deine Bestzeit war \x05\x41\x16\x05\x40, aber\x01ich war eine Sekunde schneller!\x04Keuch... Hust... \x01Versuche es irgendwann noch\x01einmal!\x04Keuch... Pust...\x01\x08Mach's mal gut!\x09\x0B\x02", "box_type": 0},
    {"id": 0x6086, "text": "Ich bin reisender Rennläufer!\x01Ich habe das ganze Land berannt...\x01ähh, bereist, um jemanden mit\x01echtem Sportsgeist zu finden!\x04Ich bin hierher gekommen, um durch\x01die Gespensterwüste zu laufen...\x01Aber das war, glaube ich, kein\x01guter Zeitpunkt.\x04Ich wollte zur hylianischen Steppe\x01zurück, aber die Brücke ist...\x01Naja, das siehst Du ja selbst.\x01Jetzt sitze ich hier fest.\x04Ich kann daher auch Deine\x01Herausforderung leider noch\x01nicht annehmen. Hihihi!\x02", "box_type": 0},
    {"id": 0x7000, "text": "Ich kann dieses Huhn\x01nicht einfangen!\x02", "box_type": 0},
    {"id": 0x7001, "text": "Keuch! \x01Ich bin schwer\x01am Trainieren!\x02", "box_type": 0},
    {"id": 0x7002, "text": "Lang lebe Prinzessin Zelda!\x02", "box_type": 0},
    {"id": 0x7003, "text": "In Deinem Alter solltest Du um\x01diese Zeit im Bett liegen! Bleib\x01lieber im Haus bis morgen früh!\x02", "box_type": 0},
    {"id": 0x7004, "text": "Mann, ist mir langweilig...\x01Es wäre bestimmt spannender,\x01wenn hier mehr los wäre...\x04Hey, das bleibt aber unter uns,\x01klar?\x04Egal, vielleicht können wir ja\x01etwas Dampf ablassen, indem wir\x01ein paar Krüge zerschlagen.\x04Stelle Dich vor einen Krug und\x01drücke \x05\x43\x05\x40, um ihn anzuheben.\x01Drückst Du nochmal \x05\x43\x05\x40, wirfst\x01Du ihn!\x02", "box_type": 0},
    {"id": 0x7005, "text": "\x1AGroßartig!\x04\x1ADas habe ich ganz vergessen...\x0B\x02", "box_type": 0},
    {"id": 0x7006, "text": "\x08Im Schloß ist es zur Zeit ziemlich\x01unruhig. Daher darf es\x01niemand betreten!\x09\x02", "box_type": 0},
    {"id": 0x7007, "text": "\x1AArrgh... Bist Du der Junge aus\x01dem Wald...?\x04\x1AEndlich treffe ich Dich...\x01Ich... Ich muß Dir etwas... mitteilen...\x04\x1A\x05\x41Ganondorf\x05\x40, der Herr der Gerudo,\x01hat unseren König verraten...\x04\x1A\x05\x41Impa\x05\x40 hat die Gefahr erkannt und\x01ist mit Prinzessin Zelda aus dem\x01Schloß geflüchtet...\x04\x1AIch habe versucht, Ganondorfs\x01Leute daran zu hindern, ihnen zu\x01folgen... aber... ohne Erfolg...\x04\x1ADie Prinzessin hat... auf einen\x01Jungen aus dem Wald gewartet...\x01auf Dich... Sie wollte Dir \x05\x41etwas\x01geben\x05\x40...\x04\x1AWenn Du es hast, dann \x14\x03\x08eile\x09... \x08zur\x09\x01\x05\x44\x08Zita\x09\x08delle\x09 \x08der\x09 Zeit\x05\x40...\x14\x00\x0B\x02", "box_type": 0},
    {"id": 0x7008, "text": "Er rührt sich nicht mehr...\x02", "box_type": 2},
    {"id": 0x7009, "text": "\x1ASiehst Du den Mann dort?\x01Den mit dem bösen Blick?\x04\x1ADas ist \x05\x41Ganondorf\x05\x40, Anführer der \x01Gerudos, die in der Wüste fern im\x01Westen unseres Landes leben.\x04\x1AEr hat meinem Vater die Treue\x01geschworen, doch ich glaube nicht,\x01daß er aufrichtig ist.\x04\x1ADie dunklen Wolken, die Hyrule in\x01meinen Träumen einhüllten...\x01Sie müssen diesen Mann\x01symbolisiert haben!\x02", "box_type": 0},
    {"id": 0x700A, "text": "\x06\x08Hahaha! Ausgezeichnet, Kleiner!\x0C\x3CWie ich mir dachte, besitzt Du den\x01\x06\x1ASchlüssel zum Zeitportal!\x0C\x5A\x06\x34Du hast mich zum\x01\x06\x20Heiligen Reich geführt...\x0C\x50\x06\x12Ich muß Dir danken, Kleiner!\x0E\x32\x02", "box_type": 0},
    {"id": 0x700B, "text": "\x1ABitte! Wenn Du Dich nicht beeilst,\x01wird er fort sein!\x0B\x02", "box_type": 0},
    {"id": 0x700C, "text": "Bitte... Verkaufe mir etwas mit \x05\x46¡\x05\x40...\x01Verkaufe mir den \x05\x41Inhalt\x05\x40 einer\x01Flasche...\x01Bitte... Drücke \x05\x46¡\x05\x40...\x02", "box_type": 0},
    {"id": 0x700D, "text": "Welch merkwürdiger Laden! \x01Ich frage mich, wann er öffnet.\x01Ich habe zwar das Schild gelesen,\x01aber es ist doch sehr seltsam!\x02", "box_type": 0},
    {"id": 0x700E, "text": "Es scheint ewig zu dauern,\x01bis die Sonne aufgeht...\x04Der Blick auf Schloß Hyrule im\x01Licht der aufgehenden Sonne ist\x01einfach fantastisch!\x02", "box_type": 0},
    {"id": 0x700F, "text": "Um das Mädchen aus dem Wald zu\x01retten, brauchst Du einen\x01\x05\x41weiteren Ausrüstungsgegenstand\x05\x40... \x01Geh zurück nach Kakariko!\x02", "box_type": 0},
    {"id": 0x7010, "text": "Es scheint, als hättest Du, was \x01Du benötigst... \x01Das\x05\x42 Mädchen aus dem Wald\x01\x05\x40wartet auf Deine Hilfe...\x02", "box_type": 0},
    {"id": 0x7011, "text": "Wenn Du Elixiere kaufen willst,\x01dann bringe eine leere Flasche mit.\x01Hast Du verstanden, Junge?\x0A\x02", "box_type": 0},
    {"id": 0x7012, "text": "Tut mir leid, das ist nur eine\x01Attrappe. Wegen der Probleme in\x01Goronia haben wir in der letzten\x01Zeit kein Material mehr bekommen.\x0A\x02", "box_type": 2},
    {"id": 0x7013, "text": "Wenn Du auf den Todesberg willst,\x01kaufe besser einen \x05\x44Hylia-Schild\x05\x40.\x01Damit schützt Du Dich vor\x01herabfallenden Lavabrocken.\x04Aber für ein Kind ist der Schild\x01vielleicht eine Nummer zu groß...\x0A\x02", "box_type": 0},
    {"id": 0x7014, "text": "Ich tanze nicht, weißt Du...\x01Mir tut der Rücken weh!\x01Auu! Aaah!\x02", "box_type": 0},
    {"id": 0x7015, "text": "Es heißt, wir \x05\x44Hylianer \x05\x40hätten so\x01große Ohren, um die Stimmen der\x01Götter hören zu können.\x01Aber ich habe sie nie gehört!\x02", "box_type": 0},
    {"id": 0x7016, "text": "\x1AWarst Du schon einmal auf der\x01\x05\x46Lon Lon-Farm\x05\x40, Kleiner?\x04\x1ADie Milch dort ist köstlich!\x01Außerdem gibt es da viele Pferde,\x01und die junge Tochter des Farmers\x01ist richtig süß!\x07\x70\x17\x02", "box_type": 0},
    {"id": 0x7017, "text": "Zur \x05\x46Farm \x05\x40kommst Du, wenn Du\x01nach dem Ortsausgang durch die\x01Steppe nach Süden gehst.\x01Besuche sie unbedingt einmal!\x02", "box_type": 0},
    {"id": 0x7018, "text": "\x1AIch wollte zu \x05\x41Prinzessin Zelda\x05\x40!\x04\x1AHabe die Wachen umgangen...\x04\x1ABin durch den Burggraben\x01geschwommen...\x04\x1AIch war fast bei ihr, als sie\x01mich doch noch geschnappt haben!\x07\x70\x19\x02", "box_type": 0},
    {"id": 0x7019, "text": "Ich habe ein enges \x05\x41Abflußloch \x05\x40auf\x01der Ostseite des Schlosses\x01gefunden und dachte, ich käme\x01durch. Aber ich blieb hängen!\x02", "box_type": 0},
    {"id": 0x701A, "text": "\x06\x53\x08Ähem!\x09\x04\x06\x06Dieser Bart ist mein ganzer Stolz!\x01\x06\x01Ist er nicht eindrucksvoll, Kleiner?\x02", "box_type": 0},
    {"id": 0x701B, "text": "\x1A\x06\x37Ähem! \x08Hrrrm!\x09\x04\x1A\x06\x06Dieser Bart ist mein ganzer Stolz!\x01Ist er nicht eindrucksvoll, Kleiner?\x04\x1A\x08\x06\x56Was?!\x09\x04\x1ADu suchst den Typen von der\x01Lon Lon-Farm?\x04\x1AHmmm, wart mal...\x07\x70\x1C\x02", "box_type": 0},
    {"id": 0x701C, "text": "Ich habe gesehen, wie ein \x05\x41Typ mit\x01einem zerrupften Bart\x05\x40 Kisten zum \x01Schloß gebracht hat.\x02", "box_type": 0},
    {"id": 0x701D, "text": "\x1AKennst Du die \x05\x44Zitadelle \x01der Zeit\x05\x40, die sich im Nordosten\x01der Stadt befindet?\x07\x70\x1E\x02", "box_type": 0},
    {"id": 0x701E, "text": "Die Legenden besagen, daß sich in\x01der Zitadelle der Zeit der Zugang\x01zum Heiligen Reich befindet...\x04Hast Du das schon gewußt?\x02", "box_type": 0},
    {"id": 0x701F, "text": "\x1AHahaha! Welch dämlicher\x01Kerl!\x04\x1AKannst Du Dir vorstellen, daß er\x01sich tatsächlich ins Schloß \x01hineinschleichen wollte,\x01um \x05\x41Prinzessin Zelda\x05\x40 zu sehen?\x07\x70\x20\x02", "box_type": 0},
    {"id": 0x7020, "text": "Wegen diesem Idioten haben sie\x01die Bewachung vor dem Schloß\x01noch verstärkt!\x01Hahaha!\x02", "box_type": 0},
    {"id": 0x7021, "text": "\x1AIch habe tierisch viel verdient!\x04\x1AVielleicht sollte ich noch\x01mehr Sachen suchen, die ich\x01verkaufen kann!\x07\x70\x22\x02", "box_type": 0},
    {"id": 0x7022, "text": "Ich weiß schon! Ich sollte zum\x01\x05\x43Hylia-See\x05\x40 gehen!\x01Da wird immer eine Menge\x01interessantes Zeug angeschwemmt!\x02", "box_type": 0},
    {"id": 0x7023, "text": "\x1AHey, Waldschrat! Das ist \x05\x44Hyrule\x05\x40!\x01Nimm Dir Zeit und schau Dich in\x01aller Ruhe um!\x07\x70\x24\x02", "box_type": 0},
    {"id": 0x7024, "text": "Wenn Du zum \x05\x44Schloß von Hyrule\x05\x40\x01möchtest, nimm die Straße zu\x01Deiner Rechten.\x04Wenn Du die \x05\x43Seitenstraßen\x05\x40\x01erforschen willst, geh\x01nach links.\x02", "box_type": 0},
    {"id": 0x7025, "text": "Hey!\x04Du... siehst gut aus...\x04Fast wie der König von Hyrule...\x04Hihihi...\x02", "box_type": 0},
    {"id": 0x7026, "text": "Ohh...\x04Du bist ja...\x04noch schöner...\x04als Prinzessin Zelda...\x04Ohh...\x02", "box_type": 0},
    {"id": 0x7027, "text": "\x1AHast Du von der Legende des\x01\"Schattenvolks\" gehört?\x04\x1AEs sind die \x05\x43Shiekah\x05\x40... Die Schatten\x01der Hylianer.\x04\x1AEs heißt, sie hätten dem König von\x01Hyrule ewige Treue geschworen,\x01um ihn und seine Familie\x01stets zu beschützen.\x04\x1AAber nach solch einer langen Zeit\x01voller Frieden, haben wir schon\x01lange keinen der Shiekah mehr\x01gesehen.\x04\x1ADennoch...\x07\x70\x28\x02", "box_type": 0},
    {"id": 0x7028, "text": "Ich habe gehört, daß es noch eine\x01Vertreterin der \x05\x43Shiekah\x05\x40 geben soll.\x01Sie lebt im Schloß...\x02", "box_type": 0},
    {"id": 0x7029, "text": "Also Du sagst, Du willst \x01\x05\x41Prinzessin Zelda\x05\x40 sehen, wie?\x04Du hast bestimmt im Ort von ihr\x01gehört und willst sie jetzt\x01unbedingt kennenlernen... Nun...\x04\x08Geh heim!\x09 \x08Verschwinde!\x09\x01Einem wie Dir würde die Prinzessin\x01niemals Audienz gewähren!\x02", "box_type": 0},
    {"id": 0x702A, "text": "Zzzzzzzz...\x04Murmel... Grummel...\x04Milch... frisch abliefern...\x04Muß... mich beeilen...\x02", "box_type": 0},
    {"id": 0x702B, "text": "\x1A\x08\x06\x35Was zum Teufel...?\x09\x04\x1AKann man denn nicht mal für eine\x01Sekunde die Augen zumachen?\x02", "box_type": 0},
    {"id": 0x702C, "text": "\x1AHallo! Wer bist Du?\x04\x1AAlso ich bin \x05\x41Talon\x05\x40, Besitzer der\x01Lon Lon-Farm.\x04\x1AIch war auf dem Weg zum Schloß,\x01um frische Milch zu liefern. Als\x01ich mich kurz ausruhen wollte, muß\x01ich wohl eingeschlafen sein...\x04\x1A\x06\x4C\x12\x68\x52Was?!\x01Malon sucht nach mir?\x01Da bekomme ich wieder gehörigen\x01Ärger!\x04\x1AIch hatte ihr doch versprochen...\x04\x1AAu weia, das läuft nicht gut!\x0B\x02", "box_type": 0},
    {"id": 0x702D, "text": "\x08\x06\x35Hey, Kleiner! Halt!\x01Stehenbleiben! Im Namen des Königs!\x09\x0B\x02", "box_type": 0},
    {"id": 0x702E, "text": "\x1A\x06\x53\x08Nanu?\x09\x0B\x02", "box_type": 0},
    {"id": 0x702F, "text": "\x1A\x06\x3AWer bist Du?\x04\x1AWie hast Du es geschafft,\x01an den Wachen vorbeizukommen?\x0B\x02", "box_type": 0},
    {"id": 0x7030, "text": "Nun, hast Du ihn dabei? \x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x7031, "text": "Das ist seltsam...\x01Ich glaubte eben, Du wärst der\x01Junge aus meinem Traum...\x01Du hast ihn wirklich nicht?\x04Sag mir bitte die Wahrheit...\x0B\x02", "box_type": 0},
    {"id": 0x7032, "text": "\x1AWie ich mir dachte!\x0B\x02", "box_type": 0},
    {"id": 0x7033, "text": "Du wirst das doch\x01nicht weitererzählen?\x01\x1B\x05\x42Okay!\x01Doch!\x05\x40\x02", "box_type": 0},
    {"id": 0x7034, "text": "Also das hätte ich von Dir\x01nicht gedacht!\x0B\x02", "box_type": 0},
    {"id": 0x7035, "text": "\x1ADies ist die Legende...\x0B\x02", "box_type": 0},
    {"id": 0x7036, "text": "\x1A\x06\x11Das \x05\x41Triforce\x05\x40 vereinte die Kraft\x01\x06\x0Ader drei Göttinnen. Sie verbargen\x01\x06\x1Ces an einem Ort in Hyrule.\x0C\x50\x1A\x06\x0BDenn das Triforce hat die Macht,\x01\x06\x09die Wünsche dessen wahr werden\x01\x06\x09zu lassen, der es in Händen hält!\x0C\x50\x1A\x06\x0DEin rechtschaffenes Herz würde\x01\x06\x13Hyrule in goldene Zeiten voller\x01\x06\x14Reichtum und Frieden führen...\x0C\x3C\x1A\x06\x0DWürden Wünsche eines Menschen\x01\x06\x12mit niederer Gesinnung erfüllt,\x01\x06\x07so verschlänge das Böse die Welt!\x0C\x50\x1A\x06\x0FDaher errichteten die Weisen die\x01\x06\x06\x05\x44Zitadelle der Zeit\x05\x40, um das Triforce\x01\x06\x0Cvor bösen Mächten zu bewahren.\x0E\x5A\x02", "box_type": 2},
    {"id": 0x7037, "text": "Die Zitadelle der Zeit ist\x01in unserer Welt der Zugang zum\x01Heiligen Reich.\x04Doch dieser Zugang ist versiegelt\x01durch eine steinerne Mauer, die\x01man \x05\x44Zeitportal\x05\x40 nennt.\x04Es heißt, man brauche die drei\x01\x05\x41Heiligen Steine\x05\x40, um den Zugang\x01zu öffnen.\x04Und noch etwas... Nämlich ein\x01uraltes Relikt, das im Besitz der\x01Königsfamilie von Hyrule ist...\x0B\x02", "box_type": 0},
    {"id": 0x7038, "text": "Oh, tut mir leid...\x01Ich konnte noch nie gut\x01Geschichten erzählen...\x0B\x02", "box_type": 0},
    {"id": 0x7039, "text": "\x1A\x08Was ist passiert?\x09 Hat er Dich\x01gesehen?\x04\x1AHab keine Angst.\x04\x1AEr hat keine Ahnung von unseren\x01Plänen... Noch nicht!\x0B\x02", "box_type": 0},
    {"id": 0x703A, "text": "\x1ABitte!\x01\x01\x1B\x05\x42Ja!\x01Ich glaube kein Wort!\x05\x40\x02", "box_type": 0},
    {"id": 0x703B, "text": "\x1A\x06\x38Ich danke Dir!\x0B\x02", "box_type": 0},
    {"id": 0x703C, "text": "Meine Vertraute wird Dich aus\x01dem Schloß geleiten. Unterhalte\x01Dich ruhig mit ihr.\x02", "box_type": 0},
    {"id": 0x703D, "text": "Der Heilige Stein...\x01Du hast ihn gefunden!\x04Wesen, deren Volk einen Heiligen\x01Stein besitzt, vertrauen sich nur\x01dem an, der eine\x05\x43 Melodie aus dem\x01Erbe unserer Familie\x05\x40 kennt.\x04Doch das wußtest Du bereits,\x01nicht wahr?\x02", "box_type": 0},
    {"id": 0x703E, "text": "Hey, hast Du schon gehört, daß\x01Prinzessin Zelda in ihren Träumen\x01die Zukunft voraussieht?\x02", "box_type": 0},
    {"id": 0x703F, "text": "Häh? Was? Still, Kleiner! Still!\x02", "box_type": 0},
    {"id": 0x7040, "text": "Hier sind drei Vertiefungen\x01und eine Inschrift...\x04\x08Jener mit den drei Heiligen Steinen\x05\x43\x01\x05\x40nehme seine \x05\x44Okarina \x05\x40zur Hand\x05\x43\x01\x05\x40und spiele hier die \x05\x44Hymne der Zeit\x05\x40.\x09\x04Seltsam, aber so steht\x01es geschrieben...\x0B\x02", "box_type": 2},
    {"id": 0x7041, "text": "Hey, geht das nicht auch ein\x01bißchen billiger?\x02", "box_type": 0},
    {"id": 0x7042, "text": "Hey, nimm Deine Finger weg!\x01Ich hab es zuerst gesehen!\x02", "box_type": 0},
    {"id": 0x7043, "text": "Hey, wer drängelt sich da vor?!\x02", "box_type": 0},
    {"id": 0x7044, "text": "Es ist komisch, daß Gerudos hier\x01eingedrungen sind... Das kommt mir\x01seltsam vor...!\x02", "box_type": 0},
    {"id": 0x7045, "text": "War das nicht Prinzessin Zelda\x01auf diesem Schimmel?\x02", "box_type": 0},
    {"id": 0x7046, "text": "Der schwarze Hengst dieses\x01Reiters hätte mich um ein Haar\x01zertrampelt!\x02", "box_type": 0},
    {"id": 0x7047, "text": "Der Typ auf dem schwarzen Pferd\x01war bestimmt Ganondorf, der Herr\x01der Gerudo-Kriegerinnen!\x02", "box_type": 0},
    {"id": 0x7048, "text": "Was ist denn hier passiert?\x02", "box_type": 0},
    {"id": 0x7049, "text": "Schau Dir den Weichling an!\x01Er hat sich vor Angst fast in die \x01Hosen gemacht!\x01Hahaha!\x02", "box_type": 0},
    {"id": 0x704A, "text": "Ich habe das Gefühl, daß noch viel\x01Schrecklicheres passieren wird...\x01Vielleicht sollte ich abhauen!\x02", "box_type": 0},
    {"id": 0x704B, "text": "Im Schloß ist etwas Schlimmes\x01passiert! Sei lieber vorsichtig,\x01Kleiner!\x02", "box_type": 0},
    {"id": 0x704C, "text": "Mit diesem \x05\x41Schlüssel\x05\x40 kannst Du\x01den nächsten Raum betreten.\x01Los doch! Worauf wartest Du?\x02", "box_type": 0},
    {"id": 0x704D, "text": "Die Person auf dem Schimmel, die\x01das Mädchen festhielt... War das\x01nicht eine der legendären Shiekah?\x02", "box_type": 0},
    {"id": 0x704E, "text": "\x1A\x06\x2D\x0F...\x04\x1A\x06\x4BWach auf!\x01\x06\x21Du bist der Auserwählte!\x02", "box_type": 5},
    {"id": 0x704F, "text": "\x1AIch bin \x05\x41Rauru\x05\x40, einer der Weisen...\x04\x1AIch habe die Zitadelle der Zeit\x01erbaut, um den Zugang zum\x01Heiligen Reich zu schützen...\x04\x1ADies ist die \x05\x41Halle der Weisen \x01\x05\x40im Tempel des Lichts...\x04\x1ADer Tempel des Lichts befindet\x01sich im Zentrum des Heiligen\x01Reiches. Er ist die letzte Festung\x01gegen die Macht Ganondorfs.\x04\x1ADas \x05\x41Master-Schwert\x05\x40, das alles\x01Böse vernichtet und das Du aus\x01dem Zeitenfels zogst, öffnete\x01das Tor zum Heiligen Reich!\x04\x1A\x0F...\x01Erschrick nicht...\x01Schau Dich an...\x02", "box_type": 0},
    {"id": 0x7050, "text": "\x1A\x06\x1D\x05\x44Sieh nur, \x0F!\x01\x05\x40\x06\x31\x05\x44Du bist gewachsen!\x01\x05\x40\x06\x25\x05\x44Du bist älter geworden!\x05\x40\x02", "box_type": 0},
    {"id": 0x7051, "text": "\x1ADas Master-Schwert hat eine\x01heilige Klinge, die nie in die \x01Hände des Bösen fallen darf...\x04\x1ANur jener, der zu Recht den\x01Namen \x05\x41Herr der Zeiten\x05\x40 trägt, ist\x01in der Lage, es aus dem Zeitenfels\x01zu ziehen...\x04\x1ADoch Du warst noch zu jung für\x01diese Aufgabe...\x04\x1ADaher haben wir Deine Seele für\x01sieben Jahre hier gebannt.\x04\x1ANun ist es Zeit, daß Du wieder in\x01die Welt zurückkehrst und Deine\x01Mission vollendest!\x04Nun, hast Du verstanden, was\x01Deine Bestimmung ist?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x7052, "text": "Nun, es sieht aus, als wärest Du\x01etwas verwirrt... Laß mich noch\x01einmal von vorn beginnen.\x07\x70\x51\x02", "box_type": 0},
    {"id": 0x7053, "text": "\x1ADoch vergiß niemals...\x04\x1AObwohl Du nur mit edelstem\x01Ansinnen das Zeitportal geöffnet\x01hast...\x04\x1A...hat der niederträchtige\x01\x05\x41Ganondorf\x05\x40 dadurch das Heilige\x01Reich betreten können!\x04\x1AEr riß das Triforce-Fragment im\x01Tempel des Lichts an sich. Durch\x01dessen Kraft wurde er zum\x01\x05\x41Großmeister des Bösen\x05\x40...\x04\x1ASeine schwarze Macht überzog\x01ganz Hyrule, entweihte die Tempel\x01und verwandelte das einst blühende\x01Land in ein Refugium des Unheils!\x04\x1AMeine Kraft ist nur noch\x01verschwindend gering, selbst in\x01diesem Heiligen Reich...\x04\x1ASie kann lediglich diese Halle\x01der Weisen noch schützen.\x04\x1ADoch noch ist Hoffnung...\x04\x1ADie Kraft der Weisen blieb\x01erhalten.\x04\x1AWenn die Kraft jedes der \x05\x41Sieben\x01Weisen \x05\x40wieder geweckt wird...\x04\x1A...kann mit den \x05\x41Amuletten\x05\x40 die\x01Macht des Bösen ins Höllenreich\x01verbannt werden!\x04\x1AIch, Rauru, bin einer dieser\x01Weisen...\x04\x1ADer Auserwählte, die Kraft der\x01Weisen zu wecken, bist Du - der\x01\x05\x41Herr der Zeiten\x05\x40!\x04\x1ADu bist als Träger des \x01Master-Schwerts dazu auserwählt!\x04\x1AIch übertrage Dir meine Macht...\x01Geh nun, erwecke die Kraft der\x01anderen Weisen und vereine deren\x01Macht mit Deiner Stärke!\x02", "box_type": 0},
    {"id": 0x7054, "text": "\x1A\x05\x44\x0F... Wir sind zurück\x01in der \x05\x40Zitadelle der Zeit\x05\x44...\x01Aber sind wirklich \x05\x40sieben Jahre\x01\x05\x44vergangen?\x05\x40\x04\x1A\x05\x44Es sieht so aus, als könntest\x01Du einige \x05\x40Waffen\x05\x44, die Du damals\x01gefunden hast, nicht mehr\x01benutzen...\x04\x05\x40\x1A\x05\x44Los, laß uns gehen!\x05\x40\x02", "box_type": 0},
    {"id": 0x7055, "text": "Hey, was ist...? \x01Was ist schlimm daran, den Tag\x01über rumzuhängen, Kleiner?\x04Was willst Du?\x02", "box_type": 0},
    {"id": 0x7056, "text": "\x1AIch habe auf Dich gewartet,\x01junger Held...\x02", "box_type": 0},
    {"id": 0x7057, "text": "\x1ABeherrscht das Böse die Welt,\x01weilen jene Weisen, die von der\x01Stimme des Heiligen Reiches erweckt\x01werden, noch in den \x05\x41fünf Tempeln\x05\x40.\x04\x1AEiner in \x05\x42dunklen Wäldern\x05\x40...\x04\x1AEiner auf \x05\x41hohem Berge\x05\x40...\x04\x1AEiner im \x05\x43tiefen See\x05\x40...\x04\x1AEiner an der \x05\x45Stätte des Todes\x05\x40...\x04\x1AEiner innerhalb der\x01\x05\x46Göttin des Sandes\x05\x40...\x04\x1AZusammen mit dem Auserwählten\x01werden diese ihre Kräfte einsetzen,\x01um der Welt den Frieden\x01wiederzugeben...\x04\x1ADies ist die Legende der Tempel,\x01wie sie von meinem Volk, den\x01\x05\x43Shiekah\x05\x40, überliefert wurde.\x02", "box_type": 0},
    {"id": 0x7058, "text": "Oh, tut mir leid.\x01Wir haben noch nicht geöffnet.\x01Komm bitte später wieder!\x0B\x02", "box_type": 0},
    {"id": 0x7059, "text": "\x1ANimm das \x05\x41Master-Schwert\x05\x40!\x01Vernichte Ganon mit Deiner\x01heiligen Waffe!\x02", "box_type": 0},
    {"id": 0x705A, "text": "\x1AIch habe auf Dich gewartet,\x01\x0F.\x02", "box_type": 0},
    {"id": 0x705B, "text": "\x1A\x0F, der Auserwählte...\x04\x1ADu hast unzählige Gefahren \x01überwunden und die sechs\x01Weisen erweckt.\x04\x1ANun wartet Deine größte Aufgabe:\x01Ein letztes Zusammentreffen mit\x01Ganondorf, dem Großmeister\x01des Bösen...\x02", "box_type": 0},
    {"id": 0x705C, "text": "\x1A\x06\x24Suchst Du das Triforce,\x01\x06\x38so höre gut zu...\x0C\x3C\x1A\x06\x08Es befindet sich im Heiligen Reich.\x01\x06\x16Dies ist ein Ort, der auf die\x01\x06\x08Wünsche Deines Herzens reagiert...\x0C\x46\x1A\x06\x07Ein schwarzes Herz macht es zum\x01\x06\x10Hort des Übels. Ein reines Herz\x01\x06\x04aber verwandelt es in ein Paradies!\x0C\x5A\x1A\x06\x08Das Triforce... Symbol der Macht...\x01\x06\x12birgt das Gleichgewicht dreier\x01\x06\x0BKräfte: Weisheit, Mut und Kraft!\x0C\x5A\x1A\x06\x11Sind diese Kräfte ausgeglichen\x01\x06\x04im Herzen des Triforce-Trägers, hat\x01\x06\x02er die Macht, gerecht zu herrschen.\x0C\x50\x1A\x06\x1CDoch ist das Herz nicht im\x01\x06\x08Gleichgewicht, so spaltet sich das\x01\x06\x0ATriforce in seine drei Fragmente!\x0C\x50\x1A\x06\x07Nur ein Fragment bleibt ihm: Jenes\x01\x06\x01nämlich, das zu der Kraft gehört, an\x01\x06\x0Cdie er selbst am meisten glaubt.\x0C\x5A\x1A\x06\x29Will er nun alle Macht\x01\x06\x17erhalten, muß er die anderen\x01\x06\x10Fragmente des Triforce finden!\x0C\x50\x1A\x06\x09Noch zwei vom Schicksal Erwählte\x01\x06\x09tragen je ein Triforce-Element als\x01\x06\x14Symbol auf ihrem Handrücken!\x0E\x5A\x02", "box_type": 2},
    {"id": 0x705D, "text": "\x1ASieben Jahre zuvor drang\x01Ganondorf in das Heilige Reich\x01ein, dessen Zugang Du in der\x01Zitadelle der Zeit geöffnet hast.\x04\x1AAls seine Hände das Triforce\x01berührten, wurde die Legende wahr!\x02", "box_type": 0},
    {"id": 0x705E, "text": "\x1ADer Auserwählte mit dem \x05\x41Symbol \x01des Mutes \x05\x40bist...\x01Du, \x0F!\x02", "box_type": 0},
    {"id": 0x705F, "text": "\x1ADas \x05\x41Symbol der Weisheit\x05\x40...\x04\x1A...trägt der siebte Weise,\x01dessen Bestimmung es ist, zum\x01Meister aller zu werden...\x02", "box_type": 0},
    {"id": 0x7060, "text": "\x1AIch bin es - \x05\x41Zelda\x05\x40,\x01Prinzessin von Hyrule.\x02", "box_type": 0},
    {"id": 0x7061, "text": "\x1AVerzeih, daß ich Dich stets in\x01dieser Verkleidung aufgesucht habe.\x01Doch es war nötig, da ich mich\x01vor Ganondorf verstecken mußte.\x02", "box_type": 0},
    {"id": 0x7062, "text": "Ich habe Dich gesehen, als ich mit\x01Impa zusammen aus dem \x01Schloß floh.\x0E\x50\x02", "box_type": 2},
    {"id": 0x7063, "text": "\x1ASolange Du die Okarina in Deinen\x01Händen hältst, so dachte ich, wäre\x01es Ganondorf nicht möglich, das\x01Heilige Reich zu betreten. Aber...\x04\x1A...etwas, das ich nie erwartet\x01hätte, ist geschehen...\x02", "box_type": 0},
    {"id": 0x7064, "text": "\x1A\x06\x3DDieses Beben...\x01\x06\x30Was geschieht hier?\x01\x06\x2EDas darf nicht sein!\x02", "box_type": 0},
    {"id": 0x7065, "text": "\x1APrinzessin Zelda... Endlich\x01habe ich Dich!\x04\x1AIch bin beeindruckt, daß es Dir\x01gelungen ist, mir sieben Jahre lang\x01zu entkommen!\x02", "box_type": 2},
    {"id": 0x7066, "text": "\x1ANie wirst Du Zelda retten!\x01Wagst Du es, mein Schloß zu\x01betreten, vernichte ich auch Dich!\x02", "box_type": 2},
    {"id": 0x7067, "text": "\x1A\x0F... Hörst Du mich?\x01Hier spricht Rauru.\x04\x1ADie sechs Weisen sammeln ihre\x01Kraft, um eine Brücke zum Portal\x01von Ganondorfs Schloß zu legen...\x04\x1ADer Wachturm des Schlosses, auch\x01der \x05\x41Teufelsturm\x05\x40 genannt, wird von\x01sechs \x05\x41Siegeln des Bösen\x05\x40\x01blockiert!\x04\x1ABrich die Siegel,\x01dringe in den Turm ein und\x01rette Prinzessin Zelda!\x02", "box_type": 2},
    {"id": 0x706C, "text": "Ihr Erschaffer Hyrules!\x0C\x3CÖffnet das versiegelte Portal und\x01schickt diese Kreatur des Bösen\x01in den Abgrund der Hölle!\x0E\x5A\x02", "box_type": 0},
    {"id": 0x706D, "text": "\x1A\x0F!\x01Zerstöre ihn mit Deiner heiligen\x01Waffe - mit dem Master-Schwert!\x02", "box_type": 0},
    {"id": 0x706E, "text": "\x1AOh, heiliges Portal, entriegelt von\x01den Weisen... Schließe Dich für\x01immer und schütze unsere Welt vor\x01dieser üblen Kreatur des Bösen!\x02", "box_type": 0},
    {"id": 0x706F, "text": "\x1ADanke, \x0F...\x04\x1ADank Deiner Hilfe ist es gelungen,\x01den Großmeister des Bösen in das\x01Reich der Hölle zu verbannen!\x04\x1ANun wird wieder Frieden herrschen\x01in unserer Welt... Hoffentlich für \x01alle Zeit.\x02", "box_type": 0},
    {"id": 0x7070, "text": "\x1A\x06\x54Danke!\x01\x06\x5D\x0F...\x0C\x28\x1A\x06\x47Lebe wohl...\x0E\x3C\x02", "box_type": 2},
    {"id": 0x7071, "text": "Möchtest Du unbedingt durch\x01dieses Tor gehen? Nun, dann\x01verlange ich eine Gegenleistung...\x01Sagen wir...\x07\x70\x72\x02", "box_type": 0},
    {"id": 0x7072, "text": "Gib mir 10 Rubine!\x01\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x7073, "text": "Bitte glaube mir...\x01Meine Prophezeiungen waren\x01niemals falsch!\x0B\x02", "box_type": 0},
    {"id": 0x7074, "text": "\x1ADu hast jene bösen Geister\x01vernichtet, die im Tempel hausten.\x01Und Du hast \x05\x42Salia\x05\x40 erweckt...\x04\x1ADoch sie ist nicht die einzige, die\x01Deiner Hilfe bedarf.\x04\x1AUm alle Weisen zu erwecken, mußt\x01Du noch weit stärker werden!\x04\x1AReise zu den Bergen...\x04\x1A...in die Tiefen des Wassers...\x04\x1A...und sogar durch die Zeit...\x02", "box_type": 0},
    {"id": 0x7075, "text": "\x1ASolange Du die \x05\x44Okarina\x01der Zeit\x05\x40 und das \x05\x44Master-Schwert\x05\x40\x01in Deinen Händen hältst...\x04\x1A...hast Du auch Macht\x01über die Zeit!\x04\x1A\x0F, wir sehen\x01uns wieder!\x02", "box_type": 0},
    {"id": 0x7076, "text": "Eine neuartige Bombe! Ich kann Dir\x01nur eine begrenzte Stückzahl\x01anbieten. Ist das Lager leer,\x01gibt es keinen Nachschub mehr.\x0B\x02", "box_type": 0},
    {"id": 0x7077, "text": "\x1AIch bin \x05\x41Shiek\x05\x40. Ich gehöre\x01den letzten Überlebenden\x01der Shiekah an...\x02", "box_type": 0},
    {"id": 0x7078, "text": "\x1AWahrlich, Du siehst aus wie der,\x01der uns prophezeit wurde. Tapfer \x05\x41\x01\x05\x40hältst Du das \x05\x41Master-Schwert \x05\x40in \x01der Hand...\x02", "box_type": 0},
    {"id": 0x7079, "text": "\x1AWillst Du die Prophezeiung \x01erfüllen, so suche nach den fünf \x01Tempeln und befreie die dort \x01eingesperrten \x05\x41fünf Weisen\x05\x40...\x02", "box_type": 0},
    {"id": 0x707A, "text": "\x1AEiner von ihnen wartet im \x01\x05\x42Waldtempel\x05\x40 darauf, sich Deiner zu \x01offenbaren. Es ist ein Mädchen, an  \x01das Du Dich sicher erinnern wirst...\x04\x1AAufgrund der bösen Aura, die den \x01Tempel umgibt, kann sie den \x01Ruf des Heiligen Reiches nicht \x01hören...\x04\x1AMit Deiner jetzigen Ausrüstung\x01kannst Du den Tempel nicht \x01betreten...\x04\x1ASo höre meine Worte und begib \x01Dich nach \x05\x41Kakariko\x05\x40, um dort das \x01zu suchen, das Dein Schlüssel zum \x01Tempel sein soll...\x04\x1AHast Du mich verstanden, \x01\x0F?\x02", "box_type": 0},
    {"id": 0x707B, "text": "Ich fühlte, daß Du derjenige bist,\x01der die Okarina haben soll...\x01Ich wußte, daß es unsere beste\x01und einzige Chance war...\x0E\x50\x02", "box_type": 2},
    {"id": 0x707C, "text": "\x1ABevor Du aufbrichst, solltest\x01Du meinen Worten lauschen...\x04\x1ASo höre denn die Legende, \x01die sich die Shiekah über das \x01Triforce erzählten...\x02", "box_type": 0},
    {"id": 0x707D, "text": "\x1AAls das Triforce in drei Teile\x01zerbrach, gelang es Ganondorf \x01lediglich, das \x05\x41Triforce-Fragment\x01der Kraft \x05\x40zu erringen...\x02", "box_type": 0},
    {"id": 0x707E, "text": "\x1ADurch die Macht des Triforce-Teils\x01wurden seine teuflischen Kräfte \x01verstärkt. Doch sein Drang, Böses \x01zu tun, ist noch nicht befriedigt...\x02", "box_type": 0},
    {"id": 0x707F, "text": "\x1ADaher sucht er nun \x05\x41die, die \x01auserwählt wurden\x05\x40, Träger der \x01anderen Triforce-Elemente zu \x01sein...\x02", "box_type": 0},
    {"id": 0x7080, "text": "\x1AHeute vor genau sieben Jahren\x01suchte Ganondorf mit seiner Horde \x01wilder Kriegerinnen Hyrule heim...\x02", "box_type": 0},
    {"id": 0x7081, "text": "\x1AAls Du das Tor zur Zeit betreten \x01hast, bannte Dich das Schwert \x01sieben Jahre im Heiligen Reich...\x02", "box_type": 0},
    {"id": 0x7082, "text": "\x1ADein Geist ruhte im Vakuum der\x01Zeit... Das Triforce fiel in Ganondorfs\x01blutige Hände, die Unheil über \x01das Heilige Reich brachten...\x04\x1AGanondorf verlor mehr und mehr\x01sein menschliches Antlitz. Er\x01wurde zum Großmeister des Bösen,\x01dem Boten des Todes...\x04\x1AIn all den Jahren gelang es mir, \x01mich als Shiekah zu tarnen und \x01so meinem Schicksal zu entgehen...\x01Ich wartete sieben Jahre...\x02", "box_type": 0},
    {"id": 0x7083, "text": "\x1ADoch nun endlich bist Du \x01zurückgekehrt! Die Herrschaft des \x01Terrors soll jetzt ihr Ende finden!\x01Die Tage des Bösen sind gezählt!\x02", "box_type": 0},
    {"id": 0x7084, "text": "\x1ADie sechs Weisen werden neue \x01Siegel schaffen und Ganondorf \x01für immer in die Tiefen der Hölle\x01verbannen...\x04\x1AIst dies vollbracht, werde ich das \x01Tor zum Heiligen Reich auf ewig \x01schließen!\x04\x1AAuf diese Weise wird Ganondorf \x01und mit ihm alles Böse für alle \x01Zeit aus Hyrule verschwinden.\x04\x1A\x0F...\x01Um dieses Vorhaben mit Erfolg zu \x01krönen, mußt Du mich schützen, \x01bis der Plan vollbracht ist.\x04\x1ANimm nun die Waffe an Dich, die\x01die Kraft des Bösen mitten ins\x01schwarze Herz trifft...\x04\x1A\x06\x0DDie heiligen \x05\x44Pfeile des Lichts\x05\x40!\x02", "box_type": 0},
    {"id": 0x7085, "text": "\x1AEndlich gibst Du Dich zu erkennen...\x01Ich wußte, daß ich nur dem Jungen\x01zu folgen brauchte, um Dich zu\x01finden...\x02", "box_type": 0},
    {"id": 0x7086, "text": "\x1AMein einziger Fehler war, die\x01Kräfte des Jungen zu \x01unterschätzen...\x02", "box_type": 0},
    {"id": 0x7087, "text": "\x1ANein... Es war nicht seine\x01Kraft, die ich unterschätzte.\x01Es waren die Kräfte des Triforce-\x01Symbols für Mut!\x04\x1ADoch mit dem Element, das er \x01besitzt, und dem Triforce der \x01Weisheit, das in Deinen Händen \x01ruht, schließt sich der Kreis...\x04\x1AMit allen drei Elementen werde \x01ich zum Herrscher dieser Welt!\x02", "box_type": 0},
    {"id": 0x7088, "text": "\x08Als der Auserwählte die Okarina \x01spielte, öffnete sich das Portal \x01der Zeit. Das Master-Schwert \x01machte ihn zum Helden der Legende.\x09\x02", "box_type": 2},
    {"id": 0x7089, "text": "Ich weiß nicht, warum, aber \x01irgendwie scheinen die Hunde die\x01Nacht zu mögen...\x01Komisch, oder?\x02", "box_type": 0},
    {"id": 0x708A, "text": "Hey, Kleiner! Ich verrate Dir\x01etwas...\x04Ich hörte, daß sich in der Nähe des \x01Schlosses eine \x05\x41geheimnisvolle \x01Quelle \x05\x40befinden soll...\x02", "box_type": 0},
    {"id": 0x708B, "text": "\x1AWillst Du in die Zeit, aus der Du\x01kamst, zurückkehren, so plaziere \x01das Master-Schwert wieder im \x01\x05\x41Zeitenfels\x05\x40...\x04\x1ATust Du dies, so reist Du\x01sieben Jahre in der Zeit \x01zurück...\x02", "box_type": 0},
    {"id": 0x708C, "text": "\x1AEs wird die Zeit kommen, da\x01Du in Windeseile an diesen Ort \x01zurückkehren mußt... \x01Lausche daher meinen Worten...\x04\x1ADas Lied, das Du spielen mußt, \x01um zur Zitadelle der Zeit \x01zurückzukehren ist...\x01\x05\x44die Kantate des Lichts\x05\x40...\x02", "box_type": 0},
    {"id": 0x708D, "text": "\x1AIch bin \x05\x41Impa\x05\x40, Überlebende der \x01Shiekah. Meine Aufgabe ist, Zelda \x01zu schützen. Alles ist so geschehen, \x01wie es die Prinzessin prophezeite.\x02", "box_type": 0},
    {"id": 0x708E, "text": "Wenn Dich die Soldaten hier \x01finden, bekommst Du Ärger. Laß \x01mich Dich aus dem Schloß führen!\x02", "box_type": 0},
    {"id": 0x708F, "text": "\x08Hey, Du! Mach keinen Ärger!\x09\x0B\x02", "box_type": 0},
    {"id": 0x7090, "text": "\x1ADu bist ein tapferer Junge!\x01Die Vorsehung hat Dich an diesen \x01Ort geführt...\x04\x1AMir wird nun die Aufgabe zuteil, \x01Dich eine Melodie zu lehren, die\x01Du nie vergessen darfst!\x04\x1AEs ist ein Lied, \x05\x43das die \x01Königsfamilie von Generation zu \x01Generation weitergibt\x05\x40.\x04\x1AIch habe dieses Lied für\x01Prinzessin Zelda gespielt, als sie\x01noch ein kleines Kind war.\x04\x1AIn den Noten verbergen\x01sich mysteriöse Kräfte!\x04\x1ALausche nun der Melodie...\x02", "box_type": 0},
    {"id": 0x7091, "text": "\x1AIch bin schuld an all dem Unheil, \x01das über Hyrule kam...\x04\x1AIch war zu jung... Ich konnte noch\x01nicht wissen, welche Fährnisse\x01sich mir auftun würden...\x04\x1AIch habe Dich in all das \x01hineingezogen...\x04\x1ANun ist es an der Zeit, meinen\x01Fehler wiedergutzumachen...\x04\x1ALeg nun das Master-Schwert aus \x01Deinen Händen und schließe so\x01das Zeitportal...\x02", "box_type": 0},
    {"id": 0x7092, "text": "\x1ADie Verbindung zwischen den\x01Zeiten sei für immer gelöst...\x02", "box_type": 0},
    {"id": 0x7093, "text": "\x1A\x0F,\x01gib mir die Okarina...\x04\x1AAls eine der Weisen habe ich die \x01Gabe, Dich in Deine Zeit \x01zurückbringen zu können.\x02", "box_type": 0},
    {"id": 0x7094, "text": "\x1ANun herrscht wieder Friede\x01in Hyrule...\x04\x1AUnd nun ist es für uns an der\x01Zeit, Abschied zu nehmen...\x02", "box_type": 0},
    {"id": 0x7095, "text": "\x1AGehe nun, \x0F.\x01Hole die verlorenen sieben Jahre\x01nach!\x04\x1AGehe nach Hause... \x01Dorthin, wo Dein Platz ist...\x01Als der, als der Du aufwuchst...\x02", "box_type": 0},
    {"id": 0x7096, "text": "\x06\x46\x08Tss...\x09 \x08tss...\x09\x0B\x02", "box_type": 0},
    {"id": 0x7097, "text": "Das scheint für ein Kind\x01ein zu hoher Preis zu sein.\x0B\x02", "box_type": 0},
    {"id": 0x7098, "text": "Nun gut, ich lasse Dich passieren!\x01Schnell!\x0B\x02", "box_type": 0},
    {"id": 0x7099, "text": "ERZÄHL DAS BLOSS \x01NIEMANDEM!\x02", "box_type": 0},
    {"id": 0x709A, "text": "Mann, ich bin soooo müde!\x04Nachtwache ist total langweilig!\x01Wenn wenigstens ein paar Geister\x01rumspuken würden...\x04Ich finde so etwas nämlich\x01wirklich interessant!\x04Ich studiere Geister-Wissenschaften\x01schon seit Jahren. Man weiß\x01ja nie, ob das nicht einmal\x01nützlich sein kann!\x02", "box_type": 0},
    {"id": 0x709B, "text": "Verglichen mit den streunenden\x01Promenadenmischungen ist das Fell\x01meines Hundes prächtig und \x01glänzend!\x02", "box_type": 0},
    {"id": 0x709C, "text": "Mein Hund ist gut erzogen...\x01Aber manchmal läuft auch er \x01nachts in Hyrule herum - so wie\x01diese streunenden Stinkeköter!\x02", "box_type": 0},
    {"id": 0x709D, "text": "Hast Du meinen Richard gesehen?\x01Er ist sonst so ein braver Hund,\x01aber heute abend ist er\x01davongelaufen. Bitte suche ihn!\x02", "box_type": 0},
    {"id": 0x709E, "text": "\x08Arrrgh!\x09 Das ist nicht mein Hundi!\x01Wie kannst Du meinen Liebling mit\x01so einer Zeckenmatte\x01verwechseln?!\x02", "box_type": 0},
    {"id": 0x709F, "text": "\x06\x46\x08Richard!\x09\x04Da ist ja mein kleiner Richie\x01wieder! Vielen Dank!\x01Bitte, nimm dies als Belohnung an\x01Dich!\x02", "box_type": 0},
    {"id": 0x70A0, "text": "Nachts, wenn die Köter draußen \x01herumstreunen, ist es gefährlich!\x01Nein, nicht für Dich, sondern für\x01meinen Liebling!\x02", "box_type": 0},
    {"id": 0x70A1, "text": "Hallo und willkommen\x01beim lustigen \x05\x41Maskenhändler\x05\x40!\x01Wir handeln mit Masken, die\x01allen Leuten Freude bringen...\x04Wärst nicht auch Du gern ein Bote\x01der Freude? Paß auf, ich leihe\x01Dir eine Maske, Du verkaufst sie\x01und gibst mir dann das \x05\x41Geld\x05\x40!\x04Willst Du wissen, wie es \x01funktioniert, lies das \x05\x41Schild\x05\x40\x01zu Deiner Linken.\x04Übrigens: Wenn Du alle Masken \x01verkauft hast, wirst auch Du \x01glücklicher sein!\x04\x06\x3CVertrau mir...\x0B\x02", "box_type": 0},
    {"id": 0x70A2, "text": "\x08Wähle eine Maske, indem Du den\x01\x05\x44ª \x05\x40nach links oder rechts bewegst.\x01\x1B\x05\x42Mit dem Ladenbesitzer sprechen!\x01Nichts ausleihen!\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x70A3, "text": "Eine \x05\x41Maske \x05\x40ist ein \x05\x46¡-Knopf-\x01Gegenstand\x05\x40. Plaziere sie auf \x05\x46¡\x05\x40 \x01und drücke \x05\x46¡\x05\x40, um sie zu tragen.\x04Sprichst Du jemanden an, während\x01Du die Maske trägst, erhältst Du\x01eine entsprechende Reaktion.\x04Wenn jemand an der Maske \x01interessiert ist, wird Dich \x01derjenige danach fragen.\x04Irgendwo in diesem Land findet\x01sich für jede Maske ein Käufer.\x04\x06\x26Vertrau mir einfach...\x0B\x02", "box_type": 0},
    {"id": 0x70A4, "text": "Vor kurzem sah ich noch ein\x01goldiges, kleines Mädchen hier...\x01Vielleicht ist sie zum Schloß \x01gegangen... Wer weiß...\x02", "box_type": 0},
    {"id": 0x70A5, "text": "Du hast sie verkauft?! Fantastisch!\x01Dann zahl mir nun meine \x05\x4110 Rubine \x01\x05\x40für die Fuchs-Maske.\x0B\x02", "box_type": 0},
    {"id": 0x70A6, "text": "Oh! Du hast die Maske noch nicht\x01verkauft. Vertrau mir... Es  wird\x01sich schon ein Käufer finden.\x0B\x02", "box_type": 0},
    {"id": 0x70A7, "text": "Bezahlung erhalten!\x0B\x02", "box_type": 0},
    {"id": 0x70A8, "text": "\x08Was?!\x09\x01Du hast mein Geld verbraten?!\x04\x08Wie kannst Du es wagen!\x09\x04Du besorgst besser ganz schnell \x01mein Geld, oder...\x0B\x02", "box_type": 0},
    {"id": 0x70A9, "text": "Hey!\x04Gut gemacht!\x01Alle Masken sind verkauft.\x04Ich wußte, daß Du der richtige\x01Mann, ähh, Junge dafür bist!\x0B\x02", "box_type": 0},
    {"id": 0x70AA, "text": "\x1AAls Belohnung für Deine Mühe \x01sollst Du eine ganz besondere \x01Maske erhalten!\x04\x1ADies ist die \x05\x41Maske des Wissens.\x05\x40\x01Es ist eine mysteriöse Maske aus\x01dem Erbe der Shiekah.\x04\x1ASuche, und Du wirst die \x01verborgenen Kräfte der Maske \x01entdecken... Sie ist nützlich und\x01unheimlich zugleich...\x04\x1AWarum sie unheimlich ist?\x04\x1ADas wirst Du herausfinden, wenn\x01Du älter wirst und irgendwann den\x01Sinn des Lebens erkennst...\x04\x1AVertrau mir, hahaha...\x0B\x02", "box_type": 0},
    {"id": 0x70AB, "text": "Ich habe Nachschub bekommen! \x01Von nun an kannst Du jede \x01beliebige Maske ausleihen...\x01Vertrau mir...\x0B\x02", "box_type": 0},
    {"id": 0x70AC, "text": "Willkommen!\x01Welche Maske möchtest Du \x01leihen?\x0B\x02", "box_type": 0},
    {"id": 0x70AD, "text": "\x08Bewege den \x05\x44ª\x05\x40 nach rechts oder\x01links, um eine Maske zu wählen.\x01\x1B\x05\x42Frage nach der Maske des Wissens! \x01Nichts ausleihen!\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x70AE, "text": "Dies ist die \x05\x41Maske des Wissens\x05\x40.\x01Es ist eine mysteriöse Maske aus\x01dem Erbe der Shiekah.\x04Suche, und Du wirst die \x01verborgenen Kräfte der Maske \x01entdecken... Sie ist nützlich und\x01unheimlich zugleich...\x04Warum sie unheimlich ist?\x04Das wirst Du herausfinden, wenn\x01Du älter bist und irgendwann den\x01Sinn des Lebens erkennst...\x04Vertrau mir, hahaha...\x0B\x02", "box_type": 0},
    {"id": 0x70AF, "text": "\x08\x05\x41Maske des Wissens -- Unverkäuflich\x05\x40\x01Eine Maske mit mysteriösen Kräften.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B0, "text": "\x08\x05\x41Schädel-Maske -- Preis 20 Rubine\x05\x40\x01Eine gehörnte Totenschädelmaske.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B1, "text": "\x08\x05\x41Geister-Maske -- Preis 30 Rubine\x01\x05\x40Eine traurig blickende Holzmaske.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B2, "text": "\x08\x05\x41Fuchs-Maske -- Preis 10 Rubine\x01\x05\x40Der letzte Schrei! Sehr angesagt!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B3, "text": "\x08\x05\x41Hasenohren -- Preis 50 Rubine\x01\x05\x40Wippende Hasenohren! Supersüß!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B4, "text": "\x08\x05\x41Schädel-Maske -- Gebührenfrei!\x05\x40\x01Eine gehörnte Totenschädelmaske.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B5, "text": "\x08\x05\x41Geister-Maske -- Gebührenfrei!\x01\x05\x40Eine traurig blickende Holzmaske.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B6, "text": "\x08\x05\x41Fuchs-Maske -- Gebührenfrei!\x01\x05\x40Der letzte Schrei! Sehr angesagt!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B7, "text": "\x08\x05\x41Hasenohren -- Gebührenfrei!\x01\x05\x40Wippende Hasenohren! Supersüß!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B8, "text": "\x08\x05\x41Goronen-Maske -- Gebührenfrei! \x01\x05\x40Trägst Du diese Maske,\x01lächelst Du immerzu!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70B9, "text": "\x08\x05\x41Zora-Maske -- Gebührenfrei!\x05\x40\x01Sieht besonders cool beim\x01Schwimmen aus!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70BA, "text": "\x08\x05\x41Gerudo-Maske -- Gebührenfrei!\x01\x05\x40Mit ihren verführerischen Augen \x01macht sie aus Dir ein \x01zauberhaftes Mädchen!\x09\x0A\x02", "box_type": 0},
    {"id": 0x70BB, "text": "\x08\x05\x41Maske des Wissens -- Gebührenfrei!\x05\x40\x01Eine Maske aus dem Erbe der \x01Shiekah! Man erzählt sich, sie\x01besäße mysteriöse Kräfte.\x09\x0A\x02", "box_type": 0},
    {"id": 0x70BC, "text": "\x08Möchtest Du die \x05\x41Schädel-Maske \x01\x05\x40leihen?\x09\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x70BD, "text": "\x08Möchtest Du die \x05\x41Geister-Maske \x05\x40\x01leihen?\x09\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x70BE, "text": "\x08Möchtest Du die \x05\x41Fuchs-Maske \x05\x40\x01leihen?\x09\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x70BF, "text": "\x08Möchtest Du die \x05\x41Hasenohren\x05\x40 \x01leihen?\x09\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x70C0, "text": "\x08Möchtest Du die \x05\x41Goronen-Maske\x05\x40 \x01leihen?\x09\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x70C1, "text": "\x08Möchtest Du die \x05\x41Zora-Maske\x05\x40\x01leihen?\x09\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x70C2, "text": "\x08Möchtest Du die \x05\x41Gerudo-Maske\x05\x40\x01leihen?\x09\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x70C3, "text": "\x08Möchtest Du die \x05\x41Maske des\x01Wissens\x05\x40 leihen?\x09\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x70C4, "text": "Oh, großartig! Du hast sie\x01verkauft! Bitte zahle mir \x01für die Schädel-Maske die\x01\x05\x4120 Rubine\x05\x40.\x0B\x02", "box_type": 0},
    {"id": 0x70C5, "text": "Oh, großartig! Du hast sie\x01verkauft! Bitte zahle mir\x01für die Geister-Maske die\x01\x05\x4130 Rubine\x05\x40.\x0B\x02", "box_type": 0},
    {"id": 0x70C6, "text": "Oh, großartig! Du hast sie\x01verkauft! Bitte zahle mir\x01für die Hasenohren die\x01\x05\x4150 Rubine\x05\x40.\x0B\x02", "box_type": 0},
    {"id": 0x70C7, "text": "Oh! Du hast die Maske noch\x01nicht verkauft? Dann biete sie\x01einfach weiterhin an.\x04Oder möchtest Du sie gegen eine\x01andere Maske tauschen?\x01\x1B\x05\x42Ja!\x01Nein!\x05\x40\x02", "box_type": 0},
    {"id": 0x70C8, "text": "\x1ADie Fragmente des Triforce...\x01Ich spüre... Ihre Macht scheint\x01sich wieder zu vereinigen... \x02", "box_type": 0},
    {"id": 0x70C9, "text": "\x1ADie fehlenden zwei Fragmente!\x01Ich warte seit\x01sieben Jahren darauf!\x04\x1AIch bin wirklich überrascht! Ich\x01hätte nicht erwartet, daß gerade\x01ihr zwei sie tragen würdet!\x02", "box_type": 0},
    {"id": 0x70CA, "text": "\x1AEndlich! Endlich! Die drei\x01Fragmente sind wieder\x01vereint!\x02", "box_type": 0},
    {"id": 0x70CB, "text": "\x1ADiese Symbole der Macht sind\x01nichts für euch zwei! Ihr seid\x01dafür nicht geschaffen!\x02", "box_type": 0},
    {"id": 0x70CC, "text": "\x1AIch allein bin der rechtmäßige\x01Träger des Triforce! Übergebt mir\x01die Fragmente!\x01Ich befehle es!\x02", "box_type": 0},
    {"id": 0x70CD, "text": "\x1A\x12\x68\x5F\x05\x44\x0F!\x01Ich kann Dir nicht helfen!\x01Die Aura des Bösen ist\x01zu mächtig!\x04\x05\x44\x1ATut mir leid, \x0F!\x05\x40\x02", "box_type": 0},
    {"id": 0x70CE, "text": "\x1AIch, der Großmeister des Bösen... \x01Geschlagen von einem Kind?!\x01Das... darf... nicht... sein...\x02", "box_type": 0},
    {"id": 0x70CF, "text": "\x1A\x0F...!\x02", "box_type": 0},
    {"id": 0x70D0, "text": "\x1AGanondorf... bemitleidenswerte\x01Kreatur...\x04\x1ADa ihm der Sinn für\x01Gerechtigkeit fehlte, konnte er die\x01Macht der Götter nicht nutzen...\x02", "box_type": 0},
    {"id": 0x70D1, "text": "\x1A\x0F, hör zu!\x01Der Turm stürzt in sich zusammen!\x04\x1ADas ist Ganondorfs letzte, böse\x01Tat! Die Trümmer sollen uns\x01zerschmettern! Schnell! Wir\x01müssen fliehen!\x02", "box_type": 0},
    {"id": 0x70D2, "text": "\x1ASchnell! Folge mir!\x02", "box_type": 0},
    {"id": 0x70D3, "text": "\x1AEs ist vorüber... Alles...\x02", "box_type": 0},
    {"id": 0x70D4, "text": "\x1A\x05\x44\x0F... \x01Tut mir leid, daß ich Dir im Kampf\x01nicht helfen konnte.\x05\x40\x02", "box_type": 0},
    {"id": 0x70D5, "text": "\x1AWas ist das für ein Geräusch?\x02", "box_type": 0},
    {"id": 0x70D6, "text": "\x1A\x12\x68\x5F\x05\x44Diesmal hat er keine Macht mehr\x01über mich!\x05\x40\x01\x08\x05\x44Wir kämpfen gemeinsam!\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x70D7, "text": "\x1A\x0F!\x01Das Master-Schwert!\x01Es ist hier! \x01\x08Schnell!\x09\x02", "box_type": 0},
    {"id": 0x70D8, "text": "\x1AIch versuche, Ganon mit meiner\x01Kraft zu bannen!\x01Nimm Du das Schwert und\x01versetze ihm den Todesstoß!\x02", "box_type": 0},
    {"id": 0x70D9, "text": "\x1A\x06\x28Oh, ihr Sechs Weisen...\x01\x08\x06\x3FEs ist soweit!\x01\x06\x32Sendet Eure Kraft!\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x70DA, "text": "\x1A\x14\x03DUUUU... widerlicher...\x14\x00\x0E\x1E\x02", "box_type": 0},
    {"id": 0x70DB, "text": "\x1A\x14\x03ICH VERFLUCHE DICH... ZELDA!\x01\x14\x02ICH VERFLUCHE EUCH... IHR WEISEN!\x14\x00\x0E\x32\x02", "box_type": 0},
    {"id": 0x70DC, "text": "\x1AICH...\x01VERFLUCHE...\x01DICH... \x08\x0F!\x09\x0E\x1E\x02", "box_type": 0},
    {"id": 0x70DD, "text": "\x1AArrgh! Eines Tages werde ich\x01dieses Siegel brechen...\x0C\x50\x1ADann werde ich eure\x01Nachfahren auslöschen!\x0E\x50\x02", "box_type": 0},
    {"id": 0x70DE, "text": "\x1ASolange das Fragment der Kraft\x01in meiner Hand ist...\x0E\x50\x02", "box_type": 0},
    {"id": 0x70DF, "text": "\x14\x02Du... \x14\x00wer bist Du?\x0E\x50\x02", "box_type": 2},
    {"id": 0x70E0, "text": "\x06\x11Das \x05\x42Wald-Siegel \x05\x40ist gebrochen!\x01\x06\x1ABeeil Dich, \x0F!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E1, "text": "\x06\x0FDas \x05\x41Feuer-Siegel \x05\x40ist gebrochen!\x01\x06\x33Beeil Dich, Bruder!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E2, "text": "\x06\x0ADas \x05\x43Wasser-Siegel \x05\x40ist gebrochen!\x01\x06\x2EBeeil Dich, Liebster!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E3, "text": "\x06\x06Das \x05\x45Schatten-Siegel \x05\x40ist gebrochen!\x01\x06\x1CBitte rette die Prinzessin!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E4, "text": "\x06\x0ADas \x05\x46Geister-Siegel\x05\x40 ist gebrochen!\x01\x06\x36Streng Dich an, Kleiner!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E5, "text": "\x06\x11Das \x05\x44Licht-Siegel\x05\x40 ist gebrochen!\x01\x06\x41Schnell jetzt!\x0E\x28\x02", "box_type": 0},
    {"id": 0x70E6, "text": "\x05\x44\x0F, ist das nicht...?!\x02", "box_type": 0},
    {"id": 0x70E7, "text": "\x05\x44Diese legendäre Klinge...\x05\x40\x0E\x1E\x02", "box_type": 0},
    {"id": 0x70E8, "text": "\x08\x06\x2D\x05\x44Das Master-Schwert!\x05\x40\x09\x02", "box_type": 0},
    {"id": 0x70E9, "text": "\x1AFinde die anderen\x01Weisen und rette Hyrule!\x0E\x50\x02", "box_type": 5},
    {"id": 0x70EA, "text": "Dieser schreckliche Typ ist wie\x01wild davongaloppiert!\x02", "box_type": 0},
    {"id": 0x70EB, "text": "Oh, wie furchtbar...\x01Oh, wie schrecklich...\x02", "box_type": 0},
    {"id": 0x70EC, "text": "Hey, was willst Du?\x01Ich habe keine Zeit, mit\x01Dir zu tratschen!\x02", "box_type": 0},
    {"id": 0x70ED, "text": "Bitte... Verkaufe mir etwas mit \x05\x46¡\x05\x40...\x01Bitte verkaufe mir etwas...\x01Bitte... In einer Flasche...\x02", "box_type": 0},
    {"id": 0x70EE, "text": "Nein...\x01Das ist nicht das, was ich will...\x01Ich möchte \x05\x41etwas in einer Flasche\x05\x40...\x01Nicht so etwas...\x02", "box_type": 0},
    {"id": 0x70EF, "text": "Nein...\x01Das kann ich nicht nehmen...\x01Es ist nicht das, was ich\x01haben will...\x02", "box_type": 0},
    {"id": 0x70F0, "text": "Oh,\x05\x43 \x05\x44Blaues Feuer\x05\x40!\x01Ich kaufe es für \x05\x41150 Rubine\x05\x40!\x01Und nicht feilschen, okay?\x02", "box_type": 0},
    {"id": 0x70F1, "text": "Oh, ein \x05\x45Fisch\x05\x40!\x01Ich kaufe ihn für \x05\x41100 Rubine\x05\x40!\x01Und nicht feilschen, okay?\x02", "box_type": 0},
    {"id": 0x70F2, "text": "Oh, ein niedlicher \x05\x42Käfer\x05\x40!\x01Ich kaufe ihn für \x05\x4150 Rubine\x05\x40!\x01Und nicht feilschen, okay?\x02", "box_type": 0},
    {"id": 0x70F3, "text": "Oh, eine hübsche, kleine \x05\x44Fee\x05\x40!\x01Ich kaufe sie für \x05\x4125 Rubine\x05\x40!\x01Und nicht feilschen, okay?\x02", "box_type": 0},
    {"id": 0x70F4, "text": "\x1AOh... Du bist ja ein agiler,\x01junger Mann. Und Du bist auch\x01ganz ansehnlich. Und mutig!\x04\x1AHehehe... Du heißt\x01\x0F, nicht wahr?\x04\x1AHehehe... Schau nicht so.\x01Ich kann Gedanken lesen.\x04\x1AWenn ich so gut aussähe wie Du,\x01dann könnte ich mein Geld auf\x01andere Weise verdienen...\x01Hehehe...\x04\x1AAber immerhin betreibe ich den\x01einzigen \x05\x41Gespenstermarkt\x05\x40 von\x01Hyrule!\x04\x1ADank Ganondorf - gepriesen sei\x01sein Name - gehen die Geschäfte \x01zur Zeit blendend... Hehehe...\x04\x1AIch kann nur hoffen, daß das\x01auch so bleibt!\x04\x1ADie Geister nennt man \x01\x05\x41Irrlichter \x05\x40oder\x05\x41 Nachtschwärmer\x05\x40...\x01Sie tragen allen Haß der Welt...\x01Und sie hassen alle Welt...\x04\x1AWenn Du einen Geist fängst, dann\x01werde ich Dich reich belohnen,\x01mein Junge! Hehehe...\x02", "box_type": 0},
    {"id": 0x70F5, "text": "Na, mein Junge! Hast Du ein Irrlicht\x01oder einen Nachtschwärmer dabei?\x01Ich gebe Dir 10 Rubine \x01für ein Irrlicht.\x04Für einen Nachtschwärmer erhältst\x01Du 50 Rubine sowie 100 Punkte!\x01Du hast bis jetzt \x05\x45\x1E\x01 Punkte\x05\x40 auf\x01dem Nachtschwärmer-Konto gut!\x02", "box_type": 0},
    {"id": 0x70F6, "text": "\x1AOh, Du bringst mir etwas!\x04\x1A\x14\x02Nun...\x14\x00\x04\x1ALaß sehen...\x04\x1AEs ist ein \x05\x41Irrlicht\x05\x40.\x04\x1AHier sind \x05\x4110 Rubine\x05\x40.\x01Vielen Dank!\x04\x1AHehehe...\x02", "box_type": 0},
    {"id": 0x70F7, "text": "\x1AOh, Du bringst mir etwas!\x04\x1ANun...\x04\x1AErstaunlich!\x01Das ist ja ein \x05\x41Nachtschwärmer\x05\x40!\x04\x1ADafür bekommst Du \x05\x4150 Rubine\x05\x40!\x04\x1AObendrein hast Du nun \x05\x41100 Punkte\x01\x05\x40auf dem Nachtschwärmer-Konto gut.\x04\x1AHast Du \x05\x411.000 Punkte\x05\x40 gesammelt,\x01dann wartet eine geniale \x01Belohnung! Hehehe...\x02", "box_type": 0},
    {"id": 0x70F8, "text": "\x1AOh! WOW!\x04\x1ADu hast jetzt \x05\x411.000 Punkte\x05\x40!\x04\x1ADu bist ja der geborene\x01\x05\x41Geisterjäger\x05\x40!\x04\x1ADu erwartest noch etwas von\x01mir? Was denn? Hehehe...\x04\x1ADank Dir ist mein Bestand an\x01\x05\x41Nachtschwärmern\x05\x40 enorm gestiegen...\x01Dies ist der letzte Geist, den ich \x01Dir abnehme.\x04\x1AAch, Du wartest auf das, was ich\x01Dir für ein 1.000 Punkte-Konto\x01versprochen habe? Hehehe...\x04\x1ANa, da will ich mal nicht so sein...\x01Nimm das hier!\x02", "box_type": 0},
    {"id": 0x70F9, "text": "\x1AOh? Was ist das?\x04\x1A\x14\x02\x08Das\x09 \x08ist\x09...\x14\x00\x0B\x02", "box_type": 0},
    {"id": 0x70FA, "text": "\x08\x05\x44Eine Fee\x05\x40\x09?!\x04\x1ADann... Dann kommst Du...\x01Kommst Du aus dem Wald?\x0B\x02", "box_type": 0},
    {"id": 0x70FB, "text": "\x1ADu... Du hast nicht auch\x01zufällig... den \x05\x42Heiligen Stein des \x01Waldes\x05\x40, oder? Ich meine diesen\x01funkelnden, grünen Stein...\x0B\x02", "box_type": 0},
    {"id": 0x70FC, "text": "\x1AIch hatte einen Traum...\x01Darin überzogen dunkle Wolken\x01unser Land Hyrule...\x04\x1ADoch plötzlich... durchschnitt ein\x01Strahl hellen Lichts diese Wolken...\x01Er kam aus dem Wald, und ganz\x01Hyrule erstrahlte in seinem Glanz!\x04\x1ADas Licht verwandelte sich in\x01einen Jungen, der einen \x05\x42glitzernden,\x01grünen Stein\x05\x40 in den Händen hielt.\x01Ihn begleitete eine \x05\x44Fee\x05\x40...\x0B\x02", "box_type": 0},
    {"id": 0x70FD, "text": "\x1AIch weiß, es war eine\x01Prophezeiung, daß jemand aus den\x01\x05\x42Tiefen des Waldes\x05\x40 kommen würde...\x04\x1AIch dachte, Du wärst es...\x0B\x02", "box_type": 0},
    {"id": 0x70FE, "text": "\x1A\x06\x37Oh! Tut mir leid!\x04\x1AIch habe mich ein bißchen\x01mitreißen lassen von meiner\x01Geschichte und mich gar nicht\x01standesgemäß vorgestellt!\x0B\x02", "box_type": 0},
    {"id": 0x70FF, "text": "\x1AIch bin \x05\x44Zelda\x05\x40, Prinzessin von Hyrule.\x0B\x02", "box_type": 0},
    {"id": 0x7100, "text": "Was? Kennen wir uns?\x02", "box_type": 0},
    {"id": 0x7101, "text": "Oh... Das ist aber süß!\x01Sagst Du mir, woher Du sie\x01hast?\x02", "box_type": 0},
    {"id": 0x7102, "text": "Oh mein Gott!\x01Hilfe!\x02", "box_type": 0},
    {"id": 0x7103, "text": "Ja? Was ist denn?\x02", "box_type": 0},
    {"id": 0x7104, "text": "Ich hasse Füchse!\x02", "box_type": 0},
    {"id": 0x7105, "text": "Du siehst bescheuert aus!\x02", "box_type": 0},
    {"id": 0x7106, "text": "Hey, das steht Dir wirklich gut!\x02", "box_type": 0},
    {"id": 0x7107, "text": "\x08Bist Du so häßlich, daß Du das \x01Ding tragen mußt?!\x09\x02", "box_type": 0},
    {"id": 0x7108, "text": "Oooh... Bist Du ein Zora?\x01Diese Augen... Wirklich\x01faszinierend...\x02", "box_type": 0},
    {"id": 0x7109, "text": "Das ist ja schrecklich!\x01Komm bloß nicht näher!\x02", "box_type": 0},
    {"id": 0x710A, "text": "Wow... Eine Maske! Das erinnert\x01mich an die Zeit, als ich noch\x01ein kleines Kind war.\x02", "box_type": 0},
    {"id": 0x710B, "text": "Hey, das ist lustig... Es\x01bringt mich zum Lachen!\x01Hihihihi!\x02", "box_type": 0},
    {"id": 0x710C, "text": "\x08Oh-oh!\x09 Sorry, Mutter!\x01Oh... Ach, Du bist es!\x01Erschreck mich doch nicht \x01so!\x02", "box_type": 0},
    {"id": 0x710D, "text": "Du hast einen Riesenkürbis!\x02", "box_type": 0},
    {"id": 0x710E, "text": "Mach das nie wieder!\x01Ich bin so schreckhaft...\x02", "box_type": 0},
    {"id": 0x710F, "text": "Findet hier ein Maskenwettbewerb \x01statt? \x01\x08Wenn ja, dann wähle ich Dich!\x09\x02", "box_type": 0},
    {"id": 0x7110, "text": "Oh! Ein Hase!\x01Erst kürzlich sah ich einen \x01Mann, der auf dem Feld den \x01Hasen nachjagte.\x02", "box_type": 0},
    {"id": 0x7111, "text": "Oh, welch gutaussehende Frau!\x01Aber Du bist ein wenig klein,\x01oder?\x02", "box_type": 0},
    {"id": 0x7112, "text": "Wow, mit der Maske siehst Du \x01hübscher aus als vorher!\x02", "box_type": 0},
    {"id": 0x7113, "text": "Eine Maske... Das erinnert mich an\x01meine Jugendzeit. Damals hab ich\x01auch welche getragen. Heute würde \x01man mich als Spinner beschimpfen!\x02", "box_type": 0},
    {"id": 0x7114, "text": "Oh, hübsch... Ein wandelnder Fisch...\x01Ich könnte Dich zum Abendessen \x01einladen... Als Hauptgericht!\x02", "box_type": 0},
    {"id": 0x7115, "text": "Nicht schlecht. So einen \x01großen Hasen kriegt man selten in \x01die Pfanne!\x02", "box_type": 0},
    {"id": 0x7116, "text": "\x08AAAAAAAAAAAH!\x01EINE GERUDO-KRIEGERIN!!!!\x09\x04Was? Nur eine Maske?!\x01Wie konntest Du mich so \x01erschrecken?!\x02", "box_type": 0},
    {"id": 0x7117, "text": "Sorry, aber ich habe zu tun. Ich \x01muß etwas zum Essen einkaufen.\x02", "box_type": 0},
    {"id": 0x7118, "text": "Oh! Ein Fuchs! Hast Du auch\x01eine Gans gestohlen?!\x02", "box_type": 0},
    {"id": 0x7119, "text": "Das ist gespenstisch!\x01Ein Junge in Kakariko hat\x01nach einer Maske wie dieser\x01gesucht!\x02", "box_type": 0},
    {"id": 0x711A, "text": "Gähn... Hast Du keine andere\x01Maske?\x02", "box_type": 0},
    {"id": 0x711B, "text": "Welch eine seltsame Maske!\x01Die ist klasse!\x02", "box_type": 0},
    {"id": 0x711C, "text": "Stör uns jetzt nicht! Wir haben \x01hier Wichtiges zu, äh, \x01besprechen!\x02", "box_type": 0},
    {"id": 0x711D, "text": "Ich denke gar nicht daran,\x01irgendeine andere Frau \x01anzuschauen!\x02", "box_type": 0},
    {"id": 0x711E, "text": "Beachte ihn nicht, Darling...\x01Wir haben Besseres zu tun...\x01Küß mich...\x02", "box_type": 0},
    {"id": 0x711F, "text": "Ein Hase! Sorry, aber ich hab \x01schon ein Häschen hier... und es \x01ist hübscher als Du!\x02", "box_type": 0},
    {"id": 0x7120, "text": "Ein Gerücht besagt, daß es einen \x01Laden gibt, der das ultimative\x01Elixier verkauft!\x02", "box_type": 0},
    {"id": 0x7121, "text": "Ich hörte, daß es irgendwo eine \x01Kreatur geben soll, die \x05\x44hylianische \x01Schilde\x05\x40 frißt...\x02", "box_type": 0},
    {"id": 0x7122, "text": "Ich kam her, um Bomben zu \x01verkaufen.\x02", "box_type": 0},
    {"id": 0x7123, "text": "\x1AIch... Ich habe Angst...\x01Große Angst, daß dieser Mann \x01Hyrule den Untergang bringt.\x04\x1AEr besitzt übermenschliche Kräfte!\x04\x1ADoch nun, da Du hier bist, wird \x01alles gut...\x0B\x02", "box_type": 0},
    {"id": 0x7124, "text": "Das ist ja albern!\x02", "box_type": 0},
    {"id": 0x7125, "text": "Würdest Du arbeiten,\x01kämst Du nicht auf solch\x01dämliche Ideen!\x02", "box_type": 0},
    {"id": 0x7126, "text": "Hey, Du trägst eine Holzmaske!\x01Die brennt sicher gut!\x02", "box_type": 0},
    {"id": 0x7127, "text": "Bist Du wirklich so häßlich,\x01daß Du dieses Ding tragen mußt?\x02", "box_type": 0},
    {"id": 0x7128, "text": "Ogottogottogott... Das darfst Du \x01aber nicht, mich so erschrecken!\x02", "box_type": 0},
    {"id": 0x7129, "text": "Du Böser! \x01Mich so auf den Arm zu \x01nehmen...\x04Welch ein Schelm!\x02", "box_type": 0},
    {"id": 0x712A, "text": "Huch, eine Frau...\x01Was will die denn hier...?\x02", "box_type": 0},
    {"id": 0x712B, "text": "Ich werde auch versuchen, eine \x01Maske zu schnitzen... Vielleicht \x01eine Pinocchio-Maske. Wegen der \x01langen Nase... Hehe...\x02", "box_type": 0},
    {"id": 0x712C, "text": "Whoa! Kommst Du gerade aus dem \x01Fratzenwald?\x02", "box_type": 0},
    {"id": 0x712D, "text": "Ah, der Nachwuchsheld!\x01Wie läuft's denn so?\x01Alles klar?\x02", "box_type": 0},
    {"id": 0x712E, "text": "Ich bin im Dienst!\x01Ich darf nicht lachen!\x01VERSCHWINDE!\x02", "box_type": 0},
    {"id": 0x712F, "text": "Oh, eine Maske... Schützt sie\x01Dich auch vor Faustschlägen?\x02", "box_type": 0},
    {"id": 0x7130, "text": "Oh, wie süß!\x01Aber nicht so süß wie meine \x01Hühner!\x02", "box_type": 0},
    {"id": 0x7131, "text": "Hmmm, eine Maske...\x01Trägst Du sie, ist es ziemlich \x01schwer, festzustellen, ob Du \x01traurig oder fröhlich bist!\x02", "box_type": 0},
    {"id": 0x7132, "text": "So häßlich bist Du nun auch \x01wieder nicht, daß Du eine Maske\x01tragen müßtest.\x02", "box_type": 0},
    {"id": 0x7133, "text": "Auf dem Friedhof ist auch ein\x01Junge, dem so etwas gefallen \x01würde...\x02", "box_type": 0},
    {"id": 0x7134, "text": "Na, hübsche Frau?! Heute abend\x01schon etwas vor?\x02", "box_type": 0},
    {"id": 0x7135, "text": "WÜRG!\x01Ich dachte gerade, Du wärst meine\x01Ex-Freundin! Erschreck mich bitte\x01nie wieder so...\x02", "box_type": 0},
    {"id": 0x7136, "text": "Mein Vater sprach mal von einem\x01Meisterschmied...\x01Wie dem auch sei, ich verkaufe\x01Hühner...\x02", "box_type": 0},
    {"id": 0x7137, "text": "Ah, ein Monster! Ich werde es\x01einen Kopf kürzer machen und\x01seine Gebeine durch den\x01Fleischwolf drehen...\x02", "box_type": 0},
    {"id": 0x7138, "text": "Wer bist Du? Ich kann das von \x01hier aus schlecht erkennen...\x02", "box_type": 0},
    {"id": 0x7139, "text": "Ah, Du bist es! Trägst Du Deine \x01Haare heute anders?\x02", "box_type": 0},
    {"id": 0x713A, "text": "Hey, hast Du eine Beule am Kopf?\x02", "box_type": 0},
    {"id": 0x713B, "text": "Huch, ein Außerirdischer!\x02", "box_type": 0},
    {"id": 0x713C, "text": "Füchse finde ich nicht\x01besonders attraktiv!\x02", "box_type": 0},
    {"id": 0x713D, "text": "Mit dieser Maske wirst Du bei\x01Frauen nicht viel Erfolg haben...\x02", "box_type": 0},
    {"id": 0x713E, "text": "Ich war schon immer gegen \x01Genversuche...\x02", "box_type": 0},
    {"id": 0x713F, "text": "Wow, die Möglichkeiten der\x01plastischen Chirurgie sind\x01erstaunlich!\x02", "box_type": 0},
    {"id": 0x7140, "text": "Ungezogener Bengel!\x01Wenn Du jemanden ansprichst,\x01solltest Du stets den \x01Augenkontakt suchen!\x02", "box_type": 0},
    {"id": 0x7141, "text": "Die Jugend von heute!\x01Nun tragen sie schon Masken, um \x01wie Frauen auszusehen! Zu meiner\x01Zeit hätte es das nicht gegeben!\x02", "box_type": 0},
    {"id": 0x7142, "text": "Unverschämtes Balg! Wie läufst Du \x01überhaupt herum?! Dein Hemd ist \x01nicht gebügelt, Deine Schuhe sind\x01schmutzig und Du bist vorlaut!\x02", "box_type": 0},
    {"id": 0x7143, "text": "Äußerst interessant! Diese Maske\x01scheint eine Todesmaske des Zulu-\x01Kultes zu sein! Die Tiki-Priester\x01verwenden sie bei Ritualen...\x02", "box_type": 0},
    {"id": 0x7144, "text": "Eine Maske! Aber keine \x01besonders hübsche...\x02", "box_type": 0},
    {"id": 0x7145, "text": "Nette Maske, leider habe ich keine\x01Zeit, sie mir näher anzuschauen.\x02", "box_type": 0},
    {"id": 0x7146, "text": "Eine Maske gleicht einem\x01Musikinstrument. Sie spiegelt den\x01Charakter ihres Besitzers wieder. \x01Ich mag das...\x02", "box_type": 0},
    {"id": 0x7147, "text": "Meine Güte, was für eine \x01Superrübe! Bleibst Du damit\x01nicht überall hängen?\x02", "box_type": 0},
    {"id": 0x7148, "text": "Ist das eine Rattenmaske?!\x02", "box_type": 0},
    {"id": 0x7149, "text": "Welch bezaubernde Schönheit!\x01Niemals blickte ich in ein\x01Antlitz, das anmutiger war...\x02", "box_type": 0},
    {"id": 0x714A, "text": "Ich will Dir ja nicht zu nahe\x01treten... Aber Du siehst aus wie\x01ein Vollidiot!\x02", "box_type": 0},
    {"id": 0x714B, "text": "Cooles Outfit! Sind Deine Eltern \x01Zoras?\x02", "box_type": 0},
    {"id": 0x714C, "text": "Hör auf mit den Spielchen\x01und erlöse uns von dem Fluch!\x02", "box_type": 0},
    {"id": 0x714D, "text": "Ein Schädel! Er erinnert mich an\x01den Fluch... Den Fluch der \x01Skulltulas!\x02", "box_type": 0},
    {"id": 0x714E, "text": "Verzeih mir, daß ich nicht lache,\x01aber ich wurde verflucht, und das\x01ist nicht sehr lustig...\x02", "box_type": 0},
    {"id": 0x714F, "text": "\x12\x68\x67Whoa!\x01Das macht mir Angst!\x01Ich weiß, daß ich schon \x01furchteinflößend bin... Aber das...\x02", "box_type": 0},
    {"id": 0x7150, "text": "Huch! Aaargh!\x04Oh, es ist nur ein Kind! Du \x01darfst einen alten Mann doch \x01nicht so erschrecken!\x02", "box_type": 0},
    {"id": 0x7151, "text": "Wow, ein riesiger Schwellkopf! \x01Ich habe auch einen! Sind wir \x01verwandt?\x02", "box_type": 0},
    {"id": 0x7152, "text": "Weißt Du, was für eine Maske Du\x01trägst? Damit sollte man keine\x01Scherze treiben...\x02", "box_type": 0},
    {"id": 0x7153, "text": "Sorry, ich habe jetzt keine Zeit\x01für Dich, ich muß ein neues Grab\x01ausheben...\x02", "box_type": 0},
    {"id": 0x7154, "text": "Was ist das denn? Das sieht\x01nicht besonders unheimlich aus...\x01Na ja, vielleicht unheimlich\x01bescheuert...\x02", "box_type": 0},
    {"id": 0x7155, "text": "Hey! Eine Fuchs-Maske! \x01Abgefahren! Mein Daddy wollte \x01mir so eine besorgen!\x02", "box_type": 0},
    {"id": 0x7156, "text": "Du siehst aus wie\x01der Totengräber...\x01Das macht mir keine Angst!\x02", "box_type": 0},
    {"id": 0x7157, "text": "Wow, cool! Richtig unheimlich!\x01Unheimlicher als Boris...\x02", "box_type": 0},
    {"id": 0x7158, "text": "\x12\x68\x63Eine nette Maske... Aber wir \x01Kokiri sind hübscher, oder?\x02", "box_type": 0},
    {"id": 0x7159, "text": "Hey! Das kenne ich...\x01So etwas habe ich kürzlich in\x01den Verlorenen Wäldern gesehen...\x02", "box_type": 0},
    {"id": 0x715A, "text": "\x12\x68\x63Oh, wie goldig...\x02", "box_type": 0},
    {"id": 0x715B, "text": "Oh... Schnief... Heul...\x01Diese Maske...\x01Sie macht mir Angst...\x02", "box_type": 0},
    {"id": 0x715C, "text": "Pah! Das beeindruckt mich nicht!\x01Sicher trägst Du sie nur, weil Du\x01vor mir, dem mächtigen Mido, \x01Angst hast...\x02", "box_type": 0},
    {"id": 0x715D, "text": "Aaaargh! Was? Ach so...\x01Nein, ich habe keine Angst!\x01Aber komm bloß nicht näher,\x01hörst Du?!\x02", "box_type": 0},
    {"id": 0x715E, "text": "Hey, coole Maske!\x01Ha! War nur Spaß!\x01Damit siehst Du noch dämlicher \x01aus als vorher!\x02", "box_type": 0},
    {"id": 0x715F, "text": "Ach, unser Süßer! Das steht\x01Dir, Du solltest sie aufbehalten!\x02", "box_type": 0},
    {"id": 0x7160, "text": "Hilfeeeeeeeeee!\x01Das... Das erzähle ich Mido!\x02", "box_type": 0},
    {"id": 0x7161, "text": "Iiiiihhhhhhhhh!\x01Wenn ich das Mido erzähle, \x01bekommst Du Ärger!\x02", "box_type": 0},
    {"id": 0x7162, "text": "Aaaaaaaarggghhh!\x01Mir ist ein Waldgeist erschienen!\x02", "box_type": 0},
    {"id": 0x7163, "text": "Wow! Ist die süß!\x01Äh... Sag Mido nicht, daß mir die \x01Maske gefällt!\x02", "box_type": 0},
    {"id": 0x7164, "text": "Was?!\x01Du bist zurück!\x01Ich erkenne Dich, selbst wenn Du\x01diese Maske trägst!\x02", "box_type": 0},
    {"id": 0x7165, "text": "Ich frage mich, wie Mido auf diese \x01Maske reagieren würde.\x01Das würde ich wirklich gerne \x01sehen!\x02", "box_type": 0},
    {"id": 0x7166, "text": "Ah, verstehe...\x01Du trägst diese Maske, um Mido\x01zu erschrecken, stimmt's?!\x02", "box_type": 0},
    {"id": 0x7167, "text": "Hihi! Welch lustige Maske!\x01Obwohl, einem Mädchen würde sie\x01sicher besser stehen... Hehehe...\x02", "box_type": 0},
    {"id": 0x7168, "text": "Hihi!\x01Eine Holzmaske? Sieht aus, als\x01ob Du ein Brett vorm Kopf \x01hättest! Hihihi...\x02", "box_type": 0},
    {"id": 0x7169, "text": "Welch häßliche Fratze!\x04Und da beschweren sich manche \x01Kinder, daß sie nicht hübsch genug \x01seien...\x02", "box_type": 0},
    {"id": 0x716A, "text": "Hallo Kartoffelkopf! Hihihi...\x02", "box_type": 0},
    {"id": 0x716B, "text": "Hey! Wo hast Du das denn her?\x01Von außerhalb des Waldes!\x01Wow! Das ist unglaublich!\x02", "box_type": 0},
    {"id": 0x716C, "text": "Witzig, aber nicht ganz mein \x01Fall...\x02", "box_type": 0},
    {"id": 0x716D, "text": "Cool! Diese Maske sieht so \x01richtig unheimlich und diabolisch \x01aus! Groovy!\x02", "box_type": 0},
    {"id": 0x716E, "text": "Oh Mann! Hier laufen manchmal\x01Spinner herum...\x02", "box_type": 0},
    {"id": 0x716F, "text": "Danke, aber ich brauche nicht\x01noch eine... Meine gefällt mir ganz\x01gut...\x02", "box_type": 0},
    {"id": 0x7170, "text": "\x12\x68\x6DDu machst mir Angst! Willst \x01Du das?\x02", "box_type": 0},
    {"id": 0x7171, "text": "\x12\x68\x6BWas bist Du denn? Ach, Du bist \x01eines dieser goldigen kleinen \x01Taschenmonster, oder?\x02", "box_type": 0},
    {"id": 0x7172, "text": "\x12\x68\x6CWie goldig, ein Häschen!\x01Hast Du denn auch ein \x01Stummelschwänzchen?\x02", "box_type": 0},
    {"id": 0x7173, "text": "\x12\x68\x69Irgendwie erinnerst Du mich \x01an meine Großmutter...\x02", "box_type": 0},
    {"id": 0x7174, "text": "Hi Feen-Junge! Ach so, Du bist \x01verkleidet, ich darf Dich nicht \x01erkennen! Na gut... Huch, wer bist\x01Du denn?!\x02", "box_type": 0},
    {"id": 0x7175, "text": "Wow! Du hast aber große Augen! \x01Aber... wo sind Deine Ohren?\x02", "box_type": 0},
    {"id": 0x7176, "text": "Oh, dieses Gesicht kenne ich\x01doch! Bist Du Fox McCloud?\x01Ich habe schon viel von Dir\x01gehört!\x02", "box_type": 0},
    {"id": 0x7177, "text": "Hallo Bruder!\x01Schönes Wetter heute, oder?!\x02", "box_type": 0},
    {"id": 0x7178, "text": "Moment... Ich kenne Dich...\x01Du bist... Kaputchi... Nein...\x01Aber so ähnlich klang doch\x01Dein Name, oder...\x02", "box_type": 0},
    {"id": 0x7179, "text": "Uh... Wie häßlich! Genauso häßlich\x01wie Basil!\x02", "box_type": 0},
    {"id": 0x717A, "text": "Hey, sieht aus wie meine Frau...\x01Ähem, ich meine, nein, eigentlich...\x01Nein, niemals...\x02", "box_type": 0},
    {"id": 0x717B, "text": "Gähn...\x01Ich bin ziemlich müde...\x01Zeig mir das Ding später...\x02", "box_type": 0},
    {"id": 0x717C, "text": "Verschwinde!\x01Ich bin beschäftigt!\x02", "box_type": 0},
    {"id": 0x717D, "text": "Tja! Das macht Spaß! Genieße \x01Deine Jugend... Später, wenn Du \x01erwachsen bist, zählt nur noch die \x01Arbeit!\x02", "box_type": 0},
    {"id": 0x717E, "text": "HUCH!\x01Puh, nur eine Maske...\x01Verschwinde hier, Kleiner!\x02", "box_type": 0},
    {"id": 0x717F, "text": "Hey, wie lustig!\x01Das hat mich ein wenig \x01aufgeheitert! Danke, Kleiner!\x02", "box_type": 0},
    {"id": 0x7180, "text": "Hmmm, laß mal schauen...\x01In der Tat... Die Maske wurde aus\x01einem alten Sargdeckel gefertigt...\x01Ein Relikt aus dem Totenreich!\x02", "box_type": 0},
    {"id": 0x7181, "text": "Ah, eine Schädelmaske...\x01Sehr interessant... Es ist ein\x01echter Schädel, es kleben noch\x01ein paar Würmer und Maden daran!\x02", "box_type": 0},
    {"id": 0x7182, "text": "Zeig mal her... Ja, sehr gute\x01Handarbeit... Dies ändert jedoch\x01nichts an der Tatsache, daß Du \x01damit ziemlich dämlich aussiehst!\x02", "box_type": 0},
    {"id": 0x7183, "text": "Laß mal sehen... Aha... Sehr \x01interessant. So was hab ich schon \x01einmal gesehen... Ich glaube, es \x01war in einem Nachtclub...\x02", "box_type": 0},
    {"id": 0x7184, "text": "Mampf... Mampf...\x01Oh, eine Maske, cool...\x01Willst Du nicht ein paar Bohnen \x01kaufen?\x02", "box_type": 0},
    {"id": 0x7185, "text": "Mampf... Rülps...\x01Schön, aber ich habe keine\x01Verwendung dafür...\x02", "box_type": 0},
    {"id": 0x7186, "text": "Mampf... Börps...\x01Danke, aber die paßt nicht\x01zu meinem Wohnzimmerschrank.\x02", "box_type": 0},
    {"id": 0x7187, "text": "Mampf... Börps...\x01Danke, aber Masken mag ich nicht\x01besonders...\x02", "box_type": 0},
    {"id": 0x7188, "text": "Was ist Euer Begehr?\x02", "box_type": 0},
    {"id": 0x7189, "text": "Ihr scheint kein Wasserwesen zu \x01sein...\x02", "box_type": 0},
    {"id": 0x718A, "text": "Ihr wirkt sehr exotisch, woher\x01kommt Ihr?\x02", "box_type": 0},
    {"id": 0x718B, "text": "Ihr mögt das Antlitz der Zoras\x01besitzen, doch Eure Statur gleicht \x01der eines Gartenzwerges...\x02", "box_type": 0},
    {"id": 0x718C, "text": "Was?! Ersucht da ein niederes \x01Getier bei mir Audienz?\x02", "box_type": 0},
    {"id": 0x718D, "text": "Diese Fratze... Gar schrecklich!\x01Zu Hilfe!\x02", "box_type": 0},
    {"id": 0x718E, "text": "Diese Maske... Sie erinnert mich\x01an einen alten Freund.\x01Sein werter Name ist Biggoron!\x02", "box_type": 0},
    {"id": 0x718F, "text": "Wer wagt es, das edle hylianische \x01Zora-Geschlecht der Lächerlichkeit \x01preiszugeben?\x02", "box_type": 0},
    {"id": 0x7190, "text": "Hihi! Du bist süß... Zum Anbeißen!\x02", "box_type": 0},
    {"id": 0x7191, "text": "Das sieht lustig aus!\x02", "box_type": 0},
    {"id": 0x7192, "text": "Laß das, so etwas trägt kein \x01Mann!\x02", "box_type": 0},
    {"id": 0x7193, "text": "Wie ich sehe, hast Du Dich \x01entschloßen, ein Zora zu werden!\x01Nun steht unserer Heirat nichts\x01mehr im Wege!\x02", "box_type": 0},
    {"id": 0x7194, "text": "WHOA!\x01Mein Herz! Welch ein Schock!\x02", "box_type": 0},
    {"id": 0x7195, "text": "Das sieht nicht nett aus...\x01Tschüß...\x02", "box_type": 0},
    {"id": 0x7196, "text": "Hm...\x01Bist Du ein Travestie-Künstler?\x02", "box_type": 0},
    {"id": 0x7197, "text": "Du solltest mehr Steine fressen!\x01Wenn nicht, wirst Du immer so \x01mickrig bleiben!\x02", "box_type": 0},
    {"id": 0x7198, "text": "Laß mich allein!\x02", "box_type": 0},
    {"id": 0x7199, "text": "Willst Du mich zum Lachen bringen?\x01Vergiß es! Das ist nicht lustig.\x02", "box_type": 0},
    {"id": 0x719A, "text": "Ich habe schon mehr gelacht...\x02", "box_type": 0},
    {"id": 0x719B, "text": "Ich mag keine Gerudos!\x02", "box_type": 0},
    {"id": 0x719C, "text": "Stör mich nicht!\x01Verschwinde!\x02", "box_type": 0},
    {"id": 0x719D, "text": "Glaubst Du wirklich, daß Du\x01verkleidet bist?\x02", "box_type": 0},
    {"id": 0x719E, "text": "Aus dem Weg!\x01Verschwinde! Dies ist kein\x01Kinderspielplatz!\x02", "box_type": 0},
    {"id": 0x719F, "text": "Du scheinst Mut zu haben, Dich\x01in diese Gegend zu wagen!\x01Glaub bloß nicht, daß Du uns \x01täuschen kannst!\x02", "box_type": 0},
    {"id": 0x71A0, "text": "Was soll das?\x01Willst Du mich zum Narren\x01halten?\x02", "box_type": 0},
    {"id": 0x71A1, "text": "Du bist sehr mutig, Dich mit \x01dieser Maske in unsere Gegend\x01zu wagen! Du gefällst mir!\x02", "box_type": 0},
    {"id": 0x71A2, "text": "Das sind Spiele aus dem \x01Kindergarten! Werde erwachsen!\x02", "box_type": 0},
    {"id": 0x71A3, "text": "Nanu? Du... Du siehst aus wie ich!\x01Nein, ich bin hübscher. Und vor \x01allem nicht so klein...\x02", "box_type": 0},
    {"id": 0x71A4, "text": "Nein, nein!\x01Die Ohren sind etwas zu klein!\x01Sie sollten eher so aussehen!\x02", "box_type": 0},
    {"id": 0x71A5, "text": "Hast Du denn keine Angst, des \x01Nachts hier herumzulaufen? Noch \x01dazu mit einer Maske wie dieser?\x02", "box_type": 0},
    {"id": 0x71A6, "text": "Du scheinst ja ein richtiger \x01Maskensammler zu sein!\x02", "box_type": 0},
    {"id": 0x71A7, "text": "Ich erinnere mich, irgendwo einen\x01Stein gesehen zu haben, der \x01ähnlich aussah...\x02", "box_type": 0},
    {"id": 0x71A8, "text": "Beeil Dich, \x0F!\x01Der Teufelsturm kann jede \x01Sekunde einstürzen!\x02", "box_type": 0},
    {"id": 0x71A9, "text": "Achtung! Von überall her stürzen \x01Trümmer herab!\x02", "box_type": 0},
    {"id": 0x71AA, "text": "\x0F!\x01Hilf mir!\x02", "box_type": 0},
    {"id": 0x71AB, "text": "\x0F!\x01Der Ausgang ist hier drüben!\x02", "box_type": 0},
    {"id": 0x71AC, "text": "Hab Dank, \x0F.\x01Schnell! Laß uns fliehen!\x02", "box_type": 0},
    {"id": 0x71AD, "text": "Du brauchst offenbar\x01noch etwas Training!\x04Übe fleißig und komme wieder!\x0B\x02", "box_type": 0},
    {"id": 0x71AE, "text": "Fast!\x04Nun gut...\x01Du darfst es noch einmal \x01versuchen! Umsonst! \x01Diesmal mußt Du es schaffen!\x0B\x02", "box_type": 0},
    {"id": 0x71AF, "text": "Ich bin begeistert!\x01Klasse!\x01Göttlich!\x04Hier, nimm dieses einzigartige\x01Präsent an Dich!\x0B\x02", "box_type": 0},
    {"id": 0x71B0, "text": "\x08\x05\x44Oh-oh, \x05\x41die Zeit\x05\x44 ist abgelaufen!\x05\x41\x01\x05\x44Das Ding, das Du ausliefern \x01solltest, ist verdorben! \x01Versuch es erneut!\x05\x40\x09\x0B\x02", "box_type": 0},
    {"id": 0x71B1, "text": "\x08Man erzählt sich, es sei\x01\x1F Uhr!\x09\x0E\x28\x02", "box_type": 0},
